	ld (4306:16), wa
	ldc_cr16 wa, 0x7C
	popw wa
	ei 0
	nop
	ei 6
	push xhl
	push xwa
	push xbc
	push xde
	push xix
	push xiy
	push xiz
	jrl TaskSched_Dispatch

TaskSched_SpawnTask:
