Task_ConfigTimer:
	push	sr
	ei 6
	push xhl
	push xwa
	push xbc
	push xde
	push xix
	push xiy
	push xiz
	ld xix, xwa
	ld a, (xix + 256)
	mul a, 0x8
	add wa, 0x10C2
	ld iy, wa
	extz xiy
	ld wa, (xix + 2)
	ld (xiy + 256), wa
	ld (xiy + 2), wa
	ld xwa, (xix + 4)
	ld (xiy + 4), xwa
	jrl TaskSched_Dispatch
	push	sr
	ei 6
	push xhl
	push xwa
	push xbc
	push xde
	push xix
	push xiy
	push xiz
	ld e, c
	mul a, 0xC
	add wa, 0x103C
