	ld (xix + 8), e
	sll e, 2
	extz de
	add de, 0x1068
	ld iy, de
	extz xix
	extz xiy
	xor xwa, xwa
	ld (xix + 256), iy
	ld wa, (xiy + 2)
	ld (xix + 2), wa
	ld (xwa), ix
	ld (xiy + 2), ix
	jrl TaskSched_Dispatch

Task_Reassign_NotRunning:
	ld (xix + 8), e
	jrl TaskSched_ContextRestore
	push xwa
	push xix
	push xiy
	push xhl
	pushw de
	ld e, c
	mul a, 0xC
	add wa, 0x103C
	ld ix, wa
	extz xix
	push	sr
	ei 6
	cp (xix + 9), 0x4
	jr nz, Task_Reassign_Guard_NotRunning
	extz xix
	xor xwa, xwa
	xor xhl, xhl
	ld wa, (xix + 256)
	ld hl, (xix + 2)
	ld (xhl + 256), wa
	ld (xwa + 2), hl
	ld (xix + 8), e
	sll e, 2
	extz de
	add de, 0x1068
	ld iy, de
	extz xix
