; --- Audio buffer pointer load/store utilities ---
; Five small routines that load/store 16-bit pointer values
; from the audio buffer control block at 0x041138-0x041142.
; Each routine saves/restores caller registers.
; Read index (0x04113A) -> mark cursor (0x041138).
AudioBuf_PtrUtils:
	pushw	hl
	ld	hl, (266554:24)
	stw_da	266552, hl
	popw	hl
	ret
; Mark-cursor pop bounded by the commit index (engine 0x020B2C).
FIFO512_Get_Marked:
	pushw	ix
	push	xde
	lda	xde, (266562:24)
	call	133932
	pop	xde
	popw	ix
	ret
; Mark-cursor pop bounded by the write index (engine 0x020B47).
FIFO512_Get_From_Mark:
	pushw	ix
	push	xde
	lda	xde, (266562:24)
	call	133959
	pop	xde
	popw	ix
	ret
; Commit index (0x04113C) -> read index (0x04113A).
FIFO512_Commit:
	pushw	hl
	ld	hl, (266556:24)
	stw_da	266554, hl
	popw	hl
	ret
; Write index (0x04113E) -> commit index (0x04113C).
FIFO512_Set_Commit:
	pushw	hl
	ld	hl, (266558:24)
	stw_da	266556, hl
	popw	hl
	ret

RingBuf_Reset_256:
	ldw (xde - 10), 0x0
	ldw (xde - 8), 0x0
	ldw (xde - 4), 0x0
	ldw (xde - 6), 0x0
	ldw (xde - 2), 0xFF
	ret

RingBuf_WrappedRead_Opaque_A:
	.byte 0x9a, 0xf8, 0x24, 0x9a, 0xfc, 0xf4, 0x6e, 0x04
	.byte 0x33, 0xff, 0xff, 0x0e, 0xdb, 0xd3, 0xc3, 0x07
	.byte 0xe8, 0xf0, 0x27, 0xdc, 0x38, 0xff, 0x00, 0xba
	.byte 0xf8, 0x54, 0x9a, 0xfe, 0x61, 0x0e
; Engine: pop at the mark cursor (XDE-10), stop when it equals the commit index (XDE-6).
FIFO_Engine256_Get_Marked:
	.byte 0x9a, 0xf6
	.byte 0x24, 0x9a, 0xfa, 0xf4, 0x6e, 0x04, 0x33, 0xff
	.byte 0xff, 0x0e, 0xdb, 0xd3, 0xc3, 0x07, 0xe8, 0xf0
	.byte 0x27, 0xdc, 0x38, 0xff, 0x00, 0xba, 0xf6, 0x54
	.byte 0x0e
; Engine: pop at the mark cursor (XDE-10), stop when it equals the write index (XDE-4).
FIFO_Engine256_Get_From_Mark:
	.byte 0x9a, 0xf6, 0x24, 0x9a, 0xfc, 0xf4, 0x6e
	.byte 0x04, 0x33, 0xff, 0xff, 0x0e, 0xdb, 0xd3, 0xc3
	.byte 0x07, 0xe8, 0xf0, 0x27, 0xdc, 0x38, 0xff, 0x00
	.byte 0xba, 0xf6, 0x54, 0x0e
; Engine: if free count (XDE-2) is zero return HL=0xFFFF; else store A at (XDE + writeidx),
; advance the write index modulo 0x0FF, decrement the free count, return it in HL.
FIFO_Engine256_Put:
	.byte 0x9a, 0xfe, 0x3f, 0x00
	.byte 0x00, 0x6e, 0x04, 0x33, 0xff, 0xff, 0x0e, 0x9a
	.byte 0xfc, 0x24, 0xf3, 0x07, 0xe8, 0xf0, 0x41, 0xdc
	.byte 0x38, 0xff, 0x00, 0xba, 0xfc, 0x54, 0x9a, 0xfe
	.byte 0x69, 0x9a, 0xfe, 0x23, 0x0e

RingBuf_Reset_512:
	ldw (xde - 10), 0x0
	ldw (xde - 8), 0x0
	ldw (xde - 4), 0x0
	ldw (xde - 6), 0x0
	ldw (xde - 2), 0x1FF
	ret

RingBuf_WrappedRead_Opaque_B:
	.byte 0x9a, 0xf8, 0x24, 0x9a, 0xfc, 0xf4, 0x6e, 0x04
	.byte 0x33, 0xff, 0xff, 0x0e, 0xdb, 0xd3, 0xc3, 0x07
	.byte 0xe8, 0xf0, 0x27, 0xdc, 0x38, 0xff, 0x01, 0xba
	.byte 0xf8, 0x54, 0x9a, 0xfe, 0x61, 0x0e
; 512-byte twin of 0x020A9D (wrap mask 0x1FF).
FIFO_Engine512_Get_Marked:
	ld	ix, (xde-10)
	cp16_src_rid8	xde, 0xfa, ix	; cp IX,(XDE+0xfa)
	jr	nz, LABEL_020B38
	ldw	hl, 65535
	ret
LABEL_020B38:
	xor	hl, hl
	ld_rrb	l, xde, ix	; ld L,(XDE+IX)
	minc1_16	ix, 0x01ff	; minc1 0x01ff,IX
	ld	(xde-10), ix
	ret
; 512-byte twin of 0x020AB8 (wrap mask 0x1FF).
FIFO_Engine512_Get_From_Mark:
	ld	ix, (xde-10)
	cp16_src_rid8	xde, 0xfc, ix	; cp IX,(XDE+0xfc)
	jr	nz, LABEL_020B53
	ldw	hl, 65535
	ret
LABEL_020B53:
	xor	hl, hl
	ld_rrb	l, xde, ix	; ld L,(XDE+IX)
	minc1_16	ix, 0x01ff	; minc1 0x01ff,IX
	ld	(xde-10), ix
	ret
; 512-byte twin of 0x020AD3 (wrap mask 0x1FF).
FIFO_Engine512_Put:
	.byte 0x9a, 0xfe, 0x3f, 0x00
	.byte 0x00, 0x6e, 0x04, 0x33, 0xff, 0xff, 0x0e, 0x9a
	.byte 0xfc, 0x24, 0xf3, 0x07, 0xe8, 0xf0, 0x41, 0xdc
	.byte 0x38, 0xff, 0x01, 0xba, 0xfc, 0x54, 0x9a, 0xfe
	.byte 0x69, 0x9a, 0xfe, 0x23, 0x0e

RingBuf_Reset_1K:
	ldw (xde - 10), 0x0
	ldw (xde - 8), 0x0
	ldw (xde - 4), 0x0
	ldw (xde - 6), 0x0
	ldw (xde - 2), 0x3FF
	ret

RingBuf_WrappedRead_Opaque_C:
	.byte 0x9a, 0xf8, 0x24, 0x9a, 0xfc, 0xf4, 0x6e, 0x04
	.byte 0x33, 0xff, 0xff, 0x0e, 0xdb, 0xd3, 0xc3, 0x07
	.byte 0xe8, 0xf0, 0x27, 0xdc, 0x38, 0xff, 0x03, 0xba
	.byte 0xf8, 0x54, 0x9a, 0xfe, 0x61, 0x0e
; 1 KB twin of 0x020A9D (wrap mask 0x3FF).
FIFO_Engine1K_Get_Marked:
	.byte 0x9a, 0xf6
	.byte 0x24, 0x9a, 0xfa, 0xf4, 0x6e, 0x04, 0x33, 0xff
	.byte 0xff, 0x0e, 0xdb, 0xd3, 0xc3, 0x07, 0xe8, 0xf0
	.byte 0x27, 0xdc, 0x38, 0xff, 0x03, 0xba, 0xf6, 0x54
	.byte 0x0e
; 1 KB twin of 0x020AB8 (wrap mask 0x3FF).
FIFO_Engine1K_Get_From_Mark:
	.byte 0x9a, 0xf6, 0x24, 0x9a, 0xfc, 0xf4, 0x6e
	.byte 0x04, 0x33, 0xff, 0xff, 0x0e, 0xdb, 0xd3, 0xc3
	.byte 0x07, 0xe8, 0xf0, 0x27, 0xdc, 0x38, 0xff, 0x03
	.byte 0xba, 0xf6, 0x54, 0x0e
; 1 KB twin of 0x020AD3 (wrap mask 0x3FF).
FIFO_Engine1K_Put:
	.byte 0x9a, 0xfe, 0x3f, 0x00
	.byte 0x00, 0x6e, 0x04, 0x33, 0xff, 0xff, 0x0e, 0x9a
	.byte 0xfc, 0x24, 0xf3, 0x07, 0xe8, 0xf0, 0x41, 0xdc
	.byte 0x38, 0xff, 0x03, 0xba, 0xfc, 0x54, 0x9a, 0xfe
	.byte 0x69, 0x9a, 0xfe, 0x23, 0x0e

Audio_CmdHandler_C0_FF:
	lds hl, 0
	ret

; ===========================================================================
; InterCPU_Latch_Setup - Setup inter-CPU communication via latches
; ===========================================================================
; Entry: None
; Exit:  DMA channels and interrupt handlers configured
; Notes: Configures interrupt priority for DMA channels 0-3
;        Sets up MicroDMA for inter-CPU latch communication at 0x120000
;        Initializes DMA_XFER_STATE and CMD_PROCESSING_STATE to 0
; ===========================================================================
InterCPU_Latch_Setup:
	and_sd8b_im 0xE5, 0xF8
	res_dd8 2, 0x80
	lda_dd8l XBC, 0xEC
	ld a, (xbc)
	and a, 0xF8
	or a, 0x5
	ld (xbc), a
	lda_dd8l XBC, 0xED
	ld a, (xbc)
	and a, 0xF8
	or a, 0x5
	ld (xbc), a
	lda_dd8l XBC, 0xF0
	ld a, (xbc)
	and a, 0xF8
	set 0, a
	ld (xbc), a
	ldio 0x8A, 0x14
	lda xwa, (0x120000:24)
	ldc_cr32 xwa, 0x28
	ldb a, 0x8
	ldc_cr8 a, 0x4A
	lda xwa, (0x120000:24)
	ldc_cr32 xwa, 0x00
	ldb a, 0x0
	ldc_cr8 a, 0x42
	ld (4328:16), 0
	ld (4330:16), 0
	ret

; ===========================================================================
; InterCPU_DMA_Send - Send data via DMA to main CPU
; ===========================================================================
; Entry: XDE = source data pointer
;        BC = byte count
;        A = command/channel identifier
; Exit:  Data transferred to main CPU via inter-CPU latch
; Notes: Splits large transfers into 32-byte chunks
;        Used by tone generator and audio subsystem for command responses
; ===========================================================================
InterCPU_DMA_Send:
	dec 6, xsp
	pushw iz
	ld (xsp + 2), xde
	ld iz, bc
	ld (xsp + 6), a
	cp iz, 0x20
	jr ule, DMA_Send_Final

DMA_Send_Loop:
	ld a, (xsp + 6)
	extz wa
	ldw bc, 0x20
	ld xde, (xsp + 2)
	calr InterCPU_DMA_Send_Chunk
	ld xwa, 0x20
	add (xsp + 2), xwa
	sub iz, 0x20
	cp iz, 0x20
	jr ugt, DMA_Send_Loop

DMA_Send_Final:
	ld a, (xsp + 6)
	extz wa
	stb_erp C, 0xF8
	extz bc
	ld xde, (xsp + 2)
	calr InterCPU_DMA_Send_Chunk
	popw iz
	inc 6, xsp
	ret

; ===========================================================================
; InterCPU_DMA_Send_Chunk - Transfer a single chunk of data to main CPU
; ===========================================================================
; Entry: XDE = source data pointer
;        BC = byte count (must be non-zero)
;        A = command/channel identifier (bits 7-5 used for dispatch)
; Exit:  Data transferred via DMA channel 2
; Notes: Helper for InterCPU_DMA_Send - handles one transfer operation.
;        Waits for MSTAT1 handshake, sets up DMA, then waits for completion.
;        Command byte format: (A << 5) | (length - 1)
; ===========================================================================
InterCPU_DMA_Send_Chunk:
	cps c, 0
	ret z
	lds ix, 0

DMA_Chunk_Start:
	bit_dd8 4, 0x34	; MSTAT1 - test if Main CPU is requesting handshake
	jr z, DMA_Chunk_Wait_MSTAT1_Clear
	res_dd8 0, 0x34	; SSTAT0 - clear to acknowledge Main CPU handshake request
	ld (4328:16), 1
	ld l, c
	dec 1, l
	sll a, 5
	or a, l
	stb_da 0x120000, a
	lds ix, 0

DMA_Chunk_Transfer:
	bit_dd8 4, 0x34	; MSTAT1 - wait for Main CPU to clear (data ready to receive)
	jr nz, DMA_Chunk_Wait_MSTAT1_Set
	set_dd8 0, 0x34	; SSTAT0 - set to signal ready to receive DMA data
	ldc_cr32 xde, 0x08
	extz bc
	ldc_cr16 bc, 0x48
	ld (258:16), 22
	set_dd8 2, 0x80
	cp (4328:16), 0
	ret z

DMA_Chunk_Wait:
	cp (4328:16), 0
	jr nz, DMA_Chunk_Wait
	ret

; Retry counter for DMA_Chunk_Start, i.e. the E0/chunk path SPECIFICALLY (the E2 and E3
; paths have their own gates, E2_Wait_MSTAT1_Set and E3_Wait_MSTAT1_Clear/Set).  Spins back
; while MSTAT1 is still low; gives up after 60001 tries (compare 0xEA60).
DMA_Chunk_Wait_MSTAT1_Clear:
	ld hl, ix
	inc 1, ix
	cp hl, 0xEA60
	jr ule, DMA_Chunk_Start
	ret

; Retry counter for DMA_Chunk_Transfer on the same E0/chunk path.  Spins back while MSTAT1
; is still high; on timeout it forces SSTAT0 before returning.
DMA_Chunk_Wait_MSTAT1_Set:
	ld wa, ix
	inc 1, ix
	cp wa, 0xEA60
	jr ule, DMA_Chunk_Transfer
	set_dd8 0, 0x34	; SSTAT0 - timeout recovery: force ready state before exit
	ret

; Sends the single command byte 0xE3 to the main CPU over the 0x120000 latch, with the same
; two-phase MSTAT1 handshake InterCPU_DMA_Send_Chunk uses but no payload and no micro-DMA.
; Gate 1 (0x020D15): wait for PD bit 4 (MSTAT1, SFR 0x34) to be HIGH; drop SSTAT0 (PD bit 0)
; and write 0xE3 to 0x120000. Gate 2 (0x020D23): wait for MSTAT1 to go LOW, then raise
; SSTAT0 and return. Each gate spins through E3_Wait_MSTAT1_Clear (0x020D2C) /
; E3_Wait_MSTAT1_Set (0x020D37), which give up after 60001 iterations (compare 0xEA60);
; on the gate-1 timeout it returns having sent nothing, on the gate-2 timeout it raises
; SSTAT0 first. BC is used as the retry counter. No caller found by branch-target scan.
InterCPU_LatchProtocol_Opaque:
	.byte 0xd9, 0xa8
; Poll MSTAT1 high, then drop SSTAT0 and write 0xE3 to the latch at 0x120000.
InterCPU_E3_Gate1:
	bit_dd8	4, 52
	jr	z, 18
	res_dd8	0, 52
	stib_da	(1179648), 227
; Poll MSTAT1 low, then raise SSTAT0 and return.
InterCPU_E3_Gate2:
	bit_dd8	4, 52
	jr	nz, 15
	set_dd8	0, 52
	ret

; Retry counter for gate 1 of the 0xE3 send; spins back to 020D15h while MSTAT1 is still low, gives up after 60001 tries.
E3_Wait_MSTAT1_Clear:
	ld	wa, bc
	inc	1, bc
	cp	wa, 60000
	jr	ule, -33
	ret

; Retry counter for gate 2 of the 0xE3 send; spins back to 020D23h while MSTAT1 is still high.
E3_Wait_MSTAT1_Set:
	ld	wa, bc
	inc	1, bc
	cp	wa, 60000
	jr	ugt, -25
	jr	-32

; Sends command byte 0xE2 followed by a fixed 10-byte parameter block staged at 010D4h (XWA/XDE/BC) via micro-DMA ch2. Sibling of InterCPU_E1_DMA_Transfer.
InterCPU_E2_DMA_Transfer:
	; Converted from a 26-byte `.byte` run. Framing: unidasm; every
	; instruction re-encoded and the whole run compared byte for byte.
	; 9 instructions, of which 2 needed a spelling search because
	; llvm-mc --disassemble refuses them (it can still ASSEMBLE them).
	lds	ix, 0
	cp	(4328:16), 0
	jr	z, 17

; Spins while the TX-state flag (DMA_XFER_STATE) is non-zero, i.e. a previous micro-DMA burst is still running.
E2_Wait_DMA_Idle:
	ld	hl, ix
	inc	1, ix
	cp	hl, 60000
	ret	ugt
	cp	(4328:16), 0
	jr	nz, -17

; TX engine idle: assert SSTAT0, mark busy, push the 0xE2 header into the latch.
E2_DMA_Ready:
	res_dd8	0, 52
	ld	(4328:16), 1
	stib_da	(1179648), 226
	lds	ix, 0
	bit_dd8	4, 52
	jr	nz, 51

; Header acknowledged: stage the 10-byte block at 010D4h, program DMAS2/DMAC2/DMA2V and start timer 2.
E2_Start_Transfer:
	.byte 0xf0, 0x34, 0xb8, 0xf1, 0xd4, 0x10, 0x33, 0xb3
	.byte 0x60, 0xbb, 0x04, 0x62, 0xbb, 0x08, 0x51, 0xeb
	.byte 0x2e, 0x08, 0x30, 0x0a, 0x00, 0xd8, 0x2e, 0x48
	.byte 0xf1, 0x02, 0x01, 0x00, 0x16, 0xf0, 0x80, 0xba
	.byte 0xf1, 0xfe, 0x04, 0xbf
; Tail of InterCPU_E2_DMA_Transfer: spins on DMA_XFER_STATE (0x10E8) until the micro-DMA
; channel-2 completion ISR (0x020F01) zeroes it. NO TIMEOUT -- see the findings.
InterCPU_E2_Wait_DMA_Done:
	.byte 0xc1, 0xe8, 0x10, 0x3f
	.byte 0x00, 0xb0, 0xf6, 0xc1, 0xe8, 0x10, 0x3f, 0x00
	.byte 0x6e, 0xf9, 0x0e

; Retry counter for the 0xE2 header acknowledge; spins back to 020D6Dh while MSTAT1 is still high.
E2_Wait_MSTAT1_Set:
	ld	hl, ix
	inc	1, ix
	cp	hl, 60000
	jr	ule, -66
	set_dd8	0, 52
	ret

; ===========================================================================
; InterCPU_E1_DMA_Transfer - E1 command bulk data transfer (Sub→Main CPU)
; ===========================================================================
; Entry: XWA = destination address (in main CPU memory)
;        XDE = source address (in sub CPU memory)
;        BC = byte count
; Exit:  Data transferred to main CPU via two-phase E1 protocol
; Notes: Called from Cmd_Check_E2_Pending to send response data.
;        Phase 1: Send E1 command + 6-byte header (dest addr, byte count)
;        Phase 2: Actual data transfer via DMA channel 2
;        Uses 60000 iteration timeout (0xEA60) for handshake waits.
;        Stores parameters at 0x1110 and 0x10DE for DMA setup.
; ===========================================================================
InterCPU_E1_DMA_Transfer:
	pushw iz
	lds iz, 0
	cp (4328:16), 0
	jr z, E1_DMA_Ready

E1_Wait_DMA_Idle:
	ld hl, iz
	inc 1, iz
	cp hl, 0xEA60
	jrl ugt, E1_Exit
	cp (4328:16), 0
	jr nz, E1_Wait_DMA_Idle

E1_DMA_Ready:
	lds iz, 0

E1_Check_MSTAT1:
	bit_dd8 4, 0x34	; MSTAT1 - test if Main CPU is initiating E1 transfer
	jrl z, E1_Timeout_Retry
	res_dd8 0, 0x34	; SSTAT0 - clear to acknowledge E1 command from Main CPU
	ld (4328:16), 2
	stib_da 0x120000, 0xe1
	lds iz, 0

E1_Start_Transfer:
	bit_dd8 4, 0x34	; MSTAT1 - wait for Main CPU to clear (header data ready)
	jrl nz, E1_Busy_Wait
	set_dd8 0, 0x34	; SSTAT0 - set to signal ready to receive DMA header
	lda xhl, (4368:16)
	ld (xhl), xwa
	lda xwa, (4318:16)
	ld (xwa), xde
	ld (xhl + 4), bc
	ld (xwa + 4), bc
	ldc_cr32 xwa, 0x08
	lds wa, 6
	ldc_cr16 wa, 0x48
	ld (258:16), 22
	set_dd8 2, 0x80
	cp (4328:16), 1
	jr z, E1_Delay_Loop1

E1_Wait_State1:
	cp (4328:16), 1
	jr nz, E1_Wait_State1

E1_Delay_Loop1:
	lds iz, 0
	cp iz, 0xC8
	jr nc, E1_Phase2_Setup

E1_Delay1:
	nop
	inc 1, iz
	cp iz, 0xC8
	jr c, E1_Delay1

E1_Phase2_Setup:
	lda xwa, (4368:16)
	ld xbc, (xwa)
	ldc_cr32 xbc, 0x08
	ld wa, (xwa + 4)
	ldc_cr16 wa, 0x48
	ld (258:16), 22
	set_dd8 2, 0x80
	cp (4328:16), 0
	jr z, E1_Delay_Loop2

E1_Wait_Complete:
	cp (4328:16), 0
	jr nz, E1_Wait_Complete

E1_Delay_Loop2:
	lds iz, 0
	cp iz, 0xC8
	jr nc, E1_Done

E1_Delay2:
	nop
	inc 1, iz
	cp iz, 0xC8
	jr c, E1_Delay2

E1_Done:
	jr E1_Exit

E1_Timeout_Retry:
	ld hl, iz
	inc 1, iz
	cp hl, 0xEA60
	jrl ule, E1_Check_MSTAT1
	jr E1_Exit

E1_Busy_Wait:
	ld hl, iz
	inc 1, iz
	cp hl, 0xEA60
	jrl ule, E1_Start_Transfer
	set_dd8 0, 0x34	; SSTAT0 - timeout recovery: force ready state before exit

E1_Exit:
	popw iz
	ret


; ----------------------------------------------------------------------------
; INT0_HANDLER - External Interrupt 0 Handler (Inter-CPU Command Reception)
; Entry: Triggered when main CPU sends command via latch at 0x120000
; Notes: Reads command byte from latch, dispatches based on value:
;        0xE1 = Start E1 command (6 bytes, state 2) - bulk data transfer setup
;        0xE2 = Start E2 command (10 bytes, state 3) - extended data transfer
;        0xE3 = Payload ready signal (sets PAYLOAD_LOADED_FLAG bit 6)
;        Other = Standard command (1-32 bytes based on bits 4-0, state 1)
;
; ASYMMETRY WITH THE MAIN CPU'S INT0_HANDLER (0xEF3525 in the v9/v10 program
; ROM, 0xEF34FB in v7).  Both ISRs sit on the same kind of latch (IC22 here at
; 0x120000, IC23 the other way) and both are entered once per byte written by
; the other side.  The difference is what happens to the PAYLOAD bytes:
;   this side  - INT0_Start_DMA writes DMA0V (SFR 0x0100) = 10 = the INT0
;                vector number (subcpu_vectors.s), so once the header has been
;                parsed the payload bytes are consumed by HARDWARE micro-DMA
;                and never dispatch this ISR;
;   main side  - DMA0V is never armed at all; every payload byte re-enters the
;                main ISR, which pulls it with a SOFTWARE micro-DMA request
;                (DMAR, SFR 0x0109, bit 0).
; The main-side ISR therefore carries a re-entrancy hazard on HEADER bytes,
; documented above its INT0_HANDLER; it has only ever been observed in
; emulation, under a since-removed /INT0 re-assertion in the CPU model.  Armed
; DMA0V keeps the payload bytes on this side out of this ISR entirely, so there
; is no analogue of it here.  The same non-atomic SHAPE is present, though: the
; MSTAT0 gate is tested before the latch read and SSTAT1 is cleared only at
; INT0_Ack, at the end.
; ----------------------------------------------------------------------------
INT0_HANDLER:	; 20E86
	push xwa
	bit_dd8 2, 0x34	; MSTAT0 - test if Main CPU is currently sending data
	jr nz, INT0_Exit
	ldb_da a, 0x120000
	ld (4332:16), a
	cp a, 0xE1
	jr nz, INT0_Check_E2
	ld (4330:16), 2	; E1 command - state 2
	lda xwa, (4374:16)	; E1 data buffer
	stda32 4324, xwa	; Save DMA target
	ldc_cr32 xwa, 0x20
	lds wa, 6	; 6 bytes for E1
	ldc_cr16 wa, 0x40
	jr INT0_Start_DMA

INT0_Check_E2:	; 020EB1h
	cp a, 0xE2
	jr nz, INT0_Check_E3
	ld (4330:16), 3	; E2 command - state 3
	lda xwa, (4380:16)	; E2 data buffer
	stda32 4324, xwa
	ldc_cr32 xwa, 0x20
	ldw wa, 0xA	; 10 bytes for E2
	ldc_cr16 wa, 0x40
	jr INT0_Start_DMA

INT0_Check_E3:	; 020ECEh
	cp a, 0xE3
	jr nz, INT0_Standard_Cmd
	setda 6, 1278	; E3 = payload ready
	jr INT0_Ack

INT0_Standard_Cmd:	; 020ED9h - standard variable-length command
	ld (4330:16), 1	; State 1
	lda xwa, (4336:16)	; Standard command buffer
	stda32 4324, xwa
	ldc_cr32 xwa, 0x20
	ld a, (4332:16)
	and a, 0x1F	; Bits 4-0 = length - 1
	inc 1, a	; Add 1 for actual length
	extz wa
	ldc_cr16 wa, 0x40

INT0_Start_DMA:	; 020EF7h
	ld (256:16), 10	; Start DMA channel 0

INT0_Ack:	; 020EFCh
	res_dd8 1, 0x34	; SSTAT1 - clear to acknowledge command received from Main CPU

INT0_Exit:	; 020EFFh
	pop xwa
	reti


;=============================================================================
; MICRODMA_CH2_HANDLER - MicroDMA Channel 2 Completion Interrupt
;=============================================================================
; Called when DMA channel 2 transfer completes (payload data transfers).
; Manages the DMA state machine for multi-phase transfers:
;   - State 2 (two-phase) -> State 1 (waiting for phase 2)
;   - State 1 (single xfer) -> State 0 (idle)
; Stops the 8-bit TIMER 2 that paces the DMA transfers.  (Not "Timer 8": T8RUN
; is SFR 0x80 (shared/sfr_tmp94c241.s), the RUN register FOR the four 8-bit
; timers T0..T3, and bit 2 is timer 2's run bit; the old name reads like a
; misparse of the register name.  A 16-bit Timer 8 does exist on this part, but
; it runs from T16RUN and is not what is stopped here.  Corroborated by
; InterCPU_DMA_Send_Chunk, which arms DMA2V = 22 = the INTT2 vector number
; before setting T8RUN bit 2.)
;=============================================================================
MICRODMA_CH2_HANDLER:	; Channel #2 completion		; 20F01
	res_dd8 2, 0x80
	cp (4328:16), 1
	jr nz, MICRODMA_CH2_State2
	ld (4328:16), 0
	jr MICRODMA_CH2_Done

MICRODMA_CH2_State2:	; 020F12h - two-phase transfer, go to state 1
	cp (4328:16), 2
	jr nz, MICRODMA_CH2_Done
	ld (4328:16), 1

MICRODMA_CH2_Done:	; 020F1Eh
	reti


;=============================================================================
; MICRODMA_CH0_HANDLER - MicroDMA Channel 0 Completion Interrupt
;=============================================================================
; Called when DMA channel 0 transfer completes (inter-CPU latch reads).
; This is the main command dispatcher - receives commands from main CPU
; and processes them based on CMD_PROCESSING_STATE:
;   State 1: Decode command byte (bits 7-5 = handler, bits 4-0 = length)
;   State 2: Process E1 command (two-phase transfer setup)
;   State 3: Process E2 command (transfer parameters)
;   State 4: Process E3 command (payload ready signal)
;=============================================================================
MICRODMA_CH0_HANDLER:	; 20F1Fh - Channel #0 completion (command dispatch)
	push xiz
	push xiy
	push xix
	push xhl
	push xde
	push xbc
	push xwa
	ld a, (4330:16)
	cps a, 4
	jr z, CH0_State4_E1_Done
	cps a, 3
	jr z, CH0_State3_E2
	cps a, 2
	jr z, CH0_State2_E1
	cps a, 1
	jr nz, CH0_Timer_Reset
	; State 1: Standard command processing
	pushw 0x0
	pushw 0x10F0	; Command buffer address
	ld c, (4332:16)
	ld a, c
	and a, 0x1F
	inc 1, a	; Length = (byte & 0x1F) + 1
	extz wa
	pushw wa
	srl c, 5	; The 3 highest bits from the byte received via maincpu latch
	             ; are used to select one of the 8 call-table entries
	ld a, c
	extz wa
	sla wa, 2	; Multiply by 4 (table entry size)
	lda xbc, (0x00f46c:24)
	ld_sril3 XWA, 0x07, 0xE4, 0xE0
	call (xwa)	; Dispatch to handler
	inc 6, xsp
	ld (4330:16), 0
	jr CH0_Ack

CH0_State2_E1:	; 020F6Dh - E1 command phase 1 complete, start phase 2
	lda xwa, (4374:16)	; E1 data buffer
	ld xbc, (xwa)	; Get DMA destination address
	ldc_cr32 xbc, 0x20
	ld wa, (xwa + 4)	; Get DMA byte count
	ldc_cr16 wa, 0x40
	ld (256:16), 10	; Start DMA
	ld (4330:16), 4	; Move to state 4
	jr CH0_Timer_Reset

CH0_State3_E2:	; 020F88h - E2 command complete
	ld (4334:16), 255
	ld (4330:16), 0
	set_dd8 1, 0x34	; SSTAT1 - set to signal ready for next command from Main CPU
	setda 7, 4390	; Set E2 pending flag
	jr CH0_Timer_Reset

CH0_State4_E1_Done:	; 020F9Bh - E1 two-phase transfer complete
	ld (4330:16), 0
	resda 7, 1278

CH0_Ack:	; 020FA4h
	set_dd8 1, 0x34	; SSTAT1 - set to signal E1 transfer complete, ready for next

CH0_Timer_Reset:	; 020FA7h - reset Timer 8 if running
	bit_dd8 2, 0x80
	jr z, CH0_Exit
	res_dd8 2, 0x80	; Stop timer
	nop
	nop
	set_dd8 2, 0x80	; Restart timer

CH0_Exit:	; 020FB4h
	pop xwa
	pop xbc
	pop xde
	pop xhl
	pop xix
	pop xiy
	pop xiz
	reti

; ----------------------------------------------------------------------------
; Cmd_Check_E2_Pending - Check and process pending E2 command
; Entry: None
; Exit:  E2 data processed if pending flag set
; Notes: Called from main loop to handle deferred E2 processing
; ----------------------------------------------------------------------------
Cmd_Check_E2_Pending:	; 020FBCh
	ei 6
	lda xwa, (4390:16)
	bitm 7, (xwa)	; Check E2 pending flag
	jr z, Cmd_Check_DMA_Timeout
	resm 7, (xwa)	; Clear pending flag
	ei 0
	lda xde, (4380:16)	; E2 data buffer
	ld xwa, (xde)
	ld bc, (xde + 8)
	ld xde, (xde + 4)
	calr InterCPU_E1_DMA_Transfer	; Process E2 data

; Check for DMA timeout (stuck transfer detection)
Cmd_Check_DMA_Timeout:	; 020FD9h
	ei 0
	bit_dd8 1, 0x34	; SSTAT1 - test own status: if set, no DMA transfer in progress
	jr nz, Cmd_DMA_Idle
	ldc_16_cr wa, 0x40	; Get current DMA byte count
	cpdm16 61468, xwa	; Compare with previous
	jr nz, Cmd_DMA_Reset_Counter
	incdi16 1, 61466	; Increment stuck counter
	jr Cmd_DMA_Save_Count

Cmd_DMA_Reset_Counter:	; 020FEFh
	stdi16 61466, 0	; Reset stuck counter

Cmd_DMA_Save_Count:	; 020FF5h
	ld (61468:16), wa	; Save current count
	jr Cmd_DMA_Check_Stuck

Cmd_DMA_Idle:	; 020FFBh
	stdi16 61466, 0

Cmd_DMA_Check_Stuck:	; 021001h
	ld wa, (61466:16)
	cp wa, 0xA	; Stuck for 10 iterations?
	ret ule
	; Timeout recovery - abort stuck DMA
	stdi16 61466, 0
	ld (256:16), 0	; Stop DMA
	ld (4330:16), 0
	set_dd8 1, 0x34	; SSTAT1 - timeout recovery: force ready state after DMA abort
	incdi8 1, 61464	; Increment error counter
	ret

; ===========================================================================
; ToneGen_Read_Register - Read one tone-generator register
; ===========================================================================
; (Was DAC_Write_Sample.  Nothing here writes a sample: 0x100000 is the tone
;  generator's register-ADDRESS latch on write and its status word on read --
;  see subcpu_mem in MAME's kn5000.cpp.)
; Entry: WA = TG register number to latch.
; Exit:  HL = the word read back for that register.
; Notes: clearing P6.7 (SFR 0x18 bit 7) drives A23 low, selecting the TG rather
;        than the keybed side of the multiplex.
;        Latch 0..3     -> HL = the 16-bit ACTIVE-VOICE BITMAP for that bank.
;        Latch 0x180+ch -> HL = that channel's envelope level.
;        This is the single point where the TG active-voice bitmap re-enters
;        sub-CPU software (caller: Voice_Manager_PollBank).
;        It is the only read of the REGISTER window in the whole payload: 139 writes to the
;        address latch 0x100000, 137 direct-addressing writes to the data port 0x100002
;        (which is never read at all), and this single `ldw_da`. Qualify the line above
;        accordingly: the same chip's other window (0x110000 / 0x110002, A23 high) is read
;        four times, by Keybed_Read_Event and ToneGen_Poll_Read, and ToneGen_Poll_Read
;        keeps its own per-voice on/off bitmap at 0x01F41C -- so this is the only path for
;        the bitmap the REGISTER FILE returns, not the only voice-state feedback there is.
;        No read anywhere returns a wave-ROM byte: IC304-IC307 hang off IC303 and are in no
;        CPU's address space, which is why the wave directory is [INFERENCE] walked by the
;        chip and not by this firmware. See "WHAT +0x040 SELECTS" near the 0x0451CC staging
;        block.
; ===========================================================================
ToneGen_Read_Register:
	res_dd8 7, 0x18
	stw_da 0x100000, xwa
	ld hl, (0x100000:24)
	ret

; MIDI_Backlog_Publish(WA = the MIDI ring's current byte count) -- was
; RingBuf_SetOffsetHi, which is not what it does: it stores the count to the word at
; 0x27E7, the MIDI BACKLOG GAUGE.  Sole caller: MIDI_Dispatch (0x034D93).  The value is
; read back only by RingBuf_CheckOffset_ClearFlags (0x02103B), which compares it against
; 0x20/0x30 (or 0x40/0x50 when the byte at 0x27E6 is zero) and drops layer slots 1..3 --
; i.e. it is a backpressure threshold that thins the polyphony when MIDI falls behind.
MIDI_Backlog_Publish:
	ld (10215:16), wa
	ret

RingBuf_SetOffsetLo:
	ld (10214:16), a
	ret

RingBuf_CheckOffset_ClearFlags:
	cp (10214:16), 0
	jr z, RingBuf_CheckOffset_LoZero
	cpdi16 10215, 48
	jr c, RingBuf_CheckOffset_Level1
	resm 7, (xwa + 3)
	resm 7, (xwa + 4)
	resm 7, (xwa + 5)
	ret

RingBuf_CheckOffset_Level1:
	cpdi16 10215, 32
	ret c
	resm 7, (xwa + 4)
	resm 7, (xwa + 5)
	ret

RingBuf_CheckOffset_LoZero:
	cpdi16 10215, 80
	jr c, RingBuf_CheckOffset_LoZero_Level1
	resm 7, (xwa + 3)
	resm 7, (xwa + 4)
	resm 7, (xwa + 5)
	ret

RingBuf_CheckOffset_LoZero_Level1:
	cpdi16 10215, 64
	ret c
	resm 7, (xwa + 4)
	resm 7, (xwa + 5)
	ret

Quad_Decode_A_To_L:
	cp a, 0x40
	jr nc, Quad_Decode_Quarter2
	ldb l, 0x0
	jr Quad_Decode_Return

Quad_Decode_Quarter2:
	cp a, 0x80
	jr nc, Quad_Decode_Quarter3
	ldb l, 0x4
	jr Quad_Decode_Return

Quad_Decode_Quarter3:
	cp a, 0xC0
	jr nc, Quad_Decode_Quarter4
	ldb l, 0x8
	jr Quad_Decode_Return

Quad_Decode_Quarter4:
	ldb l, 0x0

Quad_Decode_Return:
	ret

ExtVoice_Fold_SlotNumber:
	and c, 0x3
	cps c, 3
	jr z, SlotPair_Decode_Case3
	cps c, 2
	jr z, SlotPair_Decode_Case2
	cps c, 1
	jr z, SlotPair_Decode_Case1
	cps c, 0
	ret nz

SlotPair_Decode_Case1:
	and a, 0x3F
	ld l, a
	jr SlotPair_Decode_Return

SlotPair_Decode_Case2:
	sub a, 0x40
	ld l, a
	res 7, l
	jr SlotPair_Decode_Return

SlotPair_Decode_Case3:
	ld l, a
	res 7, l

SlotPair_Decode_Return:
	ret

VoiceState_SwapSlot_DE_BC:
	ld e, c
	extz de
	ld ix, de
	ld e, a
	extz de
	muls de, 0xC
	lda xhl, (9446:16)
	exts xde
	add xde, xhl
	ld hl, ix
	extz xhl
	add xhl, xde
	ld b, (xhl)
