	extz de
	ld ix, de
	inc 4, ix
	ld e, a
	extz de
	muls de, 0xC
	lda xhl, (9446:16)
	exts xde
	add xde, xhl
	ld hl, ix
	extz xhl
	add xhl, xde
	ld w, (xhl)
	ld e, c
	extz de
	ld ix, de
