VoiceState_SwapSlot_Guarded:
	dec 8, xsp
	ld (xsp + 4), e
	ld (xsp + 6), c
	ld c, a
	extz bc
	muls bc, 0xC
	lda xde, (9446:16)
	exts xbc
	add xbc, xde
	ld (xsp), xbc
	ld c, (xsp + 6)
	extz bc
	ld de, bc
	inc 8, de
	ld xbc, (xsp)
	ldb_sri E, 0x07, 0xE4, 0xE8
	ld c, e
	cp c, 0xC0
	jr nc, VoiceState_SwapSlot_Guarded_WriteDst
	ld c, e
	extz bc
	muls bc, 0x5
	lda xde, (8486:16)
	lda_dri XIX, 0x07, 0xE8, 0xE4
	cp (xix + 4), a
	jr nz, VoiceState_SwapSlot_Guarded_WriteDst
	ld c, (xsp + 6)
	ld e, c
	extz de
	ld xbc, (xsp)
	cpb_sri_mr A, 0x07, 0xE4, 0xE8
	jr z, VoiceState_SwapSlot_Guarded_MarkInactive
	ld c, (xsp + 6)
	ld e, c
	extz de
	ld xbc, (xsp)
	ldb_sri C, 0x07, 0xE4, 0xE8
	ld (xix + 4), c
	jr VoiceState_SwapSlot_Guarded_WriteDst

VoiceState_SwapSlot_Guarded_MarkInactive:
	ld (xix + 4), 0xFF

VoiceState_SwapSlot_Guarded_WriteDst:
	ld c, (xsp + 4)
	extz bc
	muls bc, 0x5
	lda xde, (8486:16)
	lda_dri XIX, 0x07, 0xE8, 0xE4
	cp (xix + 4), 0x40
	jr ule, VoiceState_SwapSlot_Guarded_UseHL_IY
	ld (xix + 4), a
	ld e, a
	extz de
	ld a, (xsp + 6)
	ld c, a
	extz bc
	ld wa, de
	calr VoiceState_SwapSlot_DE_BC
	jr VoiceState_SwapSlot_Guarded_Return

VoiceState_SwapSlot_Guarded_UseHL_IY:
	ld l, a
	extz hl
	ld a, (xsp + 6)
	ld c, a
	extz bc
	ld a, (xix + 4)
	ld e, a
	extz de
	ld wa, hl
	calr VoiceState_SwapSlot_HL_IY

VoiceState_SwapSlot_Guarded_Return:
	ld a, (xsp + 6)
	extz wa
	ld de, wa
	inc 8, de
	ld xwa, (xsp)
	ld c, (xsp + 4)
	stb_dri C, 0x07, 0xE0, 0xE8
	inc 8, xsp
	ret

VoiceRow_FetchPair_WA_SP:
	ld c, a
	extz bc
	muls bc, 0x5
	lda xde, (8486:16)
	ldb_sri W, 0x07, 0xE8, 0xE4
	ld c, a
	extz bc
	muls bc, 0x5
	lda xde, (8487:16)
