VoiceSlot_UpdateNoteSource:
	dec 4, xsp
	push xiz
	ld (xsp + 4), e
	ld (xsp + 6), c
	ld c, a
	extz bc
	muls bc, 0x5
	lda xde, (8486:16)
	lda_dri XIZ, 0x07, 0xE8, 0xE4
	ld c, (xiz + 2)
	extz bc
	muls bc, 0x1B
	lda xde, (7757:16)
	lda_dri XHL, 0x07, 0xE8, 0xE4
	ld e, (xiz + 3)
	ld c, e
	extz bc
	cpb_sri_mr A, 0x07, 0xEC, 0xE4
	jr nz, VoiceSlot_UpdateNoteSource_WriteCurrent
	cp (xiz), a
	jr z, VoiceSlot_UpdateNoteSource_MarkInactive
	extz de
	ld c, (xiz)
	stb_dri C, 0x07, 0xEC, 0xE8
	jr VoiceSlot_UpdateNoteSource_WriteCurrent

VoiceSlot_UpdateNoteSource_MarkInactive:
	ld c, e
	extz bc
	stib_ind 0x07, 0xEC, 0xE4, 0xFF

VoiceSlot_UpdateNoteSource_WriteCurrent:
	ld c, (xsp + 6)
	extz bc
	muls bc, 0x1B
	lda xde, (7757:16)
	lda_dri XHL, 0x07, 0xE8, 0xE4
	ld c, (xsp + 4)
	extz bc
	cpib_sri 0x07, 0xEC, 0xE4, 0xC0
	jr ule, VoiceSlot_UpdateNoteSource_UseDE_WA
	ld c, (xsp + 4)
	extz bc
	stb_dri A, 0x07, 0xEC, 0xE4
	extz wa
	calr VoiceRow_FetchPair_WA_SP
	jr VoiceSlot_UpdateNoteSource_Return

VoiceSlot_UpdateNoteSource_UseDE_WA:
	ld e, a
	extz de
	ld a, (xsp + 4)
	extz wa
	ldb_sri A, 0x07, 0xEC, 0xE0
	ld c, a
	extz bc
	ld wa, de
	calr VoiceRow_FetchPair_DE_WA

VoiceSlot_UpdateNoteSource_Return:
	ld a, (xsp + 6)
	ld (xiz + 2), a
	ld a, (xsp + 4)
	ld (xiz + 3), a
	pop xiz
	inc 4, xsp
	ret

Voice_ScanSlots_ReassignSources:
	dec 6, xsp
	push xiz
	ld (xsp + 8), a
	ld a, (xsp + 8)
	extz wa
	muls wa, 0xC
	lda xbc, (9446:16)
	exts xwa
	add xwa, xbc
	ld (xsp + 4), xwa
	ldib_erp 0xFB, 0
	cpib_erp 0xFB, 4
	jrl nc, Voice_ScanSlots_Return

Voice_ScanSlots_LoopBody:
	stb_erp A, 0xFB
	extz wa
	ld bc, wa
	inc 8, bc
	ld xwa, (xsp + 4)
	ldb_sri L, 0x07, 0xE0, 0xE4
	ld a, l
	cp a, 0xC0
	jrl nc, Voice_ScanSlots_LoopNext
	ld a, l
	extz wa
	muls wa, 0x5
	lda xbc, (8486:16)
	lda_dri XDE, 0x07, 0xE4, 0xE0
	ld a, (xde + 4)
	cp a, (xsp + 8)
	jr nz, Voice_ScanSlots_MarkSlotInactive
	stb_erp A, 0xFB
	ld c, a
	extz bc
	ld xwa, (xsp + 4)
	ldb_sri A, 0x07, 0xE0, 0xE4
	cp a, (xsp + 8)
	jr z, Voice_ScanSlots_PromoteSource
	stb_erp A, 0xFB
	ld c, a
	extz bc
	ld xwa, (xsp + 4)
	ldb_sri A, 0x07, 0xE0, 0xE4
	ld (xde + 4), a
	jr Voice_ScanSlots_MarkSlotInactive

Voice_ScanSlots_PromoteSource:
	ld (xde + 4), 0xFF
	ldb_erp L, 0xF8
	extz iz
	ld a, l
	extz wa
	calr Quad_Decode_A_To_L
	ld c, l
	extz bc
	ld wa, iz
	ld de, bc
	ldw bc, 0x1A
	calr VoiceSlot_UpdateNoteSource

Voice_ScanSlots_MarkSlotInactive:
	ld a, (xsp + 8)
	ld e, a
	extz de
	stb_erp A, 0xFB
	ld c, a
	extz bc
	ld wa, de
	calr VoiceState_SwapSlot_DE_BC
	stb_erp A, 0xFB
	extz wa
	ld bc, wa
	inc 8, bc
	ld xwa, (xsp + 4)
	stib_ind 0x07, 0xE0, 0xE4, 0xFF

Voice_ScanSlots_LoopNext:
	inc1b_erp 0xFB
	cpib_erp 0xFB, 4
	jrl c, Voice_ScanSlots_LoopBody

Voice_ScanSlots_Return:
	pop xiz
	inc 6, xsp
	ret

VoiceState_FullReset:
	push xiz
	ldib_erp 0xFB, 0
	cp_erpb 0xFB, 0x40
	jr nc, VoiceState_FullReset_Phase2

VoiceState_FullReset_Phase1_SlotLoop:
	ldb c, 0x0
	cps c, 4
	jr nc, VoiceState_FullReset_Phase1_Next

VoiceState_FullReset_Phase1_ColLoop:
	ld a, c
	extz wa
	ld hl, wa
	inc 8, hl
	stb_erp A, 0xFB
	extz wa
	muls wa, 0xC
	lda xde, (9446:16)
	exts xwa
	add xwa, xde
	ld de, hl
	extz xde
	add xde, xwa
	ld (xde), 0xFF
	ld a, c
	extz wa
	ld hl, wa
	stb_erp A, 0xFB
	extz wa
	muls wa, 0xC
	lda xde, (9446:16)
	exts xwa
	add xwa, xde
	ld de, hl
	extz xde
	add xde, xwa
	stb_erp A, 0xFB
	ld (xde), a
	ld a, c
	extz wa
	ld hl, wa
	inc 4, hl
	stb_erp A, 0xFB
	extz wa
	muls wa, 0xC
	lda xde, (9446:16)
	exts xwa
	add xwa, xde
	ld de, hl
	extz xde
	add xde, xwa
	stb_erp A, 0xFB
	ld (xde), a
	inc 1, c
	cps c, 4
	jr c, VoiceState_FullReset_Phase1_ColLoop

VoiceState_FullReset_Phase1_Next:
	inc1b_erp 0xFB
	cp_erpb 0xFB, 0x40
	jr c, VoiceState_FullReset_Phase1_SlotLoop

VoiceState_FullReset_Phase2:
	ldib_erp 0xFB, 0
	cp_erpb 0xFB, 0xC0
	jr nc, VoiceState_FullReset_Phase3

VoiceState_FullReset_Phase2_Body:
	stb_erp A, 0xFB
	extz wa
	muls wa, 0x5
	ld bc, wa
	lda xde, (8486:16)
	stb_erp A, 0xFB
	stb_dri A, 0x07, 0xE8, 0xE4
	stb_erp A, 0xFB
	extz wa
	muls wa, 0x5
	ld bc, wa
	lda xde, (8487:16)
	stb_erp A, 0xFB
	stb_dri A, 0x07, 0xE8, 0xE4
	stb_erp A, 0xFB
	extz wa
	muls wa, 0x5
	lda xbc, (8488:16)
	stib_ind 0x07, 0xE4, 0xE0, 0x00
	stb_erp A, 0xFB
	extz wa
	muls wa, 0x5
	lda xbc, (8489:16)
	stib_ind 0x07, 0xE4, 0xE0, 0x00
	stb_erp A, 0xFB
	extz wa
	muls wa, 0x5
	lda xbc, (8490:16)
	stib_ind 0x07, 0xE4, 0xE0, 0xFF
	inc1b_erp 0xFB
	cp_erpb 0xFB, 0xC0
	jr c, VoiceState_FullReset_Phase2_Body

VoiceState_FullReset_Phase3:
	ldib_erp 0xFB, 0
	cp_erpb 0xFB, 0x1B
	jr nc, VoiceState_FullReset_Phase3_InitSlots

VoiceState_FullReset_Phase3_ClearLoop:
	ldb c, 0x0
	cp c, 0x1B
	jr nc, VoiceState_FullReset_Phase3_ClearNext

VoiceState_FullReset_Phase3_ClearInner:
	ld a, c
	extz wa
	ld hl, wa
	stb_erp A, 0xFB
	extz wa
	muls wa, 0x1B
	lda xde, (7757:16)
	exts xwa
	add xwa, xde
	ld de, hl
	extz xde
	add xde, xwa
	ld (xde), 0xFF
	inc 1, c
	cp c, 0x1B
	jr c, VoiceState_FullReset_Phase3_ClearInner

VoiceState_FullReset_Phase3_ClearNext:
	inc1b_erp 0xFB
	cp_erpb 0xFB, 0x1B
	jr c, VoiceState_FullReset_Phase3_ClearLoop

VoiceState_FullReset_Phase3_InitSlots:
	ldib_erp 0xFB, 0
	cp_erpb 0xFB, 0xC0
	jr nc, VoiceState_FullReset_Phase3_Return

VoiceState_FullReset_Phase3_InitBody:
	stb_erp A, 0xFB
	ldb_erp A, 0xF8
	extz iz
	stb_erp A, 0xFB
	extz wa
	calr Quad_Decode_A_To_L
	ld c, l
	extz bc
	ld wa, iz
	ld de, bc
	ldw bc, 0x1A
	calr VoiceSlot_UpdateNoteSource
	inc1b_erp 0xFB
	cp_erpb 0xFB, 0xC0
	jr c, VoiceState_FullReset_Phase3_InitBody

VoiceState_FullReset_Phase3_Return:
	pop xiz
	ret

ExtVoice_Lookup_SlotFallback:
	lda xbc, (8459:16)
	and wa, 0x3
	cps wa, 3
	jr z, ExtVoice_Lookup_SlotFallback_Case3
	cps wa, 2
	jr z, ExtVoice_Lookup_SlotFallback_Case2
	cps wa, 1
	jr z, ExtVoice_Lookup_SlotFallback_Case1
	cps wa, 0
	ret nz
	ld l, (xbc)
	jr ExtVoice_Lookup_SlotFallback_Return

ExtVoice_Lookup_SlotFallback_Case1:
	ld l, (xbc + 4)
	jr ExtVoice_Lookup_SlotFallback_Return

ExtVoice_Lookup_SlotFallback_Case2:
	ld l, (xbc + 8)
	cp l, 0xC0
	ret ule
	ld l, (xbc + 4)
	jr ExtVoice_Lookup_SlotFallback_Return

ExtVoice_Lookup_SlotFallback_Case3:
	ld l, (xbc + 8)

ExtVoice_Lookup_SlotFallback_Return:
	ret

ExtVoice_Alloc_StreamSlot:
	dec 8, xsp
	pushw_erp 0xFA
	ld (xsp + 4), e
	ld (xsp + 6), c
	ld (xsp + 8), a
	andmi8 (xsp + 4), 0x3F
	cp (xsp + 6), 0x40
	jr nc, ExtVoice_Alloc_StreamSlot_NoMatch
	cp (xsp + 8), 0x1A
	jr c, ExtVoice_Alloc_StreamSlot_Search

ExtVoice_Alloc_StreamSlot_NoMatch:
	ld a, (xsp + 4)
	extz wa
	sll wa, 8
	ld hl, wa
	or hl, 0xFF
	jrl ExtVoice_Alloc_StreamSlot_Return

ExtVoice_Alloc_StreamSlot_Search:
	ld a, (xsp + 4)
	and a, 0x1F
	extz wa
	lda xbc, (0x00f48c:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	ldb_erp A, 0xFA
	ld a, (xsp + 4)
	extz wa
	lda xbc, (0x00f4ac:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	ld (xsp + 2), a
	ld a, (xsp + 6)
	extz wa
	muls wa, 0xC
	lda xbc, (9446:16)
	lda_dri XBC, 0x07, 0xE4, 0xE0
	stb_erp A, 0xFA
	extz wa
	inc 8, wa
	ldb_sri A, 0x07, 0xE4, 0xE0
	ldb_erp A, 0xFB
	cp_erpb 0xFB, 0xC0
	jr nc, ExtVoice_Alloc_StreamSlot_FallbackFB
	stb_erp A, 0xFB
	extz wa
	muls wa, 0x5
	lda xbc, (8486:16)
	lda_dri XBC, 0x07, 0xE4, 0xE0
	ld a, (xbc + 2)
	cp a, (xsp + 8)
	jr nz, ExtVoice_Alloc_StreamSlot_FallbackFB
	ld a, (xbc + 3)
	cp a, (xsp + 2)
	jr nz, ExtVoice_Alloc_StreamSlot_FallbackFB
	stb_erp A, 0xFB
	ld e, a
	extz de
	stb_erp A, 0xFA
	ld c, a
	extz bc
	ld wa, de
	calr ExtVoice_Fold_SlotNumber
	ld c, l
	extz bc
	ld a, (xsp + 4)
	set 7, a
	extz wa
	sll wa, 8
	ld hl, wa
	or hl, bc
	jrl ExtVoice_Alloc_StreamSlot_Return

ExtVoice_Alloc_StreamSlot_FallbackFB:
	bitm 5, (xsp + 4)
	jr z, ExtVoice_Alloc_StreamSlot_TryNoteSourceTable
	stb_erp A, 0xFA
	extz wa
	calr ExtVoice_Lookup_SlotFallback
	ldb_erp L, 0xFB
	stb_erp A, 0xFB
	cp a, 0xC0
	jr nc, ExtVoice_Alloc_StreamSlot_FallbackFB_Inactive
	stb_erp A, 0xFB
	ld l, a
	extz hl
	ld a, (xsp + 8)
	ld c, a
	extz bc
	ld a, (xsp + 2)
	ld e, a
	extz de
	ld wa, hl
	calr VoiceSlot_UpdateNoteSource
	ld a, (xsp + 6)
	ld l, a
	extz hl
	stb_erp A, 0xFA
	ld c, a
	extz bc
	stb_erp A, 0xFB
	ld e, a
	extz de
	ld wa, hl
	calr VoiceState_SwapSlot_Guarded
	stb_erp A, 0xFB
	ld e, a
	extz de
	stb_erp A, 0xFA
	ld c, a
	extz bc
	ld wa, de
	calr ExtVoice_Fold_SlotNumber
	jrl ExtVoice_Alloc_StreamSlot_PackResult

ExtVoice_Alloc_StreamSlot_FallbackFB_Inactive:
	ldb l, 0xFF
	jrl ExtVoice_Alloc_StreamSlot_PackResult

ExtVoice_Alloc_StreamSlot_TryNoteSourceTable:
	ld a, (xsp + 2)
	extz wa
	ld de, wa
	ld a, (xsp + 8)
	extz wa
	muls wa, 0x1B
	lda xbc, (7757:16)
	exts xwa
	add xwa, xbc
	ld bc, de
	extz xbc
	add xbc, xwa
	ld a, (xbc)
	ldb_erp A, 0xFB
	cp_erpb 0xFB, 0xC0
	jr nc, ExtVoice_Alloc_StreamSlot_FallbackFA
	ld a, (xsp + 6)
	ld l, a
	extz hl
	stb_erp A, 0xFA
	ld c, a
	extz bc
	stb_erp A, 0xFB
	ld e, a
	extz de
	ld wa, hl
	calr VoiceState_SwapSlot_Guarded
	stb_erp A, 0xFB
	ld e, a
	extz de
	stb_erp A, 0xFA
	ld c, a
	extz bc
	ld wa, de
	calr ExtVoice_Fold_SlotNumber
	setm 7, (xsp + 4)
	jr ExtVoice_Alloc_StreamSlot_PackResult

ExtVoice_Alloc_StreamSlot_FallbackFA:
	stb_erp A, 0xFA
	extz wa
	calr ExtVoice_Lookup_SlotFallback
	ldb_erp L, 0xFB
	stb_erp A, 0xFB
	cp a, 0xC0
	jr nc, ExtVoice_Alloc_StreamSlot_FA_Inactive
	stb_erp A, 0xFB
	ld l, a
	extz hl
	ld a, (xsp + 8)
	ld c, a
	extz bc
	ld a, (xsp + 2)
	ld e, a
	extz de
	ld wa, hl
	calr VoiceSlot_UpdateNoteSource
	ld a, (xsp + 6)
	ld l, a
	extz hl
	stb_erp A, 0xFA
	ld c, a
	extz bc
	stb_erp A, 0xFB
	ld e, a
	extz de
	ld wa, hl
	calr VoiceState_SwapSlot_Guarded
	stb_erp A, 0xFB
	ld e, a
	extz de
	stb_erp A, 0xFA
	ld c, a
	extz bc
	ld wa, de
	calr ExtVoice_Fold_SlotNumber
	jr ExtVoice_Alloc_StreamSlot_PackResult

ExtVoice_Alloc_StreamSlot_FA_Inactive:
	ldb l, 0xFF

ExtVoice_Alloc_StreamSlot_PackResult:
	ld c, l
	extz bc
	ld a, (xsp + 4)
	extz wa
	sll wa, 8
	ld hl, wa
	or hl, bc

ExtVoice_Alloc_StreamSlot_Return:
	popw_erp 0xFA
	inc 8, xsp
	ret

; Builds the packed 16-bit "part handle" the voice allocator passes around, and refreshes
; the slot table first when the part index is a real one.
; Inputs: C = part index (only the low 6 bits are used, saved in a 2-byte stack slot),
;         A = a selector. If A >= 0x40 the refresh is skipped; otherwise
;         Voice_ScanSlots_ReassignSources (0x02150D) is called with WA = A.
; Output: HL = ((C & 0x3F) << 8) | 0x00FF, i.e. part in the high byte and 0xFF ("no slot
;         yet") in the low byte.  Only caller: 0x0219BB.
VoiceState_OpaqueData1:
	.byte 0xef, 0x6a, 0xb7, 0x43, 0x87, 0x3c, 0x3f, 0xc9
	.byte 0xcf, 0x40, 0x67, 0x0f, 0x87, 0x21, 0xd8, 0x12
	.byte 0xd8, 0xee, 0x08, 0xd8, 0x8b, 0xdb, 0xce, 0xff
	.byte 0x00, 0x68, 0x12, 0xd8, 0x12, 0x1e, 0x71, 0xfb
	.byte 0x87, 0x21, 0xd8, 0x12, 0xd8, 0xee, 0x08, 0xd8
	.byte 0x8b, 0xdb, 0xce, 0xff, 0x00, 0xef, 0x62, 0x0e
; Stack-argument front end that turns a (part, selector, key) triple into an assigned voice
; slot: saves C and A in a local frame, calls VOICE_PART_HANDLE_MAKE (0x02197C) with
; C = E, then calls ExtVoice_Alloc_StreamSlot (0x02177E) with WA = the saved A, C = the saved C and
; E = the caller's argument at (XSP+8). Returns with 'retd 2', i.e. it pops one word of
; caller-pushed argument. No caller found by branch-target scan (candidate for a call
; through one of the dispatch tables).
Voice_Part_Assign:
	dec	4, xsp
	ld	(xsp), c
	ld	(xsp+2), a
	ld	a, (xsp)
	extz	wa
	ld	c, e
	extz	bc
	calr	65470
	ld	a, (xsp+2)
	ld	l, a
	extz	hl
	ld	a, (xsp)
	ld	c, a
	extz	bc
	ld	a, (xsp+8)
	ld	e, a
	extz	de
	ld	wa, hl
	calr	64935
	inc	4, xsp
	retd	2
; Builds a 0xFFFF-terminated word list at 0x00286B describing the up-to-four sounding
; sub-slots of one tone entry.
; Inputs: A = tone/part row index, C = a group id, E = a group mask (the routine keeps
;         ~E in its frame and matches (table_byte & ~E) against (C & ~E)).
; Walks i = 0..3 over the bytes at (0x0024E6 + 12*A + 8 + i). A byte >= 0xC0 means "slot
; unused" and is skipped. Otherwise the byte indexes a 5-byte-stride table at 0x002129,
; whose first byte indexes VOICE_COMMANDINDEXTABLE (0x00F4EC); that result is the value
; matched against the group and is also the high byte of the emitted word. The low byte is
; whatever ExtVoice_Fold_SlotNumber (0x0210A2) returns for (WA = the raw byte, BC = i).
; Output: XHL = 0x00286B (the list). No caller found by branch-target scan.
Voice_Build_PartSlot_List:
	.byte 0xbf, 0xf4, 0x37, 0xd7, 0xfa, 0x04, 0xcd, 0x06
	.byte 0xbf, 0x08, 0x45, 0x8f, 0x08, 0xc3, 0xbf, 0x06
	.byte 0x43, 0xd8, 0x12, 0xd8, 0x09, 0x0c, 0x00, 0xf1
	.byte 0xe6, 0x24, 0x31, 0xe8, 0x13, 0xe9, 0x80, 0xbf
	.byte 0x02, 0x60, 0xf1, 0x6b, 0x28, 0x30, 0xbf, 0x0a
	.byte 0x60, 0xc7, 0xfb, 0xa8, 0xc7, 0xfb, 0xdc, 0x6f
	.byte 0x6f, 0xc7, 0xfb, 0x89, 0xd8, 0x12, 0xd8, 0x89
	.byte 0xd9, 0x60, 0xaf, 0x02, 0x20, 0xc3, 0x07, 0xe0
	.byte 0xe4, 0x25, 0xcd, 0x89, 0xc9, 0xcf, 0xc0, 0x6f
	.byte 0x4f, 0xcd, 0x89, 0xd8, 0x12, 0xd8, 0x09, 0x05
	.byte 0x00, 0xf1, 0x29, 0x21, 0x31, 0xc3, 0x07, 0xe4
	.byte 0xe0, 0x21, 0xd8, 0x12, 0xf2, 0xec, 0xf4, 0x00
	.byte 0x31, 0xc3, 0x07, 0xe4, 0xe0, 0x21, 0xc7, 0xfa
	.byte 0x99, 0x8f, 0x08, 0xc1, 0x8f, 0x06, 0xf1, 0x6e
	.byte 0x27, 0xda, 0x12, 0xc7, 0xfb, 0x89, 0xc9, 0x8b
	.byte 0xd9, 0x12, 0xda, 0x88, 0x1e, 0x47, 0xf6, 0xcf
	.byte 0x8b, 0xd9, 0x12, 0xc7, 0xfa, 0x89, 0xd8, 0x12
	.byte 0xd8, 0xee, 0x08, 0xd8, 0x8a, 0xd9, 0xe2, 0xaf
	.byte 0x0a, 0x20, 0xf5, 0xe1, 0x52, 0xbf, 0x0a, 0x60
	.byte 0xc7, 0xfb, 0x61, 0xc7, 0xfb, 0xdc, 0x67, 0x91
	.byte 0xaf, 0x0a, 0x20, 0xb0, 0x02, 0xff, 0xff, 0xf1
	.byte 0x6b, 0x28, 0x33, 0xd7, 0xfa, 0x05, 0xbf, 0x0c
	.byte 0x37, 0x0e

Voice_BuildOutputList:
	lda xsp, (xsp - 12)
	pushw_erp 0xFA
	cpl e
	ld (xsp + 8), e
	and c, (xsp + 8)
	ld (xsp + 6), c
	extz wa
	muls wa, 0x1B
	lda xbc, (7757:16)
	exts xwa
	add xwa, xbc
	ld (xsp + 2), xwa
	lda xwa, (10217:16)
	ld (xsp + 10), xwa
	ldib_erp 0xFA, 0
	cp_erpb 0xFA, 0x1B
	jr nc, Voice_BuildOutputList_Return

Voice_BuildOutputList_Loop:
	stb_erp A, 0xFA
	ld c, a
	extz bc
	ld xwa, (xsp + 2)
	ldb_sri E, 0x07, 0xE0, 0xE4
	ld a, e
	cp a, 0xC0
	jr nc, Voice_BuildOutputList_Next
	stb_erp A, 0xFA
	extz wa
	lda xbc, (0x00f4ec:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	ldb_erp A, 0xFB
	and a, (xsp + 8)
	cp a, (xsp + 6)
	jr nz, Voice_BuildOutputList_Next
	stb_erp A, 0xFB
	and a, 0x1F
	extz wa
	lda xbc, (0x00f48c:24)
	ldb_sri C, 0x07, 0xE4, 0xE0
	ld a, e
	extz wa
	extz bc
	calr ExtVoice_Fold_SlotNumber
	ld c, l
	extz bc
	stb_erp A, 0xFB
	extz wa
	sll wa, 8
	ld de, wa
	or de, bc
	ld xwa, (xsp + 10)
	stw_dpi DE, 0xE1
	ld (xsp + 10), xwa

Voice_BuildOutputList_Next:
	inc1b_erp 0xFA
	cp_erpb 0xFA, 0x1B
	jr c, Voice_BuildOutputList_Loop

Voice_BuildOutputList_Return:
	ld xwa, (xsp + 10)
	ldw (xwa), 0xFFFF
	lda xhl, (10217:16)
	popw_erp 0xFA
	lda xsp, (xsp + 12)
	ret

; Builds a 0xFF-terminated byte list at 0x0028ED of the voice ids currently sounding for a
; part group. Inputs: A = row selector (row base = 0x001E4D + 27*A), C = group id,
; E = group mask (E is complemented and ANDed into C on entry, so the test is on the bits
; NOT in the mask). For each of the 27 part indices B: the row byte is skipped when >= 0xC0;
; VOICE_COMMANDINDEXTABLE[B] (0x00F4EC) must match the group; the row byte then indexes the
; 5-byte-stride table at 0x00212A to give a voice id, which must be < 0x40 to be emitted.
; After emitting, VOICE_POLYPHONYLIMITS_TABLE (0x00F48C) indexed by the command byte & 0x1F
; gives a stride used to chain forward through 0x0024E6 + 12*voice, emitting further ids
; until the chain byte repeats. Output: XHL = 0x0028ED.
; LOW confidence: the chain walk at 0x021BB7..0x021BE2 is understood mechanically but its
; purpose (layer chaining? unison? drum-map expansion?) is not proven. No caller found.
VoiceState_OpaqueData2:
	.byte 0x2e, 0xcd, 0x06, 0xcd, 0xc3, 0xd8, 0x12, 0xd8
	.byte 0x09, 0x1b, 0x00, 0xf1, 0x4d, 0x1e, 0x33, 0xf3
	.byte 0x07, 0xec, 0xe0, 0x34, 0xf1, 0xed, 0x28, 0x33
	.byte 0x22, 0x00, 0xca, 0xcf, 0x1b, 0x7f, 0x8d, 0x00
	.byte 0xca, 0x89, 0xd8, 0x12, 0xc3, 0x07, 0xf0, 0xe0
	.byte 0x21, 0xc7, 0xe2, 0x99, 0xc9, 0xcf, 0xc0, 0x6f
	.byte 0x74, 0xca, 0x89, 0xd8, 0x12, 0xf2, 0xec, 0xf4
	.byte 0x00, 0x35, 0xc3, 0x07, 0xf4, 0xe0, 0x24, 0xcc
	.byte 0x89, 0xcd, 0xc1, 0xcb, 0xf1, 0x6e, 0x5e, 0xc7
	.byte 0xe2, 0x89, 0xd8, 0x12, 0xd8, 0x09, 0x05, 0x00
	.byte 0xf1, 0x2a, 0x21, 0x35, 0xc3, 0x07, 0xf4, 0xe0
	.byte 0x21, 0xc7, 0xe6, 0x99, 0xc9, 0xcf, 0x40, 0x6f
	.byte 0x44, 0xc7, 0xe6, 0x89, 0xc7, 0xe2, 0x99, 0xcc
	.byte 0x89, 0xc9, 0xcc, 0x1f, 0xd8, 0x12, 0xf2, 0x8c
	.byte 0xf4, 0x00, 0x35, 0xc3, 0x07, 0xf4, 0xe0, 0x24
	.byte 0xc7, 0xe6, 0x89, 0xf5, 0xec, 0x41, 0xcc, 0x89
	.byte 0xd8, 0x12, 0xd8, 0x8e, 0xc7, 0xe2, 0x89, 0xd8
	.byte 0x12, 0xd8, 0x09, 0x0c, 0x00, 0xf1, 0xe6, 0x24
	.byte 0x35, 0xe8, 0x13, 0xed, 0x80, 0xde, 0x8d, 0xed
	.byte 0x12, 0xe8, 0x85, 0x85, 0x21, 0xc7, 0xe2, 0x99
	.byte 0xc7, 0xe6, 0xf1, 0x6e, 0xd3, 0xca, 0x61, 0xca
	.byte 0xcf, 0x1b, 0x77, 0x73, 0xff, 0xb3, 0x00, 0xff
	.byte 0xf1, 0xed, 0x28, 0x33, 0x4e, 0x0e

Voice_AdvanceSlotIterator:
	dec 2, xsp
	push xiz
