; PER-TICK TONE-GENERATOR VOICE POLL. Services ONE bank of 16 hardware voices per
; call and is the ONLY place in the firmware where a voice is handed back to the
; software free pool.
; Caller: Audio_Process_Init (0x034CDB) at 0x034CED, on alternate ticks only - that
; routine toggles the byte at 0x041342 with 'xor 0xFF' and only calls us when it is
; non-zero. With the internal bank counter this means each of the 4 banks is polled
; once every 8 ticks.
; State: byte (0x1128) = bank counter, inc'd then masked to 0..3 on entry.
;   word (0x292E + bank*2) = shadow copy of the previous poll's active-voice bitmap.
;   word (0x2936 + bank*2) = software 'held / do not reap' bitmap, set by
;                            Voice_Allocate_Nodes (0x02243D) and cleared by
;                            Voice_Clear_HoldBit (0x0225BB).
; Hardware: calls ToneGen_Read_Register (0x021023), which writes the TG register-address
;   latch at 0x100000 and reads the word back. Latch value
;   0..3 returns the 16-bit active-voice bitmap for that bank; latch 0x180+ch returns
;   that channel's envelope level.
; Edge detection (0x2219F..0x02220A):
;     new  = TG_bitmap | held_bitmap        ; 0x221C5
;     hits = (new ^ prev) & prev            ; 0x221E9 / 0x221F1
;     prev = new                            ; 0x22200
;   so 'hits' are exactly the voices that were marked active last poll and are now
;   reported silent by the TG and are not software-held. Only those get reaped.
; Per-voice loop (see Voice_Manager_PollBank_SlotLoop): voice index = bank*16 + i,
;   voice record = 0x148D + index*0x27 (39-byte records, 64 voices, 0x148D..0x1E4C).
; Exit: calls Voice_AdvanceSlotIterator (0x021BF5) with WA = bank.
; *** BUG-RELEVANT: if the tone generator never clears active bits (e.g. a sine-wave
; diagnostic renderer that has no end-of-sample / no auto-free), 'hits' is
; permanently zero, no voice is ever retired, and the free pool drains to empty. ***
Voice_Manager_PollBank:
	dec 6, xsp
	push xiz
	incdi8 1, 4392
	anddi8 4392, 3
	ld a, (4392:16)
	extz wa
	calr ToneGen_Read_Register
	ld a, (4392:16)
	extz wa
	add wa, wa
	lda xbc, (10550:16)
	ldw_sri DE, 0x07, 0xE4, 0xE0
	or de, hl
	ld a, (4392:16)
	extz wa
	ld hl, wa
	add hl, hl
	lda xix, (10542:16)
	ld a, (4392:16)
	extz wa
	add wa, wa
	lda xbc, (10542:16)
	ld (xsp + 4), de
	ldw_sri WA, 0x07, 0xE4, 0xE0
	xor (xsp + 4), wa
	ldw_sri WA, 0x07, 0xF0, 0xEC
	and (xsp + 4), wa
	ld a, (4392:16)
	extz wa
	add wa, wa
	lda xbc, (10542:16)
	stw_dri DE, 0x07, 0xE4, 0xE0
	ld a, (4392:16)
	sll a, 4
	ld (xsp + 8), a
	extz wa
	muls wa, 0x27
	lda xbc, (5261:16)
	lda_dri XIZ, 0x07, 0xE4, 0xE0
	ldw (xsp + 6), 0x1
	cpw (xsp + 6), 0x0
	jr z, Voice_Manager_PollBank_Return

; Loop over the 16 voices of the bank; (XSP+6) is a walking one-hot mask that doubles
; each pass and terminates when it shifts out of the word.
Voice_Manager_PollBank_SlotLoop:
	ld wa, (xsp + 4)
	and wa, (xsp + 6)
	jr z, Voice_Manager_PollBank_DecayCheck
	bitm 0, (xiz + 34)
	jr nz, Voice_Manager_PollBank_DecayCheck
	ld xwa, xiz
	calr Voice_Retire_ToFreePool
	ld a, (xsp + 8)
	extz wa
	call ToneGen_SilenceChannel
	ld a, (xsp + 8)
	extz wa
	calr Voice_ScanSlots_ReassignSources
	jr Voice_Manager_PollBank_Next

; Not a freshly-silent voice: skip entirely if flags (voice+0x22) & 0x81 (bit0 = in the
; free pool, bit7 = held/retrigger). Otherwise read the TG envelope level for this
; channel (latch 0x180+index), keep bits 13..0, >>5, store the low byte in (voice+0x25),
; and if it is < 0x80 and flag bit2 is set call Voice_Demote_Decayed (0x021E83).
Voice_Manager_PollBank_DecayCheck:
	ld a, (xiz + 34)
	and a, 0x81
	jr nz, Voice_Manager_PollBank_Next
	ld a, (xsp + 8)
	extz wa
	add wa, 0x180
	calr ToneGen_Read_Register
	and hl, 0x3FFF
	srl hl, 5
	ld a, l
	ld (xiz + 37), a
	cp (xiz + 37), 0x80
	jr nc, Voice_Manager_PollBank_Next
	bitm 2, (xiz + 34)
	jr z, Voice_Manager_PollBank_Next
	ld xwa, xiz
	calr Voice_Demote_Decayed

; Advance to the next voice: index++, record pointer += 0x27, mask <<= 1.
Voice_Manager_PollBank_Next:
	incm8 1, (xsp + 8)
	lda xiz, (xiz + 39)
	ld wa, (xsp + 6)
	add (xsp + 6), wa
	jr nz, Voice_Manager_PollBank_SlotLoop

; Tail: WA = bank, call Voice_AdvanceSlotIterator (0x021BF5), restore and return.
Voice_Manager_PollBank_Return:
	ld a, (4392:16)
	extz wa
	calr Voice_AdvanceSlotIterator
	pop xiz
	inc 6, xsp
	ret

; FREE-VOICE / CANDIDATE-NODE SEARCH, primary form.
; In:  XWA = pointer to the 12-byte part descriptor (array base 0x1349, stride 0x0C).
;      XBC = pointer to a 0xFF-terminated byte list of pool indices in priority order
;            (the ROM lists live at 0x00F60B / 0x00F61A / 0x00F628).
; Out: XHL = pointer to a voice node, or 0 if every listed pool is empty.
; Fast path: if the 32-bit global at 0x1345 is non-zero it is returned unconditionally
;   (a forced/override node).
; Walk: for each byte b of the list - if bit7 is set the pool head is read from the
;   global pointer array at 0x130F indexed by (b & 0x7F)*4, otherwise from the array
;   embedded in the part descriptor at (*XWA)+2 indexed by b*4. First non-null wins.
; Called only from Voice_Allocate_Nodes (0x0223CF).
; *** BUG-RELEVANT: this returning 0 is how 'stops allocating voices' manifests; it is
; silent - the caller just writes 0xFF into the slot and no error is reported. ***
Voice_Find_Candidate:
	ld xde, (4933:16)
	or xde, xde
	jr z, Voice_Find_Candidate_Walk
	ld xhl, (4933:16)
	ret

; Set up the walk: XDE = 0x112D+0x1E2 = 0x130F (global pool-head array), XHL = local array at (*XWA)+2, bail out immediately if the list is empty (first byte 0xFF).
Voice_Find_Candidate_Walk:
	lda xde, (4397:16)
	lda_dri XDE, 0xE9, 0xE2, 0x01
	ld xwa, (xwa)
	lda xhl, (xwa + 2)
	cp (xbc), 0xFF
	jr z, NoteChain_FindNode_NotFound

; List entry with bit7 set: look the pool head up in the GLOBAL array at 0x130F.
Voice_Find_Candidate_Secondary:
	bitm 7, (xbc)
	jr z, Voice_Find_Candidate_Primary
	ld a, (xbc)
	res 7, a
	ldb_erp A, 0xF0
	extz wa
	sla wa, 2
	ld_sril3 XWA, 0x07, 0xE8, 0xE0
	or xwa, xwa
	jr z, Voice_Find_Candidate_Advance
	stb_erp A, 0xF0
	extz wa
	sla wa, 2
	ld_sril3 XHL, 0x07, 0xE8, 0xE0
	ret

; List entry with bit7 clear: look the pool head up in the part-descriptor-local array.
Voice_Find_Candidate_Primary:
	ld a, (xbc)
	extz wa
	sla wa, 2
	ld_sril3 XWA, 0x07, 0xEC, 0xE0
	or xwa, xwa
	jr z, Voice_Find_Candidate_Advance
	ld a, (xbc)
	extz wa
	sla wa, 2
	ld_sril3 XHL, 0x07, 0xEC, 0xE0
	ret

; Pool was empty - advance to the next byte of the priority list, stop on 0xFF.
Voice_Find_Candidate_Advance:
	inc 1, xbc
	cp (xbc), 0xFF
	jr nz, Voice_Find_Candidate_Secondary

; Shared not-found exit: XHL = 0.
NoteChain_FindNode_NotFound:
	lds32 xhl, 0
	ret

; FREE-VOICE / CANDIDATE-NODE SEARCH, secondary form (voice stealing).
; In:  XWA = part descriptor; the local pool array is at XWA+2.
; Out: XHL = first non-empty pool head, or 0.
; Uses the fixed ROM priority list at 0x00F603 (06 05 02 04 03 01 00 FF) and, unlike
; Voice_Find_Candidate, has no bit7 escape to the global array and no 0x1345 override.
; Called from Voice_Allocate_Nodes_WalkNext (0x0224DF) when the part is already at its
; polyphony limit, i.e. this is the steal-a-voice search.
NoteChain_FindNode_B:
	inc 2, xwa
	ld xde, xwa
	lda xwa, (0x00f603:24)
	ld xbc, xwa
	cp (xbc), 0xFF
	jr z, NoteChain_FindNode_B_NotFound

; Walk the 0x00F603 list, returning the first non-null local pool head.
NoteChain_FindNode_B_Walk:
	ld a, (xbc)
	extz wa
	sla wa, 2
	ld_sril3 XWA, 0x07, 0xE8, 0xE0
	or xwa, xwa
	jr z, NoteChain_FindNode_B_Advance
	ld a, (xbc)
	extz wa
	sla wa, 2
	ld_sril3 XHL, 0x07, 0xE8, 0xE0
	ret

; Advance to the next list byte, stop on the 0xFF terminator.
NoteChain_FindNode_B_Advance:
	inc 1, xbc
	cp (xbc), 0xFF
	jr nz, NoteChain_FindNode_B_Walk

; Not-found exit: XHL = 0.
NoteChain_FindNode_B_NotFound:
	lds32 xhl, 0
	ret

; NOTE-ON: ALLOCATE UP TO FOUR VOICE NODES FOR ONE NOTE EVENT.
; In: XWA = note-event record (kept in local (XSP+0x10)):
;       +0x00 word  bits 0..6  = MIDI note number
;                   bits 8..12 = part index, must be < 0x1A
;       +0x02..+0x05  one byte per layer slot: bit7 = slot enabled,
;                     bits 0..3 = index into the 6-byte ROM table at 0x00F633
;       +0x06 bit6  = 'continue chain' - if clear, the global chain head (0x1129) is
;                     reset to 0 first
;       +0x06..+0x09  per-slot bit7 = hold / retrigger flag
;       +0x0A..+0x0D  OUTPUT: allocated hardware voice index per slot, 0xFF = none
; Callers: 0x02BB66, 0x02C033, 0x02C349, 0x02C665, 0x02D034.
; Calls RingBuf_CheckOffset_ClearFlags (0x02103B) first, which clears the enable bit of
; slots 1..3 according to the polyphony/mode values at 0x27E6/0x27E7 - i.e. that is the
; layer limiter.
; Part descriptor = 0x1349 + part*0x0C. Each 0x00F633 entry is {u32 candidate-list ptr,
; u8 priority key, u8 node param}.
; *** BUG-RELEVANT: (voice+0x25) is forced to 0xFF here (0x0223FC) and the flag byte
; (voice+0x22) is set to 0x88 (held) or 0x08 (non-held) - bit2 is NOT set in either
; case. Voice_Manager_PollBank's envelope-based release path requires level < 0x80 AND
; bit2, and its 'and A,0x81' guard also skips anything with bit7 set. So a voice that
; the TG never reports silent has NO second escape route out of the pool. ***
Voice_Allocate_Nodes:
	lda xsp, (xsp - 16)
	push xiz
	ld (xsp + 16), xwa
	ld xwa, (xsp + 16)
	bitm 6, (xwa + 6)
	jr nz, Voice_Allocate_Nodes_SlotLoop
	lds32 xwa, 0
	stda32 4393, xwa

; Extract the part index (event word bits 8..12); >= 0x1A jumps to the all-slots-fail exit. Then run the layer limiter and compute the part descriptor pointer.
Voice_Allocate_Nodes_SlotLoop:
	ld xwa, (xsp + 16)
	ld wa, (xwa)
	and wa, 0x1F00
	srl wa, 8
	ldb_erp A, 0xFB
	cp_erpb 0xFB, 0x1A
	jrl nc, Voice_Allocate_Nodes_AllInactive
	ld xwa, (xsp + 16)
	calr RingBuf_CheckOffset_ClearFlags
	stb_erp A, 0xFB
	extz wa
	muls wa, 0xC
	lda xbc, (4937:16)
	exts xwa
	add xwa, xbc
	ld (xsp + 4), xwa
	ld (xsp + 12), 0x0
	cp (xsp + 12), 0x4
	jrl nc, Voice_Allocate_Nodes_Return

; Per-slot body (slot = 0..3): if the slot's enable bit7 is clear go mark it 0xFF; else fetch its 6-byte 0x00F633 entry and ask Voice_Find_Candidate for a node.
Voice_Allocate_Nodes_ProcessSlot:
	ld a, (xsp + 12)
	extz wa
	ld bc, wa
	inc 2, bc
	ld xwa, (xsp + 16)
	bit_dri 7, 0x07, 0xE0, 0xE4
	jrl z, Voice_Allocate_Nodes_SlotInactive
	ld a, (xsp + 12)
	extz wa
	ld bc, wa
	inc 2, bc
	ld xwa, (xsp + 16)
	ldb_sri A, 0x07, 0xE0, 0xE4
	and a, 0xF
	extz wa
	muls wa, 0x6
	lda xbc, (0x00f633:24)
	exts xwa
	add xwa, xbc
	ld (xsp + 8), xwa
	ld xbc, (xwa)
	ld xwa, (xsp + 4)
	calr Voice_Find_Candidate
	ld xiz, xhl
	ld xwa, xiz
	or xwa, xwa
	jrl z, Voice_Allocate_Nodes_SlotNoNode
	ld a, (xiz + 36)
	ld (xsp + 14), a
	ld xwa, (xiz + 29)
	cp (xwa + 1), 0x0
	jr z, Voice_Allocate_Nodes_ActivateNode
	ld xwa, (xiz + 29)
	decm8 1, (xwa + 1)

; Node obtained: (node+0x23) = note number, (node+0x25) = 0xFF (envelope max), (node+0x26) = entry byte +5; then branch on the slot's hold flag at event+6+slot.
Voice_Allocate_Nodes_ActivateNode:
	ld xwa, (xsp + 16)
	ld wa, (xwa)
	and wa, 0x7F
	ld (xiz + 35), a
	ld (xiz + 37), 0xFF
	ld xwa, (xsp + 8)
	ld a, (xwa + 5)
	ld (xiz + 38), a
	ld a, (xsp + 12)
	extz wa
	ld bc, wa
	inc 6, bc
	ld xwa, (xsp + 16)
	bit_dri 7, 0x07, 0xE0, 0xE4
	jr z, Voice_Allocate_Nodes_Retrigger
	ld (xiz + 34), 0x88
	ld a, (xsp + 14)
	and a, 0xF
	lds de, 1
	and a, 0xF
	jr z, Voice_Allocate_Nodes_RetriggerActive
	slla de

; Held/retrigger branch tail: OR this channel's bit into the 'held' bitmap (0x2936 + (chan>>4)*2) so Voice_Manager_PollBank will never reap it.
Voice_Allocate_Nodes_RetriggerActive:
	ld a, (xsp + 14)
	srl a, 4
	extz wa
	add wa, wa
	lda xbc, (10550:16)
	or_sriw_mr DE, 0x07, 0xE4, 0xE0
	jr Voice_Allocate_Nodes_UpdateLists

; Non-held branch: flags = 0x08, then clear this channel's bit in the held bitmap 0x2936 ...
Voice_Allocate_Nodes_Retrigger:
	ld (xiz + 34), 0x8
	ld a, (xsp + 14)
	and a, 0xF
	lds bc, 1
	and a, 0xF
	jr z, Voice_Allocate_Nodes_RetriggerMask
	slla bc

; ... using the complement mask, and ...
Voice_Allocate_Nodes_RetriggerMask:
	ld wa, bc
	cpl wa
	ld de, wa
	ld a, (xsp + 14)
	srl a, 4
	extz wa
	add wa, wa
	lda xbc, (10550:16)
	and_sriw_mr DE, 0x07, 0xE4, 0xE0
	ld a, (xsp + 14)
	and a, 0xF
	lds de, 1
	and a, 0xF
	jr z, Voice_Allocate_Nodes_RetriggerOrMask
	slla de

; ... SET the bit in the shadow bitmap 0x292E so that the next poll sees a 1->0 transition once the TG finishes the note. This is what arms the reaper.
Voice_Allocate_Nodes_RetriggerOrMask:
	ld a, (xsp + 14)
	srl a, 4
	extz wa
	add wa, wa
	lda xbc, (10542:16)
	or_sriw_mr DE, 0x07, 0xE4, 0xE0

; Link the node into the part's priority list (Voice_List_MoveToPool, key = entry byte +4) and its secondary list, then splice it into the global note chain rooted at (0x1129).
Voice_Allocate_Nodes_UpdateLists:
	ld xwa, (xsp + 8)
	ld e, (xwa + 4)
	ld xwa, xiz
	ld xbc, (xsp + 4)
	ld xbc, (xbc)
	calr Voice_List_MoveToPool
	ld xwa, xiz
	ld xbc, (xsp + 4)
	lds de, 0
	calr Voice_List_MoveToPartList
	ld xwa, (4393:16)
	or xwa, xwa
	jr z, Voice_Allocate_Nodes_SetGlobalHead
	ld xwa, xiz
	ld xbc, (4393:16)
	calr DList_Relink_Adjacent_Offsets16
	jr Voice_Allocate_Nodes_AdvancePriority

; Global chain was empty: this node becomes the head (0x1129) and self-links.
Voice_Allocate_Nodes_SetGlobalHead:
	stda32 4393, xiz
	ld xwa, xiz
	calr DList_Unlink_SelfLink_Offsets16

; Polyphony accounting: part active count is (part_desc+1), limit is (part_desc+0); if below the limit just increment it.
Voice_Allocate_Nodes_AdvancePriority:
	ld xwa, (xiz + 29)
	ld xbc, xwa
	ld a, (xwa + 1)
	cp a, (xbc)
	jr nc, Voice_Allocate_Nodes_WalkNext
	ld xwa, (xiz + 29)
	incm8 1, (xwa + 1)
	jr Voice_Allocate_Nodes_WriteSlot

; At the limit - steal: NoteChain_FindNode_B picks a victim node, it is re-keyed into the list at 0x130D with its own (node+0x21) key, the count is bumped and flag bit4 is set on it.
Voice_Allocate_Nodes_WalkNext:
	ld xwa, (xiz + 29)
	calr NoteChain_FindNode_B
	ld xiz, xhl
	ld xwa, xiz
	or xwa, xwa
	jr z, Voice_Allocate_Nodes_WriteSlot
	lda xwa, (4877:16)
	ld xbc, xwa
	ld a, (xiz + 33)
	ld e, a
	extz de
	ld xwa, xiz
	calr Voice_List_MoveToPool
	ld xwa, (xiz + 29)
	incm8 1, (xwa + 1)
	setm 4, (xiz + 34)

; Publish the result: Voice_ScanSlots_ReassignSources (0x02150D) for the channel, then event[0x0A+slot] = channel index.
Voice_Allocate_Nodes_WriteSlot:
	ld a, (xsp + 14)
	extz wa
	calr Voice_ScanSlots_ReassignSources
	ld a, (xsp + 12)
	extz wa
	ld de, wa
	add de, 0xA
	ld xwa, (xsp + 16)
	ld c, (xsp + 14)
	stb_dri C, 0x07, 0xE0, 0xE8
	jr Voice_Allocate_Nodes_SlotNext

; No node was available for this slot: event[0x0A+slot] = 0xFF.
Voice_Allocate_Nodes_SlotNoNode:
	ld a, (xsp + 12)
	extz wa
	ld bc, wa
	add bc, 0xA
	ld xwa, (xsp + 16)
	stib_ind 0x07, 0xE0, 0xE4, 0xFF
	jr Voice_Allocate_Nodes_SlotNext

; Slot was disabled: event[0x0A+slot] = 0xFF.
Voice_Allocate_Nodes_SlotInactive:
	ld a, (xsp + 12)
	extz wa
	ld bc, wa
	add bc, 0xA
	ld xwa, (xsp + 16)
	stib_ind 0x07, 0xE0, 0xE4, 0xFF

; Next slot; four slots per event.
Voice_Allocate_Nodes_SlotNext:
	incm8 1, (xsp + 12)
	cp (xsp + 12), 0x4
	jrl c, Voice_Allocate_Nodes_ProcessSlot
	jr Voice_Allocate_Nodes_Return

; Part index out of range (>= 0x1A): reject the whole event.
Voice_Allocate_Nodes_AllInactive:
	ld (xsp + 12), 0x0
	cp (xsp + 12), 0x4
	jr nc, Voice_Allocate_Nodes_Return

; Fill all four output bytes with 0xFF.
Voice_Allocate_Nodes_AllInactive_Loop:
	ld a, (xsp + 12)
	extz wa
	ld bc, wa
	add bc, 0xA
	ld xwa, (xsp + 16)
	stib_ind 0x07, 0xE0, 0xE4, 0xFF
	incm8 1, (xsp + 12)
	cp (xsp + 12), 0x4
	jr c, Voice_Allocate_Nodes_AllInactive_Loop

; Frame teardown and return.
Voice_Allocate_Nodes_Return:
	pop xiz
	lda xsp, (xsp + 16)
	ret

; RELEASE ONE HARDWARE VOICE (clear its 'held' state).
; In: A = hardware voice index 0..63.
; Clears bit7 of the byte at 0x14AF + index*0x27 (i.e. (voice_record+0x22) - the record
; base is 0x148D and 0x14AF = 0x148D+0x22), clears the channel's bit in the held bitmap
; at 0x2936 + (index>>4)*2, then TAIL-JUMPS into Voice_Reprioritise (0x021EA1)
; with XWA = the voice record.
; 12 call sites, all outside the region (0x026E94, 0x026FC6, 0x0270D1, 0x027AA2,
; 0x027B5D, 0x027B7E, 0x027C08, 0x027C29, 0x028EBB, 0x028F1C, 0x02CDCF, 0x02CE29).
; *** BUG-RELEVANT: this is the ONLY writer that clears a bit of the 0x2936 held
; bitmap. If the note-off path that calls it is bypassed, held voices are pinned
; active forever from Voice_Manager_PollBank's point of view. ***
Voice_Clear_HoldBit:
	ld c, a
	ld a, c
	extz wa
	muls wa, 0x27
	lda xde, (5295:16)
	res_dri 7, 0x07, 0xE8, 0xE0
	ld a, c
	and a, 0xF
	lds de, 1
	and a, 0xF
	jr z, Voice_Clear_HoldBit_ApplyMask
	slla de

; Build the complement of the channel's one-hot bit and AND it into the held bitmap word.
Voice_Clear_HoldBit_ApplyMask:
	ld wa, de
	cpl wa
	ld hl, wa
	ld a, c
	srl a, 4
	extz wa
	add wa, wa
	lda xde, (10550:16)
	and_sriw_mr HL, 0x07, 0xE8, 0xE0
	ld a, c
	extz wa
	muls wa, 0x27
	lda xbc, (5261:16)
	exts xwa
	add xwa, xbc
	jrl Voice_Reprioritise

; NOTE-OFF FOR ONE VOICE SLOT.
; In: A = hardware voice index; indices >= 0x40 are ignored.
; Voice record = 0x148D + index*0x27. Moves the node onto the list whose head is at
; (node+0x18) via Voice_List_MoveToPartList (DE=1), runs Voice_Reprioritise
; (0x021EA1) to start the release, and unlinks it from the 0x10/0x14 doubly-linked
; chain unless it is already self-linked.
; Single caller: 0x02C8D7.
VoiceSlot_NoteOff:
	push xiz
	cp a, 0x40
	jr nc, VoiceSlot_NoteOff_Return
	extz wa
	muls wa, 0x27
	lda xbc, (5261:16)
	lda_dri XIZ, 0x07, 0xE4, 0xE0
	ld xwa, xiz
	ld xbc, (xiz + 24)
	lds de, 1
	calr Voice_List_MoveToPartList
	ld xwa, xiz
	calr Voice_Reprioritise
	cp xiz, (xiz + 16)
	jr z, VoiceSlot_NoteOff_Return
	ld xwa, xiz
	calr DList_Unlink_SelfLink_Offsets16

; Common exit.
VoiceSlot_NoteOff_Return:
	pop xiz
	ret

; ENUMERATE A VOICE CHAIN INTO A BYTE BUFFER (non-destructive).
; In: XWA = pointer to the output cursor (a 32-bit pointer variable, auto-advanced),
;     XBC = chain head (0 = nothing to do), E = note number to match,
;     stacked word arg (XSP+0x04) = 'emit unconditionally' flag.
; Walks the chain through link (node+0x08) until it returns to the head, appending
; (node+0x24) - the hardware voice index - for every node whose (node+0x23) equals E
; (or for all nodes when the flag is non-zero). Terminates the buffer with 0xFF.
; 'retd 2' pops the stacked argument. Called only from NoteOn_RoutePacket.
OutputBuf_Flush_A:
	ld xhl, xbc
	or xhl, xhl
	jr z, OutputBuf_Flush_A_Done
	ld xiy, xhl

; Chain walk: emit unconditionally when the flag is set, otherwise only when (node+0x23) == E.
OutputBuf_Flush_A_Loop:
	cp (xsp + 4), 0x0
	jr nz, OutputBuf_Flush_A_Emit
	cp (xiy + 35), e
	jr nz, OutputBuf_Flush_A_Next

; Append (node+0x24) at the cursor and advance the cursor by one.
OutputBuf_Flush_A_Emit:
	ld xix, (xwa)
	ld c, (xiy + 36)
	ld (xix), c
	lds32 xbc, 1
	add (xwa), xbc

; Follow (node+0x08); stop when the walk wraps to the head.
OutputBuf_Flush_A_Next:
	ld xiy, (xiy + 8)
	cp xiy, xhl
	jr nz, OutputBuf_Flush_A_Loop

; Write the 0xFF terminator at the cursor and return.
OutputBuf_Flush_A_Done:
	ld xwa, (xwa)
	ld (xwa), 0xFF
	retd 0x2

; ENUMERATE A VOICE CHAIN INTO A BYTE BUFFER *AND RELEASE* EACH MATCH (destructive).
; Same interface as OutputBuf_Flush_A but for every match it first calls
; Voice_List_MoveToPartList (0x021D59, DE=1) and Voice_Reprioritise (0x021EA1)
; to put the voice into release, then appends (node+0x24) and unlinks the node from the
; 0x10/0x14 chain, resuming from the saved successor.
; This is the note-off enumerator; OutputBuf_Flush_A is the query-only one.
OutputBuf_Flush_B:
	dec 8, xsp
	push xiz
	ld (xsp + 8), xwa
	or xbc, xbc
	jr z, OutputBuf_Flush_B_Done
	ld xiz, xbc

; Chain walk with the same match rule as OutputBuf_Flush_A_Loop.
OutputBuf_Flush_B_Loop:
	cp (xsp + 16), 0x0
	jr nz, OutputBuf_Flush_B_Emit
	cp (xiz + 35), e
	jr nz, OutputBuf_Flush_B_Next

; Release the matched node, append its voice index, unlink it and continue from (node+0x10).
OutputBuf_Flush_B_Emit:
	ld xwa, xiz
	ld xbc, (xiz + 24)
	lds de, 1
	calr Voice_List_MoveToPartList
	ld xwa, xiz
	calr Voice_Reprioritise
	ld xwa, (xsp + 8)
	ld xbc, (xwa)
	ld a, (xiz + 36)
	ld (xbc), a
	ld xwa, (xsp + 8)
	lds32 xbc, 1
	add (xwa), xbc
	cp xiz, (xiz + 16)
	jr z, OutputBuf_Flush_B_Done
	ld xwa, (xiz + 16)
	ld (xsp + 4), xwa
	ld xwa, xiz
	calr DList_Unlink_SelfLink_Offsets16
	ld xiz, (xsp + 4)
	jr OutputBuf_Flush_B_Emit

; Follow (node+0x08); stop when the walk wraps to the head.
OutputBuf_Flush_B_Next:
	ld xiz, (xiz + 8)
	cp xiz, xbc
	jr nz, OutputBuf_Flush_B_Loop

; Write the 0xFF terminator at the cursor and return (retd 2).
OutputBuf_Flush_B_Done:
	ld xwa, (xsp + 8)
	ld xwa, (xwa)
	ld (xwa), 0xFF
	pop xiz
	inc 8, xsp
	retd 0x2

; ROUTE A NOTE-OFF / VOICE-QUERY PACKET AND RETURN THE AFFECTED VOICE LIST.
; In: XWA = packet:  +0x00 flag byte (bit7, bit6 select which chains to visit)
;                    +0x01 word: bits0..6 = note A, bits 8..12 = part index
;                    +0x03 word: bits0..6 = note B, bits 8..12 = broadcast selector
;                    +0x05.. = output buffer, filled with hardware voice indices and
;                              terminated by 0xFF
; If (packet+0x03) bits 8..12 are non-zero the request is a BROADCAST: every one of the
; 64 voice records at 0x148D whose flag bit0 is clear (i.e. not in the free pool) is
; listed. Otherwise the part index selects two descriptor arrays - 0x134D + part*0x0C
; and 0x1351 + part*0x0C - and flag bits 7/6 plus bit7 of each note word choose which
; of the two chains are walked and whether the destructive (Flush_B) or query-only
; (Flush_A) enumerator is used. Part indices >= 0x1A return an empty list.
; Six callers, all in 0x02CCCB..0x02CD69.
NoteOn_RoutePacket:
	lda xsp, (xsp - 16)
	push xiz
	ld bc, (xwa + 3)
	and bc, 0x7F
	ld (xsp + 14), c
	ld bc, (xwa + 1)
	and bc, 0x7F
	ld (xsp + 12), c
	lda xbc, (xwa + 5)
	ld (xsp + 16), xbc
	ld bc, (xwa + 3)
	and bc, 0x1F00
	jr z, NoteOn_RoutePacket_Targeted
	lda xiz, (5261:16)
	ldb e, 0x0
	cp e, 0x40
	jr nc, NoteOn_RoutePacket_BroadcastDone

; Broadcast body: list every voice record that is not in the free pool (flag bit0 clear).
NoteOn_RoutePacket_BroadcastLoop:
	bitm 0, (xiz + 34)
	jr nz, NoteOn_RoutePacket_BroadcastNext
	ld xbc, (xsp + 16)
	lds32 xwa, 1
	add (xsp + 16), xwa
	ld a, (xiz + 36)
	ld (xbc), a

; Next of the 64 records (stride 0x27).
NoteOn_RoutePacket_BroadcastNext:
	lda xiz, (xiz + 39)
	inc 1, e
	cp e, 0x40
	jr c, NoteOn_RoutePacket_BroadcastLoop

; Terminate the broadcast list with 0xFF.
NoteOn_RoutePacket_BroadcastDone:
	ld xwa, (xsp + 16)
	ld (xwa), 0xFF
	jrl NoteOn_RoutePacket_Return

; Targeted request: derive the two per-part descriptor pointers (0x134D / 0x1351 + part*0x0C) and validate part < 0x1A.
NoteOn_RoutePacket_Targeted:
	ld bc, (xwa + 1)
	and bc, 0x1F00
	srl bc, 8
	ld l, c
	extz bc
	muls bc, 0xC
	lda xde, (4941:16)
	exts xbc
	add xbc, xde
	ld (xsp + 4), xbc
	ld c, l
	extz bc
	muls bc, 0xC
	lda xde, (4945:16)
	exts xbc
	add xbc, xde
	ld (xsp + 8), xbc
	cp l, 0x1A
	jrl nc, NoteOn_RoutePacket_InvalidChannel
	bitm 7, (xwa)
	jr z, NoteOn_RoutePacket_Targeted_SecondaryOnly
	ld wa, (xwa + 3)
	and wa, 0x7F
	jr z, NoteOn_RoutePacket_Targeted_NoteZero
	ld xwa, (xsp + 4)
	ld xwa, (xwa)
	or xwa, xwa
	jr z, NoteOn_RoutePacket_Targeted_Done
	ld xwa, (xsp + 4)
	ld xiz, (xwa)

; Destructive drain of the primary chain: repeat OutputBuf_Flush_B until the chain head goes null or stops changing.
NoteOn_RoutePacket_Targeted_Loop:
	ld a, (xsp + 12)
	ld e, a
	extz de
	ld a, (xsp + 14)
	extz wa
	pushw wa
	lda xwa, (xsp + 18)
	ld xbc, (xsp + 6)
	ld xbc, (xbc)
	calr OutputBuf_Flush_B
	ld xwa, (xsp + 4)
	ld xwa, (xwa)
	or xwa, xwa
	jr z, NoteOn_RoutePacket_Targeted_Done
	ld xwa, (xsp + 4)
	cp (xwa), xiz
	jr nz, NoteOn_RoutePacket_Targeted_Loop

; Terminate the output list with 0xFF.
NoteOn_RoutePacket_Targeted_Done:
	ld xwa, (xsp + 16)
	ld (xwa), 0xFF
	jrl NoteOn_RoutePacket_Return

; Note B is zero: single destructive pass matching note A instead.
NoteOn_RoutePacket_Targeted_NoteZero:
	ld a, (xsp + 12)
	ld e, a
	extz de
	ld a, (xsp + 14)
	extz wa
	pushw wa
	lda xwa, (xsp + 18)
	ld xbc, (xsp + 6)
	ld xbc, (xbc)
	calr OutputBuf_Flush_B
	jrl NoteOn_RoutePacket_Return

; Flag bit7 clear: query-only paths; bit6 selects the 0x1351 chain alone.
NoteOn_RoutePacket_Targeted_SecondaryOnly:
	bitm 6, (xwa)
	jr z, NoteOn_RoutePacket_Targeted_BothLists_BitB
	ld a, (xsp + 12)
	ld e, a
	extz de
	ld a, (xsp + 14)
	extz wa
	pushw wa
	lda xwa, (xsp + 18)
	ld xbc, (xsp + 10)
	ld xbc, (xbc)
	calr OutputBuf_Flush_A
	jr NoteOn_RoutePacket_Return

; Flags 7 and 6 both clear, note-B word bit7 set: query BOTH chains (0x134D then 0x1351).
NoteOn_RoutePacket_Targeted_BothLists_BitB:
	ld bc, (xwa + 3)
	bit 7, bc
	jr z, NoteOn_RoutePacket_Targeted_PrimaryOnly_BitA
	ld a, (xsp + 12)
	ld e, a
	extz de
	ld a, (xsp + 14)
	extz wa
	pushw wa
	lda xwa, (xsp + 18)
	ld xbc, (xsp + 6)
	ld xbc, (xbc)
	calr OutputBuf_Flush_A
	ld a, (xsp + 12)
	ld e, a
	extz de
	ld a, (xsp + 14)
	extz wa
	pushw wa
	lda xwa, (xsp + 18)
	ld xbc, (xsp + 10)
	ld xbc, (xbc)
	calr OutputBuf_Flush_A
	jr NoteOn_RoutePacket_Return

; Note-B bit7 clear but note-A bit7 set: query the 0x134D chain only.
NoteOn_RoutePacket_Targeted_PrimaryOnly_BitA:
	ld wa, (xwa + 1)
	bit 7, wa
	jr z, NoteOn_RoutePacket_Targeted_SecondaryOnly_B
	ld a, (xsp + 12)
	ld e, a
	extz de
	ld a, (xsp + 14)
	extz wa
	pushw wa
	lda xwa, (xsp + 18)
	ld xbc, (xsp + 6)
	ld xbc, (xbc)
	calr OutputBuf_Flush_A
	jr NoteOn_RoutePacket_Return

; Neither note word has bit7: query the 0x1351 chain only.
NoteOn_RoutePacket_Targeted_SecondaryOnly_B:
	ld a, (xsp + 12)
	ld e, a
	extz de
	ld a, (xsp + 14)
	extz wa
	pushw wa
	lda xwa, (xsp + 18)
	ld xbc, (xsp + 10)
	ld xbc, (xbc)
	calr OutputBuf_Flush_A
	jr NoteOn_RoutePacket_Return

; Part index >= 0x1A: emit an empty (0xFF-only) list.
NoteOn_RoutePacket_InvalidChannel:
	ld xwa, (xsp + 16)
	ld (xwa), 0xFF

; Frame teardown and return.
NoteOn_RoutePacket_Return:
	pop xiz
	lda xsp, (xsp + 16)
	ret

; QUANTISE A 7-BIT VELOCITY INTO ONE OF FOUR BANDS.
; In: A = velocity (bit7 forced clear), XBC = pointer to three ascending threshold
; bytes. Out: L = 0..3, the first band whose threshold is >= the velocity.
; Single caller 0x02B76D. Byte-for-byte identical to Velocity_Select_Split_Zone_Alt.
Velocity_Select_Split_Zone:
	res 7, a
	cp a, (xbc)
	jr ule, Velocity_Select_Split_Zone_Level0
	cp a, (xbc + 1)
	jr ule, Velocity_Select_Split_Zone_Level1
	cp a, (xbc + 2)
	jr ule, Velocity_Select_Split_Zone_Level2
	ldb l, 0x3
	jr Velocity_Select_Split_Zone_Return

; Third band: L = 2.
Velocity_Select_Split_Zone_Level2:
	ldb l, 0x2
	jr Velocity_Select_Split_Zone_Return

; Second band: L = 1.
Velocity_Select_Split_Zone_Level1:
	ldb l, 0x1
	jr Velocity_Select_Split_Zone_Return

; Lowest band: L = 0.
Velocity_Select_Split_Zone_Level0:
	ldb l, 0x0

; Return.
Velocity_Select_Split_Zone_Return:
	ret

; Second, identical copy of Velocity_Select_Split_Zone (same code, same semantics).
; Callers 0x02B617, 0x02C1B2, 0x02C520. The duplication is in the original ROM.
Velocity_Select_Split_Zone_Alt:
	res 7, a
	cp a, (xbc)
	jr ule, Velocity_Select_Split_Zone_Alt_Level0
	cp a, (xbc + 1)
	jr ule, Velocity_Select_Split_Zone_Alt_Level1
	cp a, (xbc + 2)
	jr ule, Velocity_Select_Split_Zone_Alt_Level2
	ldb l, 0x3
	jr Velocity_Select_Split_Zone_Alt_Return

; Third band: L = 2.
Velocity_Select_Split_Zone_Alt_Level2:
	ldb l, 0x2
	jr Velocity_Select_Split_Zone_Alt_Return

; Second band: L = 1.
Velocity_Select_Split_Zone_Alt_Level1:
	ldb l, 0x1
	jr Velocity_Select_Split_Zone_Alt_Return

; Lowest band: L = 0.
Velocity_Select_Split_Zone_Alt_Level0:
	ldb l, 0x0

; Return.
Velocity_Select_Split_Zone_Alt_Return:
	ret

; DECODE A 2-BIT FIELD OUT OF THE 0x47-BYTE PER-VOICE PARAMETER RECORD.
; In: A = record index. Reads the first word of the record at 0x04308F + index*0x47,
; masks bits 6..7 and maps 0x00/0x40/0x80/0xC0 to L = 0/1/2/3; leaves L untouched for
; any other value (dead case). No caller found by absolute or relative call scan.
; Held as raw .byte in the LLVM source, so its internal branch targets are unlabelled
; (see the four [LABEL] proposals at 0x022892..0x02289C).
VoiceDispatch_OpaqueData:
	.byte 0xd8, 0x12, 0xd8, 0x09, 0x47, 0x00, 0xf2, 0x8f
	.byte 0x30, 0x04, 0x31, 0xd3, 0x07, 0xe4, 0xe0, 0x20
	.byte 0xd8, 0xcc, 0xc0, 0x00, 0xd8, 0xcf, 0xc0, 0x00
	.byte 0x66, 0x1c, 0xd8, 0xcf, 0x80, 0x00, 0x66, 0x12
	.byte 0xd8, 0xcf, 0x40, 0x00, 0x66, 0x08, 0xd8, 0xd8
	.byte 0xb0, 0xfe, 0x27, 0x00, 0x68, 0x0a
; Field value 0x40: L = 1. Inside a raw .byte blob in the LLVM source, hence unlabelled.
VoiceDispatch_Field_Is1:
	ldb	l, 1
	jr	6
; Field value 0x80: L = 2.
VoiceDispatch_Field_Is2:
	ldb	l, 2
	jr	2
; Field value 0xC0: L = 3.
VoiceDispatch_Field_Is3:
	.byte 0x27, 0x03
; Shared return of the 2-bit field decoder at 0x022864.
VoiceDispatch_OpaqueData_Return:
	.byte 0x0e

; COPY THE HIGH NIBBLE OF A PATCH'S BYTE +0x2A INTO THE PER-PART PROGRAM BYTE.
; In: A = part index. Record stride is 0x011F bytes throughout this family:
;   0x04136E + part*0x011F holds a 32-bit pointer to the patch parameter block;
;   (block+0x2A) high nibble is used as an index into the byte table at 0x011ACF;
;   the looked-up byte is stored at 0x0413D5 + part*0x011F.
; Called from Voice_Env_VelocityDispatch_Gate (0x0234CC).
Instrument_LookupProgram_HiNibble:
	ld c, a
	extz bc
	muls bc, 0x11F
	lda xde, (0x04136e:24)
	ld_sril3 XBC, 0x07, 0xE8, 0xE4
	ld c, (xbc + 42)
	and c, 0xF0
	srl c, 4
	extz wa
	muls wa, 0x11F
	ld de, wa
	lda xhl, (0x0413d5:24)
	ld a, c
	extz wa
	lda xbc, (0x011acf:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	stb_dri A, 0x07, 0xEC, 0xE8
	ret

; As Instrument_LookupProgram_HiNibble but takes the LOW nibble of (block+0x2A).
; Called from Voice_Env_Type2_Gate (0x02357E).
Instrument_LookupProgram_LoNibble:
	ld c, a
	extz bc
	muls bc, 0x11F
	lda xde, (0x04136e:24)
	ld_sril3 XBC, 0x07, 0xE8, 0xE4
	ld c, (xbc + 42)
	and c, 0xF
	extz wa
	muls wa, 0x11F
	ld de, wa
	lda xhl, (0x0413d5:24)
	ld a, c
	extz wa
	lda xbc, (0x011acf:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	stb_dri A, 0x07, 0xEC, 0xE8
	ret

; L = bit0 of A. One of four near-identical predicate helpers used by the velocity dispatchers.
BitTest_Bit0_L:
	bit 0, a
	jr z, BitTest_Bit0_L_Clear
	ldb l, 0x1
	ret

; Bit clear: L = 0.
BitTest_Bit0_L_Clear:
	ldb l, 0x0
	ret

; L = 1 only if bit1 of A is clear and bit0 is set; otherwise 0.
BitTest_Mode2_L:
	bit 1, a
	jr z, BitTest_Mode2_L_Bit1Clear
	ldb l, 0x0
	ret

; bit1 clear - fall through to the bit0 test.
BitTest_Mode2_L_Bit1Clear:
	bit 0, a
	jr z, BitTest_Mode2_L_AllClear
	ldb l, 0x1
	ret

; Both bits clear: L = 0.
BitTest_Mode2_L_AllClear:
	ldb l, 0x0
	ret

; Duplicate of BitTest_Bit0_L (identical code), used by the Type2 dispatcher.
BitTest_Bit0_L_v2:
	bit 0, a
	jr z, BitTest_Bit0_L_v2_Clear
	ldb l, 0x1
	ret

; Bit clear: L = 0.
BitTest_Bit0_L_v2_Clear:
	ldb l, 0x0
	ret

; Duplicate of BitTest_Mode2_L, used by the Type2 dispatcher.
BitTest_Mode2_L_v2:
	bit 1, a
	jr z, BitTest_Mode2_L_v2_Bit1Clear
	ldb l, 0x0
	ret

; bit1 clear - fall through to the bit0 test.
BitTest_Mode2_L_v2_Bit1Clear:
	bit 0, a
	jr z, BitTest_Mode2_L_v2_AllClear
	ldb l, 0x1
	ret

; Both bits clear: L = 0.
BitTest_Mode2_L_v2_AllClear:
	ldb l, 0x0
	ret

; PATCH TRANSPOSE / OCTAVE-SHIFT LOOKUP (returns a signed 8.8 semitone offset).
; In: WA = a selector byte, C = a patch byte. Out: XHL = offset, 0 when disabled.
; If bit1 of the global audio-mode word at 0x041343 is set the function returns 0,
; i.e. that bit is a global disable for this contribution.
; Otherwise WA-0x10 in 0..9 indexes the 10-entry u16 offset table at 0x00F693 whose
; values are added to 0x022982 to form the jump target; in v142 nine of the ten
; entries point at the 'return 0' stub and only selector 0x14 reaches the fallback.
; Fallback: (C & 0x0F) indexes the byte table at 0x011ACF, sign-extends and shifts
; left 8 (one semitone = 0x100). Called from Voice_Pitch_Compute (0x0235F1).
Pitch_Get_Patch_Octave_Shift:
	ld de, (0x041343:24)
	bit 1, de
	jr z, Pitch_Get_Patch_Octave_Shift_Dispatch
	lds hl, 0
	jr Pitch_Get_Patch_Octave_Shift_Return

; Range-check the selector and dispatch through the 0x00F693 offset table.
Pitch_Get_Patch_Octave_Shift_Dispatch:
	extz wa
	sub wa, 0x10
	cps wa, 0
	jr lt, Pitch_Get_Patch_Octave_Shift_Fallback
	cp wa, 0x9
	jr gt, Pitch_Get_Patch_Octave_Shift_Fallback
	add wa, wa
	lda xix, (0x00f693:24)
	ldw_sri WA, 0x07, 0xF0, 0xE0
	lda xix, (0x022982:24)
	jp_ind 8, 0x07, 0xF0, 0xE0

; Jump-table base AND the case body for offset 0: XHL = 0.
Pitch_Get_Patch_Octave_Shift_JumpTable:
	lds	hl, 0
	jr	22

; Fallback case: signed semitone from the 0x011ACF table, scaled to 8.8.
Pitch_Get_Patch_Octave_Shift_Fallback:
	and c, 0xF
	ld a, c
	extz wa
	lda xbc, (0x011acf:24)
	ldb_sri L, 0x07, 0xE4, 0xE0
	exts hl
	sla hl, 8

; Return.
Pitch_Get_Patch_Octave_Shift_Return:
	ret

; CLAMP A PITCH ACCUMULATOR INTO A KEY RANGE (saturating, no folding).
; In: WA = signed 16-bit pitch value, C = low key limit, E = high key limit.
; Out: XHL. Negative inputs are first saturated: values <= 0xC000 become 0x7FFF, the
; rest become 0. Then the result is clamped to [C*256+0x80, E*256+0x80], i.e. the key
; limits expressed in the same 8.8 units used everywhere in the pitch chain.
; Called from Voice_Pitch_ApplyFineTune_LegatoB (0x0237FB); also 0x02B431.
Pitch_Clamp_Into_Range:
	ld hl, wa
	bit 15, wa
	jr z, Pitch_Clamp_Into_Range_CompareLo
	cp hl, 0xC000
	jr le, Pitch_Clamp_Into_Range_Clamp7FFF
	lds hl, 0
	jr Pitch_Clamp_Into_Range_CompareLo

; Wrapped-negative case: clamp to 0x7FFF.
Pitch_Clamp_Into_Range_Clamp7FFF:
	ldw hl, 0x7FFF

; Low-limit comparison against C*256+0x80.
Pitch_Clamp_Into_Range_CompareLo:
	ld a, c
	extz wa
	sla wa, 8
	add wa, 0x80
	cp hl, wa
	jr ge, Pitch_Clamp_Into_Range_CompareHi
	ld a, c
	extz wa
	ld hl, wa
	sla hl, 8
	add hl, 0x80
	jr Pitch_Clamp_Into_Range_Return

; High-limit comparison against E*256+0x80.
Pitch_Clamp_Into_Range_CompareHi:
	ld a, e
	extz wa
	sla wa, 8
	add wa, 0x80
	cp hl, wa
	ret le
	ld a, e
	extz wa
	ld hl, wa
	sla hl, 8
	add hl, 0x80

; Return.
Pitch_Clamp_Into_Range_Return:
	ret

; FOLD A PITCH VALUE INTO A KEY RANGE BY WHOLE OCTAVES.
; In: WA = signed 16-bit pitch (8.8 semitones), C = low key limit, E = high key limit.
; Out: XHL. Adds or subtracts 0x0C00 (twelve semitones) until the value lies inside
; [C*256+0x80, E*256+0x80]. This is the transpose-into-range used when a sample zone
; cannot cover the played key. Callers: Voice_Pitch_ApplyFineTune (0x0237DA),
; Voice_Pitch_CopyBase (0x023841), 0x02B481.
Pitch_Fold_Octaves_Into_Range:
	ld hl, wa
	jr PitchBend_AlignLoop_CheckSign

; Value has wrapped negative: step by +/- one octave to recover.
PitchBend_AlignLoop_CheckWrapped:
	cp hl, 0xC000
	jr le, PitchBend_AlignLoop_SubStep
	add hl, 0xC00
	jr PitchBend_AlignLoop_CheckSign

; Subtract one octave.
PitchBend_AlignLoop_SubStep:
	sub hl, 0xC00

; Sign test that drives the recovery loop.
PitchBend_AlignLoop_CheckSign:
	ld wa, hl
	bit 15, wa
	jr nz, PitchBend_AlignLoop_CheckWrapped
	jr PitchBend_AlignLoop_LoCheck

; Add one octave (raising loop).
PitchBend_AlignLoop_AddStep:
	add hl, 0xC00

; Keep adding octaves while below the low limit.
PitchBend_AlignLoop_LoCheck:
	ld a, c
	extz wa
	sla wa, 8
	add wa, 0x80
	cp hl, wa
	jr lt, PitchBend_AlignLoop_AddStep
	jr PitchBend_AlignLoop_HiCheck

; Subtract one octave (lowering loop).
PitchBend_AlignLoop_SubFinal:
	sub hl, 0xC00

; Keep subtracting octaves while above the high limit.
PitchBend_AlignLoop_HiCheck:
	ld a, e
	extz wa
	sla wa, 8
	add wa, 0x80
	cp hl, wa
	jr gt, PitchBend_AlignLoop_SubFinal
	ret

; INDEX A BYTE TABLE BY THE TOP 7 BITS OF A WORD.
; In: XWA = table base, BC = word. Out: L = table[(BC & 0x7F00) >> 8] (arithmetic
; shift). Used by WaveSel_StageB_Build_Reg040 (0x023880) to turn the current pitch into
; a key-zone number.
WaveSel_KeyTable_Lookup:
	and bc, 0x7F00
	sra bc, 8
	ldb_sri L, 0x07, 0xE0, 0xE4
	ret

; EMIT A KEY-ZONE PARAMETER RECORD OF STRIDE 0x0F.
; In: XWA = voice work record, XBC = record table base, DE = zone index.
; Computes XBC += DE*0x0F, stores that pointer at (XWA+0x0F), ORs the type code 0x7000
; into the word at (XWA+0x01), copies the record's first word to the staging word at
; 0x0451CE and its word at +0x0D to 0x293E.
; One of six stride variants selected by WaveSel_StageB_Build_Reg040 from three flag
; bits of the zone descriptor.
WaveSel_Emit_ZoneRecord_S15:
	extz de
	muls de, 0xF
	lda_dri XBC, 0x07, 0xE4, 0xE8
	ld (xwa + 15), xbc
	ormi16 (xwa + 1), 0x7000
	ld wa, (xbc)
	stw_da 0x0451ce, xwa
	ld wa, (xbc + 13)
	ld (10558:16), wa
	ret

; EMIT A KEY-ZONE PARAMETER RECORD OF STRIDE 0x0C.
; In: XWA = voice work record, XBC = record table base, DE = zone index.
; Computes XBC += DE*0x0C, stores that pointer at (XWA+0x0F), ORs the type code 0x5000
; into the word at (XWA+0x01), copies the record's first word to the staging word at
; 0x0451CE and its word at +0x0A to 0x293E.
; One of six stride variants selected by WaveSel_StageB_Build_Reg040 from three flag
; bits of the zone descriptor.
WaveSel_Emit_ZoneRecord_S12:
	extz de
	muls de, 0xC
	lda_dri XBC, 0x07, 0xE4, 0xE8
	ld (xwa + 15), xbc
	ormi16 (xwa + 1), 0x5000
	ld wa, (xbc)
	stw_da 0x0451ce, xwa
	ld wa, (xbc + 10)
	ld (10558:16), wa
	ret

; EMIT A KEY-ZONE PARAMETER RECORD OF STRIDE 0x0D.
; In: XWA = voice work record, XBC = record table base, DE = zone index.
; Computes XBC += DE*0x0D, stores that pointer at (XWA+0x0F), ORs the type code 0x3000
; into the word at (XWA+0x01), copies the record's first word to the staging word at
; 0x0451CE and its word at none (0 is written) to 0x293E.
; One of six stride variants selected by WaveSel_StageB_Build_Reg040 from three flag
; bits of the zone descriptor.
WaveSel_Emit_ZoneRecord_S13:
	extz de
	muls de, 0xD
	lda_dri XBC, 0x07, 0xE4, 0xE8
	ld (xwa + 15), xbc
	ormi16 (xwa + 1), 0x3000
	ld wa, (xbc)
	stw_da 0x0451ce, xwa
	stdi16 10558, 0
	ret

; EMIT A KEY-ZONE PARAMETER RECORD OF STRIDE 0x0A.
; In: XWA = voice work record, XBC = record table base, DE = zone index.
; Computes XBC += DE*0x0A, stores that pointer at (XWA+0x0F), ORs the type code 0x1000
; into the word at (XWA+0x01), copies the record's first word to the staging word at
; 0x0451CE and its word at none (0 is written) to 0x293E.
; One of six stride variants selected by WaveSel_StageB_Build_Reg040 from three flag
; bits of the zone descriptor.
WaveSel_Emit_ZoneRecord_S10:
	extz de
	muls de, 0xA
	lda_dri XBC, 0x07, 0xE4, 0xE8
	ld (xwa + 15), xbc
	ormi16 (xwa + 1), 0x1000
	ld wa, (xbc)
	stw_da 0x0451ce, xwa
	stdi16 10558, 0
	ret

; EMIT A KEY-ZONE PARAMETER RECORD OF STRIDE 0x06.
; In: XWA = voice work record, XBC = record table base, DE = zone index.
; Computes XBC += DE*0x06, stores that pointer at (XWA+0x0F), ORs the type code 0x4000
; into the word at (XWA+0x01), copies the record's first word to the staging word at
; 0x0451CE and its word at +0x04 to 0x293E.
; One of six stride variants selected by WaveSel_StageB_Build_Reg040 from three flag
; bits of the zone descriptor.
WaveSel_Emit_ZoneRecord_S6:
	extz de
	muls de, 0x6
	lda_dri XBC, 0x07, 0xE4, 0xE8
	ld (xwa + 15), xbc
	ormi16 (xwa + 1), 0x4000
	ld wa, (xbc)
	stw_da 0x0451ce, xwa
	ld wa, (xbc + 4)
	ld (10558:16), wa
	ret

; EMIT A KEY-ZONE PARAMETER RECORD OF STRIDE 4 (index shifted left 2 instead of a
; multiply). Unlike the other five variants it writes NO type code into (XWA+0x01) and
; always zeroes 0x293E. This is the base/default zone format.
; ALL SIX VARIANTS ABOVE (S15, S12, S13, S10, S6 and this one) copy the zone record's word 0
; to 0x0451CE unchanged -- `ld wa, (xbc)` then `stw_da 0x0451ce, xwa`, no masking -- and
; that word IS the wave selector, (class << 12) | entry. [INFERENCE] it is resolved by IC303
; itself against the wave ROM's own per-page directory; no CPU here can read that ROM.
; The firmware never range-checks the entry and never dereferences it, but it does modify it
; downstream: WaveSel_StageB_Store_Reg040 doubles the top nibble when bit 2 of 0x041343 is
; set, and Voice_Init_Type1 adds (tick & 7) through Voice_Slot_ApplyPitchJitter. See
; "WHAT +0x040 SELECTS" in the staging-block header for the format and the open questions.
WaveSel_Emit_ZoneRecord_S4:
	extz de
	sla de, 2
	lda_dri XBC, 0x07, 0xE4, 0xE8
	ld (xwa + 15), xbc
	ld wa, (xbc)
	stw_da 0x0451ce, xwa
	stdi16 10558, 0
	ret

; SATURATE A SIGNED 16-BIT PITCH VALUE TO [0, 0x7FFF].
; In: WA. Out: WA and XHL. Values with bit15 set become 0x7FFF if <= 0xC000 (treated as
; a wrap of a large positive) and 0 otherwise. Used all over the pitch chain
; (0x02373A, 0x023A85, 0x023AC7) and from 0x02B431.
Pitch_Saturate_15bit:
	ld bc, wa
	bit 15, bc
	jr z, Pitch_Saturate_15bit_Return
	cp wa, 0xC000
	jr ule, Pitch_Saturate_15bit_Clamp7FFF
	lds wa, 0
	jr Pitch_Saturate_15bit_Return

; Wrapped-positive case: 0x7FFF.
Pitch_Saturate_15bit_Clamp7FFF:
	ldw wa, 0x7FFF

; Copy the result to XHL and return.
Pitch_Saturate_15bit_Return:
	ld hl, wa
	ret

; CLAMP WA INTO [DE, BC] (signed). Out: WA and XHL. Callers 0x03079E, 0x0307E9 and the
; level packer at 0x023C44 / 0x023C92 / 0x023CA2 / 0x023CB2 / 0x023CC0.
ClampS16_WA_To_DEBC:
	cp wa, bc
	jr le, ClampS16_WA_To_DEBC_CheckLo
	ld wa, bc
	jr ClampS16_WA_To_DEBC_Return

; Low-bound test against DE.
ClampS16_WA_To_DEBC_CheckLo:
	cp wa, de
	jr ge, ClampS16_WA_To_DEBC_Return
	ld wa, de

; Copy to XHL and return.
ClampS16_WA_To_DEBC_Return:
	ld hl, wa
	ret

; SCALE A SIGNED DEPTH BY A CURVE-TABLE COEFFICIENT.
; In: A = signed depth, C = curve index (bit7 forced clear), E = shift amount in its
; low nibble. Negative depths are re-mapped through the ROM byte table at 0x00FEE4
; before being negated; the coefficient itself comes from the ROM byte table at
; 0x00FF64 indexed by C. Out: XHL = (coeff * |depth|) >> (E & 0x0F).
; Called from Voice_Level_Triplet_ModByEnv (0x023B3D).
PitchBend_Scale:
	res 7, c
	cps a, 0
	jr ge, PitchBend_Scale_Multiply
	extz bc
	lda xhl, (0x00fee4:24)
	ldb_sri C, 0x07, 0xEC, 0xE4
	extz bc
	cpl a
	inc 1, a

; Signed multiply of the coefficient by the depth, then the optional right shift.
PitchBend_Scale_Multiply:
	ldb_erp A, 0xF0
	exts ix
	ld a, c
	extz wa
	lda xbc, (0x00ff64:24)
	ldb_sri L, 0x07, 0xE4, 0xE0
	exts hl
	ld wa, hl
	extpfx2 0xDC, 0x48
	ld hl, wa
	ld a, e
	and a, 0xF
	ret z
	sraa hl
	ret

; SYMMETRIC DETUNE CURVE LOOKUP.
; In: WA = signed amount. |WA| is clamped to 0x32 (50) and used to index the byte table
; at 0x0119C8; the result is negated again for negative inputs. Out: XHL.
; Called from the level packer (0x023C4D, 0x023CC9, 0x023CD2).
Detune_ScaleSymmetric:
	cps wa, 0
	jr ge, Detune_ScaleSymmetric_PosArm
	cpl wa
	inc 1, wa
	cp wa, 0x32
	jr le, Detune_ScaleSymmetric_NegArm
	ldw wa, 0x32

; Negative arm: table lookup then two's-complement negate.
Detune_ScaleSymmetric_NegArm:
	extz wa
	lda xbc, (0x0119c8:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	cpl wa
	inc 1, wa
	jr Detune_ScaleSymmetric_Return

; Positive arm: clamp to 0x32.
Detune_ScaleSymmetric_PosArm:
	cp wa, 0x32
	jr le, Detune_ScaleSymmetric_PosClamp
	ldw wa, 0x32

; Positive arm table lookup.
Detune_ScaleSymmetric_PosClamp:
	extz wa
	lda xbc, (0x0119c8:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa

; Copy to XHL and return.
Detune_ScaleSymmetric_Return:
	ld hl, wa
	ret

; Unsigned variant: XHL = byte table 0x0119C8 indexed directly by WA, no clamp, no sign handling.
Detune_ScaleUnsigned:
	extz wa
	lda xbc, (0x0119c8:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld hl, wa
	ret

; INTERPOLATE A PARAMETER BETWEEN TWO LIMITS AND SCALE BY A SIGNED DEPTH.
; In: WA = word whose bits 8..14 hold the control value, BC = baseline, E = low limit,
; two stacked args: (XSP+0x06) = high limit, (XSP+0x04) = signed depth.
; Out: XHL = ((clamp(ctrl, E, hi) - BC) * depth) >> 5. 'retd 4' pops both arguments.
; Called from Voice_Level_ApplyVelocityMod (0x023C36) and 0x023C83.
Pan_ScaleWithVelocity:
	and wa, 0x7F00
	srl wa, 8
	ld l, (xsp + 6)
	extz hl
	cp wa, hl
	jr ule, Pan_ScaleWithVelocity_ClampLo
	ld a, (xsp + 6)
	extz wa
	jr Pan_ScaleWithVelocity_Multiply

; Low-limit clamp against E.
Pan_ScaleWithVelocity_ClampLo:
	ld l, e
	extz hl
	cp wa, hl
	jr nc, Pan_ScaleWithVelocity_Multiply
	ld a, e
	extz wa

; Signed multiply by the stacked depth, then >> 5.
Pan_ScaleWithVelocity_Multiply:
	extz bc
	ld de, wa
	sub de, bc
	ld l, (xsp + 4)
	exts hl
	ld wa, hl
	extpfx2 0xDA, 0x48
	ld hl, wa
	sra hl, 5
	retd 0x4

; CLAMP A FILTER-CUTOFF VALUE TO [0, 0x78] (0..120). Out: WA and XHL.
; Called by TVF_Calc_Cutoff/_B and from 0x0306C4, 0x03070D, 0x030753.
TVF_Clamp_Cutoff:
	cp wa, 0x78
	jr le, TVF_Clamp_Cutoff_CheckLo
	ldw wa, 0x78
	jr TVF_Clamp_Cutoff_Return

; Low-bound test.
TVF_Clamp_Cutoff_CheckLo:
	cps wa, 0
	jr ge, TVF_Clamp_Cutoff_Return
	lds wa, 0

; Copy to XHL and return.
TVF_Clamp_Cutoff_Return:
	ld hl, wa
	ret

; COMPUTE A FILTER-CUTOFF CONTRIBUTION WITH KEY FOLLOW AND LEVEL SCALING.
; In: XWA = voice work record, BC = running accumulator, DE = key-follow depth,
;     stacked byte (XSP+0x04) = level-scaling depth. Out: XHL = value in 0..0x78.
; XIX = (XWA+0x17) = the patch parameter block.
; Key follow (when DE != 0): curve = (patch+0x36) >> 5 selects one of eight 128-byte
;   curves in the table at 0x011519; the key number (XWA+0x0C) & 0x7F indexes inside it;
;   the signed byte is multiplied by DE and added as (product >> 5).
; Level scaling (when the stacked depth != 0): the control value (XWA+0x08) bits 8..14
;   is clamped between (patch+0x3A) and (patch+0x3B), (patch+0x39) is subtracted, the
;   difference is multiplied by the depth and added as (product >> 5).
; Finally +0x18 of bias and TVF_Clamp_Cutoff. 'retd 2' pops the stacked argument.
; Called from all five filter builders at 0x023D42, 0x023E04, 0x023E76, 0x023F11,
; 0x023F80, 0x024002.
; See [UNCERTAIN]: this is a TVF (filter) computation, not portamento.
TVF_Calc_Cutoff:
	ld hl, de
	ld xix, (xwa + 23)
	cps hl, 0
	jr z, TVF_Calc_Cutoff_DepthScale
	ld e, (xix + 54)
	and e, 0xE0
	srl e, 5
	extz de
	ld iy, de
	sla iy, 7
	ld e, (xwa + 12)
	extz de
	and de, 0x7F
	extz xde
	lda_dri XDE, 0x07, 0xE8, 0xF4
	ld xiy, 0x11519
	add xiy, xde
	ld e, (xiy)
	ldb_erp E, 0xF4
	exts iy
	ld de, hl
	extpfx2 0xDD, 0x4A
	ld hl, de
	sra hl, 5
	add bc, hl

; Level-scaling stage: clamp (XWA+0x08) hi-byte between (patch+0x3A) and (patch+0x3B).
TVF_Calc_Cutoff_DepthScale:
	cp (xsp + 4), 0x0
	jr z, TVF_Calc_Cutoff_AddBaseline
	ld de, (xwa + 8)
	and de, 0x7F00
	srl de, 8
	ld a, (xix + 59)
	extz wa
	cp de, wa
	jr ule, TVF_Calc_Cutoff_ClampHi
	ld a, (xix + 59)
	ld e, a
	extz de
	jr TVF_Calc_Cutoff_Multiply

; Lower clamp arm against (patch+0x3A).
TVF_Calc_Cutoff_ClampHi:
	ld a, (xix + 58)
	extz wa
	cp de, wa
	jr nc, TVF_Calc_Cutoff_Multiply
	ld a, (xix + 58)
	ld e, a
	extz de

; Subtract the (patch+0x39) reference, multiply by the stacked depth, >> 5.
TVF_Calc_Cutoff_Multiply:
	ld a, (xix + 57)
	extz wa
	sub de, wa
	ld a, (xsp + 4)
	exts wa
	extpfx2 0xDA, 0x48
	sra wa, 5
	add bc, wa

; Add the +0x18 bias and clamp to 0..0x78.
TVF_Calc_Cutoff_AddBaseline:
	add bc, 0x18
	ld wa, bc
	calr TVF_Clamp_Cutoff
	retd 0x2

; SECOND CUTOFF CONTRIBUTION VARIANT - same shape as TVF_Calc_Cutoff but the
; key-follow depth comes from (patch+0x10) and the curve selector from (patch+0x0F),
; and there is no level-scaling stage and no stacked argument. Ends with the same +0x18
; bias and TVF_Clamp_Cutoff (reached by tail jump). No in-ROM caller was found by a
; call/calr scan, so it may be reachable only through a table this pass did not decode.
TVF_Calc_Cutoff_NoKeyFollow:
	ld xix, (xwa + 23)
	ld e, (xix + 16)
	ld l, e
	exts hl
	cps hl, 0
	jr z, TVF_Calc_Cutoff_NoKeyFollow_AddBaseline
	ld e, (xix + 15)
	and e, 0xE0
	srl e, 5
	extz de
	sla de, 7
	ld a, (xwa + 12)
	extz wa
	and wa, 0x7F
	extz xwa
	lda_dri XWA, 0x07, 0xE0, 0xE8
	ld xde, 0x11519
	add xde, xwa
	ld a, (xde)
	ld e, a
	exts de
	ld wa, hl
	extpfx2 0xDA, 0x48
	ld hl, wa
	sra hl, 5
	ld wa, hl
	add bc, wa

; Add the +0x18 bias and tail-jump into TVF_Clamp_Cutoff.
TVF_Calc_Cutoff_NoKeyFollow_AddBaseline:
	add bc, 0x18
	ld wa, bc
	jrl TVF_Clamp_Cutoff

; Add the +0x18 bias to WA and clamp the result to at most 0x78 (no lower clamp).
; Out: WA and XHL. Used by the filter builders for the second register field.
TVF_Bias_Clamp_Amount:
	add wa, 0x18
	cp wa, 0x78
	jr le, TVF_Bias_Clamp_Amount_Return
	ldw wa, 0x78

; Copy to XHL and return.
TVF_Bias_Clamp_Amount_Return:
	ld hl, wa
	ret

; LOOK UP A THREE-BYTE FILTER COEFFICIENT RECORD.
; In: A - low nibble selects the record, bit7 selects the table:
;     bit7 set   -> records at 0x011A25 (byte0), 0x011A26 (byte1), 0x011A27 (byte2)
;     bit7 clear -> records at 0x0119FB / 0x0119FC / 0x0119FD
;   (three parallel byte arrays with a stride of 3, i.e. one 3-byte record per index).
; Out: XHL = (byte1 << 8) | byte0-in-IX; byte2 is sign-extended into the global word at
; 0x2940. Called from the filter builders at 0x023D7C, 0x023DA2, 0x023E33, 0x023EAF,
; 0x023F3D.
TVF_Lookup_Depth_Amount:
	ld c, a
	and c, 0xF
	ld e, c
	extz de
	bit 7, a
	jr z, TVF_Lookup_Depth_Amount_SetA
	ld wa, de
	extz xwa
	ld xbc, xwa
	add xbc, xbc
	add xbc, xwa
	lda xwa, (0x011a26:24)
	add xwa, xbc
	ld a, (xwa)
	ld l, a
	extz hl
	sll hl, 8
	ld wa, de
	extz xwa
	ld xbc, xwa
	add xbc, xbc
	add xbc, xwa
	ld xwa, 0x11A25
	add xwa, xbc
	ld a, (xwa)
	ldb_erp A, 0xF0
	extz ix
	ld wa, de
	extz xwa
	ld xbc, xwa
	add xbc, xbc
	add xbc, xwa
	lda xwa, (0x011a27:24)
	add xwa, xbc
	ld a, (xwa)
	exts wa
	ld (10560:16), wa
	jr TVF_Lookup_Depth_Amount_Return

; bit7-clear arm: use the 0x0119FB/FC/FD record set.
TVF_Lookup_Depth_Amount_SetA:
	ld wa, de
	extz xwa
	ld xbc, xwa
	add xbc, xbc
	add xbc, xwa
	lda xwa, (0x0119fc:24)
	add xwa, xbc
	ld a, (xwa)
	ld l, a
	extz hl
	sll hl, 8
	ld wa, de
	extz xwa
	ld xbc, xwa
	add xbc, xbc
	add xbc, xwa
	ld xwa, 0x119FB
	add xwa, xbc
	ld a, (xwa)
	ldb_erp A, 0xF0
	extz ix
	ld wa, de
	extz xwa
	ld xbc, xwa
	add xbc, xbc
	add xbc, xwa
	lda xwa, (0x0119fd:24)
	add xwa, xbc
	ld a, (xwa)
	exts wa
	ld (10560:16), wa

; Merge the two halves into XHL and return.
TVF_Lookup_Depth_Amount_Return:
	or hl, ix
	ret

; FILTER BYPASS: write the neutral pair (XWA+0x42) = 0x017F and (XWA+0x44) = 0x7F7F.
; This is entry 0 of the filter-mode dispatch table at 0x02412B, selected when
; (patch+0x36) & 7 == 0. XWA = voice work record.
TVF_Set_Bypass:
	ldw (xwa + 66), 0x17F
	ldw (xwa + 68), 0x7F7F
	ret

; Clamp WA into [DE, BC]; identical code to ClampS16_WA_To_DEBC. Callers 0x03083D, 0x03086D, 0x03089D, 0x0308CD, 0x030901, 0x03093F.
ClampS16_WA_Short:
	cp wa, bc
	jr le, ClampS16_WA_Short_CheckLo
	ld wa, bc
	jr ClampS16_WA_Short_Return

; Low-bound test against DE.
ClampS16_WA_Short_CheckLo:
	cp wa, de
	jr ge, ClampS16_WA_Short_Return
	ld wa, de

; Copy to XHL and return.
ClampS16_WA_Short_Return:
	ld hl, wa
	ret

; ZERO ONE 9-BYTE ENVELOPE SUB-RECORD.
; In: WA = sub-record number (0..2), C = voice/part index. Address is
; 0x04424E + index*0x1B + sub*9; bytes +0..+5 and +7 are cleared (+6 and +8 are left
; alone). Called from 0x034C23. The 0x1B-byte record is exactly three of these.
NoteState_ClearRecord:
	extz wa
	muls wa, 0x9
	ld de, wa
	ld a, c
	extz wa
	muls wa, 0x1B
	lda xbc, (0x04424e:24)
	exts xwa
	add xwa, xbc
	lda_dri XWA, 0x07, 0xE0, 0xE8
	ld (xwa + 1), 0x0
	ld (xwa + 2), 0x0
	ld (xwa + 3), 0x0
	ld (xwa + 4), 0x0
	ld (xwa), 0x0
	ld (xwa + 5), 0x0
	ld (xwa + 7), 0x0
	ret

; CAP AN ENVELOPE DEPTH BY A NORMALISED (0x7F - x) FACTOR.
; In: XWA = value, C and E = two 0..0x7F parameters. Uses FP_MulAccum64 (0x03D8CA)
; twice: t = (0x7F - C) * E, then result = (value * t) >> 12, finally capped at the
; original value. Out: XHL. Called by every EG/frequency computation in this region
; (0x022E85, 0x022F97, 0x0230A8, 0x023127).
EnvDepth_Cap:
	dec 4, xsp
	push xiz
	ld (xsp + 4), xwa
	lds32 xwa, 0
	ld a, c
	ld xbc, 0x7F
	sub xbc, xwa
	lds32 xwa, 0
	ld a, e
	call FP_MulAccum64
	ld xiz, xhl
	ld xbc, (xsp + 4)
	ld xwa, xiz
	call FP_MulAccum64
	srl xhl, 12
	cp xhl, (xsp + 4)
	jr ule, EnvDepth_Cap_Return
	ld xhl, (xsp + 4)

; Restore and return.
EnvDepth_Cap_Return:
	pop xiz
	inc 4, xsp
	ret

; COMPUTE ENVELOPE VALUE A FOR ONE VOICE (rate/level pair, formatted for the TG).
; In: WA = index. Record = 0x04424E + index*0x1B.
;   (rec+0x01) indexes the u16 table at 0x010A64 -> base value;
;   base is multiplied by (rec+0x02) through FP_MulAccum64;
;   if (rec+0x05) != 0 the EnvDepth_Cap of ((rec+0x05),(rec+0x06)) is subtracted;
;   the accumulator is >> 7 and clamped to 0x1FFF;
;   finally (rec+0x00) & 3 indexes the u16 table at 0x011511 and those bits are OR'ed
;   in, producing the 16-bit word the TG expects. Out: XHL.
; Callers 0x0293B9, 0x02F5F0.
EGEnv_Compute_A:
	dec 4, xsp
	push xiz
	extz wa
	muls wa, 0x1B
	lda xbc, (0x04424e:24)
	exts xwa
	add xwa, xbc
	ld (xsp + 4), xwa
	ld a, (xwa + 1)
	extz wa
	add wa, wa
	lda xbc, (0x010a64:24)
	ldw_sri WA, 0x07, 0xE4, 0xE0
	ld iz, wa
	extz xiz
	ld xwa, (xsp + 4)
	ld a, (xwa + 2)
	lds32 xbc, 0
	ld c, a
	ld xwa, xiz
	call FP_MulAccum64
	ld xiz, xhl
	ld xwa, (xsp + 4)
	cp (xwa + 5), 0x0
	jr z, EGEnv_Compute_A_Normalise
	ld xwa, (xsp + 4)
	ld a, (xwa + 6)
	ld c, a
	extz bc
	ld xwa, (xsp + 4)
	ld a, (xwa + 5)
	ld e, a
	extz de
	ld xwa, xiz
	calr EnvDepth_Cap
	sub xiz, xhl

; >> 7 and clamp the accumulator to 0x1FFF.
EGEnv_Compute_A_Normalise:
	srl xiz, 7
	cp xiz, 0x1FFF
	jr ule, EGEnv_Compute_A_FormatBits
	ld xiz, 0x1FFF

; OR in the 2-bit mode field fetched from the 0x011511 table.
EGEnv_Compute_A_FormatBits:
	ld xwa, (xsp + 4)
	ld a, (xwa)
	and a, 0x3
	extz wa
	add wa, wa
	lda xbc, (0x011511:24)
	ldw_sri WA, 0x07, 0xE4, 0xE0
	ld bc, iz
	ld hl, bc
	or hl, wa
	pop xiz
	inc 4, xsp
	ret

; SIMPLE ENVELOPE VALUE: (rec+0x03) indexes the u16 table at 0x010964, the value is
; multiplied by (rec+0x04), >> 7 and clamped to 0x3FFF. No depth cap, no mode bits.
; Record base 0x04424E, stride 0x1B. Callers 0x0295C8, 0x02F5FE.
EGEnv_Compute_A_Simple:
	extz wa
	muls wa, 0x1B
	lda xbc, (0x04424e:24)
	lda_dri XDE, 0x07, 0xE4, 0xE0
	ld a, (xde + 3)
	extz wa
	add wa, wa
	lda xbc, (0x010964:24)
	ldw_sri HL, 0x07, 0xE4, 0xE0
	extz xhl
	ld a, (xde + 4)
	lds32 xbc, 0
	ld c, a
	ld xwa, xhl
	call FP_MulAccum64
	srl xhl, 7
	cp xhl, 0x3FFF
	ret ule
	ld xhl, 0x3FFF
	ret

; BYTE-IDENTICAL DUPLICATE of EGEnv_Compute_A_Simple (0x022EBA) - same table, same
; shift, same clamp. No caller found by a call/calr scan over the whole ROM.
EGEnv_OpaqueData:
	.byte 0xd8, 0x12, 0xd8, 0x09, 0x1b, 0x00, 0xf2, 0x4e
	.byte 0x42, 0x04, 0x31, 0xf3, 0x07, 0xe4, 0xe0, 0x32
	.byte 0x8a, 0x03, 0x21, 0xd8, 0x12, 0xd8, 0x80, 0xf2
	.byte 0x64, 0x09, 0x01, 0x31, 0xd3, 0x07, 0xe4, 0xe0
	.byte 0x23, 0xeb, 0x12, 0x8a, 0x04, 0x21, 0xe9, 0xa8
	.byte 0xc9, 0x8b, 0xeb, 0x88, 0x1d, 0xca, 0xd8, 0x03
	.byte 0xeb, 0xef, 0x07, 0xeb, 0xcf, 0xff, 0x3f, 0x00
	.byte 0x00, 0xb0, 0xf3, 0x43, 0xff, 0x3f, 0x00, 0x00
	.byte 0x0e

; Envelope value B: identical structure to EGEnv_Compute_A but the record base is
; 0x044257 (= 0x04424E + 9, the second 9-byte sub-record) and the base-value table is
; 0x010B64 instead of 0x010A64. Callers 0x0297CD, 0x02F6F6.
EGEnv_Compute_B:
	dec 4, xsp
	push xiz
	extz wa
	muls wa, 0x1B
	lda xbc, (0x044257:24)
	exts xwa
	add xwa, xbc
	ld (xsp + 4), xwa
	ld a, (xwa + 1)
	extz wa
	add wa, wa
	lda xbc, (0x010b64:24)
	ldw_sri WA, 0x07, 0xE4, 0xE0
	ld iz, wa
	extz xiz
	ld xwa, (xsp + 4)
	ld a, (xwa + 2)
	lds32 xbc, 0
	ld c, a
	ld xwa, xiz
	call FP_MulAccum64
	ld xiz, xhl
	ld xwa, (xsp + 4)
	cp (xwa + 5), 0x0
	jr z, EGEnv_Compute_B_Normalise
	ld xwa, (xsp + 4)
	ld a, (xwa + 6)
	ld c, a
	extz bc
	ld xwa, (xsp + 4)
	ld a, (xwa + 5)
	ld e, a
	extz de
	ld xwa, xiz
	calr EnvDepth_Cap
	sub xiz, xhl

; >> 7 and clamp the accumulator to 0x1FFF.
EGEnv_Compute_B_Normalise:
	srl xiz, 7
	cp xiz, 0x1FFF
	jr ule, EGEnv_Compute_B_FormatBits
	ld xiz, 0x1FFF

; OR in the 2-bit mode field fetched from the 0x011511 table.
EGEnv_Compute_B_FormatBits:
	ld xwa, (xsp + 4)
	ld a, (xwa)
	and a, 0x3
	extz wa
	add wa, wa
	lda xbc, (0x011511:24)
	ldw_sri WA, 0x07, 0xE4, 0xE0
	ld bc, iz
	ld hl, bc
	or hl, wa
	pop xiz
	inc 4, xsp
	ret

; Simple envelope value for sub-record B: base 0x044257, table 0x010964, clamp 0x3FFF.
; Callers 0x0299DF, 0x02F704.
EGEnv_Compute_B_Simple:
	extz wa
	muls wa, 0x1B
	lda xbc, (0x044257:24)
	exts xwa
	add xwa, xbc
	ld xde, xwa
	ld a, (xde + 3)
	extz wa
	add wa, wa
	lda xbc, (0x010964:24)
	ldw_sri HL, 0x07, 0xE4, 0xE0
	extz xhl
	ld a, (xde + 4)
	lds32 xbc, 0
	ld c, a
	ld xwa, xhl
	call FP_MulAccum64
	srl xhl, 7
	cp xhl, 0x3FFF
	ret ule
	ld xhl, 0x3FFF
	ret

; RAW FREQUENCY/CUTOFF VALUE FROM SUB-RECORD B, without clamping or a register write.
; In: WA = index; record 0x044257 + index*0x1B; (rec+0x03) indexes the u16 table at
; 0x010964, multiplied by (rec+0x04) via FP_MulAccum64, >> 7. Out: XHL.
; No caller found by a call/calr scan.
Voice_Freq_ComputeLeft_Raw:
	.byte 0xd8, 0x12, 0xd8, 0x09, 0x1b, 0x00, 0xf2, 0x57
	.byte 0x42, 0x04, 0x31, 0xe8, 0x13, 0xe9, 0x80, 0xe8
	.byte 0x8a, 0x8a, 0x03, 0x21, 0xd8, 0x12, 0xd8, 0x80
	.byte 0xf2, 0x64, 0x09, 0x01, 0x31, 0xd3, 0x07, 0xe4
	.byte 0xe0, 0x23, 0xeb, 0x12, 0x8a, 0x04, 0x21, 0xe9
	.byte 0xa8, 0xc9, 0x8b, 0xeb, 0x88, 0x1d, 0xca, 0xd8
	.byte 0x03, 0xeb, 0xef, 0x07, 0x0e

; COMPUTE AND STORE THE LEFT-CHANNEL FREQUENCY WORD.
; In: A = index (0..0x7F). Record = 0x044260 + index*0x1B (the third 9-byte
; sub-record). Same pipeline as EGEnv_Compute_A - base from the u16 table at 0x010C64
; indexed by (rec+0x01), multiplied by (rec+0x02), optional EnvDepth_Cap subtraction,
; >> 7, clamp 0x1FFF, OR the 0x011511 mode bits - then stores the result in the staging
; word at 0x045204 for indices < 0x40 and 0x04520E for indices >= 0x40.
; Callers 0x029BEB, 0x02F7FB.
Voice_Freq_WriteLeft:
	dec 4, xsp
	push xiz
	ld c, a
	extz bc
	muls bc, 0x1B
	lda xde, (0x044260:24)
	exts xbc
	add xbc, xde
	ld (xsp + 4), xbc
	cp a, 0x40
	jr nc, Voice_Freq_WriteLeft_HiRange
	ld xwa, (xsp + 4)
	ld a, (xwa + 1)
	extz wa
	add wa, wa
	lda xbc, (0x010c64:24)
	ldw_sri WA, 0x07, 0xE4, 0xE0
	ld iz, wa
	extz xiz
	ld xwa, (xsp + 4)
	ld a, (xwa + 2)
	lds32 xbc, 0
	ld c, a
	ld xwa, xiz
	call FP_MulAccum64
	ld xiz, xhl
	ld xwa, (xsp + 4)
	cp (xwa + 5), 0x0
	jr z, Voice_Freq_WriteLeft_Clamp
	ld xwa, (xsp + 4)
	ld a, (xwa + 6)
	ld c, a
	extz bc
	ld xwa, (xsp + 4)
	ld a, (xwa + 5)
	ld e, a
	extz de
	ld xwa, xiz
	calr EnvDepth_Cap
	sub xiz, xhl

; Low range: >> 7 and clamp to 0x1FFF.
Voice_Freq_WriteLeft_Clamp:
	srl xiz, 7
	cp xiz, 0x1FFF
	jr ule, Voice_Freq_WriteLeft_Store
	ld xiz, 0x1FFF

; Low range: OR the mode bits and store to 0x045204.
Voice_Freq_WriteLeft_Store:
	ld xwa, (xsp + 4)
	ld a, (xwa)
	and a, 0x3
	extz wa
	add wa, wa
	lda xbc, (0x011511:24)
	ldw_sri WA, 0x07, 0xE4, 0xE0
	ld bc, iz
	or bc, wa
	stw_da 0x045204, xbc
	jr Voice_Freq_WriteLeft_Return

; Index >= 0x40: the identical computation for the upper voice bank.
Voice_Freq_WriteLeft_HiRange:
	ld xwa, (xsp + 4)
	ld a, (xwa + 1)
	extz wa
	add wa, wa
	lda xbc, (0x010c64:24)
	ldw_sri WA, 0x07, 0xE4, 0xE0
	ld iz, wa
	extz xiz
	ld xwa, (xsp + 4)
	ld a, (xwa + 2)
	lds32 xbc, 0
	ld c, a
	ld xwa, xiz
	call FP_MulAccum64
	ld xiz, xhl
	ld xwa, (xsp + 4)
	cp (xwa + 5), 0x0
	jr z, Voice_Freq_WriteLeft_HiRange_Clamp
	ld xwa, (xsp + 4)
	ld a, (xwa + 6)
	ld c, a
	extz bc
	ld xwa, (xsp + 4)
	ld a, (xwa + 5)
	ld e, a
	extz de
	ld xwa, xiz
	calr EnvDepth_Cap
	sub xiz, xhl

; High range: >> 7 and clamp to 0x1FFF.
Voice_Freq_WriteLeft_HiRange_Clamp:
	srl xiz, 7
	cp xiz, 0x1FFF
	jr ule, Voice_Freq_WriteLeft_HiRange_Store
	ld xiz, 0x1FFF

; High range: OR the mode bits and store to 0x04520E.
Voice_Freq_WriteLeft_HiRange_Store:
	ld xwa, (xsp + 4)
	ld a, (xwa)
	and a, 0x3
	extz wa
	add wa, wa
	lda xbc, (0x011511:24)
	ldw_sri WA, 0x07, 0xE4, 0xE0
	ld bc, iz
	or bc, wa
	stw_da 0x04520e, xbc

; Restore and return.
Voice_Freq_WriteLeft_Return:
	pop xiz
	inc 4, xsp
	ret

; COMPUTE AND STORE THE RIGHT-CHANNEL FREQUENCY WORD.
; In: A = index. Record = 0x044260 + index*0x1B; (rec+0x03) indexes the u16 table at
; 0x010964, multiplied by (rec+0x04), >> 7, clamped to 0x3FFF. For indices < 0x40 bit15
; is forced when (rec+0x00) bit5 is set and the value goes to 0x045206; for indices
; >= 0x40 it goes to 0x04520A with no bit15 handling.
; Callers 0x029DFF, 0x02F804.
Voice_Freq_WriteRight:
	dec 2, xsp
	push xiz
	ld (xsp + 4), a
	ld a, (xsp + 4)
	extz wa
	muls wa, 0x1B
	lda xbc, (0x044260:24)
	exts xwa
	add xwa, xbc
	ld xiz, xwa
	ld a, (xiz + 3)
	extz wa
	add wa, wa
	lda xbc, (0x010964:24)
	ldw_sri HL, 0x07, 0xE4, 0xE0
	extz xhl
	ld a, (xiz + 4)
	lds32 xbc, 0
	ld c, a
	ld xwa, xhl
	call FP_MulAccum64
	srl xhl, 7
	cp (xsp + 4), 0x40
	jr nc, Voice_Freq_WriteRight_HiRange
	cp xhl, 0x3FFF
	jr ule, Voice_Freq_WriteRight_FlagSet
	ld xhl, 0x3FFF

; (rec+0x00) bit5 set: force bit15 of the result before storing.
Voice_Freq_WriteRight_FlagSet:
	bitm 5, (xiz)
	jr z, Voice_Freq_WriteRight_Store
	set 15, hl
	stw_da 0x045206, xhl
	jr Voice_Freq_WriteRight_Return

; Store to the low-bank staging word 0x045206.
Voice_Freq_WriteRight_Store:
	stw_da 0x045206, xhl
	jr Voice_Freq_WriteRight_Return

; Index >= 0x40: clamp for the upper bank.
Voice_Freq_WriteRight_HiRange:
	cp xhl, 0x3FFF
	jr ule, Voice_Freq_WriteRight_HiRange_Store
	ld xhl, 0x3FFF

; Store to the high-bank staging word 0x04520A.
Voice_Freq_WriteRight_HiRange_Store:
	stw_da 0x04520a, xhl

; Restore and return.
Voice_Freq_WriteRight_Return:
	pop xiz
	inc 2, xsp
	ret

; Same computation as Voice_Freq_WriteRight but without the (rec+0x00) bit5 handling;
; stores to 0x045206 (index < 0x40) or 0x04520A. No caller found by a call/calr scan.
; Emitted as raw .byte in the LLVM source, so its internal branch targets and the small
; clamp helper that follows it at 0x023242 carry no symbols - see the [LABEL] and
; [ROUTINE] proposals for 0x023226..0x02324B.
Voice_Freq_ComputeRight_Raw:
	.byte 0xef, 0x6a, 0xb7, 0x41, 0x87, 0x21, 0xd8, 0x12
	.byte 0xd8, 0x09, 0x1b, 0x00, 0xf2, 0x60, 0x42, 0x04
	.byte 0x31, 0xe8, 0x13, 0xe9, 0x80, 0xe8, 0x8a, 0x8a
	.byte 0x03, 0x21, 0xd8, 0x12, 0xd8, 0x80, 0xf2, 0x64
	.byte 0x09, 0x01, 0x31, 0xd3, 0x07, 0xe4, 0xe0, 0x23
	.byte 0xeb, 0x12, 0x8a, 0x04, 0x21, 0xe9, 0xa8, 0xc9
	.byte 0x8b, 0xeb, 0x88, 0x1d, 0xca, 0xd8, 0x03, 0xeb
	.byte 0xef, 0x07, 0x87, 0x3f, 0x40, 0x6f, 0x14, 0xeb
	.byte 0xcf, 0xff, 0x3f, 0x00, 0x00, 0x63, 0x05, 0x43
	.byte 0xff, 0x3f, 0x00, 0x00
; Index < 0x40: store the clamped value to the low-bank staging word 0x045206.
Voice_Freq_ComputeRight_Raw_StoreLow:
	stw_da	(283142), hl
	jr	18
; Index >= 0x40: clamp for the upper voice bank.
Voice_Freq_ComputeRight_Raw_HiRange:
	cp	xhl, 16383
	jr	ule, 5
	ld	xhl, 16383
; Store the clamped value to the high-bank staging word 0x04520A.
Voice_Freq_ComputeRight_Raw_StoreHigh:
	stw_da	(283146), hl
; Frame teardown and return.
Voice_Freq_ComputeRight_Raw_Return:
	inc	2, xsp
	ret
; Clamp WA to at most 0x00FF using an unsigned compare (no lower bound); the result is
; also copied to XHL. 12 bytes, ends with 'ret' at 0x02324D.
; Unreferenced: no call, calr, jp or 24-bit pointer to 0x023242 exists anywhere in the
; 0x30000-byte image. It sits inside the raw .byte blob that the LLVM source emits for
; Voice_Freq_ComputeRight_Raw, which is why it carries no symbol at all today.
; NAMING NOTE: this proposal follows the CamelCase style of its neighbours rather than
; the UPPER_SNAKE house style - see the last [UNCERTAIN] entry.
Voice_Clamp_Byte_Unsigned:
	cp	wa, 255
	jr	ule, 3
	ldw	wa, 255
; Copy the clamped value to XHL and return.
Voice_Clamp_Byte_Unsigned_Return:
	ld	hl, wa
	ret

; TWO-STAGE LOOKUP OF A TONE-COLOUR / WAVE INDEX.
; In: XWA = a 0..0xFF value, C = a byte whose top 3 bits select the group.
; group = C >> 5; the byte table at 0x0106E4 indexed by XWA gives a row offset, and the
; final byte is read from the ROM table at 0x00FFE4 at (group << 8) + row.
; Out: XHL (zero-extended byte). Four callers at 0x02B316, 0x02B336, 0x02B475, 0x02B492.
Voice_Colour_LookupIndex:
	and c, 0xE0
	srl c, 5
	extz xwa
	ld xde, 0x106E4
	add xde, xwa
	ld a, (xde)
	ld e, a
	extz de
	ld a, c
	extz wa
	sla wa, 8
	add wa, de
	lda xbc, (0x00ffe4:24)
	ldb_sri L, 0x07, 0xE4, 0xE0
	extz hl
	ret

; Clamp the control value (WA bits 8..14) against the stacked high limit at (XSP+0x06).
Voice_Colour_ClampUpper:
	and wa, 0x7F00
	srl wa, 8
	ld l, (xsp + 6)
	extz hl
	cp wa, hl
	jr ule, Voice_Colour_ClampLower
	ld a, (xsp + 6)
	extz wa
	jr Voice_Colour_InterpolateDelta

; Clamp against the low limit in E.
Voice_Colour_ClampLower:
	ld l, e
	extz hl
	cp wa, hl
	jr nc, Voice_Colour_InterpolateDelta
	ld a, e
	extz wa

; (clamped - BC) * stacked depth (XSP+0x04), >> 5; 'retd 4' pops both stacked args. Structurally identical to Pan_ScaleWithVelocity.
Voice_Colour_InterpolateDelta:
	extz bc
	ld de, wa
	sub de, bc
	ld l, (xsp + 4)
	exts hl
	ld wa, hl
	extpfx2 0xDA, 0x48
	ld hl, wa
	sra hl, 5
	retd 0x4

; Clamp WA to [0, 0xFF] (signed compare). Out: WA and XHL.
Voice_Clamp_Byte_WA:
	cp wa, 0xFF
	jr le, Voice_Clamp_Byte_WA_LowBound
	ldw wa, 0xFF
	jr Voice_Clamp_Byte_WA_Return

; Low-bound test.
Voice_Clamp_Byte_WA_LowBound:
	cps wa, 0
	jr ge, Voice_Clamp_Byte_WA_Return
	lds wa, 0

; Copy to XHL and return.
Voice_Clamp_Byte_WA_Return:
	ld hl, wa
	ret

; ---------------------------------------------------------------------------------------
; THE TONE GENERATOR STAGING BLOCK AT 0x0451CC
;
; The words from 0x0451CE upwards are staged copies of IC303's per-voice registers. The
; firmware fills them from many places and ToneGen_WriteVoiceParams then bursts the block
; to the chip, so every one of these addresses is a register by another name:
;
;     0x0451CC -> +0x000   CONTROL / gate -- PRESENT IN THE FORMAT, UNUSED HERE. See below.
;     0x0451CE -> +0x040   recording selector, (class << 12) | entry
;     0x0451D0 -> +0x080   output level + the 3-bit descriptor field (built below)
;     0x0451D2 -> +0x0C0   coarse level + expression
;     0x0451D4 -> +0x100   TVF cutoff
;     0x0451D6 -> +0x140   TVF depth / bias
;     0x0451D8 -> +0x180   pan, 0x0040 = centre
;     0x0451DA -> +0x400   absolute log pitch          (Pitch_Emit_Reg400)
;     0x0451DC -> +0x440
;     0x0451DE -> +0x480
;     0x0451E0 -> +0x4C0   oscillator config + slot
;     0x0451E2 -> +0x500   detune / bend pair
;     0x0451E4 -> +0x800   amplitude envelope segment 0
;     0x0451E6 -> +0x840   amplitude envelope segment 1
;     0x0451E8 -> +0x880   amplitude envelope segment 2
;     0x0451EA -> +0x8C0   amplitude envelope segment 3
;     0x0451EC -> +0x900   second envelope, segment 0
;     0x0451EE -> +0x940   second envelope, segment 1
;     0x0451F0 -> +0x980   second envelope, segment 2
;     0x0451F2 -> +0x9C0   third envelope, segment 0
;     0x0451F4 -> +0xA00   third envelope, segment 1
;     0x0451F6 -> +0xA40   third envelope, segment 2
;
; RECORD TAIL, 0x0451F8..0x04520E = words 22..33 of the same 34-word (0x44-byte) record.
; ToneGen_WriteVoiceParams does not transmit them, but at THIS base they are not inert, and
; that is what sizes the record from this file instead of by analogy with the ROM templates:
;     0x045204 (+0x38, word 28)  TG register 0x1C0; EGEnv_Compute_B writes it
;     0x045206 (+0x3A, word 29)  EGEnv_Compute_B_Simple writes it; it reaches the chip
;                                through the ToneGen_WriteExtParam* writers, not this burst
;     0x04520E (+0x42, word 33)  the last word of the record; the secondary-pitch path
;                                writes it and reads it straight back
;                                (`stw_da 0x04520e, xwa` / `ldw_da xiz, 0x04520e`)
;
; Assembled from this file's own scattered annotations (the +0x0C0, +0x100/+0x140,
; +0x180/+0x4C0, +0x400, and the 0x8C0..0xA40 zeroing routine all name their targets) plus
; a capture of every write the chip receives over 1705 note-ons of the built-in demo, which
; agrees register by register.
;
; THE +0x000 CONTROL WORD IS PART OF THE BLOCK FORMAT BUT NOT OF THIS BLOCK'S TRAFFIC.
; ToneGen_Config_Init (0x02DFCF) hands a 68-byte block to ToneGen_WriteVoiceParams and then
; passes that block's WORD 0 to ToneGen_WriteSingleReg with WA = the bare channel, i.e. to
; register (0x0000 + ch) -- so offset +0x00 of a 68-byte block is the CONTROL word. The
; block it is handed is the DRAM copy at (XSP + 2): DSP_Config_Init copies 0x22 words from
; ROM 0x00F8D5 into DRAM 0x2AA4 first. (ROM 0x00F8D5 starts with 0x1200; the dormant probe
; at 0x02E0EE is the only site that hands a ROM pointer directly, `lda xwa, 0x00f919`,
; whose template starts with 0xF000.) The run-time block is different: ToneGen_WriteVoiceParams
; reads from +0x02 upwards and never touches +0x00, and a grep for 0x0451CC in this file
; finds only `lda_24 xbc, 0x0451cc` pointer loads -- no store. At run time the control word
; lives, IN THE VOICE-ENGINE PATHS, in the LIVE SLOT RECORD at 0x0430BB + slot*0x47
; (record +0x2D) instead, built by Voice_Build_GateCommand (0x025589) / _NoPartial
; (0x0255F3) and issued as a separate write after the burst. The auxiliary 8-voice pool is
; the exception: its run-time block at 0x3B1C is refilled by `ldirw` from ROM 0x012115 and
; its OWN word 0 is sent (ToneGen_SetupPolyVoice, 0x0355AD). The command set and the demo capture are documented at 0x025589.
;
; ---------------------------------------------------------------------------------------
; WHAT +0x040 SELECTS: THE WAVE ROM'S OWN DIRECTORY -- WHICH THIS FIRMWARE NEVER READS
;
; NEGATIVE RESULT FIRST, because it is the answer to the obvious question: nothing in this
; ROM, nor in the sub-CPU boot ROM, nor in the main program, walks the waveform ROMs.
; IC304-IC307 hang off IC303 and are in no CPU's address space:
;
;   * THE SCHEMATICS. kn5000-docs/tone-generator.md:300,321 reads the service manual's Tone
;     Generator Sections A and B as "Waveform ROMs (IC304-307) --> Tone Generator LSI
;     (IC303)". The only CPU-facing windows on IC303 are its register file and its keybed
;     side, and kn5000-docs/kn7000-expansion-and-wave-dump.md states plainly that NONE of
;     them is a wave-memory read port.
;
;   * THIS PAYLOAD'S OWN TRAFFIC, counted over the whole file. Two windows on IC303,
;     selected by P6.7 driving A23:
;         0x100000  register-ADDRESS latch  139 writes, 1 read (ToneGen_Read_Register,
;                                           documented below)
;         0x100002  register DATA port      137 direct-addressing writes, plus one more
;                                           through a pointer set up in
;                                           ToneGen_ReadPitch_Compute; NEVER read
;         0x110000  keybed / voice DATA     2 reads, no writes
;         0x110002  keybed / voice STATUS   2 reads, no writes
;     The five reads live in three routines -- ToneGen_Read_Register (the active-voice
;     bitmap, or a channel's envelope level), Keybed_Read_Event (one key event) and
;     ToneGen_Poll_Read (one voice's on/off bit, kept in the bitmap at 0x01F41C). Not one
;     of them returns a wave byte, and there is no port through which one could.
;
;   * THE BOOT ROM. subcpu/boot/kn5000_subcpu_boot.s: 29 writes to 0x100000, 28 to
;     0x100002, one read at 0x100004; on the other window one write to 0x110002 and one
;     read each of 0x110002 and 0x110000. Same story, no wave read.
;
;   * THE MAIN PROGRAM. In v7, v9 and v10 the value 0x100000 only ever appears as an
;     IMMEDIATE -- `cp xiz, 0x100000`, `cp xbc, 0x100000`, `add xbc, 0x100000`, i.e. the
;     1 MB DRAM top bound -- never as a direct-addressing access, and 0x110000 is
;     FDC_MAP__BASE_ADDR (maincpu/fdc_constants.s:16). The main CPU has no window on IC303.
;
;   * THE MACHINE'S OWN WAVE ROM CHECK (service test 6, chord E3+E4) is ACOUSTIC: the ROMs
;     are made to sound and a technician listens for distortion. See
;     kn5000-docs/test-modes.md and kn5000-docs/kn7000-expansion-and-wave-dump.md. The
;     KN7000 does have a CPU-visible wave read port; the KN5000 has no equivalent.
;
; [INFERENCE] So the directory walk happens inside IC303. That is a conclusion by
; elimination -- nobody has watched IC303 do it -- but the firmware's whole contribution to
; choosing a recording is provably one 16-bit index, and the rest of this block documents
; the format that index is resolved against, because none of the per-voice work in this
; file means anything without it.
;
; THE SELECTOR. 0x0451CE is shadow+0x02 of the voice-engine staging block, the FIRST word
; ToneGen_WriteVoiceParams pushes (register 0x0040 + ch). Its layout, validated in
; kn7000_mame/notes/kn5000-structural-validation.md section 0, is
;
;     class = word >> 12       selects one 1 MB PAGE of one 4 MB wave socket
;     entry = word & 0x0FFF    plain 0-based index into that page's directory, base 0
;
; and the firmware treats it as opaque. Every instruction in this ROM that touches 0x0451CE
; is accounted for: eight stores (the six WaveSel_Emit_ZoneRecord_S* variants and
; WaveSel_StageB_Store_Reg040, each copying word 0 of a zone record verbatim, plus
; Voice_InitVoiceState storing 0), the read half of WaveSel_StageB_Store_Reg040's
; read-modify-write, and the `lda_24 xwa, 0x0451ce` that hands the word to
; Voice_Slot_ApplyPitchJitter. Nothing splits the word, range-checks the entry against a
; count, or dereferences anything with it.
;
; * BUT IT IS NOT ALWAYS EMITTED AS STORED, AND THAT IS AN OPEN PROBLEM. Two sites change
; it after the zone record has been copied in:
;   - WaveSel_StageB_Store_Reg040 DOUBLES the top nibble in place when bit 2 of the global
;     audio-mode word 0x041343 is set -- class *= 2, i.e. a page/bank re-select;
;   - Voice_Init_Type1 calls Voice_Slot_ApplyPitchJitter(0x0451CE) immediately after
;     WaveSel_StageB_Build_Reg040, and that adds (tick & 7) to the WHOLE word.
; Under entry = bits[11:0] the second one picks a DIFFERENT directory entry on every note
; that goes through Voice_Init_Type1. On page 0 the consecutive entries of a shared-wave
; run are different KEY ZONES of one recording (185-190, 191-197), so a +0..7 step there
; would not be a subtle effect. Either the low bits are not a plain entry index on this
; path, or the path is not what it looks like. UNRESOLVED -- do not quote the index model
; as settled without addressing it.
;
; A SECOND TENSION, same register from a different block: ToneGen_SetupPolyVoice fills the
; auxiliary 8-voice block at 0x3B1C, whose +0x02 comes from the octave-indexed table at
; 0x01217D and is annotated in this file as a pitch/rate constant. Under the decode above
; that word is instead a wave selector chosen per octave, which is what a multisample looks
; like. Both readings cannot be right; nobody has checked which.
;
; THE PAGE FORMAT, measured on kn5000_waveform_rom.ic307 (SHA1
; 4b511bff6625f4655cabd96a263bf548d2ef4bf7), the only hardware-rooted wave dump that
; exists -- the files circulating as IC304/IC305/IC306 are mostly-0xFF reads, and
; mame_driver/src/mame/matsushita/kn5000.cpp:771-773 declares all three NO_DUMP. Each 1 MB
; page is independently self-describing:
;
;     u16 param_ptr, u16 wave_off      x N     ; the directory, at page offset 0
;     ... variable-length parameter records ...
;     ... signed 16-bit little-endian PCM ...
;
;     N          = u16[page + 0] / 4           ; entry 0's param_ptr points just past the
;                                              ; directory, so THE DIRECTORY DECLARES ITS
;                                              ; OWN LENGTH -- there is no count field
;     PCM start  = page + wave_off * 16        ; 16-byte (8-sample) granule
;     PCM end    = page + 16 * (next strictly greater wave_off in the directory)
;     param rec  = page + param_ptr .. page + (next strictly greater param_ptr)
;
; wave_off is a u16 scaled by 16, so it reaches 0x0FFFF0 and no further: the field
; addresses exactly 1 MB, which is [INFERENCE] why the page is 1 MB, and why a 4-bit class
; field spans exactly the 16 MB of four 4 MB sockets. IC307's four pages, all four measured
; (columns as published in kn5000-structural-validation.md section 1):
;
;   page  base       N     directory      last param_ptr  first PCM   last wave
;   0     0x000000   198   0x0000-0x0317  0x1A26          0x001A30    0x0FEF60
;   1     0x100000   168   0x0000-0x029F  0x182C          0x001840    0x0FEB60
;   2     0x200000  1072   0x0000-0x10BF  0x2694          0x0026A0    0x0FFEE0
;   3     0x300000    57   0x0000-0x00E3  0x022C          0x000240    0x0FF5C0
;
; 1495 directory slots, 1413 unique wave offsets, in one 4 MB chip. Both columns rise
; monotonically except three entries on page 1 (79, 82, 85) whose wave_off steps backwards
; to re-use an earlier recording. The last parameter record of a page starts 10-20 bytes
; before the first PCM byte, its tail zero-padded up to the granule.
;
; IT IS SELF-VALIDATING. The first word of every parameter record repeats that entry's own
; wave_off: 198/198, 168/168, 1072/1072, 57/57 -- flagcensus.py prints
; "back-reference OK: 1495 / 1495", no exceptions. That redundancy is the cheapest possible
; check that a (class, entry) pair landed on a real slot, and it is also what proves the
; four-page reading is not pattern-matching on noise: mis-framed data cannot satisfy a
; back-reference 1072 times in a row.
;
; WHAT A PARAMETER RECORD CONTAINS. The redundant wave_off word, then zero or more
; { value:8, flag:8 } pairs (little-endian word = value | flag << 8). flagcensus.py counts
; 7203 pairs over the 1495 records -- that total includes the all-zero words padding each
; page's last record -- and waverec.py's size histograms show 964 records with no pairs at
; all (960 of them on page 2, which holds short one-shot material) and the largest record
; at 850 bytes.
;   flag 0x00        KEY-SPLIT BOUNDARY, usually listed high-to-low within a record. The
;                    unit is NOT MIDI: against the firmware's own zone table the relation
;                    is key = 1.5 * (value - 0x28), i.e. one unit = 1/8 octave, and
;                    successive zones of a multisample step by 8 (worked table in
;                    kn5000-structural-validation.md section 4.2 -- MEASURED relation,
;                    INFERRED unit interpretation).
;   flag 0x01-0x2F   PER-ZONE FINE TUNE, values clustered in 0xEA-0xFF, i.e. small negative
;                    trims. Page-0 records 180 and 181 are 53 and 130 such pairs and
;                    nothing else: a per-key detune table across the keyboard, exactly what
;                    a stretched multisample needs. See
;                    kn7000_mame/notes/kn5000-ic307-content-map.md section 3.2.
;   flag bit 7       END OF RECORD. flagcensus.py counts 286 pairs with bit 7 set, and its
;                    per-record last-pair histogram accounts for all 286: bit 7 never
;                    appears on a pair that is not its record's last. Not every record uses
;                    it -- the extent is delimited by the next param_ptr regardless.
;   flag bit 6       A MARKER, 258 occurrences, NOT decoded. content-map section 3.3 groups
;                    0xC0/0xC5/0x80/0x40 as terminators/markers without settling bit 6.
; NO ROOT NOTE AND NO LOOP POINTS ARE STORED HERE [INFERENCE]: every field in every record
; is a single byte, while a loop point into a wave of tens of thousands of samples needs at
; least 16 bits, and loopprobe.py found none. The pitch origin comes from the firmware side
; (the tone database's zone records and this file's pitch chain). Note that
; kn5000-structural-validation.md section 7 leaves open that some of the flag != 0x00 bytes
; are IC303's own per-wave loop/envelope/tune parameters.
;
; MULTISAMPLES SHOW UP AS RUNS OF CONSECUTIVE ENTRIES sharing one wave_off with shifted
; split lists -- page 0 entries 185-190 (wave 0xFCA6) and 191-197 (wave 0xFEF6), each
; successive entry's splits shifted by +8 units. The firmware's own key zones for those
; same entries tile the keyboard contiguously with no overlap (section 4.1): a cross-check
; between two ROMs written by different tools.
;
; PROVENANCE. Format, four-page split and the class decode:
; kn7000_mame/notes/kn5000-structural-validation.md (2026-07-25) and
; kn7000_mame/notes/kn5000-ic307-content-map.md; re-runnable probes in
; kn7000_mame/tools/kn5000-rom-structure/ (waverec.py prints the per-page counts and the
; record-size histograms, flagcensus.py the back-reference check and the flag census,
; loopprobe.py is the loop-point negative). The class -> page assignment was PREDICTED from
; the firmware alone -- max(entry)+1 over the 1444 (class, entry) pairs the table-data ROM's
; zone records produce -- and then checked against IC307's self-declared counts: class 4
; needs 198 and page 0 has 198, class 5 needs 168 and page 1 has 168, class 7 needs 57 and
; page 3 has 57. Three exact hits, zero out-of-range entries; a pitch regression of class 7
; onto page 3 gives slope 1.003 / R^2 0.998, where every wrong page collapses to slope ~0
; (section 4.3). [INFERENCE] hence page = class & 3, bank = (class >> 2) & 3, IC307 = bank 1.
; STILL OPEN: WHICH PHYSICAL SOCKET IS BANK 0. That is a wiring fact, not a decoding one,
; and it cannot be settled until one of IC304/IC305/IC306 is really dumped; section 7 of
; the validation note gives the falsifiable prediction that will identify it.
; ---------------------------------------------------------------------------------------
;
; THE THREE ENVELOPES share one word format, (target << 8) | rate.
; MEASURED (demo capture, 1705 note-ons; harness in kn7000_mame,
; tools/rigs/kn5000_demo_capture.lua): segments 0 and 1 took extra writes during a note,
; segment 2 exactly one write per note-on, and segment 3 of the amplitude envelope was used
; on about 4% of notes, decaying to zero while segment 2 held a sustain level; on the rest
; it was left zero, which means "unused" rather than "fall silent".
; ★ THE ONCE-PER-NOTE-ON FIGURE IS A PROPERTY OF THAT CAPTURE, NOT OF THE CODE: the writer
; census below finds three routines besides the note-on burst that can write segment 2, two
; of which run while a voice is sounding.
;
; [INFERENCE] RATE 0 PROBABLY MEANS "GO TO THE TARGET NOW", not "hold there". The argument is
; entirely firmware-side: Voice_EnvelopeRate_Table (0x011963) has exactly one entry below 4
; (entry 0 = 0x00), and all four envelope-1 builders floor segment 1's rate at 4, so that
; floor exists for no purpose other than keeping 0 off that one segment -- while segments 0
; and 2 are left free to carry it. See Voice_Calc_LevelPair_PatchAtk_ClampDepth.
; NOT MEASURED: no rate-to-time law and no time constant for IC303 has been captured, so
; nothing here fixes what any rate value other than 0 does, or which end of 0x00..0x7F is
; fast. Do not turn the ordering argument above into a number.
;
; WHY THE TEN ENVELOPE REGISTERS ARE REFRESHED AT DIFFERENT RATES. Bank = register number *
; 0x40, so these ten words are IC303 registers 0x20..0x29 (the same conversion is spelled out
; at ToneGen_WriteVoice_6Words, _Pan_Pair, _EnvLevel and _Reg11). Every routine that talks to
; the chip latches 0x100000 with `add wa, <bank>` and then writes 0x100002, so counting that
; one opcode gives the writer list per bank.
; ★ COUNT IT IN THE ROM IMAGE, NOT IN THIS FILE: at the time this was written, a grep for
; `add wa, 0x8..` here missed two real bank writers that were still emitted as `.byte` (see
; the now-resolved MISLABELLED notes at 0x0280FE-0x028838 and 0x028F75-0x029E30, both fully
; converted to instructions as of 2026-09-02). Scanning
; kn5000_subprogram_v142.rom for the opcode bytes D8 C8 <lo> <hi> gives:
;
;   seg 0   +0x800 r0x20 : 24 sites     seg 1   +0x840 r0x21 : 29 sites
;           +0x900 r0x24 :  3 sites             +0x940 r0x25 :  3 sites
;           +0x9C0 r0x27 :  3 sites             +0xA00 r0x28 :  3 sites
;   seg 2   +0x880 r0x22 :  4 sites  -- ToneGen_WriteVoiceParams, ToneGen_WriteEnvSegments,
;                                      ToneGen_WriteSegRegs_SameLevel, and
;                                      ToneGen_WriteVoice_Reg21_Reg22 (0x028170)
;           +0x980 r0x26 :  1 site   -- ToneGen_WriteVoiceParams
;           +0xA40 r0x29 :  1 site   -- ToneGen_WriteVoiceParams
;   +0x8C0  r0x23        :  1 site   -- ToneGen_WriteVoiceParams
;
; So segment 2 of envelopes 2 and 3 (r0x26, r0x29) and r0x23 have exactly ONE writer each:
; whatever ToneGen_WriteVoiceParams leaves in them at note-on is what the chip keeps for the
; whole note, and a model must not expect them to be refreshed.
; ★ SEGMENT 2 OF THE AMPLITUDE ENVELOPE (r0x22) IS NOT IN THAT CLASS. Three routines besides
; the note-on burst write it, and two of them can run while a voice is sounding:
; ToneGen_WriteSegRegs_SameLevel, called from Voice_AllNotes_SustainRetrigger_BranchB/BranchD
; (the sustain-pedal walk over live voices) as well as from Voice_Reload_Levels_BranchA/C,
; and ToneGen_WriteVoice_Reg21_Reg22, called from AudioChannel_AllVoices_Update_PanShift (an
; audio-channel command handler that walks a part's live voices). The third,
; ToneGen_WriteEnvSegments, is reached only from Voice_Reload_Levels_BranchD. The capture
; quoted above saw r0x22 written exactly once per note-on, which says those three branches
; did not fire in it -- not that they cannot fire.
;
; SEGMENTS 0 AND 1 HAVE A SECOND SHADOW. The per-tick path keeps its own copies just above
; the block and ToneGen_WriteLevelBurst (0x02D436) pushes them to the same six registers:
;
;     0x0451F8 -> +0x800   0x0451FA -> +0x840   built by Voice_Calc_LevelPair_EGA 0x026769
;     0x0451FC -> +0x900   0x0451FE -> +0x940   built by Voice_Calc_LevelPair_EGB 0x026975
;     0x045200 -> +0x9C0   0x045202 -> +0xA00   built by Voice_Calc_LevelPair_EGC 0x026AAA
;
; No register outside that set has a second shadow. The three builders do NOT agree on the
; low byte: EGA emits (level << 8) with bit 7 forced on the +0x800 word and clear on +0x840,
; so its rate field is 0; EGB and EGC emit (level << 8) | Detune_ScaleSymmetric(...), a
; signed -0x7F..+0x7F byte that is usually NOT 0 and often has bit 7 set, and each of them
; writes the SAME word to both of its two registers.
;
; TARGET POLARITY: in the amplitude envelope the high byte is an ATTENUATION and 0xFF is
; SILENT. (1) Both parameter curves descend from 0xFF -- Voice_LevelPair_AttackCurve
; (0x011899, 0xFF..0x09) and Voice_EnvelopeLevel_Curve (0x0118FE, 0xFF..0x04). Note neither
; curve can produce 0x00: a target of 0x00 is off the loud end of the curve, not a value the
; builders ever emit. (2) The firmware's mute idiom -- 11 sites writing r0x21 <- 0xFF00 and
; r0x20 <- 0xFF80 -- is called the documented "mute" level word at Voice_SetPitch. (3)
; Voice_Step_ExprRamp counts toward 0xFF00 on r0x21 and releases the slot on arrival, and
; Voice_Calc_LevelPair_Full_CheckMax reserves 0xFF as "fully attenuated / voice finished".
; [INFERENCE] proofs (2) and (3) reach banks +0x800/+0x840 only. Envelopes 2 and 3 share the
; word format and the same 0x0118FE curve, so the same polarity is carried over to
; +0x900..+0xA40 by construction; no firmware site writes a mute word to those banks.
; ★ OPEN CONFLICT: kn5000-docs/tone-generator.md reads +0x0840/+0x0880 as "Pan Left/Right,
; 0x00 = silent" -- the opposite polarity. That document and this block disagree, and the
; disagreement is not settled here.
;
; THE BUILDERS (all take XWA = voice-slot record; paramA = the u32 at slot+0x17, tonerec =
; the u32 at slot+0x23):
;     amplitude  r0x20..0x22   Voice_Calc_LevelPair_PatchAtk / _FixedAtk / _Full / _Mono
;     second     r0x24..0x26   Voice_Level_ComputeTriplet  0x023AD0
;     third      r0x27..0x29   Voice_StereoLevel_Compute   0x024664
;     r0x23                    Voice_PortaLevel_Compute    0x0248D5 -- NOT part of the
;                              amplitude family: its high byte is Detune_ScaleSymmetric of
;                              paramA+0x08 and its low byte Detune_ScaleSymmetric of
;                              paramA+0x3D + paramA+0x3E, i.e. the same parameter family the
;                              THIRD envelope's rate bytes use, not the +0x27..+0x2C run.
;
; BUILD AND STORE THE VOICE OUTPUT-LEVEL WORD (tone generator register +0x080).
; In: XWA = voice work record, BC = starting level.
;
; LEVEL, bits 11..0: adds (record+0x23)->[0x0C] and (record+0x23)->[0x10] and
; (record+0x33), clamps to 0..0xFF, uses the result*2 to index the u16 table at 0x010764
; and doubles that. The table is a logarithmic law, 256 counts per octave.
;
; BITS 14..12 ARE NOT PAN -- pan is a separate register, +0x180, staged at 0x0451D8.
; This field is three bits of per-recording data, from one of two sources chosen by bit 7
; of the SELECTED ZONE RECORD's byte +0x02:
;
;     bit 7 SET   -> field = (zone_record[+0x02] >> 4) & 7    the descriptor's own bits
;     bit 7 CLEAR -> field = T[folded note mod 12]            u16 table at 0x00FBE4,
;                                                             T[n] = floor(2*(n mod 12)/3)
;
; That zone record is the same one whose first word becomes the +0x040 selector and whose
; word at (stride-2) is the multisample's pitch trim -- so three bits of the multisample
; descriptor travel to the chip verbatim, which is the only per-recording data that does.
;
; MEASURED, 2026-08-20: over a demo capture, the override branch predicts the value the
; chip is given 196 times out of 196 for selectors reachable from exactly one zone record.
; The low nibble of byte +0x02 is zero across all 1444 selectors the firmware's tables
; produce, which is the field structure showing itself in the data.
;
; bit15 is forced here, but it is not data: it is the parameter-latch commit strobe that
; ToneGen_WriteVoiceParams raises on a burst's first word and lowers on its last, so this
; SET is redundant with the writer's own.
;
; No caller found by a call/calr scan over the ROM (reached indirectly).
Voice_Build_OutputLevel:
	push xiz
	ld xiz, xwa
	ld xwa, (xiz + 35)
	add bc, (xwa + 12)
	ld xwa, (xiz + 35)
	add bc, (xwa + 16)
	add bc, (xiz + 51)
	ld wa, bc
	calr Voice_Clamp_Byte_WA
	ld bc, hl
	add bc, bc
	lda xwa, (0x010764:24)
	ldw_sri WA, 0x07, 0xE0, 0xE4
	add wa, wa
	ld bc, wa
	ld xwa, (xiz + 15)
	bitm 7, (xwa + 2)
	jr z, Voice_Build_OutputLevel_NoPanOverride
	ld xwa, (xiz + 15)
	ld a, (xwa + 2)
	extz wa
	and wa, 0x70
	sll wa, 8
	jr Voice_Build_OutputLevel_Store

; No descriptor override (bit 7 of zone_record[+0x02] clear): take bits 14..12 from the
; 0x00FBE4 table, indexed by the folded note.
Voice_Build_OutputLevel_NoPanOverride:
	ld wa, (xiz + 6)
	srl wa, 8
	extz xwa
	add xwa, xwa
	ld xde, 0xFBE4
	add xde, xwa
	ld wa, (xde)

; OR the level and the bits-14..12 field together, force the commit strobe and store to
; 0x0451D0 (tone generator register +0x080).
Voice_Build_OutputLevel_Store:
	or bc, wa
	set 15, bc
	stw_da 0x0451d0, xbc
	pop xiz
	ret

; Clamp WA to [0, 0xFF] using an unsigned upper compare. Out: WA and XHL.
Voice_Clamp_Byte_HL:
	ld bc, wa
	cp bc, 0xFF
	jr ule, Voice_Clamp_Byte_HL_LowBound
	ldw wa, 0xFF
	jr Voice_Clamp_Byte_HL_Return

; Low-bound test.
Voice_Clamp_Byte_HL_LowBound:
	cps wa, 0
	jr ge, Voice_Clamp_Byte_HL_Return
	lds wa, 0

; Copy to XHL and return.
Voice_Clamp_Byte_HL_Return:
	ld hl, wa
	ret

; AGE A PART'S RETRIGGER/VELOCITY-PHASE COUNTER AGAINST THE MASTER TICK.
; In: A = part index. Per-part stride 0x011F:
;   0x041481 + part*0x011F  = 32-bit timestamp of the last update
;   0x041485 + part*0x011F  = phase counter byte
;   0x041486 + part*0x011F  = phase output byte (0x00 / 0x10 / 0x20)
; Master tick is the 32-bit counter at 0x1040. Delta 0 -> only refresh the timestamp;
; delta >= 0x19 (25 ticks) -> reset both counter and phase to 0; otherwise bump the
; counter and map 1 -> 0x10, 0 -> 0x00, anything else -> 0x20.
; Callers 0x02C734, 0x02C838, 0x02C93C, 0x02CAA5.
Voice_Env_UpdateVelocityCounters:
	ld c, a
	extz bc
	muls bc, 0x11F
	lda xde, (0x041481:24)
	ld xhl, (4160:16)
	sub_sril_rm XHL, 0x07, 0xE8, 0xE4
	jrl z, Voice_Env_UpdateVelocity_Store
	cp xhl, 0x19
	jr nc, Voice_Env_UpdateVelocity_Reset
	ld c, a
	extz bc
	muls bc, 0x11F
	lda xde, (0x041485:24)
	exts xbc
	add xbc, xde
	incm8 1, (xbc)
	ld c, (xbc)
	cps c, 1
	jr z, Voice_Env_UpdateVelocity_SetPhase1
	cps c, 0
	jr nz, Voice_Env_UpdateVelocity_SetPhase2
	ld c, a
	extz bc
	muls bc, 0x11F
	lda xde, (0x041486:24)
	stib_ind 0x07, 0xE8, 0xE4, 0x00
	jr Voice_Env_UpdateVelocity_Store

; Counter reached 1: phase byte = 0x10.
Voice_Env_UpdateVelocity_SetPhase1:
	ld c, a
	extz bc
	muls bc, 0x11F
	lda xde, (0x041486:24)
	stib_ind 0x07, 0xE8, 0xE4, 0x10
	jr Voice_Env_UpdateVelocity_Store

; Counter is neither 0 nor 1: phase byte = 0x20.
Voice_Env_UpdateVelocity_SetPhase2:
	ld c, a
	extz bc
	muls bc, 0x11F
	lda xde, (0x041486:24)
	stib_ind 0x07, 0xE8, 0xE4, 0x20
	jr Voice_Env_UpdateVelocity_Store

; Timed out (>= 0x19 ticks): clear both the counter and the phase byte.
Voice_Env_UpdateVelocity_Reset:
	ld c, a
	extz bc
	muls bc, 0x11F
	lda xde, (0x041485:24)
	stib_ind 0x07, 0xE8, 0xE4, 0x00
	ld c, a
	extz bc
	muls bc, 0x11F
	lda xde, (0x041486:24)
	stib_ind 0x07, 0xE8, 0xE4, 0x00

; Refresh the timestamp from the master tick at 0x1040 and return.
Voice_Env_UpdateVelocity_Store:
	extz wa
	muls wa, 0x11F
	ld bc, wa
	lda xde, (0x041481:24)
	ld xwa, (4160:16)
	stl_dri XWA, 0x07, 0xE8, 0xE4
	ret

; VELOCITY-SWITCH DISPATCHER, TYPE 0/1 (and entry point for type 2).
; In: A = part index (0, 1 or 2 selects the variant), C = sub-case 0..3.
; First clears the per-part program byte at 0x0413D5 + part*0x011F. A == 2 diverts to
; Voice_Env_ApplyVelocity_Type2. For A == 0 or 1 the sub-case in C picks which flag is
; tested: cases 0 and 1 test the global config byte at 0x04134B (bit3, then bit0/bit1
; via BitTest_*), cases 2 and 3 test bit3 / bit0 / bit1 of the per-part byte at
; 0x04137F + part*0x011F. If the resulting predicate L is non-zero,
; Instrument_LookupProgram_HiNibble installs the program byte.
; Callers 0x02C72B, 0x02C82F, 0x02C933, 0x02CA9C.
Voice_Env_ApplyVelocity_Type0:
	dec 2, xsp
	ld (xsp), a
	ld a, (xsp)
	extz wa
	muls wa, 0x11F
	lda xde, (0x0413d5:24)
	stib_ind 0x07, 0xE8, 0xE0, 0x00
	ld a, (xsp)
	cps a, 2
	jrl z, Voice_Env_ApplyVelocity_Type2
	cps a, 1
	jr z, Voice_Env_VelocityDispatch_c1
	cps a, 0
	jrl nz, Voice_Env_ApplyVelocity_Return

; Sub-case selector for the type-0/1 variant.
Voice_Env_VelocityDispatch_c1:
	cps c, 3
	jr z, Voice_Env_VelocityDispatch_c3
	cps c, 2
	jr z, Voice_Env_VelocityDispatch_c2
	cps c, 1
	jr z, Voice_Env_VelocityDispatch_c1_Bit1
	cps c, 0
	jrl nz, Voice_Env_VelocityDispatch_ClearFlag
	bitda_24 3, 267083
	jr z, Voice_Env_VelocityDispatch_c0_NoBit3
	ldb l, 0x0
	jrl Voice_Env_VelocityDispatch_Gate

; Case 0, config bit3 clear: predicate = bit0 of the 0x04134B config byte.
Voice_Env_VelocityDispatch_c0_NoBit3:
	ldb_da a, 0x04134b
	extz wa
	calr BitTest_Bit0_L
	jr Voice_Env_VelocityDispatch_Gate

; Case 1: test bit3 of the 0x04134B config byte.
Voice_Env_VelocityDispatch_c1_Bit1:
	bitda_24 3, 267083
	jr z, Voice_Env_VelocityDispatch_c1_NoBit3
	ldb l, 0x0
	jr Voice_Env_VelocityDispatch_Gate

; Case 1, bit3 clear: predicate = BitTest_Mode2_L of the config byte.
Voice_Env_VelocityDispatch_c1_NoBit3:
	ldb_da a, 0x04134b
	extz wa
	calr BitTest_Mode2_L
	jr Voice_Env_VelocityDispatch_Gate

; Case 2: test bit3 of the per-part byte at 0x04137F + part*0x011F.
Voice_Env_VelocityDispatch_c2:
	ld a, (xsp)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x04137f:24)
	bit_dri 3, 0x07, 0xE4, 0xE0
	jr z, Voice_Env_VelocityDispatch_c2_Trigger
	ldb l, 0x0
	jr Voice_Env_VelocityDispatch_Gate

; Case 2, bit3 clear: predicate = bit0 of that per-part byte.
Voice_Env_VelocityDispatch_c2_Trigger:
	ld a, (xsp)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x04137f:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	calr BitTest_Bit0_L_v2
	jr Voice_Env_VelocityDispatch_Gate

; Case 3: test bit3 of the per-part byte.
Voice_Env_VelocityDispatch_c3:
	ld a, (xsp)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x04137f:24)
	bit_dri 3, 0x07, 0xE4, 0xE0
	jr z, Voice_Env_VelocityDispatch_c3_Trigger
	ldb l, 0x0
	jr Voice_Env_VelocityDispatch_Gate

; Case 3, bit3 clear: predicate = BitTest_Mode2_L of that per-part byte.
Voice_Env_VelocityDispatch_c3_Trigger:
	ld a, (xsp)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x04137f:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	calr BitTest_Mode2_L_v2
	jr Voice_Env_VelocityDispatch_Gate

; Unknown sub-case: predicate = 0.
Voice_Env_VelocityDispatch_ClearFlag:
	ldb l, 0x0

; Gate: if the predicate is non-zero install the program byte via Instrument_LookupProgram_HiNibble (high nibble variant).
Voice_Env_VelocityDispatch_Gate:
	cps l, 0
	jrl z, Voice_Env_ApplyVelocity_Return
	ld a, (xsp)
	extz wa
	calr Instrument_LookupProgram_HiNibble
	jrl Voice_Env_ApplyVelocity_Return

; VELOCITY-SWITCH DISPATCHER, TYPE 2. Identical structure to the type-0/1 dispatcher
; but every flag test uses bit4 instead of bit3, and the gate calls
; Instrument_LookupProgram_LoNibble (low nibble of the patch byte +0x2A).
; Entered only by the A == 2 branch of Voice_Env_ApplyVelocity_Type0.
Voice_Env_ApplyVelocity_Type2:
	cps c, 3
	jr z, Voice_Env_Type2_c3
	cps c, 2
	jr z, Voice_Env_Type2_c2
	cps c, 1
	jr z, Voice_Env_Type2_c1
	cps c, 0
	jrl nz, Voice_Env_Type2_ClearFlag
	bitda_24 4, 267083
	jr z, Voice_Env_Type2_c0_NoBit4
	ldb l, 0x0
	jrl Voice_Env_Type2_Gate

; Case 0, bit4 clear: predicate = bit0 of the 0x04134B config byte.
Voice_Env_Type2_c0_NoBit4:
	ldb_da a, 0x04134b
	extz wa
	calr BitTest_Bit0_L
	jr Voice_Env_Type2_Gate

; Case 1: test bit4 of the 0x04134B config byte.
Voice_Env_Type2_c1:
	bitda_24 4, 267083
	jr z, Voice_Env_Type2_c1_NoBit4
	ldb l, 0x0
	jr Voice_Env_Type2_Gate

; Case 1, bit4 clear: predicate = BitTest_Mode2_L of the config byte.
Voice_Env_Type2_c1_NoBit4:
	ldb_da a, 0x04134b
	extz wa
	calr BitTest_Mode2_L
	jr Voice_Env_Type2_Gate

; Case 2: test bit4 of the per-part byte at 0x04137F + part*0x011F.
Voice_Env_Type2_c2:
	ld a, (xsp)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x04137f:24)
	bit_dri 4, 0x07, 0xE4, 0xE0
	jr z, Voice_Env_Type2_c2_Trigger
	ldb l, 0x0
	jr Voice_Env_Type2_Gate

; Case 2, bit4 clear: predicate = bit0 of that per-part byte.
Voice_Env_Type2_c2_Trigger:
	ld a, (xsp)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x04137f:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	calr BitTest_Bit0_L_v2
	jr Voice_Env_Type2_Gate

; Case 3: test bit4 of the per-part byte.
Voice_Env_Type2_c3:
	ld a, (xsp)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x04137f:24)
	bit_dri 4, 0x07, 0xE4, 0xE0
	jr z, Voice_Env_Type2_c3_Trigger
	ldb l, 0x0
	jr Voice_Env_Type2_Gate

; Case 3, bit4 clear: predicate = BitTest_Mode2_L_v2 of that per-part byte.
Voice_Env_Type2_c3_Trigger:
	ld a, (xsp)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x04137f:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	calr BitTest_Mode2_L_v2
	jr Voice_Env_Type2_Gate

; Unknown sub-case: predicate = 0.
Voice_Env_Type2_ClearFlag:
	ldb l, 0x0

; Gate: install the program byte via Instrument_LookupProgram_LoNibble.
Voice_Env_Type2_Gate:
	cps l, 0
	jr z, Voice_Env_ApplyVelocity_Return
	ld a, (xsp)
	extz wa
	calr Instrument_LookupProgram_LoNibble

; Shared return for both dispatchers.
Voice_Env_ApplyVelocity_Return:
	inc 2, xsp
	ret

; COMPUTE THE PITCH OF ONE VOICE (the main pitch accumulator).
; In: XWA = voice work record. Locals: (XSP+0x08) = record, (XSP+0x02) = (record+0x1F)
; = the pitch/portamento descriptor, (XSP+0x06) = (record+0x04) = part index.
; IZ accumulates the pitch in 8.8 semitone units:
;   start  = ((record+0x05) & 0x7F) * 0x100 + 0x80 + (0x041349)   [key + master tune]
;   += (record+0x23)->[0x16] << 8 and (record+0x23)->[0x6D] << 8   [two transposes]
;   += Pitch_Get_Patch_Octave_Shift(WA = (record+0x04), C = (record+0x13)->[0x29])
; Then ScaleTune_Is_Global_Enabled (0x028D42) decides between the active and inactive paths.
; Active path: bit3 of the u16 at 0x04136A + part*0x011F enables a bend-type switch
;   read through ScaleTune_Get_Global_Mode (0x028B96); 0x80 = octave/keyboard-follow via
;   ScaleTune_Get_User_Offset, 0x40 = fixed offset from (0x041366), 0x41/0x42 = the u16
;   ROM tables at 0x00FCE4 / 0x00FDE4 indexed by the key, 0 = nothing.
; Result is written to (record+0x08) and (record+0x06).
; Callers 0x02B91E, 0x02BEB7.
Voice_Pitch_Compute:
	lda xsp, (xsp - 10)
	pushw iz
	ld (xsp + 8), xwa
	ld xwa, (xsp + 8)
	ld xwa, (xwa + 31)
	ld (xsp + 2), xwa
	ld xwa, (xsp + 8)
	ld a, (xwa + 4)
	ld (xsp + 6), a
	ld xwa, (xsp + 8)
	ld a, (xwa + 5)
	ldb_erp A, 0xF8
	extz iz
	sla iz, 8
	and iz, 0x7F00
	add iz, 0x80
	addda16_24 xiz, 267081
	ld xwa, (xsp + 8)
	ld xwa, (xwa + 35)
	ld a, (xwa + 22)
	exts wa
	sla wa, 8
	add iz, wa
	ld xwa, (xsp + 8)
	ld xwa, (xwa + 35)
	ld a, (xwa + 109)
	exts wa
	sla wa, 8
	add iz, wa
	ld xwa, (xsp + 8)
	ld a, (xwa + 4)
	ld e, a
	extz de
	ld xwa, (xsp + 8)
	ld xwa, (xwa + 19)
	ld a, (xwa + 41)
	ld c, a
	extz bc
	ld wa, de
	calr Pitch_Get_Patch_Octave_Shift
	add iz, hl
	call ScaleTune_Is_Global_Enabled
	cps hl, 0
	jrl z, Voice_Pitch_Compute_Inactive
	ld a, (xsp + 6)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x04136a:24)
	ldw_sri WA, 0x07, 0xE4, 0xE0
	bit 8, wa
	jrl z, Voice_Pitch_ApplyPortamento
	call ScaleTune_Get_Global_Mode
	ld a, l
	cp a, 0x80
	jr z, Voice_Pitch_BendType_Octave
	cp a, 0x42
	jr z, Voice_Pitch_BendType_TableB
	cp a, 0x41
	jr z, Voice_Pitch_BendType_TableA
	cp a, 0x40
	jr z, Voice_Pitch_BendType_Fixed
	cps a, 0
	jrl z, Voice_Pitch_ApplyPortamento

; Bend type 0x80: key/12 selects a channel assignment via ScaleTune_Get_User_Offset (0x028C28), added as whole semitones.
Voice_Pitch_BendType_Octave:
	ld xwa, (xsp + 8)
	ld a, (xwa + 5)
	res 7, a
	extz wa
	div a, 0xC
	ld a, w
	extz wa
	call ScaleTune_Get_User_Offset
	ld a, l
	exts wa
	add wa, wa
	add iz, wa
	jrl Voice_Pitch_ApplyPortamento

; Bend type 0x40: add the fixed global offset word at 0x041366.
Voice_Pitch_BendType_Fixed:
	addda16_24 xiz, 267110
	jrl Voice_Pitch_ApplyPortamento

; Bend type 0x41: add the u16 from the ROM table at 0x00FCE4 indexed by key.
Voice_Pitch_BendType_TableA:
	ld xwa, (xsp + 8)
	ld a, (xwa + 5)
	res 7, a
	extz wa
	add wa, wa
	lda xbc, (0x00fce4:24)
	ldw_sri WA, 0x07, 0xE4, 0xE0
	add iz, wa
	jrl Voice_Pitch_ApplyPortamento

; Bend type 0x42: add the u16 from the ROM table at 0x00FDE4 indexed by key.
Voice_Pitch_BendType_TableB:
	ld xwa, (xsp + 8)
	ld a, (xwa + 5)
	res 7, a
	extz wa
	add wa, wa
	lda xbc, (0x00fde4:24)
	ldw_sri WA, 0x07, 0xE4, 0xE0
	add iz, wa
	jrl Voice_Pitch_ApplyPortamento

; Inactive/non-mono path: the bend type comes from (patch block)->[0x13] where the block pointer is at 0x04136E + part*0x011F.
Voice_Pitch_Compute_Inactive:
	ld a, (xsp + 6)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x04136e:24)
	ld_sril3 XWA, 0x07, 0xE4, 0xE0
	ld l, (xwa + 19)
	ld a, l
	cp a, 0x80
	jrl z, Voice_Pitch_ApplyPortamento
	cp a, 0x42
	jr z, Voice_Pitch_Inactive_BendType_TableB
	cp a, 0x41
	jr z, Voice_Pitch_Inactive_BendType_TableA
	cp a, 0x40
	jr z, Voice_Pitch_Inactive_BendType_Fixed
	cps a, 0
	jr nz, Voice_Pitch_Inactive_BendType_Chromatic
	jr Voice_Pitch_ApplyPortamento

; Inactive, type 0x40: add the fixed offset word at 0x041366.
Voice_Pitch_Inactive_BendType_Fixed:
	addda16_24 xiz, 267110
	jr Voice_Pitch_ApplyPortamento

; Inactive, type 0x41: 0x00FCE4 table lookup by key.
Voice_Pitch_Inactive_BendType_TableA:
	ld xwa, (xsp + 8)
	ld a, (xwa + 5)
	res 7, a
	extz wa
	add wa, wa
	lda xbc, (0x00fce4:24)
	ldw_sri WA, 0x07, 0xE4, 0xE0
	add iz, wa
	jr Voice_Pitch_ApplyPortamento

; Inactive, type 0x42: 0x00FDE4 table lookup by key.
Voice_Pitch_Inactive_BendType_TableB:
	ld xwa, (xsp + 8)
	ld a, (xwa + 5)
	res 7, a
	extz wa
	add wa, wa
	lda xbc, (0x00fde4:24)
	ldw_sri WA, 0x07, 0xE4, 0xE0
	add iz, wa
	jr Voice_Pitch_ApplyPortamento

; Inactive, any other non-zero type: chromatic map - key/12 gives the row, key%12 the column, in the 12-byte-per-row table at 0x011B68; the signed byte is added as whole semitones.
Voice_Pitch_Inactive_BendType_Chromatic:
	ld xwa, (xsp + 8)
	ld a, (xwa + 5)
	res 7, a
	extz wa
	div a, 0xC
	ld a, w
	ld e, a
	extz de
	ld a, l
	extz wa
	muls wa, 0xC
	lda xbc, (0x011b68:24)
	exts xwa
	add xwa, xbc
	ldb_sri A, 0x07, 0xE0, 0xE8
	exts wa
	add wa, wa
	add iz, wa

; PORTAMENTO / GLIDE STAGE. Saturates the accumulator into (record+0x08), then reads
; the glide mode from (record+0x17)->[0x06] & 7. Bit1 of the first byte of the
; portamento descriptor selects the 'active glide' arm; mode 7 means 'jump straight to
; the target'; other modes exponentially approach it by right-shifting the difference
; by (mode & 0x0F).
;
; ⚠ THE TWO ARMS DIFFER IN WHERE THE PITCH CENTRE COMES FROM, and anything that reads
; these descriptors offline has to honour it.
;
;   bit1 CLEAR -> the centre is built from the descriptor's own fields: the root byte at
;                 +0x0B gives pivot = (root << 8) + 0x80, which is subtracted, and the
;                 target offset at +0x0C is added back.
;   bit1 SET   -> the centre is the LITERAL 0x4280, subtracted and added back unchanged
;                 (Voice_Pitch_Portamento_Active_SubBias / _AddBias below), or loaded
;                 outright in mode 7. The descriptor's root and basepitch fields are
;                 NEVER READ on this arm, so their contents are unconstrained.
;
; They are, in fact, junk. Of the 487 multisample SET descriptors, 13 have bit1 set; those
; 13 are exactly the 13 whose root byte is not the universal 0x42, and all 13 carry the
; same impossible basepitch 0x417F. An extractor that computes (basepitch - pivot)
; unconditionally therefore fabricates an offset of +49 to +65 semitones for those SETs --
; 112 of the 1444 selectors the firmware's tables produce, about 7.8%.
;
; That bug shipped in a generated pitch table used by an emulator until 2026-08-19. Three
; independent lines of evidence confirmed the rule: this code path; the junk-field
; correlation above; and a live capture, where the affected selectors decode correctly
; only when the term is dropped (19/19, 1/1, 1/1 against 12/19, 0/1, 0/1).
Voice_Pitch_ApplyPortamento:
	ld wa, iz
	calr Pitch_Saturate_15bit
	ld xwa, (xsp + 8)
	ld (xwa + 8), hl
	ld xwa, (xsp + 8)
	ld xwa, (xwa + 23)
	ld l, (xwa + 6)
	and l, 0x7
	ld xwa, (xsp + 2)
	bitm 1, (xwa)
	jr nz, Voice_Pitch_Portamento_Active_SubBias
	cps l, 7
	jr z, Voice_Pitch_Portamento_Mode7_Direct
	ld xwa, (xsp + 2)
	ld a, (xwa + 11)
	extz wa
	sla wa, 8
	add wa, 0x80
	sub iz, wa
	ld a, l
	and a, 0xF
	jr z, Voice_Pitch_Portamento_Off_AddOffset
	sraa iz

; Glide idle: add the target offset word (descriptor+0x0C).
Voice_Pitch_Portamento_Off_AddOffset:
	ld xwa, (xsp + 2)
	ld wa, (xwa + 12)
	add iz, wa
	jr Voice_Pitch_ApplyFineTune

; Glide mode 7: load the target (descriptor+0x0C) directly, no smoothing.
Voice_Pitch_Portamento_Mode7_Direct:
	ld xwa, (xsp + 2)
	ld iz, (xwa + 12)
	jr Voice_Pitch_ApplyFineTune

; Active glide: work relative to the 0x4280 centre, shift, then restore the bias.
Voice_Pitch_Portamento_Active_SubBias:
	cps l, 7
	jr z, Voice_Pitch_Portamento_Active_SetFixed
	sub iz, 0x4280
	ld a, l
	and a, 0xF
	jr z, Voice_Pitch_Portamento_Active_AddBias
	sraa iz

; Restore the 0x4280 bias after the shift.
Voice_Pitch_Portamento_Active_AddBias:
	add iz, 0x4280
	jr Voice_Pitch_ApplyFineTune

; Active glide, mode 7: snap to the 0x4280 centre.
Voice_Pitch_Portamento_Active_SetFixed:
	ldw iz, 0x4280

; FINE-TUNE STAGE: add (record+0x17)->[0x04] and (record+0x27)->[0x20], both signed and
; scaled by 0x100, then map into the zone's key range - by octave folding
; (Pitch_Fold_Octaves_Into_Range) when the glide mode is 0, or by saturation
; (Pitch_Clamp_Into_Range) otherwise - and store the result in (record+0x06).
Voice_Pitch_ApplyFineTune:
	ld xwa, (xsp + 8)
	ld xwa, (xwa + 23)
	ld a, (xwa + 4)
	exts wa
	sla wa, 8
	add iz, wa
	ld xwa, (xsp + 8)
	ld xwa, (xwa + 39)
	ld a, (xwa + 32)
	exts wa
	sla wa, 8
	add iz, wa
	cps l, 0
	jr nz, Voice_Pitch_ApplyFineTune_LegatoB
	ld xwa, (xsp + 2)
	ld a, (xwa + 9)
	ld c, a
	extz bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 10)
	ld e, a
	extz de
	ld wa, iz
	calr Pitch_Fold_Octaves_Into_Range
	ld xwa, (xsp + 8)
	ld (xwa + 6), hl
	jr Voice_Pitch_Compute_Return

; Non-zero glide mode: clamp into the key range with Pitch_Clamp_Into_Range instead of folding.
Voice_Pitch_ApplyFineTune_LegatoB:
	ld xwa, (xsp + 2)
	ld a, (xwa + 9)
	ld c, a
	extz bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 10)
	ld e, a
	extz de
	ld wa, iz
	calr Pitch_Clamp_Into_Range
	ld xwa, (xsp + 8)
	ld (xwa + 6), hl

; Frame teardown and return.
Voice_Pitch_Compute_Return:
	popw iz
	lda xsp, (xsp + 10)
	ret

; RECOMPUTE THE VOICE'S BASE PITCH FROM THE DESCRIPTOR ONLY (no bend, no glide).
; In: XWA = voice work record. (record+0x1F)->[0x0C] is copied to (record+0x08); the
; signed bytes (record+0x17)->[0x03] (semitones) and ->[0x04] (half-steps of 2) are
; added, and the total is octave-folded into the key range given by the descriptor
; bytes +0x09 / +0x0A before being stored in (record+0x06).
; Callers 0x02B6CD, 0x02C278.
Voice_Pitch_CopyBase:
	push xiz
	ld xiz, xwa
	ld xbc, (xiz + 23)
	ld xwa, (xiz + 31)
	ld hl, (xwa + 12)
	ld (xiz + 8), hl
	ld a, (xbc + 3)
	exts wa
	sla wa, 8
	add hl, wa
	ld a, (xbc + 4)
	exts wa
	add wa, wa
	add hl, wa
	ld xwa, (xiz + 31)
	ld a, (xwa + 9)
	ld c, a
	extz bc
	ld xwa, (xiz + 31)
	ld a, (xwa + 10)
	ld e, a
	extz de
	ld wa, hl
	calr Pitch_Fold_Octaves_Into_Range
	ld (xiz + 6), hl
	pop xiz
	ret

; SELECT AND EMIT THE KEY-ZONE RECORD FOR THE CURRENT PITCH.
; In: XWA = voice work record. XIZ = (record+0x1F) = the zone descriptor.
; Two table pointers are formed by adding the 32-bit DRAM base at 0x045310 to
; (desc+0x01) and (desc+0x05). WaveSel_KeyTable_Lookup turns (record+0x06) - the pitch
; just computed - into a zone number through the first table; the byte at
; (table1 + zone + 4) becomes the record index. Descriptor bits 5, 6 and 7 then select
; one of the six SlotParam_Write_Stride* emitters (record strides 0x0F, 0x0C, 0x0D,
; 0x0A, 0x06 or 4).
; Callers 0x02B4FE, 0x02C0D1, 0x02C3E7.
WaveSel_StageB_Build_Reg040:
	lda xsp, (xsp - 12)
	push xiz
	ld (xsp + 12), xwa
	ld xwa, (xsp + 12)
	ld xiz, (xwa + 31)
	ld xwa, (xiz + 1)
	addda32_24 xwa, 283408
	ld (xsp + 4), xwa
	ld xwa, (xiz + 5)
	addda32_24 xwa, 283408
	ld (xsp + 8), xwa
	ld xwa, (xsp + 4)
	ld xwa, (xwa)
	ld xde, xwa
	addda32_24 xde, 283408
	ld xwa, (xsp + 12)
	ld bc, (xwa + 6)
	ld xwa, xde
	calr WaveSel_KeyTable_Lookup
	ld a, l
	extz wa
	ld bc, wa
	inc 4, bc
	ld xwa, (xsp + 4)
	ldb_sri E, 0x07, 0xE0, 0xE4
	bitm 6, (xiz)
	jr z, Voice_Pitch_Interp_Bit7_NoB6
	bitm 7, (xiz)
	jr z, Voice_Pitch_Interp_Bit7_NoB5
	bitm 5, (xiz)
	jr z, Voice_Pitch_Interp_Bits56
	ld xbc, (xsp + 8)
	extz de
	ld xwa, (xsp + 12)
	calr WaveSel_Emit_ZoneRecord_S15
	jr WaveSel_StageB_Return

; Descriptor bits 7 and 6 set, bit5 clear: stride 0x0C emitter.
Voice_Pitch_Interp_Bits56:
	ld xbc, (xsp + 8)
	extz de
	ld xwa, (xsp + 12)
	calr WaveSel_Emit_ZoneRecord_S12
	jr WaveSel_StageB_Return

; Descriptor bit6 set, bit7 clear: test bit5 to choose stride 0x0D or 0x0A.
Voice_Pitch_Interp_Bit7_NoB5:
	bitm 5, (xiz)
	jr z, Voice_Pitch_Interp_Bits67
	ld xbc, (xsp + 8)
	extz de
	ld xwa, (xsp + 12)
	calr WaveSel_Emit_ZoneRecord_S13
	jr WaveSel_StageB_Return

; Descriptor bits 6 and 7 set, bit5 clear on this arm: stride 0x0A emitter.
Voice_Pitch_Interp_Bits67:
	ld xbc, (xsp + 8)
	extz de
	ld xwa, (xsp + 12)
	calr WaveSel_Emit_ZoneRecord_S10
	jr WaveSel_StageB_Return

; Descriptor bit6 clear: bit7 chooses stride 0x06, otherwise the stride-4 base format.
Voice_Pitch_Interp_Bit7_NoB6:
	bitm 7, (xiz)
	jr z, Voice_Pitch_Interp_Base
	ld xbc, (xsp + 8)
	extz de
	ld xwa, (xsp + 12)
	calr WaveSel_Emit_ZoneRecord_S6
	jr WaveSel_StageB_Return

; No format bits: the stride-4 base emitter.
Voice_Pitch_Interp_Base:
	ld xbc, (xsp + 8)
	extz de
	ld xwa, (xsp + 12)
	calr WaveSel_Emit_ZoneRecord_S4

; Frame teardown and return.
WaveSel_StageB_Return:
	pop xiz
	lda xsp, (xsp + 12)
	ret

; ADVANCE THE MULTI-SAMPLE / FOOTAGE SELECTION AND STORE THE OUTPUT REGISTERS.
; In: XWA = voice work record (kept in XIZ). Base pointer = 0x045310 + (record+0x1F)->
; [0x05]. The state byte (XIZ+0x03) selects the row source:
;   0        -> Voice_Slot_CalcAmpNibble (0x02B154)
;   1 or 2   -> Voice_Slot_FindOctaveOffset (0x02B1E0)
;   >= 3     -> the u16 routing table at (XIZ+0x23) + 0x0102 + state*2
; The result is passed through Voice_KeyIndex_Pack3Nibbles (0x02B2C2) and multiplied by
; 6 to index the record array. Single caller 0x02BCF1.
WaveSel_StageB_Build_Reg040_Footage:
	dec 4, xsp
	push xiz
	ld xiz, xwa
	ld xwa, (xiz + 31)
	ld xwa, (xwa + 5)
	addda32_24 xwa, 283408
	ld (xsp + 4), xwa
	cp (xiz + 3), 0x0
	jr nz, WaveSel_StageB_Build_Reg040_Footage_StateB
	ld a, (xiz + 4)
	ld l, a
	extz hl
	ld a, (xiz)
	ld c, a
	extz bc
	ld a, (xiz + 3)
	ld e, a
	extz de
	ld wa, hl
	call Voice_Slot_CalcAmpNibble
	ld wa, hl
	call Voice_KeyIndex_Pack3Nibbles
	ld wa, hl
	extz xwa
	ld xbc, xwa
	add xbc, xbc
	add xbc, xwa
	add xbc, xbc
	add (xsp + 4), xbc
	jr WaveSel_StageB_Store_Reg040

; State 1 or 2: use Voice_Slot_FindOctaveOffset instead of the amplitude nibble.
WaveSel_StageB_Build_Reg040_Footage_StateB:
	cp (xiz + 3), 0x3
	jr nc, WaveSel_StageB_Build_Reg040_Footage_RoutingTable
	ld a, (xiz + 4)
	ld l, a
	extz hl
	ld a, (xiz)
	ld c, a
	extz bc
	ld a, (xiz + 3)
	ld e, a
	extz de
	ld wa, hl
	call Voice_Slot_FindOctaveOffset
	ld wa, hl
	call Voice_KeyIndex_Pack3Nibbles
	ld wa, hl
	extz xwa
	ld xbc, xwa
	add xbc, xbc
	add xbc, xwa
	add xbc, xbc
	add (xsp + 4), xbc
	jr WaveSel_StageB_Store_Reg040

; State >= 3: take the row directly from the per-patch routing table at (XIZ+0x23)+0x0102.
WaveSel_StageB_Build_Reg040_Footage_RoutingTable:
	ld a, (xiz + 3)
	extz wa
	add wa, wa
	ld bc, wa
	add bc, 0x102
	ld xwa, (xiz + 35)
	ldw_sri HL, 0x07, 0xE0, 0xE4
	ld wa, hl
	extz xwa
	ld xbc, xwa
	add xbc, xbc
	add xbc, xwa
	add xbc, xbc
	add (xsp + 4), xbc

; Store the selected record: pointer to (XIZ+0x0F), type code 0x4000 OR'ed into
; (XIZ+0x01), record word 0 to the staging word 0x0451CE and record word 4 to 0x293E.
; If bit2 of the global audio-mode word at 0x041343 is set the top nibble of 0x0451CE
; is doubled in place (a mode-dependent re-scale of the wave/bank field).
WaveSel_StageB_Store_Reg040:
	ld xwa, (xsp + 4)
	ld (xiz + 15), xwa
	ormi16 (xiz + 1), 0x4000
	ld xwa, (xsp + 4)
	ld wa, (xwa)
	stw_da 0x0451ce, xwa
	ld xwa, (xsp + 4)
	ld wa, (xwa + 4)
	ld (10558:16), wa
	ld wa, (0x041343:24)
	bit 2, wa
	jr z, WaveSel_StageB_Store_Reg040_Return
	ld wa, (0x0451ce:24)
	and wa, 0xF000
	add wa, wa
	anddi16_24 283086, 4095
	ordm16_24 283086, xwa

; Restore and return.
WaveSel_StageB_Store_Reg040_Return:
	pop xiz
	inc 4, xsp
	ret

; SCALE THE MASTER TICK BY A FACTOR AND PUBLISH IT AS THE GLOBAL PITCH OFFSET.
; In: XWA = multiplier. XBC = the 32-bit master tick at 0x1040; FP_MulAccum64 multiplies
; them, the product is >> 2, truncated to 8 bits, multiplied by 0x0D and >> 7, and the
; signed result is stored in the global word at 0x041366 that
; Voice_Pitch_BendType_Fixed reads. Single caller 0x02C940.
Voice_Vol_ScaleVelocityWord:
	ld xbc, (4160:16)
	ld xwa, xbc
	call FP_MulAccum64
	srl xhl, 2
	and xhl, 0xFF
	ld a, l
	exts wa
	muls wa, 0xD
	sra wa, 7
	stw_da 0x041366, xwa
	ret

; COMBINE THE PITCH SOURCES INTO (record+0x0A) AND SET THE 'GLIDE ACTIVE' FLAG.
; In: XWA = voice work record. DE = (record+0x06) + (0x293E) + (record+0x17)->[0x05]*2
;   + (record+0x27)->[0x21] + (record+0x23)->[0x14], stored at (record+0x0A).
; Then bit 0x0400 of (record+0x01) is set only when bit1 of (record+0x23)->[0x0A] AND
; bit5 of (record+0x13)->[0x10] are both set, and cleared otherwise.
; Callers 0x02B504, 0x02BCF7.
Pitch_Apply_Partial_Detune:
	ld de, (xwa + 6)
	addda16 xde, 10558
	ld xbc, (xwa + 23)
	ld c, (xbc + 5)
	exts bc
	add bc, bc
	add de, bc
	ld xbc, (xwa + 39)
	ld c, (xbc + 33)
	exts bc
	add de, bc
	ld xbc, (xwa + 35)
	add de, (xbc + 20)
	ld (xwa + 10), de
	ld xbc, (xwa + 35)
	ld bc, (xbc + 10)
	bit 2, bc
	jr z, Pitch_Apply_Partial_Detune_ClearBit
	ld xbc, (xwa + 19)
	bitm 5, (xbc + 16)
	jr z, Pitch_Apply_Partial_Detune_ClearBit
	ormi16 (xwa + 1), 0x400
	ret

; Conditions not met: clear bit 0x0400 of (record+0x01).
Pitch_Apply_Partial_Detune_ClearBit:
	andmi16 (xwa + 1), 0xFBFF
	ret

; EMIT THE FINAL PITCH REGISTER (primary channel).
; In: XWA = voice work record. DE = (record+0x0A) + the global fine-tune word at
; 0x041347; if bit4 of (record+0x27)->[0x18] is set a detune of (record+0x23)->[0x1D] is
; added or subtracted according to bit5 of the same word; if bit 0x0400 of (record+0x01)
; is set the extra offset at 0x04135A is added. The saturated result goes to the staging
; word at 0x0451DA. Callers 0x028D90, 0x02B50A, 0x02BCFD.
Pitch_Emit_Reg400:
	ld de, (xwa + 10)
	addda16_24 xde, 267079
	ld xbc, (xwa + 39)
	ld bc, (xbc + 24)
	bit 4, bc
	jr z, Voice_Pitch_Legato_StoreOutput
	ld xbc, (xwa + 39)
	ld bc, (xbc + 24)
	bit 5, bc
	jr z, Voice_Pitch_Legato_DetuneDown
	ld xbc, (xwa + 35)
	sub de, (xbc + 29)
	jr Voice_Pitch_Legato_StoreOutput

; Detune downward variant (bit5 clear): add (record+0x23)->[0x1D].
Voice_Pitch_Legato_DetuneDown:
	ld xbc, (xwa + 35)
	add de, (xbc + 29)

; Optional 0x04135A offset when (record+0x01) bit 0x0400 is set.
Voice_Pitch_Legato_StoreOutput:
	ld wa, (xwa + 1)
	bit 10, wa
	jr z, Voice_Pitch_Legato_StoreOutput_Return
	addda16_24 xde, 267098

; Saturate and store to the staging word 0x0451DA.
Voice_Pitch_Legato_StoreOutput_Return:
	ld wa, de
	calr Pitch_Saturate_15bit
	stw_da 0x0451da, xhl
	ret

; Simple pitch combine: (record+0x0A) = (record+0x06) + (0x293E). No detune, no
; register write. Callers 0x02C0D7, 0x02C3F6.
Pitch_Apply_Zone_Trim:
	ld bc, (xwa + 6)
	addda16 xbc, 10558
	ld (xwa + 10), bc
	ret

; EMIT THE FINAL PITCH REGISTER (secondary channel). Same as
; Pitch_Emit_Reg400 minus the 0x04135A offset stage; result also goes
; to 0x0451DA. Callers 0x028DA4, 0x02C0DD, 0x02C3FC.
Voice_Pitch_WriteOutputReg_Secondary:
	ld de, (xwa + 10)
	addda16_24 xde, 267079
	ld xbc, (xwa + 39)
	ld bc, (xbc + 24)
	bit 4, bc
	jr z, Voice_Pitch_Secondary_StoreOutput
	ld xbc, (xwa + 39)
	ld bc, (xbc + 24)
	bit 5, bc
	jr z, Voice_Pitch_Secondary_DetuneDown
	ld xwa, (xwa + 35)
	sub de, (xwa + 29)
	jr Voice_Pitch_Secondary_StoreOutput

; Detune downward variant: add (record+0x23)->[0x1D].
Voice_Pitch_Secondary_DetuneDown:
	ld xwa, (xwa + 35)
	add de, (xwa + 29)

; Saturate and store to 0x0451DA.
Voice_Pitch_Secondary_StoreOutput:
	ld wa, de
	calr Pitch_Saturate_15bit
	stw_da 0x0451da, xhl
	ret

; ENVELOPE 2 -- IC303 registers r0x24 / r0x25 / r0x26 (banks +0x900 / +0x940 / +0x980).
; In: XWA = voice-slot record; XIZ = paramA = the u32 at slot+0x17 (the patch parameter
; block -- NOT the tone record, which is the pointer at slot+0x23). The prologue's
; `ld xwa, (xwa+23)` is DECIMAL 23 = slot+0x17.
; Out: the three staging words 0x0451EC, 0x0451EE, 0x0451F0. Callers 0x02B510 inside
; Voice_Build_Register_Set (0x02B4E3, the type-4 note-on rebuild) and 0x02BD03 inside
; Voice_Release_Type4 (0x02BCD6, the per-tick refresh of a sounding type-4 voice) --
; type-4 voices ONLY. On the type-1/type-2 path this envelope is never built:
; Voice_Init_Type1 / _Type2 call Voice_Level_ClearAllOutputRegs, which zeroes all three
; words instead.
;
; Same word format as envelope 1, (target << 8) | rate, one (target,rate) couple per
; segment, consecutive in the record:
;   seg 0  target Voice_EnvelopeLevel_Curve[paramA+0x09]   low byte from paramA+0x0A
;   seg 1  target Voice_EnvelopeLevel_Curve[paramA+0x0B]   low byte from paramA+0x0C
;   seg 2  target Voice_EnvelopeLevel_Curve[paramA+0x0D]   low byte from paramA+0x0E
; The three targets share one key-scale term, PitchBend_Scale(paramA+0x11, slot+0x0C,
; shift 4), added only when paramA+0x11 != 0, and each is clamped 0..0xFF. Velocity
; modulation is Pan_ScaleWithVelocity(baseline paramA+0x13, limits 0..0x7F, control word
; slot+0x08) with depth paramA+0x14 on segment 0 and paramA+0x15 shared by segments 1/2.
; 0xFF is the silent end of the level curve; 0x04 is the loudest byte 0x0118FE can produce.
;
; [INFERENCE] CALLING THE LOW BYTE A "RATE" HERE IS AN ANALOGY WITH ENVELOPE 1, NOT A
; RESULT. Nothing in this routine or in the hardware documentation identifies the field, and
; two things cut against the reading. (a) The byte is SIGNED here, which collides with the
; "apply now" meaning bit 7 carries in bank +0x800. (b) Voice_Calc_LevelPair_FixedAtk reads
; paramA+0x0A and +0x0C -- the very bytes this routine pushes through Detune_ScaleSymmetric
; -- as UNSIGNED Voice_EnvelopeRate_Table indexes on the type-1/2 path, where this routine
; never runs. (The two agree on the LEVEL bytes +0x09/+0x0B, which _FixedAtk also sends
; through 0x0118FE; only the low-byte reading differs.) So either those bytes are
; voice-type-polymorphic or one of the two readings is wrong.
;
; THE LOW BYTES ARE SIGNED HERE -- that is what separates envelopes 2 and 3 from envelope 1.
; They do NOT pass through Voice_EnvelopeRate_Table; each is (i8)paramA+0x0A / +0x0C / +0x0E
; pushed through Detune_ScaleSymmetric, which clamps |x| to 0x32, looks up Detune_Scale_Curve
; (0x0119C8, 0x00..0x7F) and NEGATES the result for negative inputs, so the byte spans
; -0x7F..+0x7F and has bit 7 SET whenever the parameter is negative. The whole triple is
; negated up front when (i8)paramA+0x07 < 0. A parameter of 0 still comes out as 0, since
; Detune_Scale_Curve[0] = 0.
; [INFERENCE] bit 7 is documented as the "apply now" strobe in bank +0x800. If it means the
; same in +0x900/+0x9C0, a negative parameter raises that strobe as a side effect; the
; alternative is that bit 7 is simply a SIGN in these banks. Nothing in the firmware settles
; it -- no code here ever tests bit 7 of a value it reads back.
;
; MIRROR: envelope 3 (Voice_StereoLevel_Compute, 0x024664) reads the same parameter block
; moved up by exactly 54 bytes. 0x07/0x09/0x0A/0x0B/0x0C/0x0D/0x0E/0x11/0x13/0x14/0x15 map
; onto 0x3D/0x3F/0x40/0x41/0x42/0x43/0x44/0x47/0x49/0x4A/0x4B, 11 for 11, and the per-tick
; writers mirror too (EGB reads 0x0F/0x10/0x16 where EGC reads 0x45/0x46/0x4C) -- 14 distinct
; mirrored offsets in all. The mirror is NOT operation-preserving: at the first pair
; paramA+0x07 is a SIGN FLAG that negates envelope 2's low bytes, while paramA+0x3D is ADDED
; to each of envelope 3's, before a +-0x32 clamp that envelope 2 does not apply.
Voice_Level_ComputeTriplet:
	lda xsp, (xsp - 16)
	push xiz
	ld (xsp + 16), xwa
	ld xwa, (xsp + 16)
	ld xiz, (xwa + 23)
	cp (xiz + 7), 0x0
	jr ge, Voice_Level_Triplet_Positive
	ld a, (xiz + 10)
	exts wa
	cpl wa
	inc 1, wa
	ld (xsp + 4), wa
	ld a, (xiz + 12)
	exts wa
	cpl wa
	inc 1, wa
	ld (xsp + 6), wa
	ld a, (xiz + 14)
	exts wa
	cpl wa
	inc 1, wa
	ld (xsp + 8), wa
	jr Voice_Level_Triplet_ModByEnv

; (patch+0x07) >= 0: take the three detune bytes with their natural sign.
Voice_Level_Triplet_Positive:
	ld a, (xiz + 10)
	exts wa
	ld (xsp + 4), wa
	ld a, (xiz + 12)
	exts wa
	ld (xsp + 6), wa
	ld a, (xiz + 14)
	exts wa
	ld (xsp + 8), wa

; (patch+0x11) != 0: compute the shared envelope-scaled offset via PitchBend_Scale.
Voice_Level_Triplet_ModByEnv:
	cp (xiz + 17), 0x0
	jrl z, Voice_Level_Triplet_Unmodulated
	ld a, (xiz + 17)
	ld e, a
	exts de
	ld xwa, (xsp + 16)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	ld wa, de
	lds de, 4
	calr PitchBend_Scale
	cp (xiz + 9), 0x0
	jr z, Voice_Level_Ch1_Unmodulated
	ld de, hl
	ld a, (xiz + 9)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	add wa, de
	ld (xsp + 10), wa
	jr Voice_Level_Ch2_Modulated

; Channel 1 without the envelope offset.
Voice_Level_Ch1_Unmodulated:
	ld a, (xiz + 9)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld (xsp + 10), wa

; Channel 2 with the envelope offset.
Voice_Level_Ch2_Modulated:
	cp (xiz + 11), 0x0
	jr z, Voice_Level_Ch2_Unmodulated
	ld de, hl
	ld a, (xiz + 11)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	add wa, de
	ld (xsp + 12), wa
	jr Voice_Level_Ch3_Modulated

; Channel 2 without the envelope offset.
Voice_Level_Ch2_Unmodulated:
	ld a, (xiz + 11)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld (xsp + 12), wa

; Channel 3 with the envelope offset.
Voice_Level_Ch3_Modulated:
	cp (xiz + 13), 0x0
	jr z, Voice_Level_Ch3_Unmodulated
	ld a, (xiz + 13)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	add wa, hl
	ld (xsp + 14), wa
	jr Voice_Level_ApplyVelocityMod

; Channel 3 without the envelope offset.
Voice_Level_Ch3_Unmodulated:
	ld a, (xiz + 13)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld (xsp + 14), wa
	jr Voice_Level_ApplyVelocityMod

; (patch+0x11) == 0: all three levels come straight from the 0x0118FE table.
Voice_Level_Triplet_Unmodulated:
	ld a, (xiz + 9)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld (xsp + 10), wa
	ld a, (xiz + 11)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld (xsp + 12), wa
	ld a, (xiz + 13)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld (xsp + 14), wa

; Velocity modulation of channel 1 when (patch+0x14) != 0.
Voice_Level_ApplyVelocityMod:
	cp (xiz + 20), 0x0
	jr z, Voice_Level_PackAndStore
	ld a, (xiz + 19)
	ld c, a
	extz bc
	pushw 0x7F
	ld a, (xiz + 20)
	exts wa
	pushw wa
	ld xwa, (xsp + 20)
	ld wa, (xwa + 8)
	lds de, 0
	calr Pan_ScaleWithVelocity
	add (xsp + 10), hl

; Clamp channel 1 to 0..0xFF, map its detune through Detune_ScaleSymmetric, pack level<<8|detune and store to 0x0451EC; then optionally velocity-modulate channels 2 and 3 via (patch+0x15).
Voice_Level_PackAndStore:
	ld wa, (xsp + 10)
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 10), hl
	ld wa, (xsp + 4)
	calr Detune_ScaleSymmetric
	ld (xsp + 4), hl
	ld wa, (xsp + 4)
	ldb w, 0x0
	ld bc, (xsp + 10)
	sla bc, 8
	or bc, wa
	stw_da 0x0451ec, xbc
	cp (xiz + 21), 0x0
	jr z, Voice_Level_PackAndStore_NoVelocityMod
	ld a, (xiz + 19)
	ld c, a
	extz bc
	pushw 0x7F
	ld a, (xiz + 21)
	exts wa
	pushw wa
	ld xwa, (xsp + 20)
	ld wa, (xwa + 8)
	lds de, 0
	calr Pan_ScaleWithVelocity
	ld iz, hl
	ld wa, (xsp + 12)
	add wa, iz
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 12), hl
	ld wa, (xsp + 14)
	add wa, iz
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 14), hl
	jr Voice_Level_PackSideChannels

; No channel-2/3 velocity modulation: clamp both levels as they are.
Voice_Level_PackAndStore_NoVelocityMod:
	ld wa, (xsp + 12)
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 12), hl
	ld wa, (xsp + 14)
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 14), hl

; Map the channel-2/3 detunes, pack them with their levels and store to 0x0451EE and 0x0451F0.
Voice_Level_PackSideChannels:
	ld wa, (xsp + 6)
	calr Detune_ScaleSymmetric
	ld (xsp + 6), hl
	ld wa, (xsp + 8)
	calr Detune_ScaleSymmetric
	ld (xsp + 8), hl
	ld wa, (xsp + 6)
	ldb w, 0x0
	ld bc, (xsp + 12)
	sla bc, 8
	or bc, wa
	stw_da 0x0451ee, xbc
	ld wa, (xsp + 8)
	ldb w, 0x0
	ld bc, (xsp + 14)
	sla bc, 8
	or bc, wa
	stw_da 0x0451f0, xbc
	pop xiz
	lda xsp, (xsp + 16)
	ret

; FILTER REGISTER BUILDER, MODE 1 (single cutoff + coefficient).
; In: XWA = voice work record; (XSP+0x02) = (record+0x17) = the patch block.
; Cutoff seed = (patch+0x4D) + (record+0x23)->[0x67]; TVF_Calc_Cutoff adds key
; follow ((patch+0x37)) and level scaling ((patch+0x3C)). The slope/mode field
; (patch+0x4E) is shifted left 13 and bit10 is set, then OR'ed with the cutoff to form
; (record+0x42). The second register (record+0x44) is TVF_Bias_Clamp_Amount OR
; TVF_Lookup_Depth_Amount of either the constants 0x48/0x8D (when bit9 of
; (record+0x23)->[0x02] is set) or the patch bytes (patch+0x4F)/(patch+0x50).
; Reached through the mode-1 thunk at 0x02412E of the dispatch table selected by
; (patch+0x36) & 7 - see TVF_Build_Dispatch (0x024102).
TVF_Build_Full:
	dec 8, xsp
	pushw iz
	ld (xsp + 6), xwa
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 23)
	ld (xsp + 2), xwa
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld a, (xwa + 103)
	ld c, a
	exts bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 77)
	ldb_erp A, 0xF8
	extz iz
	add iz, bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 55)
	ld e, a
	exts de
	ld xwa, (xsp + 2)
	ld a, (xwa + 60)
	exts wa
	pushw wa
	ld xwa, (xsp + 8)
	ld bc, iz
	calr TVF_Calc_Cutoff
	ld iz, hl
	ld xwa, (xsp + 2)
	ld a, (xwa + 78)
	extz wa
	sll wa, 13
	ld de, wa
	set 10, de
	ld wa, iz
	ld bc, wa
	or bc, de
	ld xwa, (xsp + 6)
	ld (xwa + 66), bc
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld wa, (xwa + 2)
	bit 9, wa
	jr z, TVF_Build_Full_UseVoiceLUT
	ldw wa, 0x48
	calr TVF_Bias_Clamp_Amount
	ld iz, hl
	ldw wa, 0x8D
	calr TVF_Lookup_Depth_Amount
	ld wa, iz
	ld bc, wa
	or bc, hl
	ld xwa, (xsp + 6)
	ld (xwa + 68), bc
	jr TVF_Build_Full_Return

; Bit9 of (record+0x23)->[0x02] clear: take the resonance/depth pair from (patch+0x4F) and (patch+0x50) instead of the 0x48/0x8D constants.
TVF_Build_Full_UseVoiceLUT:
	ld xwa, (xsp + 2)
	ld a, (xwa + 79)
	extz wa
	calr TVF_Bias_Clamp_Amount
	ld iz, hl
	ld xwa, (xsp + 2)
	ld a, (xwa + 80)
	extz wa
	calr TVF_Lookup_Depth_Amount
	ld wa, iz
	ld bc, wa
	or bc, hl
	ld xwa, (xsp + 6)
	ld (xwa + 68), bc

; Restore and return.
TVF_Build_Full_Return:
	popw iz
	inc 8, xsp
	ret

; FILTER REGISTER BUILDER, MODE 2. Same ingredients as mode 1 but computes the pair
; twice - once with the 0x48/0x8D constants and once from (patch+0x4F)/(patch+0x50) -
; and packs a different bit layout into (record+0x42) / (record+0x44).
; Reached through the thunk at 0x024131.
Voice_PitchPack_Mode2:
	dec 8, xsp
	pushw iz
	ld (xsp + 6), xwa
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 23)
	ld (xsp + 2), xwa
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld wa, (xwa + 2)
	bit 9, wa
	jr z, Voice_PitchPack_Mode2_AltPath
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld a, (xwa + 103)
	ld c, a
	exts bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 77)
	ldb_erp A, 0xF8
	extz iz
	sub iz, bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 55)
	ld e, a
	exts de
	ld xwa, (xsp + 2)
	ld a, (xwa + 60)
	exts wa
	pushw wa
	ld xwa, (xsp + 8)
	ld bc, iz
	calr TVF_Calc_Cutoff
	ld iz, hl
	ld xwa, (xsp + 2)
	ld a, (xwa + 78)
	extz wa
	sll wa, 13
	ld bc, wa
	set 10, bc
	ld wa, iz
	or wa, bc
	ld bc, wa
	set 7, bc
	ld xwa, (xsp + 6)
	ld (xwa + 66), bc
	ldw wa, 0x48
	calr TVF_Bias_Clamp_Amount
	ld iz, hl
	ldw wa, 0x8D
	calr TVF_Lookup_Depth_Amount
	ld wa, iz
	ld bc, wa
	or bc, hl
	ld xwa, (xsp + 6)
	ld (xwa + 68), bc
	jr Voice_PitchPack_Mode2_Return

; Alternate arm taken when bit9 of (record+0x23)->[0x02] is clear.
Voice_PitchPack_Mode2_AltPath:
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld a, (xwa + 103)
	ld c, a
	exts bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 77)
	ldb_erp A, 0xF8
	extz iz
	add iz, bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 55)
	ld e, a
	exts de
	ld xwa, (xsp + 2)
	ld a, (xwa + 60)
	exts wa
	pushw wa
	ld xwa, (xsp + 8)
	ld bc, iz
	calr TVF_Calc_Cutoff
	ld iz, hl
	ld xwa, (xsp + 2)
	ld a, (xwa + 78)
	extz wa
	sll wa, 13
	ld bc, wa
	set 10, bc
	ld wa, iz
	or wa, bc
	ld bc, wa
	set 7, bc
	ld xwa, (xsp + 6)
	ld (xwa + 66), bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 79)
	extz wa
	calr TVF_Bias_Clamp_Amount
	ld iz, hl
	ld xwa, (xsp + 2)
	ld a, (xwa + 80)
	extz wa
	calr TVF_Lookup_Depth_Amount
	ld wa, iz
	ld bc, wa
	or bc, hl
	ld xwa, (xsp + 6)
	ld (xwa + 68), bc

; Restore and return.
Voice_PitchPack_Mode2_Return:
	popw iz
	inc 8, xsp
	ret

; FILTER REGISTER BUILDER, MODE 3. Structurally the same as mode 2 with a third bit
; packing of the cutoff and slope fields. Reached through the thunk at 0x024134.
Voice_PitchPack_Mode3:
	dec 8, xsp
	pushw iz
	ld (xsp + 6), xwa
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 23)
	ld (xsp + 2), xwa
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld wa, (xwa + 2)
	bit 9, wa
	jr z, Voice_PitchPack_Mode3_AltPath
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld a, (xwa + 103)
	ld c, a
	exts bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 77)
	ldb_erp A, 0xF8
	extz iz
	add iz, bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 55)
	ld e, a
	exts de
	ld xwa, (xsp + 2)
	ld a, (xwa + 60)
	exts wa
	pushw wa
	ld xwa, (xsp + 8)
	ld bc, iz
	calr TVF_Calc_Cutoff
	ld iz, hl
	ld xwa, (xsp + 2)
	ld a, (xwa + 78)
	extz wa
	sll wa, 13
	ld de, wa
	set 10, de
	ld wa, iz
	ld bc, wa
	or bc, de
	ld xwa, (xsp + 6)
	ld (xwa + 66), bc
	ldw wa, 0x48
	calr TVF_Bias_Clamp_Amount
	ld iz, hl
	ldw wa, 0x8D
	calr TVF_Lookup_Depth_Amount
	ld wa, iz
	ld bc, wa
	or bc, hl
	ld xwa, (xsp + 6)
	ld (xwa + 68), bc
	jr Voice_PitchPack_Mode3_Return

; Alternate arm taken when bit9 of (record+0x23)->[0x02] is clear.
Voice_PitchPack_Mode3_AltPath:
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld a, (xwa + 103)
	ld c, a
	exts bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 77)
	ldb_erp A, 0xF8
	extz iz
	add iz, bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 55)
	ld e, a
	exts de
	ld xwa, (xsp + 2)
	ld a, (xwa + 60)
	exts wa
	pushw wa
	ld xwa, (xsp + 8)
	ld bc, iz
	calr TVF_Calc_Cutoff
	ld iz, hl
	ld xwa, (xsp + 2)
	ld a, (xwa + 78)
	extz wa
	ld bc, wa
	sll bc, 10
	ld xwa, (xsp + 2)
	ld a, (xwa + 78)
	extz wa
	ld de, wa
	sll de, 13
	or de, bc
	ld wa, iz
	ld bc, wa
	or bc, de
	ld xwa, (xsp + 6)
	ld (xwa + 66), bc
	ld xwa, (xsp + 6)
	ld (xwa + 68), iz
	stdi16 10560, 0

; Restore and return.
Voice_PitchPack_Mode3_Return:
	popw iz
	inc 8, xsp
	ret

; FILTER REGISTER BUILDER, MODE 4 (single-slope form).
; Cutoff = (patch+0x4D), plus (record+0x23)->[0x67] when bit9 of (record+0x23)->[0x02]
; is clear. TVF_Calc_Cutoff applies key follow (patch+0x37) and level scaling
; (patch+0x3C). (patch+0x4E) is placed at both bit10 and bit13, bit7 is forced in both
; registers, and the coefficient global at 0x2940 is cleared.
; Reached through the thunk at 0x024137.
Voice_PitchPack_Mode4_Single:
	dec 4, xsp
	push xiz
	ld (xsp + 4), xwa
	ld xwa, (xsp + 4)
	ld xiz, (xwa + 23)
	ld xwa, (xsp + 4)
	ld xwa, (xwa + 35)
	ld wa, (xwa + 2)
	bit 9, wa
	jr z, Voice_PitchPack_Mode4_AltPath
	ld l, (xiz + 77)
	extz hl
	jr Voice_PitchPack_Mode4_Finalize

; Bit9 clear: add the tone-record offset (record+0x23)->[0x67] to the cutoff seed.
Voice_PitchPack_Mode4_AltPath:
	ld xwa, (xsp + 4)
	ld xwa, (xwa + 35)
	ld a, (xwa + 103)
	exts wa
	ld l, (xiz + 77)
	extz hl
	add hl, wa

; Shared tail: key follow, bit packing into (record+0x42)/(record+0x44), and (0x2940) = 0.
Voice_PitchPack_Mode4_Finalize:
	ld a, (xiz + 55)
	ld e, a
	exts de
	ld a, (xiz + 60)
	exts wa
	pushw wa
	ld xwa, (xsp + 6)
	ld bc, hl
	calr TVF_Calc_Cutoff
	ld a, (xiz + 78)
	extz wa
	ld bc, wa
	sll bc, 10
	ld a, (xiz + 78)
	extz wa
	ld de, wa
	sll de, 13
	or de, bc
	ld wa, hl
	or wa, de
	ld bc, wa
	set 7, bc
	ld xwa, (xsp + 4)
	ld (xwa + 66), bc
	set 7, hl
	ld xwa, (xsp + 4)
	ld (xwa + 68), hl
	stdi16 10560, 0
	pop xiz
	inc 4, xsp
	ret

; FILTER REGISTER BUILDER, MODE 5 (dual cutoff). Reads BOTH (patch+0x4D) and
; (patch+0x4F) as two independent cutoff seeds. Reached through the thunk at 0x02413A,
; which uses 'calr' rather than 'jrl' so this one returns through the dispatcher.
; *** THIS ROUTINE EXTENDS PAST THE END OF THE REGION: its body continues at
; Voice_PitchPack_Mode5_ApplyDetune (0x024069) and
; Voice_PitchPack_Mode5_Finalize (0x024097), which belong to the next region. ***
Voice_PitchPack_Mode5_Dual:
	dec 8, xsp
	push xiz
	ld (xsp + 8), xwa
	ld xwa, (xsp + 8)
	ld xiz, (xwa + 23)
	ld xwa, (xsp + 8)
	ld xwa, (xwa + 35)
	ld wa, (xwa + 2)
	bit 9, wa
	jr z, Voice_PitchPack_Mode5_ApplyDetune
	ld a, (xiz + 77)
	extz wa
	ld (xsp + 4), wa
	ld a, (xiz + 79)
	extz wa
	ld (xsp + 6), wa
	jr Voice_PitchPack_Mode5_Finalize

; Detune arm of Voice_PitchPack_Mode5_Dual: adds the signed byte (tonerec+103) to each of
; the two zero-extended coarse values (tonerec+77, tonerec+79) into the frames at (xsp+4)/(xsp+6).
Voice_PitchPack_Mode5_ApplyDetune:
	ld xwa, (xsp + 8)
	ld xwa, (xwa + 35)
	ld a, (xwa + 103)
	ld c, a
	exts bc
	ld a, (xiz + 77)
	extz wa
	add wa, bc
	ld (xsp + 4), wa
	ld xwa, (xsp + 8)
	ld xwa, (xwa + 35)
	ld a, (xwa + 103)
	ld c, a
	exts bc
	ld a, (xiz + 79)
	extz wa
	add wa, bc
	ld (xsp + 6), wa

; Common tail of pitch-pack mode 5. Runs TVF_Calc_Cutoff twice (once per coarse
; value) then packs word = (tonerec+78)<<13 | (tonerec+78)<<10 | contrib, sets bit 7, and
; stores the pair to voice+66 / voice+68 (later emitted as TG regs 0x100 / 0x140).
; Clears the 16-bit flag at 0x2940 on exit, as every pitch-pack mode does.
Voice_PitchPack_Mode5_Finalize:
	ld a, (xiz + 55)
	ld e, a
	exts de
	ld a, (xiz + 60)
	exts wa
	pushw wa
	ld xwa, (xsp + 10)
	ld bc, (xsp + 6)
	calr TVF_Calc_Cutoff
	ld (xsp + 4), hl
	ld a, (xiz + 55)
	ld e, a
	exts de
	ld a, (xiz + 60)
	exts wa
	pushw wa
	ld xwa, (xsp + 10)
	ld bc, (xsp + 8)
	calr TVF_Calc_Cutoff
	ld (xsp + 6), hl
	ld a, (xiz + 80)
	extz wa
	ld bc, wa
	sll bc, 10
	ld a, (xiz + 78)
	extz wa
	ld de, wa
	sll de, 13
	or de, bc
	ld wa, (xsp + 4)
	or wa, de
	ld bc, wa
	set 7, bc
	ld xwa, (xsp + 8)
	ld (xwa + 66), bc
	ld xwa, (xsp + 8)
	ld bc, (xsp + 6)
	ld (xwa + 68), bc
	stdi16 10560, 0
	pop xiz
	inc 8, xsp
	ret

TVF_Build_Dispatch:
	ld xbc, (xwa + 23)
	ld c, (xbc + 54)
	and c, 0x7
	extz bc
	cps bc, 0
	jr mi, TVF_Build_Dispatch_Table
	cps bc, 5
	jr gt, TVF_Build_Dispatch_Table
	add bc, bc
	lda xix, (0x00f6a7:24)
	ldw_sri BC, 0x07, 0xF0, 0xE4
	lda xix, (0x02412b:24)
	jp_ind 8, 0x07, 0xF0, 0xE4

; Six-entry computed-goto landing pad for TVF_Build_Dispatch. Entry 0 falls through
; to TVF_Set_Bypass (0x022DA1, which sets voice+66=0x017F, voice+68=0x7F7F);
; entries 1..5 reach the mode bodies at 0x023D01, 0x023DB5, 0x023EC2, 0x023FBD, 0x02403D.
; Offsets come from the word table at 0x00F6A7.
TVF_Build_Dispatch_Table:
	jrl TVF_Set_Bypass
	jrl TVF_Build_Full
	jrl Voice_PitchPack_Mode2
	jrl Voice_PitchPack_Mode3
	jrl Voice_PitchPack_Mode4_Single
	calr Voice_PitchPack_Mode5_Dual
	ret

TVF_Build_Short:
	dec 8, xsp
	pushw iz
	ld (xsp + 6), xwa
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 23)
	ld (xsp + 2), xwa
	ld a, (xwa + 17)
	ld c, a
	extz bc
	ld xwa, (xsp + 6)
	calr TVF_Calc_Cutoff_NoKeyFollow
	ld iz, hl
	ld xwa, (xsp + 2)
	ld a, (xwa + 18)
	extz wa
	sll wa, 13
	ld de, wa
	set 10, de
	ld wa, iz
	ld bc, wa
	or bc, de
	ld xwa, (xsp + 6)
	ld (xwa + 66), bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 19)
	extz wa
	calr TVF_Bias_Clamp_Amount
	ld iz, hl
	ld xwa, (xsp + 2)
	ld a, (xwa + 20)
	extz wa
	calr TVF_Lookup_Depth_Amount
	ld wa, iz
	ld bc, wa
	or bc, hl
	ld xwa, (xsp + 6)
	ld (xwa + 68), bc
	popw iz
	inc 8, xsp
	ret

; Pitch-pack route B. In: XWA = per-voice record. Out: voice+66, voice+68.
; Identical to route A (0x02413E) except that bit 7 is additionally set in the reg-0x100
; word. voice+66 = TVF_Calc_Cutoff_NoKeyFollow(tonerec+0x11) | (tonerec+0x12)<<13 | bit10 | bit7;
; voice+68 = TVF_Bias_Clamp_Amount(tonerec+0x13) | TVF_Lookup_Depth_Amount(tonerec+0x14).
; Touches no hardware. Reached only through TVF_BuildEmit_Short_Dispatch's table.
Voice_PitchPack_RouteB:
	dec 8, xsp
	pushw iz
	ld (xsp + 6), xwa
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 23)
	ld (xsp + 2), xwa
	ld a, (xwa + 17)
	ld c, a
	extz bc
	ld xwa, (xsp + 6)
	calr TVF_Calc_Cutoff_NoKeyFollow
	ld iz, hl
	ld xwa, (xsp + 2)
	ld a, (xwa + 18)
	extz wa
	sll wa, 13
	ld bc, wa
	set 10, bc
	ld wa, iz
	or wa, bc
	ld bc, wa
	set 7, bc
	ld xwa, (xsp + 6)
	ld (xwa + 66), bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 19)
	extz wa
	calr TVF_Bias_Clamp_Amount
	ld iz, hl
	ld xwa, (xsp + 2)
	ld a, (xwa + 20)
	extz wa
	calr TVF_Lookup_Depth_Amount
	ld wa, iz
	ld bc, wa
	or bc, hl
	ld xwa, (xsp + 6)
	ld (xwa + 68), bc
	popw iz
	inc 8, xsp
	ret

; Pitch-pack route C. In: XWA = per-voice record; XIZ is loaded with the tone record.
; voice+66 = TVF_Calc_Cutoff_NoKeyFollow(tonerec+0x11) | (tonerec+0x12)<<10 | (tonerec+0x12)<<13;
; voice+68 = the same contrib value unmodified. Clears 0x2940. No bit-7 set (that is what
; distinguishes it from route D).
Voice_PitchPack_RouteC:
	dec 4, xsp
	push xiz
	ld (xsp + 4), xwa
	ld xwa, (xsp + 4)
	ld xiz, (xwa + 23)
	ld a, (xiz + 17)
	ld c, a
	extz bc
	ld xwa, (xsp + 4)
	calr TVF_Calc_Cutoff_NoKeyFollow
	ld a, (xiz + 18)
	extz wa
	ld bc, wa
	sll bc, 10
	ld a, (xiz + 18)
	extz wa
	ld de, wa
	sll de, 13
	or de, bc
	ld wa, hl
	ld bc, wa
	or bc, de
	ld xwa, (xsp + 4)
	ld (xwa + 66), bc
	ld xwa, (xsp + 4)
	ld (xwa + 68), hl
	stdi16 10560, 0
	pop xiz
	inc 4, xsp
	ret

; Pitch-pack route D. Byte-for-byte route C plus `set 7` on BOTH the reg-0x100 and the
; reg-0x140 words before they are stored to voice+66 / voice+68.
Voice_PitchPack_RouteD:
	dec 4, xsp
	push xiz
	ld (xsp + 4), xwa
	ld xwa, (xsp + 4)
	ld xiz, (xwa + 23)
	ld a, (xiz + 17)
	ld c, a
	extz bc
	ld xwa, (xsp + 4)
	calr TVF_Calc_Cutoff_NoKeyFollow
	ld a, (xiz + 18)
	extz wa
	ld bc, wa
	sll bc, 10
	ld a, (xiz + 18)
	extz wa
	ld de, wa
	sll de, 13
	or de, bc
	ld wa, hl
	or wa, de
	ld bc, wa
	set 7, bc
	ld xwa, (xsp + 4)
	ld (xwa + 66), bc
	set 7, hl
	ld xwa, (xsp + 4)
	ld (xwa + 68), hl
	stdi16 10560, 0
	pop xiz
	inc 4, xsp
	ret

; Pitch-pack route E -- the two-source variant. Calls TVF_Calc_Cutoff_NoKeyFollow twice, once
; with tonerec+0x11 and once with tonerec+0x13, so the two TG pitch registers get
; independent coarse values. voice+66 = contrib(0x11) | (tonerec+0x14)<<10 |
; (tonerec+0x12)<<13 | bit7; voice+68 = contrib(0x13). Clears 0x2940.
Voice_PitchPack_RouteE:
	dec 6, xsp
	push xiz
	ld (xsp + 6), xwa
	ld xwa, (xsp + 6)
	ld xiz, (xwa + 23)
	ld a, (xiz + 17)
	ld c, a
	extz bc
	ld xwa, (xsp + 6)
	calr TVF_Calc_Cutoff_NoKeyFollow
	ld (xsp + 4), hl
	ld a, (xiz + 19)
	ld c, a
	extz bc
	ld xwa, (xsp + 6)
	calr TVF_Calc_Cutoff_NoKeyFollow
	ld a, (xiz + 20)
	extz wa
	ld bc, wa
	sll bc, 10
	ld a, (xiz + 18)
	extz wa
	ld de, wa
	sll de, 13
	or de, bc
	ld wa, (xsp + 4)
	or wa, de
	ld bc, wa
	set 7, bc
	ld xwa, (xsp + 6)
	ld (xwa + 66), bc
	ld xwa, (xsp + 6)
	ld (xwa + 68), hl
	stdi16 10560, 0
	pop xiz
	inc 6, xsp
	ret

TVF_BuildEmit_Short_Dispatch:
	push xiz
	ld xiz, xwa
	ld xwa, (xiz + 23)
	ld a, (xwa + 15)
	and a, 0x7
	extz wa
	cps wa, 0
	jr mi, TVF_BuildEmit_Short_Dispatch_Table
	cps wa, 5
	jr gt, TVF_BuildEmit_Short_Dispatch_Table
	add wa, wa
	lda xix, (0x00f6b3:24)
	ldw_sri WA, 0x07, 0xF0, 0xE0
	lda xix, (0x02432c:24)
	jp_ind 8, 0x07, 0xF0, 0xE0

; Landing pad for the dispatcher at 0x024300 (reference name TVF_BuildEmit_Short_Dispatch,
; left alone), which switches on (tonerec+0x0F)&7 using the word table at 0x00F6B3. Case 0
; body is inline here: TVF_Set_Bypass then copy voice+66/voice+68 to
; 0x0451D4/0x0451D6. Cases 1..5 are two-instruction call stubs to TVF_Build_Short..E.
TVF_BuildEmit_Short_Dispatch_Table:
	ld xwa, xiz
	calr TVF_Set_Bypass
	ld wa, (xiz + 66)
	stw_da 0x0451d4, xwa
	ld wa, (xiz + 68)
	stw_da 0x0451d6, xwa
	jr TVF_BuildEmit_Short_Dispatch_Return
	ld xwa, xiz
	calr TVF_Build_Short
	jr TVF_BuildEmit_Short_Dispatch_Return
	ld xwa, xiz
	calr Voice_PitchPack_RouteB
	jr TVF_BuildEmit_Short_Dispatch_Return
	ld xwa, xiz
	calr Voice_PitchPack_RouteC
	jr TVF_BuildEmit_Short_Dispatch_Return
	ld xwa, xiz
	calr Voice_PitchPack_RouteD
	jr TVF_BuildEmit_Short_Dispatch_Return
	ld xwa, xiz
	calr Voice_PitchPack_RouteE

; Shared epilogue: pop XIZ, ret.
TVF_BuildEmit_Short_Dispatch_Return:
	pop xiz
	ret

TVF_Emit_Offset_Reg100:
	push xiz
	ld xiz, xwa
	ld xwa, (xiz + 39)
	ld wa, (xwa + 24)
	bit 6, wa
	jr z, Voice_Pan_Write_AsIs
	ld xwa, (xiz + 39)
	ld wa, (xwa + 24)
	bit 7, wa
	jr z, TVF_Emit_Offset_Reg100_Positive
	ld xwa, (xiz + 35)
	ld a, (xwa + 31)
	exts wa
	ld bc, (xiz + 66)
	and bc, 0x7F
	sub bc, wa
	ld wa, bc
	jr TVF_Emit_Offset_Reg100_Clamp

; Additive arm (bit 7 of ((voice+39)+0x18) clear): field = (voice+66 & 0x7F) + s8(patch+0x1F).
TVF_Emit_Offset_Reg100_Positive:
	ld xwa, (xiz + 35)
	ld a, (xwa + 31)
	exts wa
	ld bc, (xiz + 66)
	and bc, 0x7F
	add bc, wa
	ld wa, bc

; TVF_Clamp_Cutoff the 7-bit field to 0..120, merge under mask 0xFF80 back into voice+66 and
; store to 0x0451D4 (TG reg 0x100).
TVF_Emit_Offset_Reg100_Clamp:
	calr TVF_Clamp_Cutoff
	ld wa, (xiz + 66)
	and wa, 0xFF80
	or wa, hl
	stw_da 0x0451d4, xwa
	jr Voice_Pan_WriteSecondary

; Offset disabled (bit 6 of ((voice+39)+0x18) clear): copy voice+66 to 0x0451D4 unchanged.
Voice_Pan_Write_AsIs:
	ld wa, (xiz + 66)
	stw_da 0x0451d4, xwa

; Common tail: copy voice+68 to 0x0451D6 (TG reg 0x140) unchanged, pop XIZ, ret.
Voice_Pan_WriteSecondary:
	ld wa, (xiz + 68)
	stw_da 0x0451d6, xwa
	pop xiz
	ret

TVF_Emit_Offset_Both:
	push xiz
	ld xiz, xwa
	ld xwa, (xiz + 39)
	ld wa, (xwa + 24)
	bit 6, wa
	jr z, Voice_Pan_WriteBoth_AsIs
	ld xwa, (xiz + 39)
	ld wa, (xwa + 24)
	bit 7, wa
	jr z, Voice_Pan_WriteBoth_Positive
	ld xwa, (xiz + 35)
	ld a, (xwa + 31)
	exts wa
	ld bc, (xiz + 66)
	and bc, 0x7F
	sub bc, wa
	ld hl, bc
	jr Voice_Pan_WriteBoth_Clamp

; Additive arm of the "both registers" variant; result kept in HL for the shared clamp.
Voice_Pan_WriteBoth_Positive:
	ld xwa, (xiz + 35)
	ld a, (xwa + 31)
	exts wa
	ld bc, (xiz + 66)
	and bc, 0x7F
	add bc, wa
	ld hl, bc

; Clamps the shared 7-bit offset once and merges it into BOTH words: voice+66 under 0xFF80
; -> 0x0451D4, voice+68 under 0xFF80 -> 0x0451D6.
Voice_Pan_WriteBoth_Clamp:
	ld wa, hl
	calr TVF_Clamp_Cutoff
	ld wa, hl
	ld bc, (xiz + 66)
	and bc, 0xFF80
	or bc, wa
	stw_da 0x0451d4, xbc
	ld wa, (xiz + 68)
	and wa, 0xFF80
	or wa, hl
	stw_da 0x0451d6, xwa
	jr Voice_Pan_WriteBoth_Return

; Offset disabled: copy voice+66/voice+68 verbatim to 0x0451D4/0x0451D6.
Voice_Pan_WriteBoth_AsIs:
	ld wa, (xiz + 66)
	stw_da 0x0451d4, xwa
	ld wa, (xiz + 68)
	stw_da 0x0451d6, xwa

; pop XIZ, ret.
Voice_Pan_WriteBoth_Return:
	pop xiz
	ret

TVF_Emit_Registers:
	dec 2, xsp
	push xiz
	ld xiz, xwa
	ld xwa, (xiz + 23)
	ld a, (xwa + 54)
	and a, 0x7
	extz wa
	cps wa, 0
	jr mi, TVF_Emit_Registers_Table
	cps wa, 5
	jr gt, TVF_Emit_Registers_Table
	add wa, wa
	lda xix, (0x00f6bf:24)
	ldw_sri WA, 0x07, 0xF0, 0xE0
	lda xix, (0x024472:24)
	jp_ind 8, 0x07, 0xF0, 0xE0

; Six-case landing pad for the (tonerec+54)&7 dispatcher; offsets from the word table at
; 0x00F6BF. Case 0 = verbatim copy of voice+66/+68; case 1 = TVF_Emit_Offset_Reg100;
; case 2 = same but gated on bit 9 of (patch+2); cases 3/4 = TVF_Emit_Offset_Both;
; case 5 = the inline arms below.
TVF_Emit_Registers_Table:
	ld wa, (xiz + 66)
	stw_da 0x0451d4, xwa
	ld wa, (xiz + 68)
	stw_da 0x0451d6, xwa
	jrl TVF_Emit_Registers_Return
	ld xwa, xiz
	calr TVF_Emit_Offset_Reg100
	jrl TVF_Emit_Registers_Return
	ld xwa, (xiz + 35)
	ld wa, (xwa + 2)
	bit 9, wa
	jr z, Voice_PanReg_Dispatch_Mode2_CheckBit9
	ld xwa, xiz
	calr TVF_Emit_Offset_Reg100
	jrl TVF_Emit_Registers_Return

; Bit-9-clear arm of case 2: use the "both registers" offset routine instead.
Voice_PanReg_Dispatch_Mode2_CheckBit9:
	ld xwa, xiz
	calr TVF_Emit_Offset_Both
	jrl TVF_Emit_Registers_Return
	ld xwa, xiz
	calr TVF_Emit_Offset_Both
	jrl TVF_Emit_Registers_Return
	ld xwa, (xiz + 39)
	ld wa, (xwa + 24)
	bit 6, wa
	jrl z, Voice_PanReg_Dispatch_Mode5_AsIs
	ld xwa, (xiz + 39)
	ld wa, (xwa + 24)
	bit 7, wa
	jr z, Voice_PanReg_Dispatch_Mode5_Positive
	ld xwa, (xiz + 35)
	ld a, (xwa + 31)
	exts wa
	ld bc, (xiz + 66)
	and bc, 0x7F
	sub bc, wa
	ld de, bc
	ld xwa, (xiz + 35)
	ld a, (xwa + 31)
	exts wa
	ld bc, (xiz + 68)
	and bc, 0x7F
	sub bc, wa
	ld (xsp + 4), bc
	jr Voice_PanReg_Dispatch_Mode5_Finalize

; Case-5 additive arm: (voice+66 & 0x7F) + s8(patch+0x1F) into DE, (voice+68 & 0x7F) +
; s8(patch+0x1F) into (xsp+4).
Voice_PanReg_Dispatch_Mode5_Positive:
	ld xwa, (xiz + 35)
	ld a, (xwa + 31)
	exts wa
	ld bc, (xiz + 66)
	and bc, 0x7F
	add bc, wa
	ld de, bc
	ld xwa, (xiz + 35)
	ld a, (xwa + 31)
	exts wa
	ld bc, (xiz + 68)
	and bc, 0x7F
	add bc, wa
	ld (xsp + 4), bc

; Clamps both offsets to 0..120 independently, merges each under 0xFF80 and stores to
; 0x0451D4 / 0x0451D6.
Voice_PanReg_Dispatch_Mode5_Finalize:
	ld wa, de
	calr TVF_Clamp_Cutoff
	ld wa, (xiz + 66)
	and wa, 0xFF80
	or wa, hl
	stw_da 0x0451d4, xwa
	ld wa, (xsp + 4)
	calr TVF_Clamp_Cutoff
	ld wa, (xiz + 68)
	and wa, 0xFF80
	or wa, hl
	stw_da 0x0451d6, xwa
	jr TVF_Emit_Registers_Return

; Case-5 with the offset disabled (bit 6 of ((voice+39)+0x18) clear): verbatim copy.
Voice_PanReg_Dispatch_Mode5_AsIs:
	ld wa, (xiz + 66)
	stw_da 0x0451d4, xwa
	ld wa, (xiz + 68)
	stw_da 0x0451d6, xwa

; pop XIZ, inc 2 xsp, ret.
TVF_Emit_Registers_Return:
	pop xiz
	inc 2, xsp
	ret

; Second copy of TVF_Emit_Registers (0x024444), instruction-for-instruction
; identical except that the mode nibble comes from (tonerec+0x0F)&7 instead of
; (tonerec+0x36)&7 and the offset table is 0x00F6CB instead of 0x00F6BF.
; In: XWA = per-voice record. Out: 0x0451D4 (TG reg 0x100), 0x0451D6 (TG reg 0x140).
; The A/B pair mirrors the two independent parameter groups in the tone record
; (cluster {0x0F..0x16} vs cluster {0x36..0x3C,0x4D..0x50}) -- i.e. the two layers/oscillators.
Voice_PanReg_WriteDispatchB:
	dec 2, xsp
	push xiz
	ld xiz, xwa
	ld xwa, (xiz + 23)
	ld a, (xwa + 15)
	and a, 0x7
	extz wa
	cps wa, 0
	jr mi, Voice_PanReg_WriteDispatchB_Table
	cps wa, 5
	jr gt, Voice_PanReg_WriteDispatchB_Table
	add wa, wa
	lda xix, (0x00f6cb:24)
	ldw_sri WA, 0x07, 0xF0, 0xE0
	lda xix, (0x024582:24)
	jp_ind 8, 0x07, 0xF0, 0xE0

; Landing pad for dispatch B; same six cases as 0x024472.
Voice_PanReg_WriteDispatchB_Table:
	ld wa, (xiz + 66)
	stw_da 0x0451d4, xwa
	ld wa, (xiz + 68)
	stw_da 0x0451d6, xwa
	jrl Voice_PanReg_WriteDispatchB_Return
	ld xwa, xiz
	calr TVF_Emit_Offset_Reg100
	jrl Voice_PanReg_WriteDispatchB_Return
	ld xwa, (xiz + 35)
	ld wa, (xwa + 2)
	bit 9, wa
	jr z, Voice_PanReg_DispatchB_Mode2_CheckBit9
	ld xwa, xiz
	calr TVF_Emit_Offset_Reg100
	jrl Voice_PanReg_WriteDispatchB_Return

; Bit-9-clear arm of case 2 in dispatch B.
Voice_PanReg_DispatchB_Mode2_CheckBit9:
	ld xwa, xiz
	calr TVF_Emit_Offset_Both
	jrl Voice_PanReg_WriteDispatchB_Return
	ld xwa, xiz
	calr TVF_Emit_Offset_Both
	jrl Voice_PanReg_WriteDispatchB_Return
	ld xwa, (xiz + 39)
	ld wa, (xwa + 24)
	bit 6, wa
	jrl z, Voice_PanReg_DispatchB_Mode5_AsIs
	ld xwa, (xiz + 39)
	ld wa, (xwa + 24)
	bit 7, wa
	jr z, Voice_PanReg_DispatchB_Mode5_Positive
	ld xwa, (xiz + 35)
	ld a, (xwa + 31)
	exts wa
	ld bc, (xiz + 66)
	and bc, 0x7F
	sub bc, wa
	ld de, bc
	ld xwa, (xiz + 35)
	ld a, (xwa + 31)
	exts wa
	ld bc, (xiz + 68)
	and bc, 0x7F
	sub bc, wa
	ld (xsp + 4), bc
	jr Voice_PanReg_DispatchB_Mode5_Finalize

; Case-5 additive arm in dispatch B.
Voice_PanReg_DispatchB_Mode5_Positive:
	ld xwa, (xiz + 35)
	ld a, (xwa + 31)
	exts wa
	ld bc, (xiz + 66)
	and bc, 0x7F
	add bc, wa
	ld de, bc
	ld xwa, (xiz + 35)
	ld a, (xwa + 31)
	exts wa
	ld bc, (xiz + 68)
	and bc, 0x7F
	add bc, wa
	ld (xsp + 4), bc

; Case-5 clamp-and-emit in dispatch B.
Voice_PanReg_DispatchB_Mode5_Finalize:
	ld wa, de
	calr TVF_Clamp_Cutoff
	ld wa, (xiz + 66)
	and wa, 0xFF80
	or wa, hl
	stw_da 0x0451d4, xwa
	ld wa, (xsp + 4)
	calr TVF_Clamp_Cutoff
	ld wa, (xiz + 68)
	and wa, 0xFF80
	or wa, hl
	stw_da 0x0451d6, xwa
	jr Voice_PanReg_WriteDispatchB_Return

; Case-5 verbatim copy in dispatch B.
Voice_PanReg_DispatchB_Mode5_AsIs:
	ld wa, (xiz + 66)
	stw_da 0x0451d4, xwa
	ld wa, (xiz + 68)
	stw_da 0x0451d6, xwa

; pop XIZ, inc 2 xsp, ret.
Voice_PanReg_WriteDispatchB_Return:
	pop xiz
	inc 2, xsp
	ret

; ENVELOPE 3 -- staged into the words that reach TG banks +0x9C0 / +0xA00 / +0xA40, i.e.
; IC303 registers r0x27 / r0x28 / r0x29.
; In: XWA = voice-slot record. Out: the staging words 0x0451F2, 0x0451F4, 0x0451F6.
; Callers: Voice_Build_Register_Set (0x02B4E3) and Voice_Release_Type4 (0x02BCD6) -- type-4
; voices only; on the type-1/type-2 path Voice_Level_ClearAllOutputRegs zeroes these three
; words instead and this routine never runs.
;
; BASE-RECORD CORRECTION: the record read here is paramA, the u32 at slot+0x17 -- the
; prologue is `ld xwa, (xwa+23)`, and that 23 is DECIMAL (0x17), not 0x23. It is NOT the tone
; record: that is the pointer at slot+0x23 = decimal 35, as
; Voice_Calc_LevelPair_Full_OscTablePath states. Every "tonerec+NN" written in the comments
; from here to Voice_StereoLevel_PackCh23 means paramA+NN, and those NN are decimal.
;
; Word format (target << 8) | rate, one couple per segment:
;   seg 0  target Voice_EnvelopeLevel_Curve[paramA+0x3F]   low byte from paramA+0x40
;   seg 1  target Voice_EnvelopeLevel_Curve[paramA+0x41]   low byte from paramA+0x42
;   seg 2  target Voice_EnvelopeLevel_Curve[paramA+0x43]   low byte from paramA+0x44
; Each low byte = Detune_ScaleSymmetric(clamp((i8)paramA+0x3D + (i8)offset, -0x32..+0x32)),
; so it is SIGNED, -0x7F..+0x7F, exactly as in envelope 2 and unlike envelope 1's unsigned
; Voice_EnvelopeRate_Table lookup. paramA+0x3D is a bias shared by all three segments (and
; by r0x23, which Voice_PortaLevel_Compute builds from paramA+0x3D + paramA+0x3E).
; [INFERENCE] naming that byte a "rate" is an analogy with envelope 1's documented word
; format, not a result -- see the same caveat at Voice_Level_ComputeTriplet.
; Targets take a shared key scale PitchBend_Scale(paramA+0x47, slot+0x0C, shift 4) when
; paramA+0x47 != 0, plus Pan_ScaleWithVelocity(baseline paramA+0x49, limits 0..0x7F,
; control word slot+0x08) with depth paramA+0x4A on segment 0 and paramA+0x4B shared by
; segments 1/2; each is then clamped 0..0xFF. 0xFF is the silent end of the curve.
;
; This parameter block is envelope 2's block moved up 54 bytes (see
; Voice_Level_ComputeTriplet for the 14-offset correspondence), with one role difference:
; paramA+0x07 is a sign flag that NEGATES envelope 2's low bytes, while paramA+0x3D is ADDED
; to envelope 3's before the +-0x32 clamp.
;
; CONFIDENCE MEDIUM, UNCHANGED: everything above is the SOURCE side -- which bytes the
; firmware puts in these words and when. What IC303 does with registers 0x27..0x29 is still
; not proved here; the register meanings in kn5000-docs/tone-generator.md (which reads
; +0x09C0/+0x0A00/+0x0A40 as aux/effect send levels, not as an envelope) are that document's
; reading, and it disagrees with the envelope reading recorded in the staging-block header.
Voice_StereoLevel_Compute:
	lda xsp, (xsp - 14)
	pushw iz
	ld (xsp + 12), xwa
	ld xwa, (xsp + 12)
	ld xwa, (xwa + 23)
	ld (xsp + 2), xwa
	cp (xwa + 71), 0x0
	jrl z, Voice_StereoLevel_AllUnmodulated
	ld xwa, (xsp + 2)
	ld a, (xwa + 71)
	ld e, a
	exts de
	ld xwa, (xsp + 12)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	ld wa, de
	lds de, 4
	calr PitchBend_Scale
	ld xwa, (xsp + 2)
	cp (xwa + 63), 0x0
	jr z, Voice_StereoLevel_Ch1_Unmodulated
	ld de, hl
	ld xwa, (xsp + 2)
	ld a, (xwa + 63)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	add wa, de
	ld (xsp + 6), wa
	jr Voice_StereoLevel_Ch2_Modulated

; Channel-1 level with no key-scaling term: table[0x0118FE + tonerec+63] straight to (xsp+6).
Voice_StereoLevel_Ch1_Unmodulated:
	ld xwa, (xsp + 2)
	ld a, (xwa + 63)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld (xsp + 6), wa

; Channel-2 level plus the key-scaled term still held in HL.
Voice_StereoLevel_Ch2_Modulated:
	ld xwa, (xsp + 2)
	cp (xwa + 65), 0x0
	jr z, Voice_StereoLevel_Ch2_Unmodulated
	ld de, hl
	ld xwa, (xsp + 2)
	ld a, (xwa + 65)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	add wa, de
	ld (xsp + 8), wa
	jr Voice_StereoLevel_Ch3_Modulated

; Channel-2 level, table value only.
Voice_StereoLevel_Ch2_Unmodulated:
	ld xwa, (xsp + 2)
	ld a, (xwa + 65)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld (xsp + 8), wa

; Channel-3 level plus the key-scaled term.
Voice_StereoLevel_Ch3_Modulated:
	ld xwa, (xsp + 2)
	cp (xwa + 67), 0x0
	jr z, Voice_StereoLevel_Ch3_Unmodulated
	ld xwa, (xsp + 2)
	ld a, (xwa + 67)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	add wa, hl
	ld (xsp + 10), wa
	jr Voice_StereoLevel_ApplyTremolo

; Channel-3 level, table value only.
Voice_StereoLevel_Ch3_Unmodulated:
	ld xwa, (xsp + 2)
	ld a, (xwa + 67)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld (xsp + 10), wa
	jr Voice_StereoLevel_ApplyTremolo

; Fast path taken when tonerec+71 == 0: all three levels are plain table lookups.
Voice_StereoLevel_AllUnmodulated:
	ld xwa, (xsp + 2)
	ld a, (xwa + 63)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld (xsp + 6), wa
	ld xwa, (xsp + 2)
	ld a, (xwa + 65)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld (xsp + 8), wa
	ld xwa, (xsp + 2)
	ld a, (xwa + 67)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld (xsp + 10), wa

; If tonerec+74 != 0, adds Pan_ScaleWithVelocity(tonerec+73, 0x7F, s8(tonerec+74),
; (voice+8)) to the channel-1 level.
Voice_StereoLevel_ApplyTremolo:
	ld xwa, (xsp + 2)
	cp (xwa + 74), 0x0
	jr z, Voice_StereoLevel_PackCh1
	ld xwa, (xsp + 2)
	ld a, (xwa + 73)
	ld c, a
	extz bc
	pushw 0x7F
	ld xwa, (xsp + 4)
	ld a, (xwa + 74)
	exts wa
	pushw wa
	ld xwa, (xsp + 16)
	ld wa, (xwa + 8)
	lds de, 0
	calr Pan_ScaleWithVelocity
	add (xsp + 6), hl

; Clamps channel 1 to 0..0xFF, computes the signed low-byte coefficient from
; tonerec+61 + tonerec+64 clamped to -0x32..+0x32 through Detune_ScaleSymmetric, and stores
; (level<<8)|coeff to 0x0451F2 (TG reg 0x9C0). Then optionally applies the tonerec+75
; modulation to channels 2 and 3.
Voice_StereoLevel_PackCh1:
	ld wa, (xsp + 6)
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 6), hl
	ld xwa, (xsp + 2)
	ld a, (xwa + 61)
	ld c, a
	exts bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 64)
	exts wa
	add wa, bc
	ldw bc, 0x32
	ldw de, 0xFFCE
	calr ClampS16_WA_To_DEBC
	ld wa, hl
	calr Detune_ScaleSymmetric
	ldb h, 0x0
	ld wa, (xsp + 6)
	sla wa, 8
	or wa, hl
	stw_da 0x0451f2, xwa
	ld xwa, (xsp + 2)
	cp (xwa + 75), 0x0
	jr z, Voice_StereoLevel_ClampCh23_NoMod
	ld xwa, (xsp + 2)
	ld a, (xwa + 73)
	ld c, a
	extz bc
	pushw 0x7F
	ld xwa, (xsp + 4)
	ld a, (xwa + 75)
	exts wa
	pushw wa
	ld xwa, (xsp + 16)
	ld wa, (xwa + 8)
	lds de, 0
	calr Pan_ScaleWithVelocity
	ld iz, hl
	ld wa, (xsp + 8)
	add wa, iz
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 8), hl
	ld wa, (xsp + 10)
	add wa, iz
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 10), hl
	jr Voice_StereoLevel_PackCh23

; tonerec+75 == 0: clamp channels 2 and 3 to 0..0xFF with no added modulation.
Voice_StereoLevel_ClampCh23_NoMod:
	ld wa, (xsp + 8)
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 8), hl
	ld wa, (xsp + 10)
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 10), hl

; Packs and stores channels 2 and 3 to 0x0451F4 (TG reg 0xA00) and 0x0451F6 (TG reg 0xA40),
; each with its own Detune_ScaleSymmetric coefficient from tonerec+61 + tonerec+66 / +68.
Voice_StereoLevel_PackCh23:
	ld xwa, (xsp + 2)
	ld a, (xwa + 61)
	ld c, a
	exts bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 66)
	exts wa
	add wa, bc
	ldw bc, 0x32
	ldw de, 0xFFCE
	calr ClampS16_WA_To_DEBC
	ld iz, hl
	ld wa, iz
	calr Detune_ScaleSymmetric
	ld iz, hl
	ld xwa, (xsp + 2)
	ld a, (xwa + 61)
	ld c, a
	exts bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 68)
	exts wa
	add wa, bc
	ldw bc, 0x32
	ldw de, 0xFFCE
	calr ClampS16_WA_To_DEBC
	ld wa, hl
	calr Detune_ScaleSymmetric
	ld wa, iz
	ldb w, 0x0
	ld bc, (xsp + 8)
	sla bc, 8
	or bc, wa
	stw_da 0x0451f4, xbc
	ldb h, 0x0
	ld wa, (xsp + 10)
	sla wa, 8
	or wa, hl
	stw_da 0x0451f6, xwa
	popw iz
	lda xsp, (xsp + 14)
	ret

; Builds the pair emitted as TG registers 0x500 (0x0451E2) and 0x8C0 (0x0451EA).
; In: XWA = per-voice record. Sign-splits tonerec+7 and tonerec+8: if tonerec+7 is negative
; both bytes are negated before scaling (Detune_ScaleUnsigned for +7, Detune_ScaleSymmetric
; for +8), so the routine has a mirrored positive arm at 0x024911. The scaled values are
; then combined with tonerec+18 and the note number (voice+12) in the tail.
Voice_PortaLevel_Compute:
	lda xsp, (xsp - 12)
	pushw iz
	ld (xsp + 10), xwa
	ld xwa, (xsp + 10)
	ld xwa, (xwa + 23)
	ld (xsp + 2), xwa
	cp (xwa + 7), 0x0
	jr ge, Voice_PortaLevel_Compute_Positive
	ld xwa, (xsp + 2)
	ld a, (xwa + 7)
	exts wa
	cpl wa
	inc 1, wa
	calr Detune_ScaleUnsigned
	ld (xsp + 8), hl
	ld xwa, (xsp + 2)
	ld a, (xwa + 8)
	exts wa
	cpl wa
	inc 1, wa
	calr Detune_ScaleSymmetric
	ld (xsp + 6), hl
	jr Voice_PortaLevel_ScaleAndPack

; Positive/zero arm: scale tonerec+7 and tonerec+8 directly, no negation.
Voice_PortaLevel_Compute_Positive:
	ld xwa, (xsp + 2)
	ld a, (xwa + 7)
	exts wa
	calr Detune_ScaleUnsigned
	ld (xsp + 8), hl
	ld xwa, (xsp + 2)
	ld a, (xwa + 8)
	exts wa
	calr Detune_ScaleSymmetric
	ld (xsp + 6), hl

; Shared tail: scales by tonerec+18 against the note number, packs and stores the two words
; to 0x0451E2 (TG reg 0x500) and 0x0451EA (TG reg 0x8C0).
Voice_PortaLevel_ScaleAndPack:
	ld xwa, (xsp + 2)
	ld a, (xwa + 18)
	ld e, a
	exts de
	ld xwa, (xsp + 10)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	ld wa, de
	lds de, 6
	calr PitchBend_Scale
	add (xsp + 8), hl
	ld wa, (xsp + 8)
	ldw bc, 0x7F
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 8), hl
	ldw iz, 0x7F
	ld xwa, (xsp + 2)
	ld a, (xwa + 72)
	ld e, a
	exts de
	ld xwa, (xsp + 10)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	ld wa, de
	lds de, 6
	calr PitchBend_Scale
	add iz, hl
	ld wa, iz
	ldw bc, 0x7F
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld iz, hl
	ld wa, iz
	ld bc, wa
	ldb b, 0x0
	ld wa, (xsp + 8)
	sll wa, 8
	or wa, bc
	stw_da 0x0451e2, xwa
	ld xwa, (xsp + 2)
	ld c, (xwa + 61)
	ld xwa, (xsp + 2)
	add c, (xwa + 62)
	ld a, c
	exts wa
	calr Detune_ScaleSymmetric
	ldb h, 0x0
	ld wa, (xsp + 6)
	sll wa, 8
	or wa, hl
	stw_da 0x0451ea, xwa
	popw iz
	lda xsp, (xsp + 12)
	ret

; Zeroes the whole level half of the staging block: 0x0451EA, 0x0451E2, 0x0451EC,
; 0x0451EE, 0x0451F0, 0x0451F2, 0x0451F4, 0x0451F6, 0x0451DC, 0x0451DE (TG regs 0x8C0,
; 0x500, 0x900, 0x940, 0x980, 0x9C0, 0xA00, 0xA40, 0x440, 0x480).
; In: XWA = per-voice record, XHL = its tone record. Then it selects the reg-0x180 value
; from the per-voice routing byte at 0x04138E + channel*0x11F: value 1 -> voice+43 = 0,
; value 2 -> voice+43 = 0x7F, anything else -> voice+43 = tonerec[0]. voice+43 is stored to
; 0x0451D8 (TG reg 0x180) and 0x0451E0 (TG reg 0x4C0) is zeroed.
; NOT teardown-only, and "silence" is not established. The only two callers are
; Voice_Init_Type2 (reached from the Voice_SetVelocity_Type0 / _Type80 note-on paths) and
; Voice_Init_Type1 (reached from Voice_SetPitch and from Voice_NoteOff); there are no
; indirect references. So this runs on every type-1/type-2 parameter rebuild, note-on
; included, and its role there is to leave envelope 1 in sole charge of the level -- those
; voice types never build envelopes 2 and 3 (Voice_Level_ComputeTriplet and
; Voice_StereoLevel_Compute are called only from the type-4 paths).
; [INFERENCE] the value written is 0x0000, which is NOT the firmware's mute word: the mute
; idiom is r0x21 <- 0xFF00 / r0x20 <- 0xFF80, and both level curves put the silent end at
; 0xFF (see the staging-block header). But that evidence covers banks +0x800/+0x840, and
; this routine writes none of them -- it clears +0x8C0, +0x500, +0x900, +0x940, +0x980,
; +0x9C0, +0xA00, +0xA40, +0x440 and +0x480. What 0x0000 means in those banks is unproved:
; under the envelope reading it is a target below the loud end of the curve, while
; kn5000-docs/tone-generator.md reads several of them as effect sends, where 0 = no send.
Voice_Level_ClearAllOutputRegs:
	ld xhl, (xwa + 23)
	stiw_da 0x0451ea, 0x0000
	stiw_da 0x0451e2, 0x0000
	stiw_da 0x0451ec, 0x0000
	stiw_da 0x0451ee, 0x0000
	stiw_da 0x0451f0, 0x0000
	stiw_da 0x0451f2, 0x0000
	stiw_da 0x0451f4, 0x0000
	stiw_da 0x0451f6, 0x0000
	stiw_da 0x0451dc, 0x0000
	stiw_da 0x0451de, 0x0000
	ld c, (xwa + 4)
	extz bc
	muls bc, 0x11F
	lda xde, (0x04138e:24)
	cpib_sri 0x07, 0xE8, 0xE4, 0x01
	jr nz, Voice_Level_ClearAllOutputRegs_Check2
	ldw (xwa + 43), 0x0
	jr Voice_Level_ClearAllOutputRegs_Store

; Second routing-byte comparison (== 2 -> voice+43 = 0x7F).
Voice_Level_ClearAllOutputRegs_Check2:
	ld c, (xwa + 4)
	extz bc
	muls bc, 0x11F
	lda xde, (0x04138e:24)
	cpib_sri 0x07, 0xE8, 0xE4, 0x02
	jr nz, Voice_Level_ClearAllOutputRegs_FromTable
	ldw (xwa + 43), 0x7F
	jr Voice_Level_ClearAllOutputRegs_Store

; Default arm: voice+43 = first byte of the tone record.
Voice_Level_ClearAllOutputRegs_FromTable:
	ld c, (xhl)
	extz bc
	ld (xwa + 43), bc

; Store voice+43 to 0x0451D8 (TG reg 0x180), clear 0x0451E0 (TG reg 0x4C0), ret.
Voice_Level_ClearAllOutputRegs_Store:
	ld wa, (xwa + 43)
	stw_da 0x0451d8, xwa
	stiw_da 0x0451e0, 0x0000
	ret

; Writes one operator/slot's envelope parameters into the physical slot record.
; In: A = channel, E = operator index, C/(xsp+20) = slot number, (xsp+22) = group index,
; XBC = patch record pointer. Computes three bases: 0x04136E + channel*0x11F (per-voice
; operator parameters), 0x041368 + channel*0x11F, and 0x04424E + slot*0x1B (the physical
; slot record, XIZ). Unless the direct path is taken it offsets each parameter by the signed
; bytes at patch+104/105/106 and clamps (0..0x7F, 0..0x7F, 0..0x1E) before storing to
; slotrec+1, +3 and +7.
; The direct/bypass path is chosen when the group index == 2, or the operator index == 0,
; or the byte at 0x0451A7 == 0xF5 (a global "raw parameters" mode flag).
Voice_OpSlot_WriteParams:
	lda xsp, (xsp - 12)
	push xiz
	ld (xsp + 12), xbc
	ld l, (xsp + 22)
	ld c, e
	extz bc
	ld ix, bc
	sla ix, 2
	ld c, l
	extz bc
	sla bc, 4
	ld iy, bc
	add iy, ix
	ld c, a
	extz bc
	muls bc, 0x11F
	lda xix, (0x04136e:24)
	ld_sril3 XBC, 0x07, 0xF0, 0xE4
	lda_dri XBC, 0x07, 0xE4, 0xF4
	ld (xsp + 4), xbc
	ld xbc, 0x2B
	add (xsp + 4), xbc
	ld c, l
	extz bc
	muls bc, 0x9
	ld iy, bc
	ld c, (xsp + 20)
	extz bc
	muls bc, 0x1B
	lda xix, (0x04424e:24)
	exts xbc
	add xbc, xix
	lda_dri XIZ, 0x07, 0xE4, 0xF4
	ld c, e
	extz bc
	ld ix, bc
	sla ix, 2
	ld c, l
	extz bc
	sla bc, 4
	ld iy, bc
	add iy, ix
	extz wa
	muls wa, 0x11F
	lda xbc, (0x041368:24)
	exts xwa
	add xwa, xbc
	lda_dri XWA, 0x07, 0xE0, 0xF4
	ld (xsp + 8), xwa
	ld xwa, 0x27
	add (xsp + 8), xwa
	cps l, 2
	jr z, Voice_OpSlot_WriteParams_Direct
	cps e, 0
	jr nz, Voice_OpSlot_WriteParams_Direct
	cpib_da 0x0451a7, 0xf5
	jr z, Voice_OpSlot_WriteParams_Direct
	ld xwa, (xsp + 12)
	ld a, (xwa + 104)
	ld c, a
	exts bc
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	add wa, bc
	ldw bc, 0x7F
	lds de, 0
	calr ClampS16_WA_Short
	ld (xiz + 1), l
	ld xwa, (xsp + 12)
	ld a, (xwa + 105)
	ld c, a
	exts bc
	ld xwa, (xsp + 4)
	ld a, (xwa + 1)
	extz wa
	add wa, bc
	ldw bc, 0x7F
	lds de, 0
	calr ClampS16_WA_Short
	ld (xiz + 3), l
	ld xwa, (xsp + 12)
	ld a, (xwa + 106)
	ld c, a
	exts bc
	ld xwa, (xsp + 4)
	ld a, (xwa + 3)
	and a, 0x3F
	extz wa
	add wa, bc
	ldw bc, 0x1E
	lds de, 0
	calr ClampS16_WA_Short
	ld (xiz + 7), l
	jr Voice_OpSlot_ApplySustainPedal

; Bypass path: copy the three parameter bytes into slotrec+1/+3/+7 with no patch offset
; and no clamping.
Voice_OpSlot_WriteParams_Direct:
	ld xwa, (xsp + 4)
	ld a, (xwa)
	ld (xiz + 1), a
	ld xwa, (xsp + 4)
	ld a, (xwa + 1)
	ld (xiz + 3), a
	ld xwa, (xsp + 4)
	ld a, (xwa + 3)
	and a, 0x3F
	ld (xiz + 7), a

; If the sustain bit is set in the per-voice flag word, forces the release segment of this
; slot record to the sustain-pedal value instead of the patch value.
Voice_OpSlot_ApplySustainPedal:
	ld xwa, (xsp + 8)
	bitm 1, (xwa)
	jr z, Voice_OpSlot_SustainRelease_Set
	ld xwa, (xsp + 8)
	ld a, (xwa + 3)
	ld (xiz + 2), a
	ld (xiz + 7), 0x0
	jr Voice_OpSlot_ApplySostenuto

; Two-instruction store of the sustain-pedal release value.
Voice_OpSlot_SustainRelease_Set:
	ld (xiz + 2), 0x80

; Same test/override for the sostenuto pedal.
Voice_OpSlot_ApplySostenuto:
	ld xwa, (xsp + 8)
	bitm 3, (xwa)
	jr z, Voice_OpSlot_SostenutoRelease_Set
	ld xwa, (xsp + 8)
	ld a, (xwa + 2)
	ld (xiz + 4), a
	ld (xiz + 7), 0x0
	jr Voice_OpSlot_CopyWaveformBits

; Two-instruction store of the sostenuto release value.
Voice_OpSlot_SostenutoRelease_Set:
	ld (xiz + 4), 0x80

; Copies the waveform-select bits from the patch record into the slot record.
Voice_OpSlot_CopyWaveformBits:
	ld xwa, (xsp + 4)
	bitm 7, (xwa + 2)
	jr z, Voice_OpSlot_ClearWaveformBit5
	setm 5, (xiz)
	jr Voice_OpSlot_PackEnvelopeBits

; Single `res 5` on the waveform byte.
Voice_OpSlot_ClearWaveformBit5:
	resm 5, (xiz)

; Final packing of the envelope-shape bit-field into the slot record; restores XIZ and returns.
Voice_OpSlot_PackEnvelopeBits:
	ld xwa, (xsp + 4)
	ld a, (xwa + 3)
	and a, 0xC0
	extz wa
	srl wa, 6
	andmi8 (xiz), 0xFC
	or (xiz), a
	ld xwa, (xsp + 4)
	ld a, (xwa + 2)
	res 7, a
	ld (xiz + 5), a
	pop xiz
	lda xsp, (xsp + 12)
	retd 0x4

ExtVoice_Build_SlotRegisters:
	lda xsp, (xsp - 22)
	push xiz
	ld (xsp + 22), xwa
	stiw_da 0x0451dc, 0x0000
	stiw_da 0x0451de, 0x0000
	ld xwa, (xsp + 22)
	ld xwa, (xwa + 35)
	ld (xsp + 4), xwa
	ld xwa, (xsp + 22)
	ld xwa, (xwa + 39)
	ld (xsp + 8), xwa
	ld xwa, (xsp + 22)
	ld a, (xwa + 4)
	ld (xsp + 16), a
	ld xwa, (xsp + 22)
	ld a, (xwa + 3)
	ld (xsp + 18), a
	ld xwa, (xsp + 8)
	cpw (xwa + 26), 0x0
	jrl z, Voice_Chan_Fallback_NoWaveTable
	ld xwa, (xsp + 8)
	ld wa, (xwa + 26)
	and a, 0x3
	ld (xsp + 20), a
	extz wa
	sla wa, 2
	ld bc, wa
	add bc, 0x2B
	ld xwa, (xsp + 22)
	ld xwa, (xwa + 19)
	lda_dri XWA, 0x07, 0xE0, 0xE4
	bitm 7, (xwa + 2)
	jr z, ExtVoice_Build_SlotRegisters_NoAlgoSelect
	ld a, (xsp + 16)
	ld l, a
	extz hl
	ld xwa, (xsp + 22)
	ld a, (xwa)
	ld c, a
	extz bc
	ld a, (xsp + 20)
	extz wa
	set 5, wa
	ld e, a
	extz de
	ld wa, hl
	call ExtVoice_Alloc_StreamSlot
	ld (xsp + 12), hl
	ld wa, (xsp + 12)
	ldb w, 0x0
	ld (xsp + 14), wa
	call ToneGen_WriteExtParam_600_Mute
	jr ExtVoice_Store_SlotNumber

; Taken when bit 7 of (partrec+2) is clear: identical ExtVoice_Alloc_StreamSlot call but the group
; index passed in E has bit 5 clear, and ToneGen_WriteExtParam_600_Mute is NOT issued first.
ExtVoice_Build_SlotRegisters_NoAlgoSelect:
	ld a, (xsp + 16)
	ld l, a
	extz hl
	ld xwa, (xsp + 22)
	ld a, (xwa)
	ld c, a
	extz bc
	ld a, (xsp + 20)
	extz wa
	ld e, a
	extz de
	ld wa, hl
	call ExtVoice_Alloc_StreamSlot
	ld (xsp + 12), hl
	ld wa, (xsp + 12)
	ldb w, 0x0
	ld (xsp + 14), wa

ExtVoice_Store_SlotNumber:
	ld wa, (xsp + 14)
	extz xwa
	ld xbc, 0x1B
	call FP_MulAccum64
	lda xiz, (0x04424e:24)
	add xiz, xhl
	ld xwa, (xsp + 22)
	ld a, (xwa + 12)
	res 7, a
	ld (xiz + 6), a
	cpw (xsp + 14), 0x80
	jrl nc, Voice_Chan_SecondaryPitch_Trigger
	ld xwa, (xsp + 8)
	ld wa, (xwa + 26)
	and wa, 0xC0
	or wa, (xsp + 14)
	stw_da 0x0451dc, xwa
	ld wa, (xsp + 12)
	bit 15, wa
	jr z, Voice_Chan_WriteOpSlots
	ld xwa, (xsp + 4)
	ld wa, (xwa)
	and wa, 0xC
	jr z, Voice_Chan_CheckPitchEnvGate

; Calls Voice_OpSlot_WriteParams for the resolved slot, computes the envelope level with
; EGEnv_Compute_A_Simple into 0x045208 (TG reg 0x580), then hands the whole block at
; 0x0451CC to ToneGen_WriteExtParams_56_Alt.
Voice_Chan_WriteOpSlots:
	ld a, (xsp + 16)
	ld c, a
	extz bc
	ld a, (xsp + 20)
	ld e, a
	extz de
	pushw 0x0
	ld wa, (xsp + 16)
	extz wa
	pushw wa
	ld wa, bc
	ld xbc, (xsp + 8)
	calr Voice_OpSlot_WriteParams
	ld wa, (xsp + 14)
	extz wa
	calr EGEnv_Compute_A_Simple
	stw_da 0x045208, xhl
	ld wa, (xsp + 14)
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParams_56_Alt

; Decides whether the pitch-envelope generator has to be re-triggered: slotstate+7 == 0, or
; bit 13 of (partrec+2) set.
Voice_Chan_CheckPitchEnvGate:
	cp (xiz + 7), 0x0
	jr z, Voice_Chan_PitchEnvGate_CheckBit5
	ld xwa, (xsp + 4)
	ld wa, (xwa + 2)
	bit 13, wa
	jr nz, Voice_Chan_PitchEnvGate_Trigger

; Secondary condition: bit 5 of slotstate[0].
Voice_Chan_PitchEnvGate_CheckBit5:
	bitm 5, (xiz)
	jr z, Voice_Chan_PitchEnvFreeRun_Check

; Re-trigger: slotstate+8 = 0, slotstate[0] &= 0xF3 then bit 4 set, 0x04520C (TG reg 0x600)
; = 0, and ToneGen_WriteExtParam_600 emits it.
Voice_Chan_PitchEnvGate_Trigger:
	ld (xiz + 8), 0x0
	andmi8 (xiz), 0xF3
	setm 4, (xiz)
	stiw_da 0x04520c, 0x0000
	ld wa, (xsp + 14)
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParam_600
	jrl Voice_Chan_SecondaryPitch_Trigger

; Free-running arm: slotstate+5 != 0, or bit 15 of the slot word.
Voice_Chan_PitchEnvFreeRun_Check:
	cp (xiz + 5), 0x0
	jr nz, Voice_Chan_PitchEnvFreeRun_Trigger
	ld wa, (xsp + 12)
	bit 15, wa
	jr nz, Voice_Chan_ChokeGroup_Trigger

; Computes the envelope level with EGEnv_Compute_A into 0x04520C (TG reg 0x600) and emits it,
; but only if slotstate[0] & 0x38 == 0.
Voice_Chan_PitchEnvFreeRun_Trigger:
	ld a, (xiz)
	and a, 0x38
	jr nz, Voice_Chan_ChokeGroup_Trigger
	ld wa, (xsp + 14)
	extz wa
	calr EGEnv_Compute_A
	stw_da 0x04520c, xhl
	ld wa, (xsp + 14)
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParam_600
	jrl Voice_Chan_SecondaryPitch_Trigger

; Third trigger arm, gated on (partrec[0] & 0x0C) != 0 -- the exclusive/choke-group bits.
; Same EGEnv_Compute_A -> 0x04520C -> ToneGen_WriteExtParam_600 sequence.
Voice_Chan_ChokeGroup_Trigger:
	ld xwa, (xsp + 4)
	ld wa, (xwa)
	and wa, 0xC
	jrl z, Voice_Chan_SecondaryPitch_Trigger
	ld wa, (xsp + 14)
	extz wa
	calr EGEnv_Compute_A
	stw_da 0x04520c, xhl
	ld wa, (xsp + 14)
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParam_600
	jrl Voice_Chan_SecondaryPitch_Trigger

; Entered when (perfrec+26) == 0, i.e. no wave-table assignment for this channel. Bails out
; entirely unless bit 15 of (partrec+10) is set; otherwise writes a precomputed slot word to
; 0x0451DC (TG reg 0x440).
Voice_Chan_Fallback_NoWaveTable:
	ld xwa, (xsp + 4)
	ld wa, (xwa + 10)
	extz xwa
	bit 15, wa
	jrl z, Voice_Chan_SecondaryPitch_Trigger
	ld a, (xsp + 16)
	ld e, a
	extz de
	ld a, (xsp + 18)
	ld c, a
	extz bc
	ld wa, de
	lds de, 1
	call DSP_AlgoType_Dispatch3
	ld (xsp + 20), hl
	cpw (xsp + 20), 0x0
	jr z, Voice_Chan_SecondaryPitch_Trigger
	ld a, (xsp + 16)
	ld e, a
	extz de
	ld xwa, (xsp + 22)
	ld a, (xwa)
	ld c, a
	extz bc
	ld wa, de
	ldw de, 0xD
	call ExtVoice_Alloc_StreamSlot
	ld (xsp + 12), hl
	ld wa, (xsp + 12)
	ldb w, 0x0
	ld (xsp + 14), wa
	cpw (xsp + 14), 0x80
	jr nc, Voice_Chan_SecondaryPitch_Trigger
	ld wa, (xsp + 14)
	extz wa
	ld bc, wa
	lds wa, 0
	calr NoteState_ClearRecord
	ld wa, (xsp + 12)
	and wa, 0x7F
	or wa, (xsp + 20)
	stw_da 0x0451dc, xwa
	ld wa, (xsp + 12)
	bit 15, wa
	jr z, Voice_Chan_Fallback_WritePrecomputed
	ld xwa, (xsp + 4)
	ld wa, (xwa)
	bit 2, wa
	jr z, Voice_Chan_SecondaryPitch_Trigger

; Stores the precomputed envelope words to 0x04520C (TG reg 0x600) and 0x045208 (TG reg
; 0x580) and emits the block.
Voice_Chan_Fallback_WritePrecomputed:
	ld xwa, (xsp + 4)
	ld wa, (xwa + 91)
	stw_da 0x04520c, xwa
	ld xwa, (xsp + 4)
	ld wa, (xwa + 93)
	stw_da 0x045208, xwa
	ld wa, (xsp + 14)
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParams_56

; Common tail of ExtVoice_Build_SlotRegisters and the also the bail-out target when no slot was
; assigned. Writes the secondary slot word to 0x0451DE (TG reg 0x480).
Voice_Chan_SecondaryPitch_Trigger:
	ld xwa, (xsp + 4)
	ld wa, (xwa + 10)
	extz xwa
	bit 15, wa
	jrl z, ExtVoice_Build_SlotRegisters_Return
	ld a, (xsp + 16)
	ld e, a
	extz de
	ld a, (xsp + 18)
	ld c, a
	extz bc
	ld wa, de
	lds de, 0
	call DSP_AlgoType_Dispatch3
	ld (xsp + 20), hl
	cpw (xsp + 20), 0x0
	jrl z, ExtVoice_Build_SlotRegisters_Return
	ld a, (xsp + 16)
	ld e, a
	extz de
	ld xwa, (xsp + 22)
	ld a, (xwa)
	ld c, a
	extz bc
	ld wa, de
	ldw de, 0xC
	call ExtVoice_Alloc_StreamSlot
	ld (xsp + 12), hl
	ld wa, (xsp + 12)
	ldb w, 0x0
	ld (xsp + 14), wa
	cpw (xsp + 14), 0x80
	jr nc, ExtVoice_Build_SlotRegisters_Return
	ld wa, (xsp + 14)
	or wa, (xsp + 20)
	stw_da 0x0451de, xwa
	ld a, (xsp + 16)
	extz wa
	call AlgoType_AB_Checker
	cps l, 0
	jr nz, Voice_Chan_SecondaryPitch_ComputeDelta
	ld wa, (xsp + 12)
	bit 15, wa
	jr z, Voice_Chan_SecondaryPitch_ComputeDelta
	ld xwa, (xsp + 4)
	ld wa, (xwa)
	bit 2, wa
	jr z, ExtVoice_Build_SlotRegisters_Return

; Computes the secondary pitch delta into 0x04520E, reloads it, derives 0x04520A (TG reg
; 0x5C0) from it and emits the block again.
Voice_Chan_SecondaryPitch_ComputeDelta:
	ld xwa, (xsp + 4)
	ld wa, (xwa + 87)
	stw_da 0x04520e, xwa
	ld iz, (0x04520e:24)
	extz xiz
	and xiz, 0x1FFF
	ld xwa, (xsp + 22)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	ld e, l
	extz de
	ld xwa, xiz
	calr EnvDepth_Cap
	sub xiz, xhl
	anddi16_24 283150, 57344
	ld wa, iz
	ordm16_24 283150, xwa
	ld xwa, (xsp + 4)
	ld wa, (xwa + 89)
	stw_da 0x04520a, xwa
	ld wa, (xsp + 14)
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParams_56b

; pop XIZ, unwind 22 bytes of frame, ret.
ExtVoice_Build_SlotRegisters_Return:
	pop xiz
	lda xsp, (xsp + 22)
	ret

; The sub-voice (second layer) twin of ExtVoice_Build_SlotRegisters. Same shape: read the
; patch/perf pointers out of the per-voice record, select the algorithm group, call
; ExtVoice_Alloc_StreamSlot, then fill the staging block and emit.
; The differences are (a) the group index gets `set 2` rather than `set 5`, and (b) the slot
; record base is 0x044257 (= 0x04424E + 9) with the bound check at 0x40 instead of 0x80.
Voice_SubVoice_ComputeAndTrigger:
	lda xsp, (xsp - 24)
	pushw iz
	ld (xsp + 22), xwa
	ld xwa, (xsp + 22)
	ld xwa, (xwa + 35)
	ld (xsp + 2), xwa
	ld xwa, (xsp + 22)
	ld xwa, (xwa + 39)
	ld (xsp + 6), xwa
	ld xwa, (xsp + 22)
	ld a, (xwa + 4)
	ld (xsp + 18), a
	ld xwa, (xsp + 22)
	ld c, (xwa + 3)
	ldw (xsp + 16), 0x0
	ld xwa, (xsp + 6)
	cpw (xwa + 28), 0x0
	jrl z, Voice1_UpdatePitch_AltEntry
	ld xwa, (xsp + 6)
	ld wa, (xwa + 28)
	and a, 0x3
	ld (xsp + 20), a
	extz wa
	sla wa, 2
	ld bc, wa
	add bc, 0x3B
	ld xwa, (xsp + 22)
	ld xwa, (xwa + 19)
	lda_dri XWA, 0x07, 0xE0, 0xE4
	bitm 7, (xwa + 2)
	jr z, Voice_SubVoice_Compute_NoAlgoSelect
	ld a, (xsp + 18)
	ld l, a
	extz hl
	ld xwa, (xsp + 22)
	ld a, (xwa)
	ld c, a
	extz bc
	ld a, (xsp + 20)
	extz wa
	or wa, 0x24
	ld e, a
	extz de
	ld wa, hl
	call ExtVoice_Alloc_StreamSlot
	ld (xsp + 14), hl
	ld iz, (xsp + 14)
	ldib_erp 0xF9, 0
	ld wa, iz
	call ToneGen_WriteExtParam_540_Mute
	jr Voice_SubVoice_ResolveSlot

; Sub-voice path with algorithm selection disabled.
Voice_SubVoice_Compute_NoAlgoSelect:
	ld a, (xsp + 18)
	ld l, a
	extz hl
	ld xwa, (xsp + 22)
	ld a, (xwa)
	ld c, a
	extz bc
	ld a, (xsp + 20)
	extz wa
	set 2, wa
	ld e, a
	extz de
	ld wa, hl
	call ExtVoice_Alloc_StreamSlot
	ld (xsp + 14), hl
	ld iz, (xsp + 14)
	ldib_erp 0xF9, 0

; XIZ = slot number (high byte force-zeroed). Slot record = 0x044257 + slot*0x1B via
; FP_MulAccum64; stores the note number to slotrec+6 and THEN bounds-checks
; `cp iz,0x40 / jr nc` -- see [UNCERTAIN], the store precedes the check.
Voice_SubVoice_ResolveSlot:
	ld wa, iz
	extz xwa
	ld xbc, 0x1B
	call FP_MulAccum64
	lda xwa, (0x044257:24)
	add xwa, xhl
	ld (xsp + 10), xwa
	ld xwa, (xsp + 22)
	ld xbc, (xsp + 10)
	ld a, (xwa + 12)
	ld (xbc + 6), a
	cp iz, 0x40
	jrl nc, Voice1_UpdatePitch_WriteStereoField
	ld xwa, (xsp + 6)
	ld wa, (xwa + 28)
	and wa, 0xC000
	ld (xsp + 16), wa
	ld wa, iz
	sll wa, 8
	or (xsp + 16), wa
	ld wa, (xsp + 14)
	bit 15, wa
	jr z, Voice1_UpdatePitch_WritePBend
	ld xwa, (xsp + 2)
	ld wa, (xwa)
	and wa, 0xC
	jr z, Voice1_UpdatePitch_CheckSustain

; Layer-1 pitch update: calls Voice_OpSlot_WriteParams for group 1, computes the envelope
; with EGEnv_Compute_B_Simple into 0x045206, and emits the block at 0x0451CC.
Voice1_UpdatePitch_WritePBend:
	ld a, (xsp + 18)
	ld c, a
	extz bc
	ld a, (xsp + 20)
	ld e, a
	extz de
	pushw 0x1
	stb_erp A, 0xF8
	extz wa
	pushw wa
	ld wa, bc
	ld xbc, (xsp + 6)
	calr Voice_OpSlot_WriteParams
	stb_erp A, 0xF8
	extz wa
	calr EGEnv_Compute_B_Simple
	stw_da 0x045206, xhl
	ld wa, iz
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParams_15_Alt

; Tests the per-voice sustain/hold flags before deciding whether the oscillator may be
; deactivated.
Voice1_UpdatePitch_CheckSustain:
	ld xwa, (xsp + 10)
	cp (xwa + 7), 0x0
	jr z, Voice1_UpdatePitch_CheckBit5
	ld xwa, (xsp + 2)
	ld wa, (xwa + 2)
	bit 13, wa
	jr nz, Voice1_UpdatePitch_DeactivateOsc

; Bit-5 test on the slot state byte.
Voice1_UpdatePitch_CheckBit5:
	ld xwa, (xsp + 10)
	bitm 5, (xwa)
	jr z, Voice1_UpdatePitch_CheckPhase

; Clears 0x045204 (TG reg 0x1C0) to zero and emits it via ToneGen_WriteExtParam_1C0_Single
; -- the oscillator-off write.
Voice1_UpdatePitch_DeactivateOsc:
	ld xwa, (xsp + 10)
	ld (xwa + 8), 0x0
	ld xwa, (xsp + 10)
	andmi8 (xwa), 0xF3
	ld xwa, (xsp + 10)
	setm 4, (xwa)
	stiw_da 0x045204, 0x0000
	ld wa, iz
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParam_1C0_Single
	jrl Voice1_UpdatePitch_WriteStereoField

; Phase/segment test that selects between the two frequency-write tails.
Voice1_UpdatePitch_CheckPhase:
	ld xwa, (xsp + 10)
	cp (xwa + 5), 0x0
	jr nz, Voice1_UpdatePitch_CheckStateFlags
	ld wa, (xsp + 14)
	bit 15, wa
	jr nz, Voice1_UpdatePitch_WriteFreq

; State-flag arm: computes the value into 0x045204 (TG reg 0x1C0) and emits.
Voice1_UpdatePitch_CheckStateFlags:
	ld xwa, (xsp + 10)
	ld a, (xwa)
	and a, 0x38
	jr nz, Voice1_UpdatePitch_WriteFreq
	stb_erp A, 0xF8
	extz wa
	calr EGEnv_Compute_B
	stw_da 0x045204, xhl
	ld wa, iz
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParam_1C0_Single
	jrl Voice1_UpdatePitch_WriteStereoField

; Main frequency write: result of Voice_Freq_WriteLeft into 0x045204 (TG reg 0x1C0),
; emitted through ToneGen_WriteExtParam_TypeDispatch_Single.
Voice1_UpdatePitch_WriteFreq:
	ld xwa, (xsp + 2)
	ld wa, (xwa)
	and wa, 0xC
	jrl z, Voice1_UpdatePitch_WriteStereoField
	stb_erp A, 0xF8
	extz wa
	calr EGEnv_Compute_B
	stw_da 0x045204, xhl
	ld wa, iz
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParam_1C0_Single
	jrl Voice1_UpdatePitch_WriteStereoField

; Alternate entry used when the caller already holds the computed frequency.
Voice1_UpdatePitch_AltEntry:
	ld xwa, (xsp + 2)
	ld wa, (xwa + 10)
	extz xwa
	bit 15, wa
	jrl z, Voice1_UpdatePitch_WriteStereoField
	ld a, (xsp + 18)
	extz wa
	extz bc
	call Algo67_LUTOffset_Check
	ld (xsp + 16), hl
	cpw (xsp + 16), 0x0
	jr z, Voice1_UpdatePitch_WriteStereoField
	ld a, (xsp + 18)
	ld e, a
	extz de
	ld xwa, (xsp + 22)
	ld a, (xwa)
	ld c, a
	extz bc
	ld wa, de
	ldw de, 0x10
	call ExtVoice_Alloc_StreamSlot
	ld (xsp + 14), hl
	ld iz, (xsp + 14)
	and iz, 0xFF
	cp iz, 0x40
	jr nc, Voice1_UpdatePitch_WriteStereoField
	stb_erp A, 0xF8
	extz wa
	ld bc, wa
	lds wa, 1
	calr NoteState_ClearRecord
	ld wa, iz
	sll wa, 8
	or (xsp + 16), wa
	ld wa, (xsp + 14)
	bit 15, wa
	jr z, Voice1_UpdatePitch_WriteAltFreq
	ld xwa, (xsp + 2)
	ld wa, (xwa)
	bit 2, wa
	jr z, Voice1_UpdatePitch_WriteStereoField

; Writes both 0x045204 (TG reg 0x1C0) and 0x045206 before emitting.
Voice1_UpdatePitch_WriteAltFreq:
	ld xwa, (xsp + 2)
	ld wa, (xwa + 95)
	stw_da 0x045204, xwa
	ld xwa, (xsp + 2)
	ld wa, (xwa + 97)
	stw_da 0x045206, xwa
	ld wa, iz
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParams_15

; Shared tail (also the no-slot bail-out target of Voice_SubVoice_ResolveSlot). Reads the
; per-voice routing byte at 0x04138E + channel*0x11F to pick the reg-0x180 value.
Voice1_UpdatePitch_WriteStereoField:
	ld xwa, (xsp + 22)
	ld a, (xwa + 4)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x04138e:24)
	cpib_sri 0x07, 0xE4, 0xE0, 0x01
	jr nz, Voice1_UpdatePitch_StereoPart2
	ld bc, (xsp + 16)
	ld xwa, (xsp + 22)
	ld (xwa + 43), bc
	jr Voice1_UpdatePitch_StoreStereo

; Second routing-byte comparison arm.
Voice1_UpdatePitch_StereoPart2:
	ld xwa, (xsp + 22)
	ld a, (xwa + 4)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x04138e:24)
	cpib_sri 0x07, 0xE4, 0xE0, 0x02
	jr nz, Voice1_UpdatePitch_StereoFallthrough
	ld bc, (xsp + 16)
	or bc, 0x7F
	ld xwa, (xsp + 22)
	ld (xwa + 43), bc
	jr Voice1_UpdatePitch_StoreStereo

; Default arm of the routing selection.
Voice1_UpdatePitch_StereoFallthrough:
	ld xwa, (xsp + 6)
	ld a, (xwa + 35)
	extz wa
	ld bc, wa
	or bc, (xsp + 16)
	ld xwa, (xsp + 22)
	ld (xwa + 43), bc

; Stores the selected value to 0x0451D8 (TG reg 0x180) and returns.
Voice1_UpdatePitch_StoreStereo:
	ld xwa, (xsp + 22)
	ld wa, (xwa + 43)
	stw_da 0x0451d8, xwa
	popw iz
	lda xsp, (xsp + 24)
	ret

; Layer-2 twin of the Voice1_UpdatePitch family. Seeds 0x0451E0 (TG reg 0x4C0) with the
; constant 0x4400, then follows the same deactivate / phase / frequency structure.
; In: XWA = per-voice record. Touches only the staging block; emission is via the
; ToneGen_WriteExtParam_* helpers.
Voice2_UpdatePitch:
	lda xsp, (xsp - 22)
	pushw iz
	ld (xsp + 20), xwa
	stiw_da 0x0451e0, 0x4400
	ld xwa, (xsp + 20)
	ld xwa, (xwa + 35)
	ld (xsp + 2), xwa
	ld xwa, (xsp + 20)
	ld xwa, (xwa + 39)
	ld (xsp + 6), xwa
	ld xwa, (xsp + 20)
	ld a, (xwa + 4)
	ld (xsp + 16), a
	ld xwa, (xsp + 6)
	cpw (xwa + 30), 0x0
	jrl z, Voice2_UpdatePitch_Done
	ld xwa, (xsp + 6)
	ld wa, (xwa + 30)
	and a, 0x3
	ld (xsp + 18), a
	extz wa
	sla wa, 2
	ld bc, wa
	add bc, 0x4B
	ld xwa, (xsp + 20)
	ld xwa, (xwa + 19)
	lda_dri XWA, 0x07, 0xE0, 0xE4
	bitm 7, (xwa + 2)
	jr z, Voice2_UpdatePitch_NoOsc7Flag
	ld a, (xsp + 16)
	ld l, a
	extz hl
	ld xwa, (xsp + 20)
	ld a, (xwa)
	ld c, a
	extz bc
	ld a, (xsp + 18)
	extz wa
	or wa, 0x28
	ld e, a
	extz de
	ld wa, hl
	call ExtVoice_Alloc_StreamSlot
	ld (xsp + 14), hl
	ld iz, (xsp + 14)
	ldib_erp 0xF9, 0
	ld wa, iz
	call ToneGen_WriteExtParam_Mute_TypeDispatch
	jr Voice2_UpdatePitch_ChanEntry

; Arm taken when the oscillator-7 flag is clear.
Voice2_UpdatePitch_NoOsc7Flag:
	ld a, (xsp + 16)
	ld l, a
	extz hl
	ld xwa, (xsp + 20)
	ld a, (xwa)
	ld c, a
	extz bc
	ld a, (xsp + 18)
	extz wa
	set 3, wa
	ld e, a
	extz de
	ld wa, hl
	call ExtVoice_Alloc_StreamSlot
	ld (xsp + 14), hl
	ld iz, (xsp + 14)
	ldib_erp 0xF9, 0

; Channel-indexed entry; reads the per-channel table at 0x044260 (= 0x04424E + 18).
Voice2_UpdatePitch_ChanEntry:
	ld wa, iz
	extz xwa
	ld xbc, 0x1B
	call FP_MulAccum64
	lda xwa, (0x044260:24)
	add xwa, xhl
	ld (xsp + 10), xwa
	ld xwa, (xsp + 20)
	ld xbc, (xsp + 10)
	ld a, (xwa + 12)
	ld (xbc + 6), a
	cp iz, 0x80
	jrl nc, Voice2_UpdatePitch_Done
	ld xwa, (xsp + 6)
	ld wa, (xwa + 30)
	and wa, 0x3300
	or wa, iz
	ordm16_24 283104, xwa
	ld wa, (xsp + 14)
	bit 15, wa
	jr z, Voice2_UpdatePitch_WritePBend
	ld xwa, (xsp + 2)
	ld wa, (xwa)
	and wa, 0xC
	jr z, Voice2_UpdatePitch_CheckSustain

; Layer-2 equivalent of 0x025051: fill and emit the block at 0x0451CC.
Voice2_UpdatePitch_WritePBend:
	ld a, (xsp + 16)
	ld c, a
	extz bc
	ld a, (xsp + 18)
	ld e, a
	extz de
	pushw 0x2
	stb_erp A, 0xF8
	extz wa
	pushw wa
	ld wa, bc
	ld xbc, (xsp + 6)
	calr Voice_OpSlot_WriteParams
	stb_erp A, 0xF8
	extz wa
	calr Voice_Freq_WriteRight
	ld wa, iz
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParams_TypeDispatch

; Sustain/hold test before oscillator deactivation.
Voice2_UpdatePitch_CheckSustain:
	ld xwa, (xsp + 10)
	cp (xwa + 7), 0x0
	jr z, Voice2_UpdatePitch_CheckBit5
	ld xwa, (xsp + 2)
	ld wa, (xwa + 2)
	bit 13, wa
	jr nz, Voice2_UpdatePitch_DeactivateOsc

; Bit-5 test on the slot state byte.
Voice2_UpdatePitch_CheckBit5:
	ld xwa, (xsp + 10)
	bitm 5, (xwa)
	jr z, Voice2_UpdatePitch_CheckPhase

; Clears both 0x045204 (TG reg 0x1C0) and 0x04520E, then emits -- layer-2 oscillator off.
Voice2_UpdatePitch_DeactivateOsc:
	ld xwa, (xsp + 10)
	ld (xwa + 8), 0x0
	ld xwa, (xsp + 10)
	andmi8 (xwa), 0xF3
	ld xwa, (xsp + 10)
	setm 4, (xwa)
	stiw_da 0x045204, 0x0000
	stiw_da 0x04520e, 0x0000
	ld wa, iz
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParam_TypeDispatch_Single
	jr Voice2_UpdatePitch_Done

; Phase/segment test.
Voice2_UpdatePitch_CheckPhase:
	ld xwa, (xsp + 10)
	cp (xwa + 5), 0x0
	jr nz, Voice2_UpdatePitch_CheckStateFlags
	ld wa, (xsp + 14)
	bit 15, wa
	jr nz, Voice2_UpdatePitch_WriteFreq

; State-flag arm; emits the block.
Voice2_UpdatePitch_CheckStateFlags:
	ld xwa, (xsp + 10)
	ld a, (xwa)
	and a, 0x38
	jr nz, Voice2_UpdatePitch_WriteFreq
	stb_erp A, 0xF8
	extz wa
	calr Voice_Freq_WriteLeft
	ld wa, iz
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParam_TypeDispatch_Single
	jr Voice2_UpdatePitch_Done

; Layer-2 frequency write and emit.
Voice2_UpdatePitch_WriteFreq:
	ld xwa, (xsp + 2)
	ld wa, (xwa)
	and wa, 0xC
	jr z, Voice2_UpdatePitch_Done
	stb_erp A, 0xF8
	extz wa
	calr Voice_Freq_WriteLeft
	ld wa, iz
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParam_TypeDispatch_Single

; Frame unwind and ret.
Voice2_UpdatePitch_Done:
	popw iz
	lda xsp, (xsp + 22)
	ret

Level_Build_Reg0C0:
	ld xbc, (xwa + 35)
	cp (xbc + 15), 0x0
	jr z, Level_Build_Reg0C0_ZeroCoarse
	ld xbc, (xwa + 35)
	cp (xbc + 18), 0x0
	jr z, Level_Build_Reg0C0_ZeroCoarse
	ldb_da c, 0x04134c
	cps c, 6
	jr nz, Level_Build_Reg0C0_UseCoarse
	lds de, 0
	jr Level_Build_Reg0C0_ApplyDetune

; Global mode byte 0x04134C != 6: DE = zext(patchrec+15).
Level_Build_Reg0C0_UseCoarse:
	ld xbc, (xwa + 35)
	ld c, (xbc + 15)
	extz bc
	ld de, bc
	jr Level_Build_Reg0C0_ApplyDetune

; Entered when patchrec+15 == 0 or patchrec+18 == 0; DE = zext(patchrec+15) regardless of
; the global mode.
Level_Build_Reg0C0_ZeroCoarse:
	ld xbc, (xwa + 35)
	ld c, (xbc + 15)
	extz bc
	ld de, bc

; If DE != 0: DE += (partrec+92) - 0x40, DE += s8(patchrec+102); negative results are floored
; to 0.
Level_Build_Reg0C0_ApplyDetune:
	cps de, 0
	jr z, Level_Build_Reg0C0_CheckExpr
	ld xbc, (xwa + 19)
	ld c, (xbc + 92)
	extz bc
	sub bc, 0x40
	add de, bc
	ld xbc, (xwa + 35)
	ld c, (xbc + 102)
	exts bc
	add de, bc
	jr ge, Level_Build_Reg0C0_ClampHigh
	lds de, 0
	jr Level_Build_Reg0C0_ShiftLeft

; Ceiling at 0x7F.
Level_Build_Reg0C0_ClampHigh:
	cp de, 0x7F
	jr le, Level_Build_Reg0C0_ShiftLeft
	ldw de, 0x7F

; `sla de, 8` -- the high byte of the reg-0x0C0 word is this 7-bit field.
Level_Build_Reg0C0_ShiftLeft:
	sla de, 8

; Selects the low byte: patchrec+18 == 0 -> use patchrec+18 (i.e. 0); global mode 5 or 6 ->
; force 0x7F; otherwise use patchrec+18.
Level_Build_Reg0C0_CheckExpr:
	ld xbc, (xwa + 35)
	cp (xbc + 18), 0x0
	jr z, Level_Build_Reg0C0_NoExpr
	ldb_da c, 0x04134c
	cps c, 6
	jr z, Level_Build_Reg0C0_FullExpr
	cps c, 5
	jr nz, Level_Build_Reg0C0_PartialExpr

; `or de, 0x7F` -- low byte forced to maximum.
Level_Build_Reg0C0_FullExpr:
	or de, 0x7F
	jr Level_Build_Reg0C0_Write

; Low byte = patchrec+18.
Level_Build_Reg0C0_PartialExpr:
	ld xwa, (xwa + 35)
	ld a, (xwa + 18)
	extz wa
	or de, wa
	jr Level_Build_Reg0C0_Write

; Low byte = patchrec+18 (reached with the high field left at 0).
Level_Build_Reg0C0_NoExpr:
	ld xwa, (xwa + 35)
	ld a, (xwa + 18)
	extz wa
	or de, wa

; Stores DE to 0x0451D2 (TG reg 0x0C0) and returns.
Level_Build_Reg0C0_Write:
	stw_da 0x0451d2, xde
	ret

; Second copy of the routine at 0x0253FE, differing only in that it pre-loads the part
; record pointer (voice+19) into XHL on entry and uses it directly for the +92 term rather
; than re-loading it. Same output: 0x0451D2 (TG reg 0x0C0).
Voice_ComputePitchBend2:
	ld xhl, (xwa + 19)
	ld xbc, (xwa + 35)
	cp (xbc + 15), 0x0
	jr z, Voice_ComputePitchBend2_ZeroCoarse
	ld xbc, (xwa + 35)
	cp (xbc + 18), 0x0
	jr z, Voice_ComputePitchBend2_ZeroCoarse
	ldb_da c, 0x04134c
	cps c, 6
	jr nz, Voice_ComputePitchBend2_UseCoarse
	lds de, 0
	jr Voice_ComputePitchBend2_ApplyDetune

; As 0x02541D.
Voice_ComputePitchBend2_UseCoarse:
	ld xbc, (xwa + 35)
	ld c, (xbc + 15)
	extz bc
	ld de, bc
	jr Voice_ComputePitchBend2_ApplyDetune

; As 0x025429.
Voice_ComputePitchBend2_ZeroCoarse:
	ld xbc, (xwa + 35)
	ld c, (xbc + 15)
	extz bc
	ld de, bc

; As 0x025433.
Voice_ComputePitchBend2_ApplyDetune:
	cps de, 0
	jr z, Voice_ComputePitchBend2_CheckExpr
	ld c, (xhl + 15)
	extz bc
	sub bc, 0x40
	add de, bc
	jr ge, Voice_ComputePitchBend2_ClampHigh
	lds de, 0
	jr Voice_ComputePitchBend2_ShiftLeft

; As 0x025455.
Voice_ComputePitchBend2_ClampHigh:
	cp de, 0x7F
	jr le, Voice_ComputePitchBend2_ShiftLeft
	ldw de, 0x7F

; As 0x02545E.
Voice_ComputePitchBend2_ShiftLeft:
	sla de, 8

; As 0x025461.
Voice_ComputePitchBend2_CheckExpr:
	ld xbc, (xwa + 35)
	cp (xbc + 18), 0x0
	jr z, Voice_ComputePitchBend2_NoExpr
	ldb_da c, 0x04134c
	cps c, 6
	jr z, Voice_ComputePitchBend2_FullExpr
	cps c, 5
	jr nz, Voice_ComputePitchBend2_PartialExpr

; As 0x025477.
Voice_ComputePitchBend2_FullExpr:
	or de, 0x7F
	jr Voice_ComputePitchBend2_Write

; As 0x02547D.
Voice_ComputePitchBend2_PartialExpr:
	ld xwa, (xwa + 35)
	ld a, (xwa + 18)
	extz wa
	or de, wa
	jr Voice_ComputePitchBend2_Write

; As 0x025489.
Voice_ComputePitchBend2_NoExpr:
	ld xwa, (xwa + 35)
	ld a, (xwa + 18)
	extz wa
	or de, wa

; Stores DE to 0x0451D2 (TG reg 0x0C0) and returns.
Voice_ComputePitchBend2_Write:
	stw_da 0x0451d2, xde
	ret

Voice_Apply_GateRouting:
	ld e, a
	extz de
	muls de, 0x11F
	lda xhl, (0x04138d:24)
	ldb_sri E, 0x07, 0xEC, 0xE8
	and e, 0xF
	cps e, 1
	jr z, Voice_Apply_GateRouting_HighNibble
	cps e, 2
	jr z, Voice_Apply_GateRouting_Mode2
	cps e, 0
	jr nz, Voice_Apply_GateRouting_HighNibble
	or bc, 0xE00
	jr Voice_Apply_GateRouting_HighNibble

; Low-nibble routing value 2: `and bc,0xF1FF` then `set 9,bc` -- forces the [11:9] field to 1.
Voice_Apply_GateRouting_Mode2:
	and bc, 0xF1FF
	set 9, bc

; Second half: re-reads (0x04138D + channel*0x11F) & 0xF0. 0x10 -> leave alone; 0x20 -> jump
; to the [14:12] override; 0x00 -> `or bc,0x7000`.
Voice_Apply_GateRouting_HighNibble:
	extz wa
	muls wa, 0x11F
	lda xde, (0x04138d:24)
	ldb_sri A, 0x07, 0xE8, 0xE0
	and a, 0xF0
	cp a, 0x10
	jr z, Voice_Apply_GateRouting_Done
	cp a, 0x20
	jr z, Voice_Apply_GateRouting_Mode2High
	cps a, 0
	jr nz, Voice_Apply_GateRouting_Done
	or bc, 0x7000
	jr Voice_Apply_GateRouting_Done

; `and bc,0x8FFF` then `set 12,bc` -- forces the [14:12] field to 1.
Voice_Apply_GateRouting_Mode2High:
	and bc, 0x8FFF
	set 12, bc

; `ld hl, bc` / ret -- the patched word is returned in HL.
Voice_Apply_GateRouting_Done:
	ld hl, bc
	ret

; ---------------------------------------------------------------------------------------
; THE TONE GENERATOR CONTROL REGISTER (bank +0x000), AND THE WORD BUILT FOR IT
;
; Register address (0x0000 + slot) on IC303 is the per-voice CONTROL/gate register. This
; routine and its twin Voice_Build_GateCommand_NoPartial (0x0255F3) build the word that is
; handed to it and park it in the LIVE slot record at +0x2D (0x0430BB + slot*0x47). They
; touch no hardware; the writers listed below push it.
;
; FROM THE CODE -- the command set. Every bank-0x0000 access in the ROM was enumerated by
; scanning the binary for the address latch `ld (0x100000),WA` (f2 00 00 10 50) whose
; preceding instruction is NOT `add WA,imm16`, plus the one immediate-form latch
; (f2 00 00 10 02 with a value < 0x40). Thirteen sites, no others; one is the read-back:
;
;   NOTE-ON GATE   literal 0x8100. Always exactly that value, never computed. Three sites,
;                  all mid-burst: ToneGen_WriteVoiceParams (data write at 0x02D2B4),
;                  ToneGen_WriteVoiceParams_Ext (0x02D6CA), _Ext2 (0x02D777).
;   FREE           literal 0x7E00. Four sites: ToneGen_SilenceChannel (0x02B4D4),
;                  ToneGen_Config_Init (0x02E085), Voice_Reset_Engine phase B (0x021F94),
;                  and the dormant probe ToneGen_ConfigInit_AltData (0x02E17D).
;   HAND-OFF       the word built here, bit 15 SET. Five sites: ToneGen_WriteSingleReg
;                  (0x02D41B), ToneGen_WriteVoice_Direct (0x027FBB), and the tails of
;                  ToneGen_WriteVoiceParams_Ext (0x02D731) / _Ext2 (0x02D7B9).
;                  The SAME word with bit 15 CLEARED is the update-without-re-gate form,
;                  emitted by ToneGen_ReadPitch_AndScale (`res 15, bc` at 0x02E1E3).
;   READ-BACK      0x021026, inside ToneGen_Read_Register: bank 0x0000 indices 0..3 read as
;                  four 16-bit ACTIVE-VOICE BITMAPS (Voice_Manager_PollBank, 0x02219F).
;
; HOW THIS ROUTINE BUILDS THE WORD (IN: XWA = live slot record; OUT: record+0x2D):
;   bits 7..0   0xFF - 4*(P[0] & 0x3F), where P = the u32 pointer at record+0x17 and P[0]
;               is its first BYTE. Range 0x03..0xFF, and always == 3 (mod 4).
;   bit 8       SET iff that same byte P[0] is non-zero. Meaning not established.
;   bits 15..9  0xFE00 when the global mode byte 0x04134C is 0, 5 or 6, else 0xF000; the
;               selector is skipped and 0xF000 forced when byte +0x12 of the record at
;               record+0x23 is zero.
;   then        Voice_Apply_GateRouting (0x02552A) may overwrite bits [14:12] and [11:9]
;               from the two nibbles of (0x04138D + channel*0x11F). Neither arm can clear
;               bit 15 -- the masks are 0x8FFF and 0xF1FF -- so the hand-off word always
;               leaves here with bit 15 set.
; The twin Voice_Build_GateCommand_NoPartial stores the bare literal 0xFE00 / 0xF000 with no
; level byte at all, so it is the ONLY producer of a 0x00 low byte.
;
; MEASURED (capture of a running machine, 1705 note-ons of the built-in demo): only FOUR
; hand-off values are ever issued -- F0FF, F000, F1D7, F187 -- and the LOW BYTE is an OUTPUT
; LEVEL (0xFF full, 0x00 silent), not a mode flag. All four reconcile with the arithmetic
; above, exactly:
;   F0FF  this routine, P[0] == 0            -> 0xFF - 0    = 0xFF, bit 8 clear
;   F1D7  this routine, P[0] & 0x3F == 0x0A  -> 0xFF - 0x28 = 0xD7, bit 8 set
;   F187  this routine, P[0] & 0x3F == 0x1E  -> 0xFF - 0x78 = 0x87, bit 8 set
;   F000  the NoPartial twin's literal -- unreachable from here, because the computed low
;         byte is always == 3 (mod 4) and can never be 0x00.
; The 0xFExx family is absent from the capture. 0x04134C has exactly one store, at the head
; of Voice_AllVoices_UpdateVelocity (0x028C39), which masks A to 4 bits. That routine has
; TWO entries: Voice_ResetAllControllers calls it with A = 1 (not in {0,5,6}), and a
; parameter-dispatch path tail-jumps into it (`jrl`) with A loaded from a message byte at
; (xwa + 3). So the mode is 1 after an audio-side reset, and only a later parameter write
; can select the 0xFE00 arm -- which the demo never does. [INFERENCE: the dispatch-table
; producers of that message byte were not exhaustively traced.]
;
; A voice handed F000 is meant to be INAUDIBLE, and the firmware relies on it: the capture
; shows one voice left gated and never freed at the end of boot, with its envelope
; programmed to hold. The code makes that state stable -- Voice_Manager_PollBank_SlotLoop
; (0x02222A) frees a slot only on a 1 -> 0 edge of the active-voice bitmap it reads back
; through ToneGen_Read_Register, so a voice whose envelope never decays never produces the
; edge and never reaches ToneGen_SilenceChannel.
;
; INFERENCE: read in the same field layout, the 0x8100 note-on gate is "gate on, both
; routing fields 0, level 0" -- the burst gates the voice silent and the hand-off word that
; follows supplies the routing and the level. Not proven; 0x8100 is a literal in the ROM.
; ---------------------------------------------------------------------------------------
Voice_Build_GateCommand:
	push xiz
	ld xiz, xwa
	ld xwa, (xiz + 23)
	ld a, (xwa)
	extz wa
	and wa, 0x3F
	sll wa, 2
	ldw bc, 0xFF
	sub bc, wa
	ld xwa, (xiz + 23)
	cp (xwa), 0x0
	jr z, Voice_Build_GateCommand_CheckExpr
	set 8, bc

; Selects the high field: patchrec+18 == 0 -> 0xF000; global mode byte 0x04134C in {0,5,6}
; -> 0xFE00; otherwise 0xF000.
Voice_Build_GateCommand_CheckExpr:
	ld xwa, (xiz + 35)
	cp (xwa + 18), 0x0
	jr z, Voice_Build_GateCommand_NoExpr
	ldb_da a, 0x04134c
	cps a, 6
	jr z, Voice_Build_GateCommand_FullExpr
	cps a, 5
	jr z, Voice_Build_GateCommand_FullExpr
	cps a, 0
	jr nz, Voice_Build_GateCommand_PartialExpr

; `or wa,0xFE00` and store to voice+45.
Voice_Build_GateCommand_FullExpr:
	ld wa, bc
	or wa, 0xFE00
	ld (xiz + 45), wa
	jr Voice_Build_GateCommand_ApplyMode

; `or wa,0xF000` and store to voice+45.
Voice_Build_GateCommand_PartialExpr:
	ld wa, bc
	or wa, 0xF000
	ld (xiz + 45), wa
	jr Voice_Build_GateCommand_ApplyMode

; `or wa,0xF000` and store to voice+45 (patchrec+18 == 0 arm).
Voice_Build_GateCommand_NoExpr:
	ld wa, bc
	or wa, 0xF000
	ld (xiz + 45), wa

; Runs voice+45 through Voice_Apply_GateRouting with A = voice+4 (the channel) and stores
; the patched word back to voice+45.
Voice_Build_GateCommand_ApplyMode:
	ld a, (xiz + 4)
	extz wa
	ld bc, (xiz + 45)
	calr Voice_Apply_GateRouting
	ld (xiz + 45), hl
	pop xiz
	ret

; The level-less twin of Voice_Build_GateCommand (0x025589 -- the CONTROL register, bank
; +0x000, is documented in full there). IN: XWA = live slot record; OUT: record+0x2D.
;
; It runs the SAME high-field selector (record+0x23 byte +0x12, then the global mode byte
; 0x04134C in {0,5,6}) and the SAME Voice_Apply_GateRouting patch, but stores a bare literal
; -- `ldw (xiz + 45), 0xFE00` / `0xF000` at 0x025613 / 0x02561A / 0x025621 -- with no level
; byte and no bit 8. Its third instruction, `ld xwa, (xiz + 19)`, loads a pointer that the
; next load immediately discards; dead code, kept for byte fidelity.
;
; ★ THIS IS ONE OF THE TWO SOURCES OF 0xF000. The computed sibling cannot produce a 0x00
; low byte (its byte is 0xFF - 4*k, always == 3 mod 4), so no computed path reaches F000.
; The other source is the auxiliary voice template at ROM 0x012115, whose WORD 0 is 0xF000:
; ToneGen_SetupPolyVoice (0x0355AD) copies it verbatim into staging 0x3B1C with `ldirw` and
; hands that word to ToneGen_WriteSingleReg. MEASURED (demo capture, 1705 note-ons; harness in kn7000_mame,
; tools/rigs/kn5000_demo_capture.lua): F000 is one of only four hand-off values
; ever issued, and its low byte 0x00 means output level zero -- the voice is gated but
; inaudible.
; Callers, all of them slot-parameter rebuilds that end in ToneGen_WriteVoiceParams:
; Voice_Init_Type1 (0x02C3CC), Voice_Init_Type2 (0x02C0B6), and the TypeB arm of
; Voice_AllVoices_UpdateVelocity (0x028C39).
Voice_Build_GateCommand_NoPartial:
	push xiz
	ld xiz, xwa
	ld xwa, (xiz + 19)
	ld xwa, (xiz + 35)
	cp (xwa + 18), 0x0
	jr z, Voice_Build_GateCommand_NoPartial_NoExpr
	ldb_da a, 0x04134c
	cps a, 6
	jr z, Voice_Build_GateCommand_NoPartial_FullExpr
	cps a, 5
	jr z, Voice_Build_GateCommand_NoPartial_FullExpr
	cps a, 0
	jr nz, Voice_Build_GateCommand_NoPartial_PartialExpr

; Unmuted twin of 0x0255C4.
Voice_Build_GateCommand_NoPartial_FullExpr:
	ldw (xiz + 45), 0xFE00
	jr Voice_Build_GateCommand_NoPartial_ApplyMode

; Unmuted twin of 0x0255CF.
Voice_Build_GateCommand_NoPartial_PartialExpr:
	ldw (xiz + 45), 0xF000
	jr Voice_Build_GateCommand_NoPartial_ApplyMode

; Unmuted twin of 0x0255DA.
Voice_Build_GateCommand_NoPartial_NoExpr:
	ldw (xiz + 45), 0xF000

; Unmuted twin of 0x0255E3.
Voice_Build_GateCommand_NoPartial_ApplyMode:
	ld a, (xiz + 4)
	extz wa
	ld bc, (xiz + 45)
	calr Voice_Apply_GateRouting
	ld (xiz + 45), hl
	pop xiz
	ret

; ===========================================================================
; Voice_Calc_LevelPair_* -- the three-pair ENVELOPE writers.
; ===========================================================================
; These four routines (_PatchAtk 0x025636, _FixedAtk 0x025A35, _Full 0x025C87,
; _Mono 0x025F7F) were named Voice_ComputeAndWritePan / Voice_UpdatePan_*.
; Nothing in them computes a left/right balance.  Each builds THREE 16-bit words
; of the form (level << 8) | rate -- rate bit 7 being the "apply now" flag -- from
; the paramA (level,rate) couples (+39,+40), (+41,+42) and (+43,+44), and stores
; them to the shadows 0x0451E4 / 0x0451E6 / 0x0451E8 (TG registers 0x800 / 0x840 /
; 0x880).  That is an envelope-segment layout, which is why the curated symbol
; reference calls the single-pair siblings at 0x0267xx Voice_Calc_LevelPair_EG*.
; _PatchAtk takes its first-pair attack from the patch record, _FixedAtk uses a
; fixed one; _Full adds an oscillator-table branch and _Mono drops the base-pair
; oscillator trim.
;
; WHERE ENVELOPE 1'S SEGMENTS COME FROM. paramA = the u32 at slot+0x17, tonerec = the u32
; at slot+0x23 (both offsets hex; the code writes them as decimal 23 / 35). Targets index a
; DESCENDING attenuation curve (0xFF = silent); rates index Voice_EnvelopeRate_Table
; (0x011963, 0x00..0x7F, so bit 7 is always clear here -- unlike envelopes 2 and 3, whose
; low bytes are signed Detune_ScaleSymmetric outputs).
;
;   TYPE-4 voices -- _PatchAtk (note-on, from Voice_Build_Register_Set 0x02B4E3) and
;   _Full / _Mono (per-tick refresh, from Voice_Release_Type4 0x02BCD6 and its _BranchA):
;     seg 0  target Voice_LevelPair_AttackCurve[clamp(paramA+0x27 + (i8)tonerec[0x6B],
;                   0..0x64)]. _Full's bit-11-clear arm uses (i8)tonerec[0x010C] in place of
;                   tonerec[0x6B]; _Mono adds no trim byte and skips the clamp; _Full's
;                   bit-11-set arm substitutes the fixed byte at 0x0118B3.
;            rate   Voice_EnvelopeRate_Table[paramA+0x28]
;     seg 1  target Voice_EnvelopeLevel_Curve[paramA+0x29]
;            rate   max(4, Voice_EnvelopeRate_Table[paramA+0x2A])
;     seg 2  target Voice_EnvelopeLevel_Curve[paramA+0x2B]
;            rate   Voice_EnvelopeRate_Table[paramA+0x2C]     -- no floor
;     Modulation: key scale PitchBend_Scale(paramA+0x2E, slot+0x0C) on segment 0 and
;     paramA+0x2F on segments 1/2; Pan_ScaleWithVelocity with the control triple
;     paramA+0x30..0x32 and depths paramA+0x33 (seg 0) / paramA+0x34 (segs 1,2); every sum
;     re-clamped 0..0xFF.
;
;   TYPE-1/TYPE-2 voices -- _FixedAtk (from Voice_Init_Type1 0x02C3CC / _Type2 0x02C0B6):
;     seg 0  target Voice_LevelPair_AttackCurve[paramA+0x08], key scale paramA+0x0E
;            rate   the CONSTANT 0x7F -- the "FixedAtk" the name refers to
;     seg 1  target Voice_EnvelopeLevel_Curve[paramA+0x09]
;            rate   max(4, Voice_EnvelopeRate_Table[paramA+0x0A])
;     seg 2  target Voice_EnvelopeLevel_Curve[paramA+0x0B]
;            rate   Voice_EnvelopeRate_Table[paramA+0x0C], or 0 when bit 5 of
;                   (*(slot+0x13))[+0x0D] is clear. The bit-5-SET arm additionally caches
;                   Voice_EnvelopeLevel_Curve[paramA+0x0D] in slot+0x46; the clear arm
;                   zeroes that byte.
;     ★ paramA+0x0A and +0x0C are the very bytes Voice_Level_ComputeTriplet pushes through
;     Detune_ScaleSymmetric as SIGNED values on the type-4 path, while this routine uses them
;     as UNSIGNED rate-table indexes. (The two agree on the level bytes +0x09/+0x0B, which
;     both send through 0x0118FE.) There is no run-time conflict, because the type-1/2 chain calls
;     Voice_Level_ClearAllOutputRegs and never builds envelope 2 or 3, and the two allocation
;     paths (Voice_Allocate_Typed vs Voice_NoteOn_Type3) bind different record kinds to
;     slot+0x17. But it does mean the two readings cannot both describe the same field.
;
; _PatchAtk and _FixedAtk write only 0x0451E4 directly; segments 1 and 2 are cached in
; slot+0x3E / slot+0x40 and pushed to 0x0451E6 / 0x0451E8 by Voice_WriteChPanShift 0x02591D
; / _2 0x025B6F, which may add OR subtract (bit 9 of (*(slot+0x27))[+0x18] selects) the
; signed byte tonerec[0x20] against the RATE field, gated on bit 8 of the same word, and
; re-clamps segment 1's rate to [4..0x7F] and segment 2's to [0..0x7F]. _Full and _Mono
; write all three shadows themselves. The seg-0 word is additionally cached in slot+0x3C.
;
; [INFERENCE] RATE 0 IS SPECIAL, AND THE FIRMWARE GUARDS IT. Voice_EnvelopeRate_Table begins
; {0x00, 0x04, 0x08, 0x0A, ...}: entry 0 is the ONLY entry below 4. So the max(4, ...)
; applied to segment 1 in all four builders, and the [4..0x7F] clamp Voice_WriteChPanShift
; applies to the same field, have exactly one effect between them -- they turn a rate of 0
; into 4 -- while segments 0 and 2 are left free to carry 0. The natural reading is that
; rate 0 means "arrive immediately", harmless on an attack and on a final target but not on
; a segment that has to be heard falling. That is an inference from what the firmware
; AVOIDS, not a measurement: nothing here shows what IC303 does with rate 0, and the
; supporting mute idiom is weaker than it looks -- it pairs rate 0 with bit 7 SET on r0x20
; (0xFF80) and CLEAR on r0x21 (0xFF00), which would be redundant if rate 0 already meant
; "go now". Note also that the per-tick writers do NOT all emit rate 0: only
; Voice_Calc_LevelPair_EGA does; EGB and EGC emit signed Detune_ScaleSymmetric bytes.
Voice_Calc_LevelPair_PatchAtk:
	lda xsp, (xsp - 14)
	push xiz
	ld (xsp + 14), xwa
	ld xwa, (xsp + 14)
	ld xwa, (xwa + 23)
	ld (xsp + 4), xwa
	ld xwa, (xsp + 14)
	ld xwa, (xwa + 31)
	ld (xsp + 10), xwa
	ld xwa, (xsp + 14)
	ld xbc, (xwa + 35)
	ld xwa, (xsp + 14)
	ld xwa, (xwa + 19)
	bitm 4, (xwa + 16)
	jr z, Voice_Calc_LevelPair_PatchAtk_SetInvFlag
	ld xwa, (xsp + 14)
	andmi16 (xwa + 1), 0x7FFF
	jr Voice_Calc_LevelPair_PatchAtk_ApplyKeyTrack

; Sets the "inverted" flag in the local frame when the patch record asks for the reversed
; curve.
Voice_Calc_LevelPair_PatchAtk_SetInvFlag:
	ld xwa, (xsp + 14)
	ormi16 (xwa + 1), 0x8000

; Segment 0's TARGET index: (i8)tonerec[0x6B] + paramA+0x27, clamped 0..0x64, then curved
; through Voice_LevelPair_AttackCurve (0x011899) into IZ. It is a plain signed ADD of the
; tone record's byte 0x6B -- there is no PitchBend_Scale and no 0..0xFF clamp at this point.
; The PitchBend_Scale key-scale term (depth paramA+0x2E, note slot+0x0C, shift 4) comes
; later, after the curve lookup, in this routine's own fall-through tail and in _NoOscLFO's
; paramA+0x2E-non-zero branch; _NoLFO is the arm that SKIPS it. The 0..0xFF clamp is applied
; on the fall-through tail, in _NoLFO and in _NoOscLFO's non-zero branch alike.
; NO RENAME PROPOSED -- _ApplyKeyTrack is a `jr` branch target and is also listed in
; symbols/subcpu_symbols_reference.txt, so only the comment is corrected here.
Voice_Calc_LevelPair_PatchAtk_ApplyKeyTrack:
	ld a, (xbc + 107)
	ld c, a
	exts bc
	ld xwa, (xsp + 4)
	ld a, (xwa + 39)
	extz wa
	add wa, bc
	ldw bc, 0x64
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld iz, hl
	stb_erp A, 0xF8
	extz wa
	lda xbc, (0x011899:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld iz, wa
	ld xwa, (xsp + 4)
	cp (xwa + 51), 0x0
	jr z, Voice_Calc_LevelPair_PatchAtk_NoOscLFO
	ld xwa, (xsp + 4)
	ld a, (xwa + 48)
	ld c, a
	extz bc
	ld xwa, (xsp + 4)
	ld a, (xwa + 49)
	ld e, a
	extz de
	ld xwa, (xsp + 4)
	ld a, (xwa + 50)
	extz wa
	pushw wa
	ld xwa, (xsp + 6)
	ld a, (xwa + 51)
	exts wa
	pushw wa
	ld xwa, (xsp + 18)
	ld wa, (xwa + 8)
	calr Pan_ScaleWithVelocity
	ld (xsp + 8), hl
	ld xwa, (xsp + 4)
	cp (xwa + 46), 0x0
	jr z, Voice_Calc_LevelPair_PatchAtk_NoLFO
	ld xwa, (xsp + 4)
	ld a, (xwa + 46)
	ld e, a
	exts de
	ld xwa, (xsp + 14)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	ld wa, de
	lds de, 4
	calr PitchBend_Scale
	ldw_erp HL, 0xFA
	ld wa, iz
	add wa, (xsp + 8)
	addw_erp WA, 0xFA
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld iz, hl
	jr Voice_Calc_LevelPair_PatchAtk_CheckMax

; Arm taken when the LFO depth is zero.
Voice_Calc_LevelPair_PatchAtk_NoLFO:
	ld wa, iz
	add wa, (xsp + 8)
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld iz, hl
	jr Voice_Calc_LevelPair_PatchAtk_CheckMax

; Arm taken when the oscillator LFO depth is zero.
Voice_Calc_LevelPair_PatchAtk_NoOscLFO:
	ld xwa, (xsp + 4)
	cp (xwa + 46), 0x0
	jr z, Voice_Calc_LevelPair_PatchAtk_CheckMax
	ld xwa, (xsp + 4)
	ld a, (xwa + 46)
	ld e, a
	exts de
	ld xwa, (xsp + 14)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	ld wa, de
	lds de, 4
	calr PitchBend_Scale
	ldw_erp HL, 0xFA
	ld wa, iz
	addw_erp WA, 0xFA
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld iz, hl

; If bit 0 of the flag word is set and the accumulator is exactly 0xFF, decrement it -- the
; firmware refuses to emit the 0xFF "hard mute" level on this path.
Voice_Calc_LevelPair_PatchAtk_CheckMax:
	ld xwa, (xsp + 10)
	bitm 0, (xwa)
	jr z, Voice_Calc_LevelPair_PatchAtk_WriteDSP
	ld wa, iz
	cp wa, 0xFF
	jr nz, Voice_Calc_LevelPair_PatchAtk_WriteDSP
	dec 1, iz

; Packs (level << 8) | table[0x011963 + tonerec+40] and stores it to 0x0451E4 (TG reg 0x800,
; the main volume register) AND caches it in voice+60. Then continues into the per-channel
; L/R words.
Voice_Calc_LevelPair_PatchAtk_WriteDSP:
	ld xwa, (xsp + 4)
	ld a, (xwa + 40)
	extz wa
	lda xbc, (0x011963:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ldb w, 0x0
	ld bc, iz
	sla bc, 8
	or bc, wa
	stw_da 0x0451e4, xbc
	ld xwa, (xsp + 14)
	ld (xwa + 60), bc
	ld xwa, (xsp + 4)
	ld a, (xwa + 41)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld (xsp + 10), wa
	ld xwa, (xsp + 4)
	ld a, (xwa + 43)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld (xsp + 12), wa
	ld xwa, (xsp + 4)
	cp (xwa + 52), 0x0
	jrl z, Voice_Calc_LevelPair_PatchAtk_NoDepth2
	ld xwa, (xsp + 4)
	ld a, (xwa + 48)
	ld c, a
	extz bc
	ld xwa, (xsp + 4)
	ld a, (xwa + 49)
	ld e, a
	extz de
	ld xwa, (xsp + 4)
	ld a, (xwa + 50)
	extz wa
	pushw wa
	ld xwa, (xsp + 6)
	ld a, (xwa + 52)
	exts wa
	pushw wa
	ld xwa, (xsp + 18)
	ld wa, (xwa + 8)
	calr Pan_ScaleWithVelocity
	ld (xsp + 8), hl
	ld xwa, (xsp + 4)
	cp (xwa + 47), 0x0
	jr z, Voice_Calc_LevelPair_PatchAtk_NoModDepth
	ld xwa, (xsp + 4)
	ld a, (xwa + 47)
	ld e, a
	exts de
	ld xwa, (xsp + 14)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	ld wa, de
	lds de, 4
	calr PitchBend_Scale
	ldw_erp HL, 0xFA
	ld wa, (xsp + 10)
	add wa, (xsp + 8)
	addw_erp WA, 0xFA
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 10), hl
	ld wa, (xsp + 12)
	add wa, (xsp + 8)
	addw_erp WA, 0xFA
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 12), hl
	jr Voice_Calc_LevelPair_PatchAtk_WriteChans

; No-modulation arm of the per-channel level computation.
Voice_Calc_LevelPair_PatchAtk_NoModDepth:
	ld wa, (xsp + 10)
	add wa, (xsp + 8)
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 10), hl
	ld wa, (xsp + 12)
	add wa, (xsp + 8)
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 12), hl
	jr Voice_Calc_LevelPair_PatchAtk_WriteChans

; Second no-depth arm.
Voice_Calc_LevelPair_PatchAtk_NoDepth2:
	ld xwa, (xsp + 4)
	cp (xwa + 47), 0x0
	jr z, Voice_Calc_LevelPair_PatchAtk_WriteChans
	ld xwa, (xsp + 4)
	ld a, (xwa + 47)
	ld e, a
	exts de
	ld xwa, (xsp + 14)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	ld wa, de
	lds de, 4
	calr PitchBend_Scale
	ldw_erp HL, 0xFA
	ld wa, (xsp + 10)
	addw_erp WA, 0xFA
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 10), hl
	ld wa, (xsp + 12)
	addw_erp WA, 0xFA
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 12), hl

; Falls through into the per-channel writer that fills 0x0451E6 / 0x0451E8 (TG regs 0x840 /
; 0x880).
Voice_Calc_LevelPair_PatchAtk_WriteChans:
	ld xwa, (xsp + 4)
	ld a, (xwa + 42)
	extz wa
	lda xbc, (0x011963:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld hl, wa
	lds wa, 4
	cps hl, 4
	jr lt, Voice_Calc_LevelPair_PatchAtk_ClampDepth
	ld wa, hl

; NOT a modulation depth -- this is segment 1's rate field, floored at 4.
; Voice_EnvelopeRate_Table has exactly one entry below 4 (entry 0 = 0x00), so the floor's
; sole effect is to turn a rate of 0 into 4. Segments 0 and 2 are left free to use 0.
; [INFERENCE] the staging-block header reads that asymmetry as "rate 0 means arrive
; immediately, and segment 1 is the one segment where an instant jump would be audible";
; neither the chip behaviour nor the claim that segment 1 is a decay is measured here.
; NO RENAME PROPOSED -- _ClampDepth is a `jr lt` branch target and is also listed in
; symbols/subcpu_symbols_reference.txt, so only the comment is corrected here.
Voice_Calc_LevelPair_PatchAtk_ClampDepth:
	ld hl, wa
	ld xwa, (xsp + 4)
	ld a, (xwa + 44)
	extz wa
	lda xbc, (0x011963:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld de, wa
	ld wa, hl
	ldb w, 0x0
	ld bc, (xsp + 10)
	sla bc, 8
	or bc, wa
	ld xwa, (xsp + 14)
	ld (xwa + 62), bc
	ld wa, de
	ldb w, 0x0
	ld bc, (xsp + 12)
	sla bc, 8
	or bc, wa
	ld xwa, (xsp + 14)
	ld (xwa + 64), bc
	pop xiz
	lda xsp, (xsp + 14)
	ret

; Emits the per-channel L/R level pair. In: XWA (frame (xsp+6)) = per-voice record.
; Left value starts from (patchrec+32) added to (voice+62 & 0x7F); right value from the same
; signed byte added to (voice+64 & 0x7F). Both clamped (right to 0..0x7F, left to 4..0x7F),
; merged into the cached words voice+62 / voice+64 keeping their high bytes, and stored to
; 0x0451E6 (TG reg 0x840) and 0x0451E8 (TG reg 0x880).
; If the "channel" flag in the frame is set, the right word gets bit 15 forced instead of
; the cached high byte.
Voice_WriteChPanShift:
	dec 8, xsp
	pushw iz
	ld (xsp + 4), c
	ld (xsp + 6), xwa
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 39)
	ld wa, (xwa + 24)
	bit 8, wa
	jrl z, Voice_WriteChPanShift_Passthrough
	ld xwa, (xsp + 6)
	ld wa, (xwa + 64)
	and wa, 0xFF
	jrl z, Voice_WriteChPanShift_Passthrough
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 39)
	ld wa, (xwa + 24)
	bit 9, wa
	jr z, Voice_WriteChPanShift_AddShift
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld a, (xwa + 32)
	ld c, a
	exts bc
	ld xwa, (xsp + 6)
	ld wa, (xwa + 62)
	and wa, 0x7F
	ld (xsp + 2), wa
	sub (xsp + 2), bc
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld a, (xwa + 32)
	ld c, a
	exts bc
	ld xwa, (xsp + 6)
	ld wa, (xwa + 64)
	and wa, 0x7F
	ld iz, wa
	sub iz, bc
	jr Voice_WriteChPanShift_ClampAndWrite

; Adds the signed shift byte to both 7-bit channel fields.
Voice_WriteChPanShift_AddShift:
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld a, (xwa + 32)
	ld c, a
	exts bc
	ld xwa, (xsp + 6)
	ld wa, (xwa + 62)
	and wa, 0x7F
	ld (xsp + 2), wa
	add (xsp + 2), bc
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld a, (xwa + 32)
	ld c, a
	exts bc
	ld xwa, (xsp + 6)
	ld wa, (xwa + 64)
	and wa, 0x7F
	ld iz, wa
	add iz, bc

; Clamps both fields via ClampS16_WA_To_DEBC and branches on the channel flag.
Voice_WriteChPanShift_ClampAndWrite:
	ld wa, (xsp + 2)
	ldw bc, 0x7F
	lds de, 4
	calr ClampS16_WA_To_DEBC
	ld (xsp + 2), hl
	ld wa, iz
	ldw bc, 0x7F
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld iz, hl
	cp (xsp + 4), 0x0
	jr z, Voice_WriteChPanShift_NoChanFlag
	ld wa, iz
	set 15, wa
	stw_da 0x0451e8, xwa
	jr Voice_WriteChPanShift_WriteL

; Channel flag clear: merge the right field under the cached voice+64 high byte before
; storing to 0x0451E8.
Voice_WriteChPanShift_NoChanFlag:
	ld wa, iz
	ldb w, 0x0
	ld bc, wa
	ld xwa, (xsp + 6)
	ld wa, (xwa + 64)
	ldb a, 0x0
	or wa, bc
	stw_da 0x0451e8, xwa

; Merge and store the left field to 0x0451E6 (TG reg 0x840).
Voice_WriteChPanShift_WriteL:
	ld wa, (xsp + 2)
	ldb w, 0x0
	ld bc, wa
	ld xwa, (xsp + 6)
	ld wa, (xwa + 62)
	ldb a, 0x0
	or wa, bc
	stw_da 0x0451e6, xwa
	jr Voice_WriteChPanShift_Done

; No-shift path: copy the cached voice+62 / voice+64 words verbatim to 0x0451E6 / 0x0451E8.
Voice_WriteChPanShift_Passthrough:
	ld xwa, (xsp + 6)
	ld wa, (xwa + 62)
	stw_da 0x0451e6, xwa
	ld xwa, (xsp + 6)
	ld wa, (xwa + 64)
	stw_da 0x0451e8, xwa

; popw IZ, inc 8 xsp, ret.
Voice_WriteChPanShift_Done:
	popw iz
	inc 8, xsp
	ret

Voice_Calc_LevelPair_FixedAtk:
	lda xsp, (xsp - 12)
	pushw iz
	ld (xsp + 10), xwa
	ld xwa, (xsp + 10)
	ld xwa, (xwa + 19)
	ld (xsp + 2), xwa
	ld xwa, (xsp + 10)
	ld xwa, (xwa + 23)
	ld (xsp + 6), xwa
	ld xwa, (xsp + 10)
	ormi16 (xwa + 1), 0x8000
	ld xwa, (xsp + 6)
	ld a, (xwa + 8)
	extz wa
	lda xbc, (0x011899:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld iz, wa
	ld xwa, (xsp + 6)
	cp (xwa + 14), 0x0
	jr z, Voice_Calc_LevelPair_FixedAtk_WriteLevel
	ld xwa, (xsp + 6)
	ld a, (xwa + 14)
	ld e, a
	exts de
	ld xwa, (xsp + 10)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	ld wa, de
	lds de, 4
	calr PitchBend_Scale
	add iz, hl
	ld wa, iz
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld iz, hl

; Packs (level << 8) | 0x7F and stores to 0x0451E4 (TG reg 0x800) and to the cache at
; voice+60. The low byte is the constant 0x7F here, which is what distinguishes the "simple"
; path from Voice_Calc_LevelPair_PatchAtk's table lookup.
Voice_Calc_LevelPair_FixedAtk_WriteLevel:
	ld wa, iz
	sla wa, 8
	ld bc, wa
	or bc, 0x7F
	stw_da 0x0451e4, xbc
	ld xwa, (xsp + 10)
	ld (xwa + 60), bc
	ld xwa, (xsp + 6)
	ld a, (xwa + 9)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld hl, wa
	ld xwa, (xsp + 6)
	ld a, (xwa + 11)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld de, wa
	ld xwa, (xsp + 6)
	ld a, (xwa + 10)
	extz wa
	lda xbc, (0x011963:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld bc, wa
	lds wa, 4
	cps bc, 4
	jr lt, Voice_Calc_LevelPair_FixedAtk_WriteChans
	ld wa, bc

; Per-channel L/R computation for the simple path (table 0x0118FE indexed by tonerec+9/+11).
Voice_Calc_LevelPair_FixedAtk_WriteChans:
	ld bc, wa
	ldb w, 0x0
	ld bc, hl
	sla bc, 8
	or bc, wa
	ld xwa, (xsp + 10)
	ld (xwa + 62), bc
	ld xwa, (xsp + 2)
	bitm 5, (xwa + 13)
	jr z, Voice_Calc_LevelPair_FixedAtk_NoChanFlag
	ld xwa, (xsp + 6)
	ld a, (xwa + 12)
	extz wa
	lda xbc, (0x011963:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ldb w, 0x0
	ld bc, de
	sla bc, 8
	or bc, wa
	ld xwa, (xsp + 10)
	ld (xwa + 64), bc
	ld xwa, (xsp + 6)
	ld a, (xwa + 13)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld c, a
	ld xwa, (xsp + 10)
	ld (xwa + 70), c
	jr Voice_Calc_LevelPair_FixedAtk_Done

; Channel-flag-clear arm of the simple path.
Voice_Calc_LevelPair_FixedAtk_NoChanFlag:
	ld bc, de
	sla bc, 8
	ld xwa, (xsp + 10)
	ld (xwa + 64), bc
	ld xwa, (xsp + 10)
	ld (xwa + 70), 0x0

; popw IZ, unwind 12 bytes, ret.
Voice_Calc_LevelPair_FixedAtk_Done:
	popw iz
	lda xsp, (xsp + 12)
	ret

; Second, instruction-identical copy of Voice_WriteChPanShift (0x02591D). Same inputs, same
; outputs (0x0451E6 / 0x0451E8 = TG regs 0x840 / 0x880); it exists so the "full" level path
; can call it with a `calr` in range.
Voice_WriteChPanShift2:
	dec 8, xsp
	pushw iz
	ld (xsp + 4), c
	ld (xsp + 6), xwa
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 39)
	ld wa, (xwa + 24)
	bit 8, wa
	jrl z, Voice_WriteChPanShift2_Passthrough
	ld xwa, (xsp + 6)
	ld wa, (xwa + 64)
	and wa, 0xFF
	jrl z, Voice_WriteChPanShift2_Passthrough
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 39)
	ld wa, (xwa + 24)
	bit 9, wa
	jr z, Voice_WriteChPanShift2_AddShift
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld a, (xwa + 32)
	ld c, a
	exts bc
	ld xwa, (xsp + 6)
	ld wa, (xwa + 62)
	and wa, 0x7F
	ld (xsp + 2), wa
	sub (xsp + 2), bc
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld a, (xwa + 32)
	ld c, a
	exts bc
	ld xwa, (xsp + 6)
	ld wa, (xwa + 64)
	and wa, 0x7F
	ld iz, wa
	sub iz, bc
	jr Voice_WriteChPanShift2_ClampAndWrite

; As 0x02598A.
Voice_WriteChPanShift2_AddShift:
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld a, (xwa + 32)
	ld c, a
	exts bc
	ld xwa, (xsp + 6)
	ld wa, (xwa + 62)
	and wa, 0x7F
	ld (xsp + 2), wa
	add (xsp + 2), bc
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld a, (xwa + 32)
	ld c, a
	exts bc
	ld xwa, (xsp + 6)
	ld wa, (xwa + 64)
	and wa, 0x7F
	ld iz, wa
	add iz, bc

; As 0x0259C2.
Voice_WriteChPanShift2_ClampAndWrite:
	ld wa, (xsp + 2)
	ldw bc, 0x7F
	lds de, 4
	calr ClampS16_WA_To_DEBC
	ld (xsp + 2), hl
	ld wa, iz
	ldw bc, 0x7F
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld iz, hl
	cp (xsp + 4), 0x0
	jr z, Voice_WriteChPanShift2_NoChanFlag
	ld wa, iz
	set 15, wa
	stw_da 0x0451e8, xwa
	jr Voice_WriteChPanShift2_WriteL

; As 0x0259EE.
Voice_WriteChPanShift2_NoChanFlag:
	ld wa, iz
	ldb w, 0x0
	ld bc, wa
	ld xwa, (xsp + 6)
	ld wa, (xwa + 64)
	ldb a, 0x0
	or wa, bc
	stw_da 0x0451e8, xwa

; As 0x025A03.
Voice_WriteChPanShift2_WriteL:
	ld wa, (xsp + 2)
	ldb w, 0x0
	ld bc, wa
	ld xwa, (xsp + 6)
	ld wa, (xwa + 62)
	ldb a, 0x0
	or wa, bc
	stw_da 0x0451e6, xwa
	jr Voice_WriteChPanShift2_Done

; As 0x025A1B.
Voice_WriteChPanShift2_Passthrough:
	ld xwa, (xsp + 6)
	ld wa, (xwa + 62)
	stw_da 0x0451e6, xwa
	ld xwa, (xsp + 6)
	ld wa, (xwa + 64)
	stw_da 0x0451e8, xwa

; As 0x025A31.
Voice_WriteChPanShift2_Done:
	popw iz
	inc 8, xsp
	ret

; Full level-pair recomputation for one voice; the body runs past the end of this region
; (to ~0x025F7E). In: XWA = per-voice record. Same shape as Voice_Calc_LevelPair_PatchAtk
; (0x025636) but with an extra oscillator-table branch at 0x025CCB. Ultimately writes
; 0x0451E4 / 0x0451E6 / 0x0451E8 (TG regs 0x800 / 0x840 / 0x880) via Voice_WriteChPanShift2.
Voice_Calc_LevelPair_Full:
	lda xsp, (xsp - 14)
	push xiz
	ld (xsp + 14), xwa
	ld xwa, (xsp + 14)
	ld xwa, (xwa + 23)
	ld (xsp + 4), xwa
	ld xwa, (xsp + 14)
	ld xwa, (xwa + 19)
	bitm 4, (xwa + 16)
	jr z, Voice_Calc_LevelPair_Full_SetInvFlag
	ld xwa, (xsp + 14)
	andmi16 (xwa + 1), 0x7FFF
	jr Voice_Calc_LevelPair_Full_CheckBit11

; Sets the inverted-curve flag in the local frame.
Voice_Calc_LevelPair_Full_SetInvFlag:
	ld xwa, (xsp + 14)
	ormi16 (xwa + 1), 0x8000

; Bit-11 test that selects between the oscillator-table path (0x025CCB, just past this
; region) and the direct path.
Voice_Calc_LevelPair_Full_CheckBit11:
	ld xwa, (xsp + 14)
	ld wa, (xwa + 1)
	bit 11, wa
	jr z, Voice_Calc_LevelPair_Full_OscTablePath
	ldb_da a, 0x0118b3
	extz wa
	ld iz, wa
	jrl Voice_Calc_LevelPair_Full_CheckMax

; Not a routine entry -- this is the main body of Voice_Calc_LevelPair_Full, whose entry
; (0x025C87) sits just below this region's lower boundary. Documented here because the
; region starts inside it.
;
; Voice_Calc_LevelPair_Full(XWA = voice-slot record) computes the THREE (level,rate) register
; pairs that the sub-CPU keeps for a voice in the tone-generator shadow block, for the
; "full" voice type -- the one whose tone record carries a per-oscillator trim table.
; Called from Voice_Release_Type4.
;
; This branch is taken when bit 11 of slot+1 is CLEAR. It reads a signed per-oscillator
; trim byte from tonerec[0x010C] (tonerec = the pointer at slot+35), adds it to
; paramA+39 (paramA = the pointer at slot+23), clamps the sum to 0..0x64 with
; ClampS16_WA_To_DEBC, and converts it through the 101-entry curve at 0x011899 into an
; 8-bit register level. The bit-11-set branch instead takes a fixed level from the byte
; at 0x0118B3 and jumps straight to _CheckMax.
;
; Level modulation then follows: if paramA+51 is non-zero the LFO/velocity scaler
; Pan_ScaleWithVelocity(paramA+48,+49,+50, depth paramA+51, velocity slot+8) is added,
; and if paramA+46 is non-zero PitchBend_Scale(depth paramA+46, note slot+12) is added
; too; each sum is re-clamped to 0..0xFF.
;
; Register value format written into the shadow block is (level << 8) | rate, where rate
; comes from the 0..0x7F curve at 0x011963. Bit 7 of the low byte is a separate "apply
; immediately" flag that only the per-tick writers (Voice_ComputeAndWriteVolume*) set.
;
; Hardware: nothing directly. The results land in RAM at 0x0451E4/E6/E8; they reach the
; tone generator later, when ToneGen_WriteVoiceParams pushes shadow offsets +24/+26/+28
; to TG register banks 0x800/0x840/0x880 via the 0x100000/0x100002 latch pair.
Voice_Calc_LevelPair_Full_OscTablePath:
	ld xwa, (xsp + 14)
	ld xwa, (xwa + 35)
	ldb_sri0 A, (xwa + 0x010c)
	ld c, a
	exts bc
	ld xwa, (xsp + 4)
	ld a, (xwa + 39)
	extz wa
	add wa, bc
	ldw bc, 0x64
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld iz, hl
	stb_erp A, 0xF8
	extz wa
	lda xbc, (0x011899:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld iz, wa
	ld xwa, (xsp + 4)
	cp (xwa + 51), 0x0
	jr z, Voice_Calc_LevelPair_Full_NoLFO
	ld xwa, (xsp + 4)
	ld a, (xwa + 48)
	ld c, a
	extz bc
	ld xwa, (xsp + 4)
	ld a, (xwa + 49)
	ld e, a
	extz de
	ld xwa, (xsp + 4)
	ld a, (xwa + 50)
	extz wa
	pushw wa
	ld xwa, (xsp + 6)
	ld a, (xwa + 51)
	exts wa
	pushw wa
	ld xwa, (xsp + 18)
	ld wa, (xwa + 8)
	calr Pan_ScaleWithVelocity
	ld (xsp + 8), hl
	ld xwa, (xsp + 4)
	cp (xwa + 46), 0x0
	jr z, Voice_Calc_LevelPair_Full_NoDepth
	ld xwa, (xsp + 4)
	ld a, (xwa + 46)
	ld e, a
	exts de
	ld xwa, (xsp + 14)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	ld wa, de
	lds de, 4
	calr PitchBend_Scale
	ldw_erp HL, 0xFA
	ld wa, iz
	add wa, (xsp + 8)
	addw_erp WA, 0xFA
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld iz, hl
	jr Voice_Calc_LevelPair_Full_CheckMax

; LFO term only (paramA+46 == 0): add the scaler result, clamp 0..0xFF, go to _CheckMax.
Voice_Calc_LevelPair_Full_NoDepth:
	ld wa, iz
	add wa, (xsp + 8)
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld iz, hl
	jr Voice_Calc_LevelPair_Full_CheckMax

; paramA+51 == 0: skip the LFO scaler; apply only the paramA+46 depth term, if any.
Voice_Calc_LevelPair_Full_NoLFO:
	ld xwa, (xsp + 4)
	cp (xwa + 46), 0x0
	jr z, Voice_Calc_LevelPair_Full_CheckMax
	ld xwa, (xsp + 4)
	ld a, (xwa + 46)
	ld e, a
	exts de
	ld xwa, (xsp + 14)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	ld wa, de
	lds de, 4
	calr PitchBend_Scale
	ldw_erp HL, 0xFA
	ld wa, iz
	addw_erp WA, 0xFA
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld iz, hl

; If bit 0 of the byte pointed to by slot+31 is set and the computed level is exactly
; 0xFF, decrement it. Reserves 0xFF as a "fully attenuated / voice finished" code -- the
; portamento ramp uses 0xFF00 as its terminal value and releases the voice there.
Voice_Calc_LevelPair_Full_CheckMax:
	ld xwa, (xsp + 14)
	ld xwa, (xwa + 31)
	bitm 0, (xwa)
	jr z, Voice_Calc_LevelPair_Full_WriteDSP
	ld wa, iz
	cp wa, 0xFF
	jr nz, Voice_Calc_LevelPair_Full_WriteDSP
	dec 1, iz

; Assembles pair 1: rate = table_0x011963[paramA+40], word = (level<<8)|rate, stored to
; the shadow word 0x0451E4 (TG bank 0x800) and cached in the slot at +60. Then starts
; pairs 2 and 3 from paramA+41 and paramA+43 through the 101-entry curve at 0x0118FE.
Voice_Calc_LevelPair_Full_WriteDSP:
	ld xwa, (xsp + 4)
	ld a, (xwa + 40)
	extz wa
	lda xbc, (0x011963:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ldb w, 0x0
	ld bc, iz
	sla bc, 8
	or bc, wa
	stw_da 0x0451e4, xbc
	ld xwa, (xsp + 14)
	ld (xwa + 60), bc
	ld xwa, (xsp + 4)
	ld a, (xwa + 41)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld (xsp + 10), wa
	ld xwa, (xsp + 4)
	ld a, (xwa + 43)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld (xsp + 12), wa
	ld xwa, (xsp + 4)
	cp (xwa + 52), 0x0
	jrl z, Voice_Calc_LevelPair_Full_NoDepth2
	ld xwa, (xsp + 4)
	ld a, (xwa + 48)
	ld c, a
	extz bc
	ld xwa, (xsp + 4)
	ld a, (xwa + 49)
	ld e, a
	extz de
	ld xwa, (xsp + 4)
	ld a, (xwa + 50)
	extz wa
	pushw wa
	ld xwa, (xsp + 6)
	ld a, (xwa + 52)
	exts wa
	pushw wa
	ld xwa, (xsp + 18)
	ld wa, (xwa + 8)
	calr Pan_ScaleWithVelocity
	ld (xsp + 8), hl
	ld xwa, (xsp + 4)
	cp (xwa + 47), 0x0
	jr z, Voice_Calc_LevelPair_Full_NoModDepth
	ld xwa, (xsp + 4)
	ld a, (xwa + 47)
	ld e, a
	exts de
	ld xwa, (xsp + 14)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	ld wa, de
	lds de, 4
	calr PitchBend_Scale
	ldw_erp HL, 0xFA
	ld wa, (xsp + 10)
	add wa, (xsp + 8)
	addw_erp WA, 0xFA
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 10), hl
	ld wa, (xsp + 12)
	add wa, (xsp + 8)
	addw_erp WA, 0xFA
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 12), hl
	jr Voice_Calc_LevelPair_Full_WriteChDepth

; paramA+47 == 0 while paramA+52 != 0: add only the LFO scaler to pairs 2 and 3.
Voice_Calc_LevelPair_Full_NoModDepth:
	ld wa, (xsp + 10)
	add wa, (xsp + 8)
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 10), hl
	ld wa, (xsp + 12)
	add wa, (xsp + 8)
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 12), hl
	jr Voice_Calc_LevelPair_Full_WriteChDepth

; paramA+52 == 0: no LFO term for pairs 2/3; apply only the paramA+47 depth term.
Voice_Calc_LevelPair_Full_NoDepth2:
	ld xwa, (xsp + 4)
	cp (xwa + 47), 0x0
	jr z, Voice_Calc_LevelPair_Full_WriteChDepth
	ld xwa, (xsp + 4)
	ld a, (xwa + 47)
	ld e, a
	exts de
	ld xwa, (xsp + 14)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	ld wa, de
	lds de, 4
	calr PitchBend_Scale
	ldw_erp HL, 0xFA
	ld wa, (xsp + 10)
	addw_erp WA, 0xFA
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 10), hl
	ld wa, (xsp + 12)
	addw_erp WA, 0xFA
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 12), hl

; Rate for pair 2 = table_0x011963[paramA+42], floored at 4 (values below 4 are raised).
Voice_Calc_LevelPair_Full_WriteChDepth:
	ld xwa, (xsp + 4)
	ld a, (xwa + 42)
	extz wa
	lda xbc, (0x011963:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld hl, wa
	lds wa, 4
	cps hl, 4
	jr lt, Voice_Calc_LevelPair_Full_WriteCh2
	ld wa, hl

; Rate for pair 3 = table_0x011963[paramA+44]; writes shadow words 0x0451E6 (TG bank
; 0x840) and 0x0451E8 (TG bank 0x880) and returns.
Voice_Calc_LevelPair_Full_WriteCh2:
	ld hl, wa
	ld xwa, (xsp + 4)
	ld a, (xwa + 44)
	extz wa
	lda xbc, (0x011963:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld de, wa
	ld wa, hl
	ldb w, 0x0
	ld bc, (xsp + 10)
	sla bc, 8
	or bc, wa
	stw_da 0x0451e6, xbc
	ld wa, de
	ldb w, 0x0
	ld bc, (xsp + 12)
	sla bc, 8
	or bc, wa
	stw_da 0x0451e8, xbc
	pop xiz
	lda xsp, (xsp + 14)
	ret

; Voice_Calc_LevelPair_Mono(XWA = voice-slot record) -- the same three-pair computation as
; Voice_Calc_LevelPair_Full, for the voice type that has no per-oscillator trim on the base
; pair but does have one on pairs 2 and 3. Called from Voice_Release_Type4_BranchA.
;
; Differences from the _Full variant, all verified against the disassembly:
;   * pair 1 level is table_0x011899[paramA+39] with NO tonerec byte added and no
;     0..0x64 clamp before the lookup;
;   * pairs 2 and 3 add the signed tonerec[0x010B] byte to paramA+41 / paramA+43 and
;     clamp to 0..0x64 before the table_0x0118FE lookup;
;   * the modulation term for pairs 2/3 is added to BOTH pairs (the _Full variant adds
;     it to pair 2 and pair 3 separately, without the extra IZ term).
; The result words and their destinations (0x0451E4/E6/E8) are identical.
;
; Its tail labels (0x0261BC..0x026244) used to be named "..._Full2_..."; there is no
; "Full2" routine -- _Full ends at 0x025F7E with its own ret -- so they now carry the
; _Mono prefix they belong to.
Voice_Calc_LevelPair_Mono:
	lda xsp, (xsp - 14)
	push xiz
	ld (xsp + 14), xwa
	ld xwa, (xsp + 14)
	ld xwa, (xwa + 23)
	ld (xsp + 4), xwa
	ld xwa, (xsp + 14)
	ld xwa, (xwa + 19)
	bitm 4, (xwa + 16)
	jr z, Voice_Calc_LevelPair_Mono_SetInvFlag
	ld xwa, (xsp + 14)
	andmi16 (xwa + 1), 0x7FFF
	jr Voice_Calc_LevelPair_Mono_ComputeLevel

; Bit 4 of tonerec-ish record (slot+19)[+16] clear -> set bit 15 of slot+1; set -> clear
; it. Same polarity flag the _Full variant maintains.
Voice_Calc_LevelPair_Mono_SetInvFlag:
	ld xwa, (xsp + 14)
	ormi16 (xwa + 1), 0x8000

; Base level = table_0x011899[paramA+39]; then the LFO / depth modulation chain.
Voice_Calc_LevelPair_Mono_ComputeLevel:
	ld xwa, (xsp + 4)
	ld a, (xwa + 39)
	extz wa
	lda xbc, (0x011899:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ldw_erp WA, 0xFA
	ld xwa, (xsp + 4)
	cp (xwa + 51), 0x0
	jrl z, Voice_Calc_LevelPair_Mono_NoLFO
	ld xwa, (xsp + 4)
	ld a, (xwa + 48)
	ld c, a
	extz bc
	ld xwa, (xsp + 4)
	ld a, (xwa + 49)
	ld e, a
	extz de
	ld xwa, (xsp + 4)
	ld a, (xwa + 50)
	extz wa
	pushw wa
	ld xwa, (xsp + 6)
	ld a, (xwa + 51)
	exts wa
	pushw wa
	ld xwa, (xsp + 18)
	ld wa, (xwa + 8)
	calr Pan_ScaleWithVelocity
	ld (xsp + 8), hl
	ld xwa, (xsp + 4)
	cp (xwa + 46), 0x0
	jr z, Voice_Calc_LevelPair_Mono_NoDepth
	ld xwa, (xsp + 4)
	ld a, (xwa + 46)
	ld e, a
	exts de
	ld xwa, (xsp + 14)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	ld wa, de
	lds de, 4
	calr PitchBend_Scale
	ld iz, hl
	stw_erp WA, 0xFA
	add wa, (xsp + 8)
	add wa, iz
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ldw_erp HL, 0xFA
	jr Voice_Calc_LevelPair_Mono_CheckMax

; paramA+46 == 0: add only the Pan_ScaleWithVelocity term, clamp 0..0xFF.
Voice_Calc_LevelPair_Mono_NoDepth:
	stw_erp WA, 0xFA
	add wa, (xsp + 8)
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ldw_erp HL, 0xFA
	jr Voice_Calc_LevelPair_Mono_CheckMax

; paramA+51 == 0: skip the velocity/LFO scaler entirely.
Voice_Calc_LevelPair_Mono_NoLFO:
	ld xwa, (xsp + 4)
	cp (xwa + 46), 0x0
	jr z, Voice_Calc_LevelPair_Mono_CheckMax
	ld xwa, (xsp + 4)
	ld a, (xwa + 46)
	ld e, a
	exts de
	ld xwa, (xsp + 14)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	ld wa, de
	lds de, 4
	calr PitchBend_Scale
	ld iz, hl
	stw_erp WA, 0xFA
	add wa, iz
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ldw_erp HL, 0xFA

; Same 0xFF reservation as Voice_Calc_LevelPair_Full_CheckMax.
Voice_Calc_LevelPair_Mono_CheckMax:
	ld xwa, (xsp + 14)
	ld xwa, (xwa + 31)
	bitm 0, (xwa)
	jr z, Voice_Calc_LevelPair_Mono_WriteDSP
	stw_erp WA, 0xFA
	cp wa, 0xFF
	jr nz, Voice_Calc_LevelPair_Mono_WriteDSP
	dec1w_erp 0xFA

; Writes pair 1 to 0x0451E4 and slot+60, then builds pairs 2 and 3 with the tonerec
; [0x010B] trim added before the 0x0118FE lookup.
Voice_Calc_LevelPair_Mono_WriteDSP:
	ld xwa, (xsp + 4)
	ld a, (xwa + 40)
	extz wa
	lda xbc, (0x011963:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ldb w, 0x0
	stw_erp BC, 0xFA
	sla bc, 8
	or bc, wa
	stw_da 0x0451e4, xbc
	ld xwa, (xsp + 14)
	ld (xwa + 60), bc
	ld xwa, (xsp + 14)
	ld xwa, (xwa + 35)
	ldb_sri0 A, (xwa + 0x010b)
	ld c, a
	exts bc
	ld xwa, (xsp + 4)
	ld a, (xwa + 41)
	extz wa
	add wa, bc
	ldw bc, 0x64
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 10), hl
	ld wa, (xsp + 10)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld (xsp + 10), wa
	ld xwa, (xsp + 14)
	ld xwa, (xwa + 35)
	ldb_sri0 A, (xwa + 0x010b)
	ld c, a
	exts bc
	ld xwa, (xsp + 4)
	ld a, (xwa + 43)
	extz wa
	add wa, bc
	ldw bc, 0x64
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 12), hl
	ld wa, (xsp + 12)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld (xsp + 12), wa
	ld xwa, (xsp + 4)
	cp (xwa + 52), 0x0
	jrl z, Voice_Calc_LevelPair_Mono_NoDepth2
	ld xwa, (xsp + 4)
	ld a, (xwa + 48)
	ld c, a
	extz bc
	ld xwa, (xsp + 4)
	ld a, (xwa + 49)
	ld e, a
	extz de
	ld xwa, (xsp + 4)
	ld a, (xwa + 50)
	extz wa
	pushw wa
	ld xwa, (xsp + 6)
	ld a, (xwa + 52)
	exts wa
	pushw wa
	ld xwa, (xsp + 18)
	ld wa, (xwa + 8)
	calr Pan_ScaleWithVelocity
	ld (xsp + 8), hl
	ld xwa, (xsp + 4)
	cp (xwa + 47), 0x0
	jr z, Voice_Calc_LevelPair_Mono_NoModDepth
	ld xwa, (xsp + 4)
	ld a, (xwa + 47)
	ld e, a
	exts de
	ld xwa, (xsp + 14)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	ld wa, de
	lds de, 4
	calr PitchBend_Scale
	ld iz, hl
	ld wa, (xsp + 10)
	add wa, (xsp + 8)
	add wa, iz
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 10), hl
	ld wa, (xsp + 12)
	add wa, (xsp + 8)
	add wa, iz
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 12), hl
	jr Voice_Calc_LevelPair_Mono_WriteChDepth

; Tail of Voice_Calc_LevelPair_Mono: paramA+47 == 0 -> add only the LFO scaler to pairs 2/3.
Voice_Calc_LevelPair_Mono_NoModDepth:
	ld wa, (xsp + 10)
	add wa, (xsp + 8)
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 10), hl
	ld wa, (xsp + 12)
	add wa, (xsp + 8)
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 12), hl
	jr Voice_Calc_LevelPair_Mono_WriteChDepth

; Tail of Voice_Calc_LevelPair_Mono: paramA+52 == 0 -> apply only the paramA+47 depth term.
Voice_Calc_LevelPair_Mono_NoDepth2:
	ld xwa, (xsp + 4)
	cp (xwa + 47), 0x0
	jr z, Voice_Calc_LevelPair_Mono_WriteChDepth
	ld xwa, (xsp + 4)
	ld a, (xwa + 47)
	ld e, a
	exts de
	ld xwa, (xsp + 14)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	ld wa, de
	lds de, 4
	calr PitchBend_Scale
	ld iz, hl
	ld wa, (xsp + 10)
	add wa, iz
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 10), hl
	ld wa, (xsp + 12)
	add wa, iz
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld (xsp + 12), hl

; Tail of Voice_Calc_LevelPair_Mono: rate for pair 2, floored at 4.
Voice_Calc_LevelPair_Mono_WriteChDepth:
	ld xwa, (xsp + 4)
	ld a, (xwa + 42)
	extz wa
	lda xbc, (0x011963:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld hl, wa
	lds wa, 4
	cps hl, 4
	jr lt, Voice_Calc_LevelPair_Mono_WriteCh2
	ld wa, hl

; Tail of Voice_Calc_LevelPair_Mono: rate for pair 3; writes 0x0451E6 and 0x0451E8; returns.
Voice_Calc_LevelPair_Mono_WriteCh2:
	ld hl, wa
	ld xwa, (xsp + 4)
	ld a, (xwa + 44)
	extz wa
	lda xbc, (0x011963:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld de, wa
	ld wa, hl
	ldb w, 0x0
	ld bc, (xsp + 10)
	sla bc, 8
	or bc, wa
	stw_da 0x0451e6, xbc
	ld wa, de
	ldb w, 0x0
	ld bc, (xsp + 12)
	sla bc, 8
	or bc, wa
	stw_da 0x0451e8, xbc
	pop xiz
	lda xsp, (xsp + 14)
	ret

; Voice_InterpolatePanCurve(XWA = voice-slot record, XBC = paramA record) -> HL.
; Velocity crossfade/zone shaper. Takes the velocity byte from slot+8 (bits 8..14) and
; four breakpoints from the paramA record:
;     +30 = plateau low edge      +31 = fade-out low edge
;     +32 = plateau high edge     +33 = fade-out high edge
; Returns 0 inside the plateau [+30..+32]; a linear ramp in [0..-64] between +31 and +30
; and between +32 and +33 (numerator scaled by 0xFFC0 = -64, divided by the breakpoint
; span with a signed 32/16 divs); and the constant 0xFE00 (-512) outside [+31..+33].
; Pure computation; no hardware, no memory written.
; Sole caller: Voice_ComputePitch_ApplyLFO, which ADDS the result into the pitch
; accumulator -- so despite the "Pan" in the name this is a pitch-domain correction.
Voice_InterpolatePanCurve:
	ld hl, (xwa + 8)
	and hl, 0x7F00
	sra hl, 8
	ld a, (xbc + 30)
	extz wa
	cp hl, wa
	jr ge, Voice_InterpolatePanCurve_HighCheck
	ld a, (xbc + 31)
	extz wa
	cp hl, wa
	jr ge, Voice_InterpolatePanCurve_LowRange
	ldw hl, 0xFE00
	jr Voice_InterpolatePanCurve_Done

; Velocity between +31 and +30: ramp -64 -> 0 as velocity rises.
Voice_InterpolatePanCurve_LowRange:
	ld a, (xbc + 31)
	ld e, a
	extz de
	ld a, (xbc + 30)
	extz wa
	ld ix, wa
	sub ix, de
	ld a, (xbc + 30)
	extz wa
	sub wa, hl
	muls wa, 0xFFC0
	ld hl, wa
	exts xwa
	divs xwa, xix
	ld hl, wa
	jr Voice_InterpolatePanCurve_Done

; Velocity at or above +30: test it against the upper plateau edge +32.
Voice_InterpolatePanCurve_HighCheck:
	ld a, (xbc + 32)
	extz wa
	cp hl, wa
	jr le, Voice_InterpolatePanCurve_Zero
	ld a, (xbc + 33)
	extz wa
	cp hl, wa
	jr le, Voice_InterpolatePanCurve_HighRange
	ldw hl, 0xFE00
	jr Voice_InterpolatePanCurve_Done

; Velocity between +32 and +33: ramp 0 -> -64 as velocity rises.
Voice_InterpolatePanCurve_HighRange:
	ld a, (xbc + 32)
	ld e, a
	extz de
	ld a, (xbc + 33)
	extz wa
	ld ix, wa
	sub ix, de
	ld a, (xbc + 32)
	extz wa
	ld bc, hl
	sub bc, wa
	ld wa, bc
	muls wa, 0xFFC0
	ld hl, wa
	exts xwa
	divs xwa, xix
	ld hl, wa
	jr Voice_InterpolatePanCurve_Done

; Inside the plateau: return 0 (no correction).
Voice_InterpolatePanCurve_Zero:
	lds hl, 0

; Common return.
Voice_InterpolatePanCurve_Done:
	ret

; Voice_InterpolateNoteCurve(XWA = voice-slot record, XBC = paramA record) -> HL.
; Byte-for-byte the same shaper as Voice_InterpolatePanCurve, but keyed on the MIDI note
; number (slot+12 & 0x7F) and using paramA breakpoints +34/+35/+36/+37 instead of
; +30..+33. Returns 0 / [0..-64] / -512 with the same meanings.
; Sole caller: Voice_ComputePitch_ApplyLFO, added to the pitch accumulator.
Voice_InterpolateNoteCurve:
	ld a, (xwa + 12)
	ld l, a
	extz hl
	and hl, 0x7F
	ld a, (xbc + 34)
	extz wa
	cp hl, wa
	jr ge, Voice_InterpolateNoteCurve_HighCheck
	ld a, (xbc + 35)
	extz wa
	cp hl, wa
	jr ge, Voice_InterpolateNoteCurve_LowRange
	ldw hl, 0xFE00
	jr Voice_InterpolateNoteCurve_Done

; Note between +35 and +34: ramp -64 -> 0.
Voice_InterpolateNoteCurve_LowRange:
	ld a, (xbc + 35)
	ld e, a
	extz de
	ld a, (xbc + 34)
	extz wa
	ld ix, wa
	sub ix, de
	ld a, (xbc + 34)
	extz wa
	sub wa, hl
	muls wa, 0xFFC0
	ld hl, wa
	exts xwa
	divs xwa, xix
	ld hl, wa
	jr Voice_InterpolateNoteCurve_Done

; Note at or above +34: test against the upper plateau edge +36.
Voice_InterpolateNoteCurve_HighCheck:
	ld a, (xbc + 36)
	extz wa
	cp hl, wa
	jr le, Voice_InterpolateNoteCurve_Zero
	ld a, (xbc + 37)
	extz wa
	cp hl, wa
	jr le, Voice_InterpolateNoteCurve_HighRange
	ldw hl, 0xFE00
	jr Voice_InterpolateNoteCurve_Done

; Note between +36 and +37: ramp 0 -> -64.
Voice_InterpolateNoteCurve_HighRange:
	ld a, (xbc + 36)
	ld e, a
	extz de
	ld a, (xbc + 37)
	extz wa
	ld ix, wa
	sub ix, de
	ld a, (xbc + 36)
	extz wa
	ld bc, hl
	sub bc, wa
	ld wa, bc
	muls wa, 0xFFC0
	ld hl, wa
	exts xwa
	divs xwa, xix
	ld hl, wa
	jr Voice_InterpolateNoteCurve_Done

; Inside the plateau: return 0.
Voice_InterpolateNoteCurve_Zero:
	lds hl, 0

; Common return.
Voice_InterpolateNoteCurve_Done:
	ret

; Voice_ComputePitch(XWA = voice-slot record). Computes the voice's pitch word and
; stores it at slot+13; also clears the portamento offset at slot+51.
; Callers: Voice_Build_Register_Set, Voice_Release_Type4, Voice_Release_Type4_BranchA.
;
; Inputs: slot+12 = MIDI note (bit 7 is a flag, not part of the note -- if set, bit 11
; of slot+1 is raised); slot+23 = paramA record; slot+15, slot+35 = controller and tone
; records; global tuning-mode word 0x041343; global master offset dword at 0x045314.
;
; Two mutually exclusive note->pitch mappings:
;   * ALTERNATE mapping, taken when bit 0 of 0x041343 is set (set by
;     Voice_SetPolyphonyMode with A==1), or bit 1 is set (Voice_SetCCMaxFlag), or
;     paramA+25 == 0xE0: pitch = table_0x011C96[note] - 0x0C. That table is a plain
;     128-byte monotonic curve 0x00..0xFF -- a direct, un-detuned note->increment map.
;   * NORMAL mapping: table_0x00FEE4[note] fed through Voice_Colour_LookupIndex with
;     paramA+25, minus 0xD0, multiplied by the signed detune paramA+24, arithmetic-
;     shifted right by 5 and biased by +0xD8.
;
; Both paths then converge on _ApplyLFO, which sums: the LFO/velocity scaler
; (paramA+26..+29 via Voice_Colour_ClampUpper), table_0x011A4F[slot+43 & 0x7F] (a signed
; +-8 fine-tune curve), the signed byte at (slot+15)+3, the 32-bit global at 0x045314,
; the constant 0x2940, and the two crossfade corrections from
; Voice_InterpolatePanCurve / Voice_InterpolateNoteCurve. If bit 7 of paramA[0] is set,
; tonerec[0x011E] is added on top.
; Touches no hardware; the result reaches the TG later via Voice_ApplyPortamento ->
; Voice_Build_OutputLevel.
Voice_ComputePitch:
	dec 8, xsp
	pushw iz
	ld (xsp + 6), xwa
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 23)
	ld (xsp + 2), xwa
	ld xwa, (xsp + 6)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	bit 7, bc
	jr z, Voice_ComputePitch_CheckSysExTune
	ld xwa, (xsp + 6)
	ormi16 (xwa + 1), 0x800

; Mask the note to 7 bits; select the alternate table if 0x041343 bit 0 is set or
; paramA+25 == 0xE0.
Voice_ComputePitch_CheckSysExTune:
	and bc, 0x7F
	ld wa, (0x041343:24)
	bit 0, wa
	jr nz, Voice_ComputePitch_SysExTable
	ld xwa, (xsp + 2)
	cp (xwa + 25), 0xE0
	jr nz, Voice_ComputePitch_CheckAltTune

; Alternate mapping: IZ = table_0x011C96[note] - 0x0C.
Voice_ComputePitch_SysExTable:
	ld wa, bc
	extz xwa
	ld xbc, 0x11C96
	add xbc, xwa
	ld a, (xbc)
	extz wa
	ld iz, wa
	sub iz, 0xC
	jrl Voice_ComputePitch_ApplyLFO

; Second entry point to the alternate mapping, gated on 0x041343 bit 1.
Voice_ComputePitch_CheckAltTune:
	ld wa, (0x041343:24)
	bit 1, wa
	jr z, Voice_ComputePitch_NormalTune
	ld wa, bc
	extz xwa
	ld xbc, 0x11C96
	add xbc, xwa
	ld a, (xbc)
	extz wa
	ld iz, wa
	sub iz, 0xC
	jr Voice_ComputePitch_ApplyLFO

; Normal mapping, negative-detune arm: negate paramA+24 before the multiply.
Voice_ComputePitch_NormalTune:
	ld xwa, (xsp + 2)
	cp (xwa + 24), 0x0
	jr ge, Voice_ComputePitch_PortaPositive
	ld wa, bc
	extz xwa
	ld xbc, 0xFEE4
	add xbc, xwa
	ld a, (xbc)
	ld c, a
	extz bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 25)
	ld e, a
	extz de
	ld wa, bc
	ld bc, de
	calr Voice_Colour_LookupIndex
	sub hl, 0xD0
	ld xwa, (xsp + 2)
	ld a, (xwa + 24)
	exts wa
	cpl wa
	ld bc, wa
	inc 1, bc
	ld wa, hl
	muls xwa, xbc
	ld hl, wa
	jr Voice_ComputePitch_PortaScale

; Normal mapping, non-negative-detune arm.
Voice_ComputePitch_PortaPositive:
	ld xwa, (xsp + 2)
	ld a, (xwa + 25)
	ld e, a
	extz de
	ld wa, bc
	ld bc, de
	calr Voice_Colour_LookupIndex
	sub hl, 0xD0
	ld xwa, (xsp + 2)
	ld a, (xwa + 24)
	ld c, a
	exts bc
	ld wa, hl
	muls xwa, xbc
	ld hl, wa

; Common scaling of the detuned value: >>5 (arithmetic) then bias +0xD8.
Voice_ComputePitch_PortaScale:
	sra hl, 5
	ld iz, hl
	add iz, 0xD8

; Accumulates every additive pitch term (LFO scaler, 0x011A4F fine tune, controller
; byte, global 0x045314, +0x2940, velocity and key crossfades, optional tonerec[0x011E]).
Voice_ComputePitch_ApplyLFO:
	ld xwa, (xsp + 2)
	ld a, (xwa + 26)
	ld c, a
	extz bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 27)
	ld e, a
	extz de
	ld xwa, (xsp + 2)
	ld a, (xwa + 28)
	extz wa
	pushw wa
	ld xwa, (xsp + 4)
	ld a, (xwa + 29)
	exts wa
	pushw wa
	ld xwa, (xsp + 10)
	ld wa, (xwa + 8)
	calr Voice_Colour_ClampUpper
	add iz, hl
	ld xwa, (xsp + 6)
	ld wa, (xwa + 43)
	and wa, 0x7F
	extz xwa
	ld xbc, 0x11A4F
	add xbc, xwa
	ld a, (xbc)
	exts wa
	add iz, wa
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 15)
	ld a, (xwa + 3)
	exts wa
	add iz, wa
	ld xwa, (0x045314:24)
	add_sriw_rm IZ, 0xE1, 0xE0, 0x00
	addda16 xiz, 10560
	ld xwa, (xsp + 6)
	ld xbc, (xsp + 2)
	calr Voice_InterpolatePanCurve
	add iz, hl
	ld xwa, (xsp + 6)
	ld xbc, (xsp + 2)
	calr Voice_InterpolateNoteCurve
	add iz, hl
	ld xwa, (xsp + 2)
	bitm 7, (xwa)
	jr z, Voice_ComputePitch_WriteDone
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ldb_sri0 A, (xwa + 0x011e)
	extz wa
	add iz, wa

; Store the accumulator to slot+13 and clear the portamento offset slot+51.
Voice_ComputePitch_WriteDone:
	ld xwa, (xsp + 6)
	ld (xwa + 13), iz
	ld xwa, (xsp + 6)
	ldw (xwa + 51), 0x0
	popw iz
	inc 8, xsp
	ret

; Despite the name, these 17 bytes are EXECUTABLE CODE, not data.
; "clamp WA into [DE..BC], return in HL" -- the same operation as
; ClampS16_WA_To_DEBC at 0x022B19, with the low bound tested first (that routine tests
; the high bound first). Nothing in the image references it; it is dead code left between
; Voice_ComputePitch and Voice_ComputePitch_Mono.
; Converted from `.byte` to real mnemonics 2026-09-01 (lane SUB): `jr ge, 4` / `jr 6` /
; `jr le, 2` take the raw 8-bit displacement field, verified byte-identical via a llvm-mc
; round trip (assemble -> objcopy -> compare against the original 17 bytes).
Voice_ComputePitch_InlineData:
	cp	wa, de
	jr	ge, 4
	ld	wa, de
	jr	6
	cp	wa, bc
	jr	le, 2
	ld	wa, bc
	ld	hl, wa
	ret

; Voice_ComputePitch_Mono(XWA = voice-slot record). The cut-down pitch computation used
; by the mono/legato voice types; callers are Voice_Init_Type1 and Voice_Init_Type2.
; Same two mappings as Voice_ComputePitch (alternate table 0x011C96 gated on 0x041343
; bits 0/1 or paramA+7 == 0xE0; otherwise the 0x00FEE4 + Voice_Colour_LookupIndex path
; scaled by the signed detune at paramA+6), but it reads its detune/curve selectors from
; paramA+6/+7 instead of +24/+25, and its _ApplyLFO tail omits the velocity/key
; crossfades and the tonerec[0x011E] term. Writes slot+13 and clears slot+51.
Voice_ComputePitch_Mono:
	dec 4, xsp
	push xiz
	ld (xsp + 4), xwa
	ld xwa, (xsp + 4)
	ld xiz, (xwa + 23)
	ld xwa, (xsp + 4)
	ld a, (xwa + 12)
	ld e, a
	extz de
	and de, 0x7F
	ld wa, (0x041343:24)
	bit 0, wa
	jr nz, Voice_ComputePitch_Mono_SysExTable
	cp (xiz + 7), 0xE0
	jr nz, Voice_ComputePitch_Mono_CheckAltTune

; Alternate mapping: HL = table_0x011C96[note] - 0x0C.
Voice_ComputePitch_Mono_SysExTable:
	ld wa, de
	extz xwa
	ld xbc, 0x11C96
	add xbc, xwa
	ld a, (xbc)
	extz wa
	ld hl, wa
	sub hl, 0xC
	jr Voice_ComputePitch_Mono_ApplyLFO

; Second gate on 0x041343 bit 1 into the alternate mapping.
Voice_ComputePitch_Mono_CheckAltTune:
	ld wa, (0x041343:24)
	bit 1, wa
	jr z, Voice_ComputePitch_Mono_CheckPorta
	ld wa, de
	extz xwa
	ld xbc, 0x11C96
	add xbc, xwa
	ld a, (xbc)
	extz wa
	ld hl, wa
	sub hl, 0xC

; Normal mapping, negative-detune arm (paramA+6 < 0).
Voice_ComputePitch_Mono_CheckPorta:
	cp (xiz + 6), 0x0
	jr ge, Voice_ComputePitch_Mono_PortaPositive
	ld wa, de
	extz xwa
	ld xbc, 0xFEE4
	add xbc, xwa
	ld a, (xbc)
	ld e, a
	extz de
	ld a, (xiz + 7)
	ld c, a
	extz bc
	ld wa, de
	calr Voice_Colour_LookupIndex
	sub hl, 0xD0
	ld a, (xiz + 6)
	exts wa
	cpl wa
	ld bc, wa
	inc 1, bc
	ld wa, hl
	muls xwa, xbc
	ld hl, wa
	jr Voice_ComputePitch_Mono_PortaScale

; Normal mapping, non-negative-detune arm.
Voice_ComputePitch_Mono_PortaPositive:
	ld a, (xiz + 7)
	ld c, a
	extz bc
	ld wa, de
	calr Voice_Colour_LookupIndex
	sub hl, 0xD0
	ld a, (xiz + 6)
	ld c, a
	exts bc
	ld wa, hl
	muls xwa, xbc
	ld hl, wa

; >>5 then bias +0xD8.
Voice_ComputePitch_Mono_PortaScale:
	sra hl, 5
	add hl, 0xD8

; Adds table_0x011A4F[slot+43 & 0x7F], the byte at (slot+15)+3, the global at 0x045314
; and +0x2940; stores to slot+13 and clears slot+51.
Voice_ComputePitch_Mono_ApplyLFO:
	ld xwa, (xsp + 4)
	ld wa, (xwa + 43)
	and wa, 0x7F
	extz xwa
	ld xbc, 0x11A4F
	add xbc, xwa
	ld a, (xbc)
	exts wa
	add hl, wa
	ld xwa, (xsp + 4)
	ld xwa, (xwa + 15)
	ld a, (xwa + 3)
	exts wa
	add hl, wa
	ld xwa, (0x045314:24)
	add_sriw_rm HL, 0xE1, 0xE0, 0x00
	addda16 xhl, 10560
	ld xwa, (xsp + 4)
	ld (xwa + 13), hl
	ld xwa, (xsp + 4)
	ldw (xwa + 51), 0x0
	pop xiz
	inc 4, xsp
	ret

; Voice_ApplyPortamento(XWA = voice-slot record). Takes the pitch computed at slot+13,
; applies the channel detune and the key-shift correction, and tail-jumps into
; Voice_Build_OutputLevel (which adds tonerec[+12], tonerec[+16] and the portamento offset
; slot+51, clamps, and pushes the value at the tone generator).
; Detune: paramA+23 non-zero -> add (paramA+23 - 0x64); zero -> subtract 0x200.
; Then always add the signed byte (slot+39)[+34].
; If bit 1 of the global mode word 0x041343 is set: for slot+4 <= 1 subtract
; tonerec[+16] and a further 8; otherwise subtract 0x10.
; Callers: Voice_Build_Register_Set, Voice_Release_Type4(_BranchA),
; Voice_AllVoices_WriteAmplitude_BranchA, and both portamento ramp write-backs
; (Voice_Step_ExprRamp_Ascend_WritePitch / _Release_WritePitch).
Voice_ApplyPortamento:
	ld de, (xwa + 13)
	ld xbc, (xwa + 23)
	cp (xbc + 23), 0x0
	jr z, Voice_ApplyPortamento_NoChanDetune
	ld xbc, (xwa + 23)
	ld c, (xbc + 23)
	extz bc
	sub bc, 0x64
	add de, bc
	jr Voice_ApplyPortamento_ApplyDetune

; paramA+23 == 0: apply the fixed -0x200 bias instead of a channel detune.
Voice_ApplyPortamento_NoChanDetune:
	sub de, 0x200

; Add the signed byte (slot+39)[+34], then test 0x041343 bit 1 for the key-shift arm.
Voice_ApplyPortamento_ApplyDetune:
	ld xbc, (xwa + 39)
	ld c, (xbc + 34)
	exts bc
	add de, bc
	ld bc, (0x041343:24)
	bit 1, bc
	jr z, Voice_ApplyPortamento_Done
	cp (xwa + 4), 0x1
	jr ugt, Voice_ApplyPortamento_HighNote
	ld xbc, (xwa + 35)
	sub de, (xbc + 16)
	dec 8, de
	jr Voice_ApplyPortamento_Done

; slot+4 > 1 arm of the key-shift correction: subtract a flat 0x10.
Voice_ApplyPortamento_HighNote:
	sub de, 0x10

; Move the result to BC and tail-jump to Voice_Build_OutputLevel.
Voice_ApplyPortamento_Done:
	ld bc, de
	jrl Voice_Build_OutputLevel

; Voice_ApplyPortamento2(XWA = voice-slot record). The mono/legato counterpart of
; Voice_ApplyPortamento. Channel detune comes from paramA+5 (not +23), there is no
; (slot+39)[+34] term, and the key-shift arm additionally subtracts tonerec[+12] and then
; adds back a vibrato contribution of tonerec[+12] >> 2 -- except when tonerec[+12] is
; exactly 0xFE00, in which case the raw 0xFE00 is added (a sentinel, the same -512 value
; the crossfade shapers use). Tail-jumps to Voice_Build_OutputLevel.
; Callers: Voice_Init_Type1, Voice_Init_Type2, Voice_AllVoices_WriteAmplitude_BranchB.
Voice_ApplyPortamento2:
	ld xbc, (xwa + 23)
	ld de, (xwa + 13)
	cp (xbc + 5), 0x0
	jr z, Voice_ApplyPortamento2_NoChanDetune
	ld c, (xbc + 5)
	extz bc
	sub bc, 0x64
	add de, bc
	jr Voice_ApplyPortamento2_ApplyDetune

; paramA+5 == 0: apply the fixed -0x200 bias.
Voice_ApplyPortamento2_NoChanDetune:
	sub de, 0x200

; Key-shift arm gated on 0x041343 bit 1; computes the tonerec[+12] vibrato term.
Voice_ApplyPortamento2_ApplyDetune:
	ld bc, (0x041343:24)
	bit 1, bc
	jr z, Voice_ApplyPortamento2_Done
	ld xbc, (xwa + 35)
	sub de, (xbc + 16)
	ld xbc, (xwa + 35)
	sub de, (xbc + 12)
	ldw hl, 0xFE00
	ld xbc, (xwa + 35)
	ld bc, (xbc + 12)
	cp bc, 0xFE00
	jr z, Voice_ApplyPortamento2_AddVibrato
	ld xbc, (xwa + 35)
	ld bc, (xbc + 12)
	sra bc, 2
	ld hl, bc

; Add the vibrato term (either tonerec[+12]>>2 or the 0xFE00 sentinel).
Voice_ApplyPortamento2_AddVibrato:
	add de, hl

; Move to BC and tail-jump to Voice_Build_OutputLevel.
Voice_ApplyPortamento2_Done:
	ld bc, de
	jrl Voice_Build_OutputLevel

; Voice_WriteChPitchWithVib(WA = part index, BC = MIDI channel). Broadcasts one part's
; note-level register pair to every voice slot currently owned by that channel.
; Sole caller: Voice_SetVelocity_Type80_SlotLoop.
;
; Reads the per-channel record at 0x0430AD + ch*0x47; returns immediately unless bit 3 of
; its first byte is set. Byte +14 of that record indexes the 0x011AE8 table (a flat table
; of 0x96), and the result is staged as (v<<8)|0x80 at 0x0451F8 and (v<<8) at 0x0451FA --
; i.e. TG banks 0x800 and 0x840.
; It then calls Voice_Query_AllChannels's sibling Voice_Query_PartVoices to obtain a
; NUL-list of matching slot indices at (XHL+5) and, for each slot whose channel byte
; (record 0x0430AD + slot*0x47, offset +14) matches, calls ToneGen_WriteLevelPair to
; push shadow offsets +44/+46 into TG banks 0x800/0x840 through 0x100000/0x100002.
Voice_WriteChPitchWithVib:
	dec 2, xsp
	push xiz
	extz bc
	muls bc, 0x47
	lda xde, (0x0430ad:24)
	ld_sril3 XBC, 0x07, 0xE8, 0xE4
	bitm 3, (xbc)
	jr z, Voice_WriteChPitchWithVib_Done
	ld c, (xbc + 14)
	ld (xsp + 4), c
	extz bc
	lda xde, (0x011ae8:24)
	ldb_sri C, 0x07, 0xE8, 0xE4
	extz bc
	sll bc, 8
	set 7, bc
	stw_da 0x0451f8, xbc
	ld c, (xsp + 4)
	extz bc
	lda xde, (0x011ae8:24)
	ldb_sri C, 0x07, 0xE8, 0xE4
	extz bc
	sll bc, 8
	stw_da 0x0451fa, xbc
	extz wa
	call Voice_Query_PartVoices
	lda xwa, (xhl + 5)
	ld xiz, xwa
	cp (xiz), 0x40
	jr nc, Voice_WriteChPitchWithVib_Done

; Per-slot body: match the slot's channel byte, then push the two TG registers.
Voice_WriteChPitchWithVib_Loop:
	ld a, (xiz)
	extz wa
	muls wa, 0x47
	lda xbc, (0x0430ad:24)
	ld_sril3 XBC, 0x07, 0xE4, 0xE0
	ld a, (xsp + 4)
	cp a, (xbc + 14)
	jr nz, Voice_WriteChPitchWithVib_NextSlot
	ld a, (xiz)
	extz wa
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteLevelPair

; Advance the slot-list cursor; the list terminates on the first index >= 0x40.
Voice_WriteChPitchWithVib_NextSlot:
	inc 1, xiz
	cp (xiz), 0x40
	jr c, Voice_WriteChPitchWithVib_Loop

; Restore IZ and return.
Voice_WriteChPitchWithVib_Done:
	pop xiz
	inc 2, xsp
	ret

Voice_Calc_LevelPair_EGA:
	dec 8, xsp
	pushw iz
	ld (xsp + 6), xwa
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 23)
	ld (xsp + 2), xwa
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld a, (xwa + 108)
	ld c, a
	exts bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 45)
	extz wa
	add wa, bc
	ldw bc, 0x64
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld iz, hl
	stb_erp A, 0xF8
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld iz, wa
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld wa, (xwa + 10)
	bit 0, wa
	jr z, Voice_Calc_LevelPair_EGA_ApplyLFO
	ld xwa, (xsp + 6)
	ld wa, (xwa + 1)
	bit 8, wa
	jr nz, Voice_Calc_LevelPair_EGA_ApplyLFO
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld a, (xwa + 24)
	extz wa
	lda xbc, (0x011adf:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	cp wa, iz
	jr gt, Voice_Calc_LevelPair_EGA_ApplyLFO
	ld iz, wa

; Body of Voice_Calc_LevelPair_EGA (entry 0x026769, already named -- left alone).
; That routine computes the level for register pair 1 from tonerec[108] + paramA+45,
; clamped 0..0x64 and curved through table_0x0118FE, optionally capped by
; table_0x0118FE[table_0x011ADF[tonerec+24]] when bit 0 of tonerec+10 is set and bit 8 of
; slot+1 is clear.
; This label is the modulation stage: if paramA+53 is non-zero, add
; Pan_ScaleWithVelocity(paramA+48..+50, depth paramA+53, velocity slot+8) and re-clamp
; through Voice_Clamp_Byte_HL.
Voice_Calc_LevelPair_EGA_ApplyLFO:
	ld xwa, (xsp + 2)
	cp (xwa + 53), 0x0
	jr z, Voice_Calc_LevelPair_EGA_WriteDSP
	ld xwa, (xsp + 2)
	ld a, (xwa + 48)
	ld c, a
	extz bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 49)
	ld e, a
	extz de
	ld xwa, (xsp + 2)
	ld a, (xwa + 50)
	extz wa
	pushw wa
	ld xwa, (xsp + 4)
	ld a, (xwa + 53)
	exts wa
	pushw wa
	ld xwa, (xsp + 10)
	ld wa, (xwa + 8)
	calr Pan_ScaleWithVelocity
	add iz, hl
	ld wa, iz
	calr Voice_Clamp_Byte_HL
	ld iz, hl

; Stage the result: 0x0451F8 = (level<<8)|0x0080, 0x0451FA = (level<<8). These are shadow
; offsets +44/+46, pushed to TG banks 0x800 and 0x840 by ToneGen_WriteLevelBurst*. Bit 7 of the
; low byte is the "apply now" flag that the note-on/full-dump path leaves clear.
Voice_Calc_LevelPair_EGA_WriteDSP:
	ld wa, iz
	sla wa, 8
	set 7, wa
	stw_da 0x0451f8, xwa
	ld wa, iz
	sla wa, 8
	stw_da 0x0451fa, xwa
	popw iz
	inc 8, xsp
	ret

Voice_Stage_EnvSegments:
	ld bc, (xwa + 62)
	stw_da 0x0451e6, xbc
	ld wa, (xwa + 64)
	stw_da 0x0451e8, xwa
	ret

; Voice_WriteVolume_SetFlag(XWA = voice-slot record). Two-instruction helper: copies the
; already-computed pair-1 word from slot+64 into shadow 0x0451F8 with bit 7 forced set,
; and the same word verbatim into 0x0451FA. Used to re-assert an existing level without
; recomputing it. Sole caller: Voice_AllNotes_SustainRetrigger_BranchE.
Voice_WriteVolume_SetFlag:
	ld bc, (xwa + 64)
	set 7, bc
	stw_da 0x0451f8, xbc
	ld wa, (xwa + 64)
	stw_da 0x0451fa, xwa
	ret

; Voice_ComputeVolume_CappedLFO(XWA = voice-slot record). Variant of
; Voice_Calc_LevelPair_EGA used on the voice-cut path (sole caller:
; Voice_Cut_BranchB). Difference: when bit 0 of tonerec+10 is SET the level is taken as
; the SMALLER of table_0x0118FE[table_0x011ADF[tonerec+24]] and
; table_0x0118FE[paramA+45] -- i.e. the oscillator ceiling wins outright rather than only
; capping. When the bit is clear it falls back to the tonerec[0x010D] + paramA+45 path.
; Stages the result to 0x0451F8/0x0451FA exactly as Volume1 does.
Voice_ComputeVolume_CappedLFO:
	dec 8, xsp
	pushw iz
	ld (xsp + 6), xwa
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 23)
	ld (xsp + 2), xwa
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld wa, (xwa + 10)
	bit 0, wa
	jr z, Voice_ComputeVolume_CappedLFO_UseOscMax
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld a, (xwa + 24)
	extz wa
	lda xbc, (0x011adf:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld iz, wa
	ld xwa, (xsp + 2)
	ld a, (xwa + 45)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld bc, iz
	cp bc, wa
	jr ule, Voice_ComputeVolume_CappedLFO_ApplyLFO
	ld xwa, (xsp + 2)
	ld a, (xwa + 45)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld iz, wa
	jr Voice_ComputeVolume_CappedLFO_ApplyLFO

; tonerec+10 bit 0 clear: level = curve(clamp(tonerec[0x010D] + paramA+45, 0..0x64)).
Voice_ComputeVolume_CappedLFO_UseOscMax:
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ldb_sri0 A, (xwa + 0x010d)
	ld c, a
	exts bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 45)
	extz wa
	add wa, bc
	ldw bc, 0x64
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld iz, hl
	stb_erp A, 0xF8
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld iz, wa

; Optional paramA+53 velocity/LFO term, then Voice_Clamp_Byte_HL.
Voice_ComputeVolume_CappedLFO_ApplyLFO:
	ld xwa, (xsp + 2)
	cp (xwa + 53), 0x0
	jr z, Voice_ComputeVolume_CappedLFO_WriteDSP
	ld xwa, (xsp + 2)
	ld a, (xwa + 48)
	ld c, a
	extz bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 49)
	ld e, a
	extz de
	ld xwa, (xsp + 2)
	ld a, (xwa + 50)
	extz wa
	pushw wa
	ld xwa, (xsp + 4)
	ld a, (xwa + 53)
	exts wa
	pushw wa
	ld xwa, (xsp + 10)
	ld wa, (xwa + 8)
	calr Pan_ScaleWithVelocity
	add iz, hl
	ld wa, iz
	calr Voice_Clamp_Byte_HL
	ld iz, hl

; Stage 0x0451F8 = (level<<8)|0x0080 and 0x0451FA = (level<<8).
Voice_ComputeVolume_CappedLFO_WriteDSP:
	ld wa, iz
	sla wa, 8
	set 7, wa
	stw_da 0x0451f8, xwa
	ld wa, iz
	sla wa, 8
	stw_da 0x0451fa, xwa
	popw iz
	inc 8, xsp
	ret

Voice_Calc_LevelPair_EGB:
	dec 8, xsp
	pushw iz
	ld (xsp + 6), xwa
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 23)
	ld (xsp + 2), xwa
	ld a, (xwa + 15)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld iz, wa
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld wa, (xwa + 10)
	bit 0, wa
	jr z, Voice_Calc_LevelPair_EGB_ApplyLFO
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld a, (xwa + 24)
	extz wa
	lda xbc, (0x011adf:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	cp wa, iz
	jr gt, Voice_Calc_LevelPair_EGB_ApplyLFO
	ld iz, wa

; Body of Voice_Calc_LevelPair_EGB (entry 0x026975, already named). That routine
; builds register pair 2 (shadow +48/+50 -> TG banks 0x900/0x940) from
; table_0x0118FE[paramA+15], optionally capped by the tonerec+24 oscillator ceiling.
; This label applies the paramA+22 velocity/LFO depth via Pan_ScaleWithVelocity with a
; fixed 0x7F ceiling.
Voice_Calc_LevelPair_EGB_ApplyLFO:
	ld xwa, (xsp + 2)
	cp (xwa + 22), 0x0
	jr z, Voice_Calc_LevelPair_EGB_NoLFO
	ld xwa, (xsp + 2)
	ld a, (xwa + 19)
	ld c, a
	extz bc
	pushw 0x7F
	ld xwa, (xsp + 4)
	ld a, (xwa + 22)
	exts wa
	pushw wa
	ld xwa, (xsp + 10)
	ld wa, (xwa + 8)
	lds de, 0
	calr Pan_ScaleWithVelocity
	add iz, hl
	ld xwa, (xsp + 2)
	cp (xwa + 17), 0x0
	jr z, Voice_Calc_LevelPair_EGB_NoKeyTrack
	ld xwa, (xsp + 2)
	ld a, (xwa + 17)
	ld e, a
	exts de
	ld xwa, (xsp + 6)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	ld wa, de
	lds de, 4
	calr PitchBend_Scale
	add iz, hl
	ld wa, iz
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld iz, hl
	jr Voice_Calc_LevelPair_EGB_WriteDSP

; paramA+17 == 0: skip the key-tracking term, just clamp 0..0xFF.
Voice_Calc_LevelPair_EGB_NoKeyTrack:
	ld wa, iz
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld iz, hl
	jr Voice_Calc_LevelPair_EGB_WriteDSP

; paramA+22 == 0: no velocity term; apply only the paramA+17 key-tracking term via
; PitchBend_Scale(note = slot+12).
Voice_Calc_LevelPair_EGB_NoLFO:
	ld xwa, (xsp + 2)
	cp (xwa + 17), 0x0
	jr z, Voice_Calc_LevelPair_EGB_WriteDSP
	ld xwa, (xsp + 2)
	ld a, (xwa + 17)
	ld e, a
	exts de
	ld xwa, (xsp + 6)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	ld wa, de
	lds de, 4
	calr PitchBend_Scale
	add iz, hl
	ld wa, iz
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld iz, hl

; Chooses the detune arm from the sign of paramA+7 and scales paramA+16 through
; Detune_ScaleSymmetric to produce the pair's low byte.
Voice_Calc_LevelPair_EGB_WriteDSP:
	ld xwa, (xsp + 2)
	cp (xwa + 7), 0x0
	jr ge, Voice_Calc_LevelPair_EGB_PositiveDetune
	ld xwa, (xsp + 2)
	ld a, (xwa + 16)
	exts wa
	cpl wa
	inc 1, wa
	calr Detune_ScaleSymmetric
	jr Voice_Calc_LevelPair_EGB_WriteResult

; paramA+7 >= 0: use paramA+16 unnegated.
Voice_Calc_LevelPair_EGB_PositiveDetune:
	ld xwa, (xsp + 2)
	ld a, (xwa + 16)
	exts wa
	calr Detune_ScaleSymmetric

; Stage (level<<8)|detune into BOTH 0x0451FC and 0x0451FE (shadow +48/+50, TG banks
; 0x900 and 0x940 -- the pair is written with the same word twice).
Voice_Calc_LevelPair_EGB_WriteResult:
	ldb h, 0x0
	ld wa, iz
	sla wa, 8
	or wa, hl
	stw_da 0x0451fc, xwa
	stw_da 0x0451fe, xwa
	popw iz
	inc 8, xsp
	ret

Voice_Calc_LevelPair_EGC:
	dec 8, xsp
	pushw iz
	ld (xsp + 6), xwa
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 23)
	ld (xsp + 2), xwa
	ld a, (xwa + 69)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	ld iz, wa
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld wa, (xwa + 10)
	bit 0, wa
	jr z, Voice_Calc_LevelPair_EGC_ApplyLFO
	ld xwa, (xsp + 6)
	ld xwa, (xwa + 35)
	ld a, (xwa + 24)
	extz wa
	lda xbc, (0x011adf:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	cp wa, iz
	jr gt, Voice_Calc_LevelPair_EGC_ApplyLFO
	ld iz, wa

; Body of Voice_Calc_LevelPair_EGC (entry 0x026AAA, already named). Identical in
; shape to Volume2 but reading paramA+69/+73/+76/+71/+70/+61 instead of
; +15/+19/+22/+17/+16/+7, and staging to 0x045200/0x045202 (shadow +52/+54, TG banks
; 0x9C0 and 0xA00).
Voice_Calc_LevelPair_EGC_ApplyLFO:
	ld xwa, (xsp + 2)
	cp (xwa + 76), 0x0
	jr z, Voice_Calc_LevelPair_EGC_NoLFO
	ld xwa, (xsp + 2)
	ld a, (xwa + 73)
	ld c, a
	extz bc
	pushw 0x7F
	ld xwa, (xsp + 4)
	ld a, (xwa + 76)
	exts wa
	pushw wa
	ld xwa, (xsp + 10)
	ld wa, (xwa + 8)
	lds de, 0
	calr Pan_ScaleWithVelocity
	add iz, hl
	ld xwa, (xsp + 2)
	cp (xwa + 71), 0x0
	jr z, Voice_Calc_LevelPair_EGC_NoKeyTrack
	ld xwa, (xsp + 2)
	ld a, (xwa + 71)
	ld e, a
	exts de
	ld xwa, (xsp + 6)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	ld wa, de
	lds de, 4
	calr PitchBend_Scale
	add iz, hl
	ld wa, iz
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld iz, hl
	jr Voice_Calc_LevelPair_EGC_WriteDSP

; paramA+71 == 0: skip key tracking, clamp 0..0xFF.
Voice_Calc_LevelPair_EGC_NoKeyTrack:
	ld wa, iz
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld iz, hl
	jr Voice_Calc_LevelPair_EGC_WriteDSP

; paramA+76 == 0: key tracking only.
Voice_Calc_LevelPair_EGC_NoLFO:
	ld xwa, (xsp + 2)
	cp (xwa + 71), 0x0
	jr z, Voice_Calc_LevelPair_EGC_WriteDSP
	ld xwa, (xsp + 2)
	ld a, (xwa + 71)
	ld e, a
	exts de
	ld xwa, (xsp + 6)
	ld a, (xwa + 12)
	ld c, a
	extz bc
	ld wa, de
	lds de, 4
	calr PitchBend_Scale
	add iz, hl
	ld wa, iz
	ldw bc, 0xFF
	lds de, 0
	calr ClampS16_WA_To_DEBC
	ld iz, hl

; Sums paramA+61 and paramA+70, clamps to -0x32..+0x32, scales via
; Detune_ScaleSymmetric, and stages (level<<8)|detune to 0x045200 and 0x045202.
Voice_Calc_LevelPair_EGC_WriteDSP:
	ld xwa, (xsp + 2)
	ld a, (xwa + 61)
	ld c, a
	exts bc
	ld xwa, (xsp + 2)
	ld a, (xwa + 70)
	exts wa
	add wa, bc
	ldw bc, 0x32
	ldw de, 0xFFCE
	calr ClampS16_WA_To_DEBC
	ld wa, hl
	calr Detune_ScaleSymmetric
	ldb h, 0x0
	ld wa, iz
	sla wa, 8
	or wa, hl
	stw_da 0x045200, xwa
	stw_da 0x045202, xwa
	popw iz
	inc 8, xsp
	ret

Voice_Calc_LevelPair_Silence:
	stiw_da 0x0451fc, 0x0000
	stiw_da 0x0451fe, 0x0000
	ld c, (xwa + 70)
	extz bc
	sll bc, 8
	set 7, bc
	stw_da 0x0451f8, xbc
	ld a, (xwa + 70)
	extz wa
	sll wa, 8
	stw_da 0x0451fa, xwa
	stiw_da 0x045200, 0x0000
	stiw_da 0x045202, 0x0000
	ret

; Voice_WriteVolume_OrPan(XWA = voice-slot record). If bit 5 of (slot+19)[+13] is set,
; stage pair 1 from table_0x0118FE[paramA+13]: 0x0451FA = (v<<8), 0x0451F8 = (v<<8)|0x80.
; Otherwise stage 0x0451F8 = 0x0080 (target 0x00 with the apply-now bit SET) and
; 0x0451FA = 0x0000 (target 0x00, apply-now bit CLEAR). Under the 0xFF = silent polarity
; that is the LOUD extreme, not silence: the firmware's silence word is 0xFF80 / 0xFF00
; (Voice_SetPitch). [INFERENCE] 0x00 is below 0x04, the loudest byte Voice_EnvelopeLevel_
; Curve can produce, so "fully open" is an extrapolation past the end of the curve rather
; than a level the builders ever emit.
; Sole caller: Voice_AllNotes_SustainRetrigger_BranchF.
Voice_WriteVolume_OrPan:
	ld xbc, (xwa + 19)
	ld xwa, (xwa + 23)
	bitm 5, (xbc + 13)
	jr z, Voice_WriteVolume_OrPan_Muted
	ld a, (xwa + 13)
	extz wa
	lda xbc, (0x0118fe:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	extz wa
	sll wa, 8
	stw_da 0x0451fa, xwa
	set 7, wa
	stw_da 0x0451f8, xwa
	ret

; Bit-5-clear arm: target 0x00 with the "apply now" bit set. Under the 0xFF = silent
; polarity that is the loud extreme, not muted -- [INFERENCE] 0x00 lies past the loud end
; of the level curve, so this is an extrapolation, not a value the builders emit.
; NO RENAME PROPOSED -- the label is a `jr z` branch target, so only the comment is
; corrected here.
Voice_WriteVolume_OrPan_Muted:
	stiw_da 0x0451f8, 0x0080
	stiw_da 0x0451fa, 0x0000
	ret

; Voice_AdvanceLFOPhase(XWA = 9-byte LFO sub-record) -> HL = phase output.
; The sub-record fields used are: +0 flags/mode, +7 period, +8 phase counter.
; Mode = (flags & 0x1C):
;   0x08 "triangle": ++phase; while phase < period return (phase<<8)/period; when it
;        reaches the period, reset phase to 0, clear flag bit 3, set bit 2, return 0x100.
;   0x10 "ramp/hold": ++phase; return 0; when phase reaches the period, reset it, clear
;        flag bit 4 and set bit 3.
;   anything else: return 0 (idle).
; Called only from the three loops of Voice_UpdateAllLFO.
Voice_AdvanceLFOPhase:
	ld c, (xwa)
	and c, 0x1C
	cp c, 0x8
	jr z, Voice_AdvanceLFOPhase_Triangle
	cp c, 0x10
	jr nz, Voice_AdvanceLFOPhase_Idle
	lda xbc, (xwa + 8)
	incm8 1, (xbc)
	ld c, (xbc)
	cp c, (xwa + 7)
	jr c, Voice_AdvanceLFOPhase_IncDone
	ld (xwa + 8), 0x0
	resm 4, (xwa)
	setm 3, (xwa)

; Ramp/hold mode still running: return 0.
Voice_AdvanceLFOPhase_IncDone:
	lds hl, 0
	jr Voice_AdvanceLFOPhase_Done

; Triangle mode: advance and return the scaled phase (phase<<8)/period.
Voice_AdvanceLFOPhase_Triangle:
	lda xbc, (xwa + 8)
	incm8 1, (xbc)
	ld c, (xbc)
	cp c, (xwa + 7)
	jr nc, Voice_AdvanceLFOPhase_TriangleReset
	ld l, (xwa + 8)
	extz hl
	sll hl, 8
	ld a, (xwa + 7)
	ld c, a
	extz bc
	ld wa, hl
	extz xwa
	div xwa, xbc
	ld hl, wa
	jr Voice_AdvanceLFOPhase_Done

; Triangle wrap: phase = 0, flag bit 3 -> bit 2, return 0x100 (full scale).
Voice_AdvanceLFOPhase_TriangleReset:
	ld (xwa + 8), 0x0
	resm 3, (xwa)
	setm 2, (xwa)
	ldw hl, 0x100
	jr Voice_AdvanceLFOPhase_Done

; Unrecognised mode: return 0.
Voice_AdvanceLFOPhase_Idle:
	lds hl, 0

; Common return.
Voice_AdvanceLFOPhase_Done:
	ret

; Voice_UpdateAllLFO(). The per-tick LFO service; the single heaviest thing in the audio
; tick. Sole caller: Audio_Tick_ServiceVoices_A.
;
; Walks the LFO record array at 0x04424E, 27 (0x1B) bytes per slot, as THREE interleaved
; 9-byte sub-records: base 0x04424E (128 slots), base 0x044257 (64 slots) and base
; 0x044260 (128 slots) -- 320 iterations per call, each doing a 64-bit multiply
; (FP_MulAccum64) for the index scaling and, when the LFO is running, a full tone-
; generator register write.
;
; Per slot: skip unless (flags & 0x18); call Voice_AdvanceLFOPhase; skip if the phase
; output is 0. Otherwise convert the phase through EGEnv_Compute_A (group 1),
; EGEnv_Compute_B (group 2) or Voice_Freq_WriteLeft (group 3), keep the result in the
; scratch words 0x04520C / 0x045204 / 0x04520E, and unless the phase was exactly 0x0100
; fold (result & 0x1FFF) * phase >> 8 back into the low 13 bits of that scratch word.
; Finally dispatch the value into the TG shadow block at 0x0451CC via
; ToneGen_WriteExtParam_600 (group 1), ToneGen_WriteExtParam_1C0_Single (group 2) or
; ToneGen_WriteExtParam_TypeDispatch_Single (group 3).
; Hardware touched (indirectly, through those writers): the TG address/data latch pair at
; 0x100000 / 0x100002.
Voice_UpdateAllLFO:
	push xiz
	lds iz, 0
	cp iz, 0x80
	jr nc, Voice_UpdateAllLFO_Loop2

; Group 1 body: 128 sub-records at 0x04424E, EGEnv_Compute_A, scratch 0x04520C.
Voice_UpdateAllLFO_Loop1:
	ld wa, iz
	extz xwa
	ld xbc, 0x1B
	call FP_MulAccum64
	lda xbc, (0x04424e:24)
	add xbc, xhl
	ld a, (xbc)
	and a, 0x18
	jr z, Voice_UpdateAllLFO_NextSlot1
	ld xwa, xbc
	calr Voice_AdvanceLFOPhase
	ldw_erp HL, 0xFA
	cpiw_erp 0xFA, 0
	jr z, Voice_UpdateAllLFO_NextSlot1
	stb_erp A, 0xF8
	extz wa
	calr EGEnv_Compute_A
	stw_da 0x04520c, xhl
	cp_erpw 0xFA, 0x00, 0x01
	jr z, Voice_UpdateAllLFO_DispatchVoice1
	ld hl, (0x04520c:24)
	extz xhl
	and xhl, 0x1FFF
	stw_erp BC, 0xFA
	extz xbc
	ld xwa, xhl
	call FP_MulAccum64
	anddi16_24 283148, 57344
	srl xhl, 8
	ordm16_24 283148, xhl

; Push the group-1 result for this slot with ToneGen_WriteExtParam_600.
Voice_UpdateAllLFO_DispatchVoice1:
	ld wa, iz
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParam_600

; ++slot; loop while slot < 0x80.
Voice_UpdateAllLFO_NextSlot1:
	inc 1, iz
	cp iz, 0x80
	jr c, Voice_UpdateAllLFO_Loop1

; Group 2 preamble: reset the slot counter, bail out to group 3 if 0x40 slots is none.
Voice_UpdateAllLFO_Loop2:
	lds iz, 0
	cp iz, 0x40
	jr nc, Voice_UpdateAllLFO_Loop3

; Group 2 body: 64 sub-records at 0x044257, EGEnv_Compute_B, scratch 0x045204.
Voice_UpdateAllLFO_Loop2_Body:
	ld wa, iz
	extz xwa
	ld xbc, 0x1B
	call FP_MulAccum64
	lda xwa, (0x044257:24)
	add xwa, xhl
	ld xbc, xwa
	ld a, (xbc)
	and a, 0x18
	jr z, Voice_UpdateAllLFO_NextSlot2
	ld xwa, xbc
	calr Voice_AdvanceLFOPhase
	ldw_erp HL, 0xFA
	cpiw_erp 0xFA, 0
	jr z, Voice_UpdateAllLFO_NextSlot2
	stb_erp A, 0xF8
	extz wa
	calr EGEnv_Compute_B
	stw_da 0x045204, xhl
	cp_erpw 0xFA, 0x00, 0x01
	jr z, Voice_UpdateAllLFO_DispatchVoice2
	ld hl, (0x045204:24)
	extz xhl
	and xhl, 0x1FFF
	stw_erp BC, 0xFA
	extz xbc
	ld xwa, xhl
	call FP_MulAccum64
	anddi16_24 283140, 57344
	srl xhl, 8
	ordm16_24 283140, xhl

; Push the group-2 result with ToneGen_WriteExtParam_1C0_Single.
Voice_UpdateAllLFO_DispatchVoice2:
	ld wa, iz
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParam_1C0_Single

; ++slot; loop while slot < 0x40.
Voice_UpdateAllLFO_NextSlot2:
	inc 1, iz
	cp iz, 0x40
	jr c, Voice_UpdateAllLFO_Loop2_Body

; Group 3 preamble: reset the slot counter for the 128-slot pass.
Voice_UpdateAllLFO_Loop3:
	lds iz, 0
	cp iz, 0x80
	jrl nc, Voice_UpdateAllLFO_Done

; Group 3 body: 128 sub-records at 0x044260, converted via Voice_Freq_WriteLeft.
Voice_UpdateAllLFO_Loop3_Body:
	ld wa, iz
	extz xwa
	ld xbc, 0x1B
	call FP_MulAccum64
	lda xwa, (0x044260:24)
	add xwa, xhl
	ld xbc, xwa
	ld a, (xbc)
	and a, 0x18
	jr z, Voice_UpdateAllLFO_NextSlot3
	ld xwa, xbc
	calr Voice_AdvanceLFOPhase
	ldw_erp HL, 0xFA
	cpiw_erp 0xFA, 0
	jr z, Voice_UpdateAllLFO_NextSlot3
	stb_erp A, 0xF8
	extz wa
	calr Voice_Freq_WriteLeft
	cp_erpw 0xFA, 0x00, 0x01
	jr z, Voice_UpdateAllLFO_DispatchVoice3
	cp iz, 0x40
	jr nc, Voice_UpdateAllLFO_DispatchGroup3_High
	ld hl, (0x045204:24)
	extz xhl
	and xhl, 0x1FFF
	stw_erp BC, 0xFA
	extz xbc
	ld xwa, xhl
	call FP_MulAccum64
	anddi16_24 283140, 57344
	srl xhl, 8
	ordm16_24 283140, xhl
	jr Voice_UpdateAllLFO_DispatchVoice3

; Slots 0x40..0x7F of group 3 fold their result into scratch 0x04520E instead of
; 0x045204.
Voice_UpdateAllLFO_DispatchGroup3_High:
	ld hl, (0x04520e:24)
	extz xhl
	and xhl, 0x1FFF
	stw_erp BC, 0xFA
	extz xbc
	ld xwa, xhl
	call FP_MulAccum64
	anddi16_24 283150, 57344
	srl xhl, 8
	ordm16_24 283150, xhl

; Push the group-3 result with ToneGen_WriteExtParam_TypeDispatch_Single.
Voice_UpdateAllLFO_DispatchVoice3:
	ld wa, iz
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParam_TypeDispatch_Single

; ++slot; loop while slot < 0x80.
Voice_UpdateAllLFO_NextSlot3:
	inc 1, iz
	cp iz, 0x80
	jrl c, Voice_UpdateAllLFO_Loop3_Body

; Restore IZ and return.
Voice_UpdateAllLFO_Done:
	pop xiz
	ret

Voice_Step_DelayTimers:
	dec 4, xsp
	pushw iz
	ld (xsp + 2), xwa
	ld xwa, (xsp + 2)
	ld iz, (xwa + 47)
	ld wa, iz
	extz xwa
	bit 15, wa
	jr z, Voice_Step_DelayTimers_LowSlot
	sub iz, 0x100
	ld wa, iz
	and wa, 0x7F00
	jr nz, Voice_Step_DelayTimers_LowSlot
	ld xwa, (xsp + 2)
	ld a, (xwa)
	extz wa
	ld xbc, (xsp + 2)
	ld bc, (xbc + 45)
	call ToneGen_WriteSingleReg
	ld xwa, (xsp + 2)
	ld a, (xwa)
	extz wa
	call Voice_Clear_HoldBit
	res 15, iz

; ---------------------------------------------------------------------------
; Voice_Step_DelayTimers (0x026E5B) -- ticks TWO independent deferred-action
; timers packed into the single word at (record + 0x2F), once per call.
;
;   bit 15      = high slot ARMED      bits 8..14 = high slot countdown
;   bit  7      = low  slot ARMED      bits 0..6  = low  slot countdown
;
; Each armed slot is decremented; when its counter reaches zero the slot fires
; and DISARMS ITSELF (res 0x0F,IZ / and IZ,0x007F), then the packed word is
; written back.
;
;   high slot expiry -> ToneGen_WriteSingleReg (param from record+0x2D)
;                    -> Voice_Clear_HoldBit
;   low  slot expiry -> Voice_Reload_Levels
;
; NAMING (2026-08-06): previously Voice_Step_AmpDelay, and a later pass argued
; for Voice_Step_ReleaseDelay. BOTH described only one slot -- "release" the
; high one, "amp" the low one -- which is why the two readings disagreed. The
; routine is a generic two-slot delay timer, so it is named for the mechanism.
; Sibling: Voice_Step_ExprRamp (0x026EC3).
; ---------------------------------------------------------------------------
; Body of Voice_Step_DelayTimers (entry 0x026E5B, already named -- left alone). That routine
; drives the packed 16-bit countdown word at slot+47, which holds TWO independent timers:
;   high byte, bit 15 = "note-off armed": each tick subtracts 0x100; when the high 7 bits
;     reach zero it writes slot+45 to the voice's TG register through
;     ToneGen_WriteSingleReg, calls Voice_Clear_HoldBit, and clears bit 15;
;   low byte, bit 7 = "release armed": handled at THIS label. Decrement by 1; when the
;     low 7 bits reach zero, call Voice_Reload_Levels for the slot and clear bit 7.
; ★ These two paths are the ONLY way a slot goes back to the free pool during steady-
; state playback (the other being the portamento terminal state), so any stall upstream
; of Voice_Step_DelayTimers stops voice reclamation outright.
Voice_Step_DelayTimers_LowSlot:
	bit 7, iz
	jr z, Voice_Step_DelayTimers_Store
	dec 1, iz
	ld wa, iz
	and wa, 0x7F
	jr nz, Voice_Step_DelayTimers_Store
	ld xwa, (xsp + 2)
	ld a, (xwa)
	extz wa
	call Voice_Reload_Levels
	and iz, 0x7F

; Write the updated countdown word back to slot+47 and return.
Voice_Step_DelayTimers_Store:
	ld xwa, (xsp + 2)
	ld (xwa + 47), iz
	popw iz
	inc 4, xsp
	ret

Voice_Step_ExprRamp:
	dec 6, xsp
	pushw iz
	ld (xsp + 4), xwa
	ld xwa, (xsp + 4)
	ld wa, (xwa + 49)
	ld (xsp + 2), wa
	and wa, 0x7F
	jrl nz, Voice_Step_ExprRamp_ActiveCount
	ld xwa, (xsp + 4)
	ld a, (xwa + 53)
	extz wa
	or (xsp + 2), wa
	xormi16 (xsp + 2), 0x800
	ld wa, (xsp + 2)
	bit 11, wa
	jrl z, Voice_Step_ExprRamp_ZeroState
	ld xwa, (xsp + 4)
	ld a, (xwa + 4)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x04138e:24)
	cpib_sri 0x07, 0xE4, 0xE0, 0x01
	jr nz, Voice_Step_ExprRamp_ModeCheck2
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	ld xbc, (xsp + 4)
	ld bc, (xbc + 43)
	call ToneGen_WriteExprReg
	jr Voice_Step_ExprRamp_DispatchMode

; Body of Voice_Step_ExprRamp (entry 0x026EC3, already named -- left alone). That
; routine drives the per-slot glide/fade state word at slot+49: bits 0..6 are a delay
; counter, bits 12..14 select the ramp mode, bit 15 marks the state machine active.
; This label is the second of three arms selecting which TG register-0x180 value to write
; before dispatching: part-record byte (0x04138E + part*0x11F) == 2.
Voice_Step_ExprRamp_ModeCheck2:
	ld xwa, (xsp + 4)
	ld a, (xwa + 4)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x04138e:24)
	cpib_sri 0x07, 0xE4, 0xE0, 0x02
	jr nz, Voice_Step_ExprRamp_ModeDefault
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	ld xbc, (xsp + 4)
	ld bc, (xbc + 43)
	call ToneGen_WriteExprReg
	jr Voice_Step_ExprRamp_DispatchMode

; Neither part mode 1 nor 2: merge (slot+39)[+36] into the low bits of slot+43 and write
; that through ToneGen_WriteExprReg.
Voice_Step_ExprRamp_ModeDefault:
	ld xwa, (xsp + 4)
	ld a, (xwa)
	ld l, a
	extz hl
	ld xwa, (xsp + 4)
	ld xwa, (xwa + 39)
	ld a, (xwa + 36)
	ld c, a
	extz bc
	ld xwa, (xsp + 4)
	ld wa, (xwa + 43)
	and wa, 0xFF80
	ld de, wa
	or de, bc
	ld wa, hl
	ld bc, de
	call ToneGen_WriteExprReg
	jr Voice_Step_ExprRamp_DispatchMode

; Bit 11 of the state word clear: write slot+43 to TG register bank 0x180 unmodified.
Voice_Step_ExprRamp_ZeroState:
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	ld xbc, (xsp + 4)
	ld bc, (xbc + 43)
	call ToneGen_WriteExprReg

; Dispatch on (state & 0x7000): 0x1000 -> Release ramp, 0x2000 -> Descend, 0x4000 ->
; Ascend, anything else -> NullMode (state cleared).
Voice_Step_ExprRamp_DispatchMode:
	ld wa, (xsp + 2)
	and wa, 0x7000
	cp wa, 0x1000
	jrl z, Voice_Step_ExprRamp_Release_Start
	cp wa, 0x2000
	jrl z, Voice_Step_ExprRamp_Descend_Tick
	cp wa, 0x4000
	jrl nz, Voice_Step_ExprRamp_NullMode
	ld xwa, (xsp + 4)
	ld iz, (xwa + 54)
	ld xwa, (xsp + 4)
	add iz, (xwa + 51)
	cp iz, 0xFF00
	jr gt, Voice_Step_ExprRamp_Ascend_Tick
	ld xwa, (xsp + 4)
	ldw (xwa + 51), 0xFF00
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	call Voice_Clear_HoldBit
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	call Voice_Reload_Levels
	andmi16 (xsp + 2), 0x6FFF
	jrl Voice_Step_ExprRamp_StoreDone

; Ascend arm, still ramping. Writes TG bank 0x840 = 0xFF00 directly (address latch
; 0x100000 = slot + 0x840, data latch 0x100002), with the P6.7 select driven around the
; latch pair (res/set bit 7 of SFR 0x18) -- the standard per-word sequence, documented in
; full at ToneGen_WriteVoiceParams.
; CORRECTION: SFR 0x18 is PORT 6 (shared/sfr_tmp94c241.s: `.equ P6, 0x18`), not an
; interrupt-mask register: every INTE* register on this part sits at 0xE0..0xF0. This pair
; masks nothing; the earlier "maskable-interrupt gate" wording was wrong. RESET programs the
; bit as a plain output (`ldio 0x1B,0x7F` then `ldio 0x1A,0x80` at 0x01F956/0x01F959), and
; the ASL-era listing renders the two instructions as RES/SET 7, (P6), unidasm as
; res/set 7,(0x18).
; [INFERENCE] that the pin is the CPU's A23 line taken out of bus mode. That reading has no
; datasheet or schematic behind it and symbols/proposals/subcpu-region-07.txt grades it
; UNCERTAIN; only the port identity above is established.
; The terminal value the ramp counts toward is 0xFF00; on reaching it the slot is handed
; to Voice_Clear_HoldBit + Voice_Reload_Levels and the mode bits are cleared.
Voice_Step_ExprRamp_Ascend_Tick:
	res_dd8 7, 0x18
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	add wa, 0x840
	stw_da 0x100000, xwa
	nop
	set_dd8 7, 0x18
	stiw_da 0x100002, 0xff00
	jr __jrt_nop_026FFD
__jrt_nop_026FFD:

; Second half of the same write burst: TG bank 0x800 = 0xFF80.
Voice_Step_ExprRamp_Ascend_Tick2:
	nop
	nop
	nop
	res_dd8 7, 0x18
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	add wa, 0x800
	stw_da 0x100000, xwa
	nop
	set_dd8 7, 0x18
	stiw_da 0x100002, 0xff80
	jr __jrt_nop_027020
__jrt_nop_027020:

; Clamp the ramp accumulator at the per-slot floor slot+58; on clamping, clear state bit
; 14 and set bit 13 (mode 0x4000 -> 0x2000, ascend hands over to descend).
Voice_Step_ExprRamp_Ascend_ClampFloor:
	nop
	nop
	nop
	ld xwa, (xsp + 4)
	cp iz, (xwa + 58)
	jr ge, Voice_Step_ExprRamp_Ascend_WritePitch
	ld xwa, (xsp + 4)
	ld iz, (xwa + 58)
	resm 6, (xsp + 3)
	setm 5, (xsp + 3)

; Store the accumulator to slot+51, re-derive the pitch via Voice_ApplyPortamento, then
; push the whole shadow block with ToneGen_WriteVoiceParams_Ext.
Voice_Step_ExprRamp_Ascend_WritePitch:
	ld xwa, (xsp + 4)
	ld (xwa + 51), iz
	ld xwa, (xsp + 4)
	calr Voice_ApplyPortamento
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	lda xbc, (0x0451cc:24)
	ld xde, (xsp + 4)
	call ToneGen_WriteVoiceParams_Ext
	jrl Voice_Step_ExprRamp_StoreDone

; Descend arm: TG bank 0x840 = 0xFF00.
Voice_Step_ExprRamp_Descend_Tick:
	res_dd8 7, 0x18
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	add wa, 0x840
	stw_da 0x100000, xwa
	nop
	set_dd8 7, 0x18
	stiw_da 0x100002, 0xff00
	jr __jrt_nop_027079
__jrt_nop_027079:

; Descend arm: TG bank 0x800 = 0xFF80.
Voice_Step_ExprRamp_Descend_Tick2:
	nop
	nop
	nop
	res_dd8 7, 0x18
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	add wa, 0x800
	stw_da 0x100000, xwa
	nop
	set_dd8 7, 0x18
	stiw_da 0x100002, 0xff80
	jr __jrt_nop_02709C
__jrt_nop_02709C:

; Push the shadow block with ToneGen_WriteVoiceParams_Ext2 (no pitch recompute on this
; arm).
Voice_Step_ExprRamp_Descend_WritePitch:
	nop
	nop
	nop
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	ld xbc, (xsp + 4)
	call ToneGen_WriteVoiceParams_Ext2
	jrl Voice_Step_ExprRamp_StoreDone

; Release arm: accumulator += slot+56 (the release increment; the ascend arm uses
; slot+54). On reaching 0xFF00 the slot is released exactly as in the ascend arm.
Voice_Step_ExprRamp_Release_Start:
	ld xwa, (xsp + 4)
	ld iz, (xwa + 56)
	ld xwa, (xsp + 4)
	add iz, (xwa + 51)
	cp iz, 0xFF00
	jr gt, Voice_Step_ExprRamp_Release_Tick
	ld xwa, (xsp + 4)
	ldw (xwa + 51), 0xFF00
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	call Voice_Clear_HoldBit
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	call Voice_Reload_Levels
	andmi16 (xsp + 2), 0x6FFF
	jrl Voice_Step_ExprRamp_StoreDone

; Release arm: TG bank 0x840 = 0xFF00.
Voice_Step_ExprRamp_Release_Tick:
	res_dd8 7, 0x18
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	add wa, 0x840
	stw_da 0x100000, xwa
	nop
	set_dd8 7, 0x18
	stiw_da 0x100002, 0xff00
	jr __jrt_nop_027108
__jrt_nop_027108:

; Release arm: TG bank 0x800 = 0xFF80.
Voice_Step_ExprRamp_Release_Tick2:
	nop
	nop
	nop
	res_dd8 7, 0x18
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	add wa, 0x800
	stw_da 0x100000, xwa
	nop
	set_dd8 7, 0x18
	stiw_da 0x100002, 0xff80
	jr __jrt_nop_02712B
__jrt_nop_02712B:

; Store to slot+51, Voice_ApplyPortamento, ToneGen_WriteVoiceParams_Ext.
Voice_Step_ExprRamp_Release_WritePitch:
	nop
	nop
	nop
	ld xwa, (xsp + 4)
	ld (xwa + 51), iz
	ld xwa, (xsp + 4)
	calr Voice_ApplyPortamento
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	lda xbc, (0x0451cc:24)
	ld xde, (xsp + 4)
	call ToneGen_WriteVoiceParams_Ext
	jr Voice_Step_ExprRamp_StoreDone

; Unrecognised mode bits: zero the state word so the slot stops being serviced.
Voice_Step_ExprRamp_NullMode:
	ldw (xsp + 2), 0x0
	jr Voice_Step_ExprRamp_StoreDone

; Delay-counter arm, taken when (state & 0x7F) != 0: the ramp has not started yet.
; When the counter is exactly 1 it emits the "pre-roll" TG values (bank 0x840 = 0xA200,
; bank 0x800 = 0xA280) before decrementing.
Voice_Step_ExprRamp_ActiveCount:
	ld wa, (xsp + 2)
	and wa, 0x7F
	cps wa, 1
	jr nz, Voice_Step_ExprRamp_CountDecrement
	res_dd8 7, 0x18
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	add wa, 0x840
	stw_da 0x100000, xwa
	nop
	set_dd8 7, 0x18
	stiw_da 0x100002, 0xa200
	jr __jrt_nop_027181
__jrt_nop_027181:

; Second half of the pre-roll burst: TG bank 0x800 = 0xA280.
Voice_Step_ExprRamp_CountTick:
	nop
	nop
	nop
	res_dd8 7, 0x18
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	add wa, 0x800
	stw_da 0x100000, xwa
	nop
	set_dd8 7, 0x18
	stiw_da 0x100002, 0xa280
	jr __jrt_nop_0271A4
__jrt_nop_0271A4:

; Decrement the delay counter and fall through to the store.
Voice_Step_ExprRamp_CountTick2:
	nop
	nop
	nop
	decm 1, (xsp + 2)
	jr Voice_Step_ExprRamp_StoreDone

; Ordinary delay tick (counter != 1): just decrement.
Voice_Step_ExprRamp_CountDecrement:
	decm 1, (xsp + 2)

; Write the state word back to slot+49 and return.
Voice_Step_ExprRamp_StoreDone:
	ld xwa, (xsp + 4)
	ld bc, (xsp + 2)
	ld (xwa + 49), bc
	popw iz
	inc 6, xsp
	ret

Pitch_Bend_Ramp_Tick:
	ld wa, (0x041343:24)
	bit 11, wa
	jr z, Pitch_Bend_Ramp_Tick_Bit12
	incdi16_24 1, 267100
	ldb_da a, 0x011c7c
	exts wa
	add wa, wa
	stw_da 0x04135a, xwa
	anddi16_24 267075, 63487
	ordi16_24 267075, 5120
	ret

; Body of Pitch_Bend_Ramp_Tick (entry 0x0271BC, already named -- left alone). That
; routine is the once-per-audio-tick step of the KEY SHIFT / transpose ramp, driven
; entirely by the global mode word at 0x041343:
;   bit 11 = "shift requested" (set by Voice_SetKeyShiftEnable). Loads the first entry of
;            the signed semitone table at 0x011C7C, doubles it into the global pitch
;            offset word 0x04135A, clears bit 11 and sets bits 10 and 12.
;   bit 12 = "shift engaged". THIS LABEL: bump the step index 0x04135C and clear bit 10.
;   bit 13 = "ramping"; bit 14 -> step index += 2, bit 15 -> step index += 1. Each step
;            reloads 0x04135A = table_0x011C7C[index] * 2 and sets bit 10.
;   bit 10 = "pitch offset changed" -- consumed by Audio_Tick_ServiceVoices_B, which uses
;            it to choose the loop arm that re-writes every sounding voice's pitch.
; The ramp self-terminates when the loaded offset is zero: entries 24 and 25 of the
; 26-byte table are 0x00, and both the +1 and +2 step sequences from index 0 land on 24.
; Also read by Voice_ComputePitch (bits 0/1) and Voice_ApplyPortamento (bit 1).
Pitch_Bend_Ramp_Tick_Bit12:
	ld wa, (0x041343:24)
	bit 12, wa
	jr z, Pitch_Bend_Ramp_Tick_Bit13Check
	incdi16_24 1, 267100
	anddi16_24 267075, 64511
	ret

; bit 13 clear -> ClearMode; set -> choose the +2 (bit 14) or +1 (bit 15) step.
Pitch_Bend_Ramp_Tick_Bit13Check:
	ld wa, (0x041343:24)
	bit 13, wa
	jrl z, Pitch_Bend_Ramp_Tick_ClearMode
	ld wa, (0x041343:24)
	bit 14, wa
	jr z, Pitch_Bend_Ramp_Tick_Bit14Clear
	incdi16_24 2, 267100
	ld wa, (0x04135c:24)
	extz xwa
	ld xbc, 0x11C7C
	add xbc, xwa
	ld a, (xbc)
	exts wa
	add wa, wa
	stw_da 0x04135a, xwa
	ordi16_24 267075, 1024
	jr Pitch_Bend_Ramp_Tick_CheckCounter

; bit 14 clear: if bit 15 is set take the +1 step, otherwise zero the offset.
Pitch_Bend_Ramp_Tick_Bit14Clear:
	ld wa, (0x041343:24)
	extz xwa
	bit 15, wa
	jr z, Pitch_Bend_Ramp_Tick_ZeroPitch
	incdi16_24 1, 267100
	ld wa, (0x04135c:24)
	extz xwa
	ld xbc, 0x11C7C
	add xbc, xwa
	ld a, (xbc)
	exts wa
	add wa, wa
	stw_da 0x04135a, xwa
	ordi16_24 267075, 1024
	jr Pitch_Bend_Ramp_Tick_CheckCounter

; No direction bit set: force the global pitch offset 0x04135A to 0 and raise bit 10.
Pitch_Bend_Ramp_Tick_ZeroPitch:
	stiw_da 0x04135a, 0x0000
	ordi16_24 267075, 1024

; Termination test: return unless the offset word 0x04135A is now zero; when it is, clear
; bits 13..15 of 0x041343, reset the step index 0x04135C and raise bit 10 one last time.
Pitch_Bend_Ramp_Tick_CheckCounter:
	cpw_da 267098, 0
	ret nz
	anddi16_24 267075, 8191
	stiw_da 0x04135c, 0x0000
	ordi16_24 267075, 1024
	ret

; Ramp inactive: clear bit 10 and return.
Pitch_Bend_Ramp_Tick_ClearMode:
	anddi16_24 267075, 64511
	ret

; Voice_InitVoiceState(WA = channel index). Loads the whole 22-word tone-generator shadow
; block at 0x0451CC with power-on defaults, immediately before the caller pushes it to
; the chip. Sole caller: Voice_TickNoteDecay.
; Notable defaults: 0x0451E4 = 0xFF7F (register pair 1 = maximum attenuation, maximum
; rate -- i.e. silent); 0x0451E6 and 0x0451E8 copied from the global word 0x041362 (set
; to 0x8000 or 0xA000 by Voice_SetRhythmMode); 0x0451DA from 0x041360; 0x0451D4 = 0x017F,
; 0x0451D6 = 0x7F7F, 0x0451D8 = 0x0040; 0x0451D0 = table_0x010764[0x041364] * 4; every
; other word zeroed. Finally stores 0xF0 into the per-channel record byte at
; 0x0430BB + ch*0x47.
Voice_InitVoiceState:
	stiw_da 0x0451ce, 0x0000
	ld bc, (0x041360:24)
	stw_da 0x0451da, xbc
	stiw_da 0x0451ec, 0x0000
	stiw_da 0x0451ee, 0x0000
	stiw_da 0x0451f0, 0x0000
	stiw_da 0x0451d4, 0x017f
	stiw_da 0x0451d6, 0x7f7f
	stiw_da 0x0451f2, 0x0000
	stiw_da 0x0451f4, 0x0000
	stiw_da 0x0451f6, 0x0000
	stiw_da 0x0451e2, 0x0000
	stiw_da 0x0451ea, 0x0000
	stiw_da 0x0451dc, 0x0000
	stiw_da 0x0451de, 0x0000
	stiw_da 0x0451d8, 0x0040
	stiw_da 0x0451e0, 0x0000
	stiw_da 0x0451d2, 0x0000
	stiw_da 0x0451e4, 0xff7f
	ld bc, (0x041362:24)
	stw_da 0x0451e6, xbc
	ld bc, (0x041362:24)
	stw_da 0x0451e8, xbc
	ld bc, (0x041364:24)
	add bc, bc
	lda xde, (0x010764:24)
	ldw_sri BC, 0x07, 0xE8, 0xE4
	add bc, bc
	stw_da 0x0451d0, xbc
	extz wa
	muls wa, 0x47
	lda xbc, (0x0430bb:24)
	stiw_ind 0x07, 0xE4, 0xE0, 0x00, 0xF0
	ret

; Voice_TickNoteDecay(). Rhythm/percussion decay tick. Sole caller:
; Audio_Tick_ServiceVoices_B (first thing it does).
; Returns immediately unless the mode byte 0x04135E is non-zero. Decrements the counter
; at 0x04135F and returns unless it reached zero. On the zero tick it calls
; Voice_SetPanning on a stack scratch structure and, if the channel index in that
; structure is below 0x40, calls Voice_InitVoiceState followed by
; ToneGen_WriteVoiceParams (base 0x0451CC) -- a full 22-register reload of that channel --
; and then one further ToneGen_WriteSingleReg using the word at 0x0430BB + ch*0x47.
; 0x04135E/0x04135F are set by Voice_SetRhythmMode.
Voice_TickNoteDecay:
	lda xsp, (xsp - 14)
	pushw_erp 0xFA
	cpib_da 0x04135e, 0x00
	jr z, Voice_TickNoteDecay_Done
	decdi8_24 1, 267103
	cpib_da 0x04135f, 0x00
	jr nz, Voice_TickNoteDecay_Done
	lda xwa, (xsp + 2)
	call Voice_SetPanning
	cp (xsp + 12), 0x40
	jr nc, Voice_TickNoteDecay_Reload
	ld a, (xsp + 12)
	ldb_erp A, 0xFB
	extz wa
	calr Voice_InitVoiceState
	stb_erp A, 0xFB
	extz wa
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteVoiceParams
	stb_erp A, 0xFB
	ld l, a
	extz hl
	stb_erp A, 0xFB
	extz wa
	muls wa, 0x47
	ld bc, wa
	lda xde, (0x0430bb:24)
	ld wa, hl
	ldw_sri BC, 0x07, 0xE8, 0xE4
	call ToneGen_WriteSingleReg

; Reload the divider: decrement the counter at 0x04135E and reset 0x04135F to 4.
Voice_TickNoteDecay_Reload:
	decdi8_24 1, 267102
	stib_da 0x04135f, 0x04

; Restore and return.
Voice_TickNoteDecay_Done:
	popw_erp 0xFA
	lda xsp, (xsp + 14)
	ret

; Voice_LoadPitchTable_Ch(A = part index, C = ramp position). Despite the name it does
; not load a table: it SCALES two DSP algorithm parameters by the ramp position and
; broadcasts the result to every voice of the part.
; Steps: DSP_AlgoType_Dispatch2(part, 1) * C >> 8, floored at 0x2C, stored to the scratch
; 0x045208 and to the per-part word 0x0413C5 + part*0x11F; then
; DSP_AlgoType_Dispatch1(part, 1) * table_0x010DCE[C] >> 8 stored to 0x04520C and to
; 0x0413C3 + part*0x11F; then Voice_BuildOutputList(part, 0x0D, 0) and, for every entry,
; ToneGen_WriteExtParams_56 with the shadow base 0x0451CC.
; The output list is a 16-bit array in the scratch buffer at 0x27E9, terminated by
; 0xFFFF; the loop runs while (entry & 0xFF) < 0x80, so at most 27 entries.
; Callers: Voice_ToneTableRamp_Up_Increment, Voice_ToneTableRamp_Down_Decrement,
; Voice_ToneTableApply_Pitch_Loop, Voice_ToneTableApply_Filter_Loop.
Voice_LoadPitchTable_Ch:
	dec 8, xsp
	pushw iz
	ld (xsp + 6), c
	ld (xsp + 8), a
	ld a, (xsp + 8)
	extz wa
	lds bc, 1
	call DSP_AlgoType_Dispatch2
	extz xhl
	ld a, (xsp + 6)
	lds32 xbc, 0
	ld c, a
	ld xwa, xhl
	call FP_MulAccum64
	srl xhl, 8
	cp xhl, 0x2C
	jr nc, Voice_LoadPitchTable_Ch_NoClamp
	stiw_da 0x045208, 0x002c
	ld a, (xsp + 8)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x0413c5:24)
	stiw_ind 0x07, 0xE4, 0xE0, 0x2C, 0x00
	jr Voice_LoadPitchTable_Ch_ScanLoop

; Scaled value already >= 0x2C: store it unclamped.
Voice_LoadPitchTable_Ch_NoClamp:
	ld wa, hl
	stw_da 0x045208, xwa
	ld a, (xsp + 8)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x0413c5:24)
	stw_dri HL, 0x07, 0xE4, 0xE0

; Second parameter (Dispatch1 * table_0x010DCE[C]) and the output-list build.
Voice_LoadPitchTable_Ch_ScanLoop:
	ld a, (xsp + 8)
	extz wa
	lds bc, 1
	call DSP_AlgoType_Dispatch1
	extz xhl
	ld a, (xsp + 6)
	extz wa
	lda xbc, (0x010dce:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	lds32 xbc, 0
	ld c, a
	ld xwa, xhl
	call FP_MulAccum64
	srl xhl, 8
	ld wa, hl
	stw_da 0x04520c, xwa
	ld a, (xsp + 8)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x0413c3:24)
	stw_dri HL, 0x07, 0xE4, 0xE0
	ld a, (xsp + 8)
	extz wa
	ldw bc, 0xD
	lds de, 0
	call Voice_BuildOutputList
	ld (xsp + 2), xhl
	lds iz, 0
	jr Voice_LoadPitchTable_Ch_LoopCheck

; Per-voice broadcast via ToneGen_WriteExtParams_56.
Voice_LoadPitchTable_Ch_LoopBody:
	ld wa, iz
	extz xwa
	add xwa, xwa
	add xwa, (xsp + 2)
	ld wa, (xwa)
	ldb w, 0x0
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParams_56
	inc 1, iz

; Continue while the list entry's low byte is < 0x80.
Voice_LoadPitchTable_Ch_LoopCheck:
	ld wa, iz
	extz xwa
	add xwa, xwa
	add xwa, (xsp + 2)
	ld wa, (xwa)
	and wa, 0xFF
	cp wa, 0x80
	jr c, Voice_LoadPitchTable_Ch_LoopBody
	popw iz
	inc 8, xsp
	ret

; Voice_LoadPitchTable_All(A = part index). The ramp-position-independent form of
; Voice_LoadPitchTable_Ch: stores the raw DSP_AlgoType_Dispatch2/Dispatch1 results to
; 0x045208 and 0x04520C (no scaling, no per-part write-back) and broadcasts them with the
; same ToneGen_WriteExtParams_56 loop.
; Sole caller: Voice_ToneTableRamp_Up, when the pitch ramp has reached its ceiling.
Voice_LoadPitchTable_All:
	dec 8, xsp
	ld (xsp + 6), a
	ld a, (xsp + 6)
	extz wa
	lds bc, 1
	call DSP_AlgoType_Dispatch2
	stw_da 0x045208, xhl
	ld a, (xsp + 6)
	extz wa
	lds bc, 1
	call DSP_AlgoType_Dispatch1
	stw_da 0x04520c, xhl
	ld a, (xsp + 6)
	extz wa
	ldw bc, 0xD
	lds de, 0
	call Voice_BuildOutputList
	ld (xsp), xhl
	ldw (xsp + 4), 0x0
	jr Voice_LoadPitchTable_All_LoopCheck

; Per-voice broadcast body.
Voice_LoadPitchTable_All_LoopBody:
	ld wa, (xsp + 4)
	extz xwa
	add xwa, xwa
	add xwa, (xsp)
	ld wa, (xwa)
	ldb w, 0x0
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParams_56
	incw 1, (xsp + 4)

; Continue while the list entry's low byte is < 0x80.
Voice_LoadPitchTable_All_LoopCheck:
	ld wa, (xsp + 4)
	extz xwa
	add xwa, xwa
	add xwa, (xsp)
	ld wa, (xwa)
	and wa, 0xFF
	cp wa, 0x80
	jr c, Voice_LoadPitchTable_All_LoopBody
	inc 8, xsp
	ret

; Voice_LoadFilterTable_Ch(A = part index, C = ramp position). Same shape as
; Voice_LoadPitchTable_Ch for the filter parameter set: DSP_AlgoType_Dispatch2(part, 0)
; scaled by C, floored at 0x1C, into 0x04520A and 0x0413C1 + part*0x11F;
; DSP_AlgoType_Dispatch1(part, 0) scaled by table_0x010ECE[C] into 0x04520E and
; 0x0413BF + part*0x11F; broadcast with Voice_BuildOutputList(part, 0x0C, 0) and
; ToneGen_WriteExtParams_56b.
Voice_LoadFilterTable_Ch:
	dec 8, xsp
	pushw iz
	ld (xsp + 6), c
	ld (xsp + 8), a
	ld a, (xsp + 8)
	extz wa
	lds bc, 0
	call DSP_AlgoType_Dispatch2
	extz xhl
	ld a, (xsp + 6)
	lds32 xbc, 0
	ld c, a
	ld xwa, xhl
	call FP_MulAccum64
	srl xhl, 8
	cp xhl, 0x1C
	jr nc, Voice_LoadFilterTable_Ch_NoClamp
	stiw_da 0x04520a, 0x001c
	ld a, (xsp + 8)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x0413c1:24)
	stiw_ind 0x07, 0xE4, 0xE0, 0x1C, 0x00
	jr Voice_LoadFilterTable_Ch_ScanFilter

; Scaled value already >= 0x1C: store unclamped.
Voice_LoadFilterTable_Ch_NoClamp:
	ld wa, hl
	stw_da 0x04520a, xwa
	ld a, (xsp + 8)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x0413c1:24)
	stw_dri HL, 0x07, 0xE4, 0xE0

; Second filter parameter and the output-list build.
Voice_LoadFilterTable_Ch_ScanFilter:
	ld a, (xsp + 8)
	extz wa
	lds bc, 0
	call DSP_AlgoType_Dispatch1
	extz xhl
	ld a, (xsp + 6)
	extz wa
	lda xbc, (0x010ece:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	lds32 xbc, 0
	ld c, a
	ld xwa, xhl
	call FP_MulAccum64
	srl xhl, 8
	ld wa, hl
	stw_da 0x04520e, xwa
	ld a, (xsp + 8)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x0413bf:24)
	stw_dri HL, 0x07, 0xE4, 0xE0
	ld a, (xsp + 8)
	extz wa
	ldw bc, 0xC
	lds de, 0
	call Voice_BuildOutputList
	ld (xsp + 2), xhl
	lds iz, 0
	jr Voice_LoadFilterTable_Ch_LoopCheck

; Per-voice broadcast via ToneGen_WriteExtParams_56b.
Voice_LoadFilterTable_Ch_LoopBody:
	ld wa, iz
	extz xwa
	add xwa, xwa
	add xwa, (xsp + 2)
	ld wa, (xwa)
	ldb w, 0x0
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParams_56b
	inc 1, iz

; Continue while the list entry's low byte is < 0x80.
Voice_LoadFilterTable_Ch_LoopCheck:
	ld wa, iz
	extz xwa
	add xwa, xwa
	add xwa, (xsp + 2)
	ld wa, (xwa)
	and wa, 0xFF
	cp wa, 0x80
	jr c, Voice_LoadFilterTable_Ch_LoopBody
	popw iz
	inc 8, xsp
	ret

; Voice_LoadFilterTable_All(A = part index). Unscaled counterpart of
; Voice_LoadFilterTable_Ch; writes 0x04520A / 0x04520E and broadcasts with
; ToneGen_WriteExtParams_56b. Sole caller: Voice_ToneTableRamp_Up_CheckFilter.
Voice_LoadFilterTable_All:
	dec 8, xsp
	ld (xsp + 6), a
	ld a, (xsp + 6)
	extz wa
	lds bc, 0
	call DSP_AlgoType_Dispatch2
	stw_da 0x04520a, xhl
	ld a, (xsp + 6)
	extz wa
	lds bc, 0
	call DSP_AlgoType_Dispatch1
	stw_da 0x04520e, xhl
	ld a, (xsp + 6)
	extz wa
	ldw bc, 0xC
	lds de, 0
	call Voice_BuildOutputList
	ld (xsp), xhl
	ldw (xsp + 4), 0x0
	jr Voice_LoadFilterTable_All_LoopCheck

; Per-voice broadcast body.
Voice_LoadFilterTable_All_LoopBody:
	ld wa, (xsp + 4)
	extz xwa
	add xwa, xwa
	add xwa, (xsp)
	ld wa, (xwa)
	ldb w, 0x0
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParams_56b
	incw 1, (xsp + 4)

; Continue while the list entry's low byte is < 0x80.
Voice_LoadFilterTable_All_LoopCheck:
	ld wa, (xsp + 4)
	extz xwa
	add xwa, xwa
	add xwa, (xsp)
	ld wa, (xwa)
	and wa, 0xFF
	cp wa, 0x80
	jr c, Voice_LoadFilterTable_All_LoopBody
	inc 8, xsp
	ret

; Voice_LoadToneTable_Ch(A = part index, C = ramp position). Third member of the family.
; Uses DSP_ChanFreq_WritePacket2(part) as its source value, scales it by C, floors at
; 0x1C, stores to 0x045206 and to 0x0413C9 + part*0x11F, then broadcasts with
; Voice_BuildOutputList(part, 0x10, 0) and ToneGen_WriteExtParams_15_Alt.
; Note its list terminator differs: the loop runs while (entry & 0xFF) < 0x40, not 0x80.
Voice_LoadToneTable_Ch:
	lda xsp, (xsp - 10)
	ld (xsp + 6), c
	ld (xsp + 8), a
	ld a, (xsp + 8)
	extz wa
	call DSP_ChanFreq_WritePacket2
	extz xhl
	ld a, (xsp + 6)
	lds32 xbc, 0
	ld c, a
	ld xwa, xhl
	call FP_MulAccum64
	srl xhl, 8
	cp xhl, 0x1C
	jr nc, Voice_LoadToneTable_Ch_NoClamp
	stiw_da 0x045206, 0x001c
	ld a, (xsp + 8)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x0413c9:24)
	stiw_ind 0x07, 0xE4, 0xE0, 0x1C, 0x00
	jr Voice_LoadToneTable_Ch_ScanLoop

; Scaled value already >= 0x1C: store unclamped.
Voice_LoadToneTable_Ch_NoClamp:
	ld wa, hl
	stw_da 0x045206, xwa
	ld a, (xsp + 8)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x0413c9:24)
	stw_dri HL, 0x07, 0xE4, 0xE0

; Build the output list for mask 0x10.
Voice_LoadToneTable_Ch_ScanLoop:
	ld a, (xsp + 8)
	extz wa
	ldw bc, 0x10
	lds de, 0
	call Voice_BuildOutputList
	ld (xsp), xhl
	ldw (xsp + 4), 0x0
	jr Voice_LoadToneTable_Ch_LoopCheck

; Per-voice broadcast via ToneGen_WriteExtParams_15_Alt.
Voice_LoadToneTable_Ch_LoopBody:
	ld wa, (xsp + 4)
	extz xwa
	add xwa, xwa
	add xwa, (xsp)
	ld wa, (xwa)
	ldb w, 0x0
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParams_15_Alt
	incw 1, (xsp + 4)

; Continue while the list entry's low byte is < 0x40.
Voice_LoadToneTable_Ch_LoopCheck:
	ld wa, (xsp + 4)
	extz xwa
	add xwa, xwa
	add xwa, (xsp)
	ld wa, (xwa)
	and wa, 0xFF
	cp wa, 0x40
	jr c, Voice_LoadToneTable_Ch_LoopBody
	lda xsp, (xsp + 10)
	ret

; Voice_LoadToneTable_All(A = part index). Unscaled counterpart of
; Voice_LoadToneTable_Ch. Sole caller: Voice_ToneTableRamp_Up_CheckFilter.
Voice_LoadToneTable_All:
	dec 8, xsp
	ld (xsp + 6), a
	ld a, (xsp + 6)
	extz wa
	call DSP_ChanFreq_WritePacket2
	stw_da 0x045206, xhl
	ld a, (xsp + 6)
	extz wa
	ldw bc, 0x10
	lds de, 0
	call Voice_BuildOutputList
	ld (xsp), xhl
	ldw (xsp + 4), 0x0
	jr Voice_LoadToneTable_All_LoopCheck

; Per-voice broadcast body.
Voice_LoadToneTable_All_LoopBody:
	ld wa, (xsp + 4)
	extz xwa
	add xwa, xwa
	add xwa, (xsp)
	ld wa, (xwa)
	ldb w, 0x0
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteExtParams_15_Alt
	incw 1, (xsp + 4)

; Continue while the list entry's low byte is < 0x40.
Voice_LoadToneTable_All_LoopCheck:
	ld wa, (xsp + 4)
	extz xwa
	add xwa, xwa
	add xwa, (xsp)
	ld wa, (xwa)
	and wa, 0xFF
	cp wa, 0x40
	jr c, Voice_LoadToneTable_All_LoopBody
	inc 8, xsp
	ret

; Voice_ToneTableRamp_Up(A = part index, XBC = part record at 0x041368 + part*0x11F).
; One step of the "sweep up" of the two DSP-parameter ramps a part owns:
;   +100 = pitch ramp position, range 0..0x4F (indexes the 80-entry curve 0x010D64)
;   +101 = filter ramp position, range 0..0x96 (divided by 6 to index the 26-entry curve
;          0x010DB4)
;   +99  = the ramp state-flag byte (bits 0..4)
; If +100 has reached 0x4F it sets flag bit 3 and calls Voice_LoadPitchTable_All;
; otherwise it increments +100, clears bit 3, and calls Voice_LoadPitchTable_Ch with
; table_0x010D64[+100]. The filter half behaves the same way against 0x96 / 6, calling
; Voice_LoadFilterTable_All + Voice_LoadToneTable_All, or _Ch with table_0x010DB4[+101/6].
; Sole caller: Audio_Tick_ServiceVoices_B_LFOLoopBody.
Voice_ToneTableRamp_Up:
	dec 4, xsp
	push xiz
	ld xiz, xbc
	ld (xsp + 6), a
	cp (xiz + 100), 0x4F
	jr c, Voice_ToneTableRamp_Up_Increment
	setm 3, (xiz + 99)
	ld a, (xsp + 6)
	extz wa
	calr Voice_LoadPitchTable_All
	jr Voice_ToneTableRamp_Up_CheckFilter

; Pitch ramp not yet at 0x4F: ++position, clear flag bit 3, push the new value.
Voice_ToneTableRamp_Up_Increment:
	incm8 1, (xiz + 100)
	resm 3, (xiz + 99)
	ld a, (xiz + 100)
	ld (xsp + 4), a
	ld a, (xsp + 6)
	ld e, a
	extz de
	ld a, (xsp + 4)
	extz wa
	lda xbc, (0x010d64:24)
	ldb_sri C, 0x07, 0xE4, 0xE0
	ld wa, de
	calr Voice_LoadPitchTable_Ch

; Filter ramp: at 0x96 -> Voice_LoadFilterTable_All + Voice_LoadToneTable_All.
Voice_ToneTableRamp_Up_CheckFilter:
	cp (xiz + 101), 0x96
	jr c, Voice_ToneTableRamp_Up_FilterIncrement
	ld a, (xsp + 6)
	extz wa
	calr Voice_LoadFilterTable_All
	ld a, (xsp + 6)
	extz wa
	calr Voice_LoadToneTable_All
	jr Voice_ToneTableRamp_Up_Done

; ++filter position, clear flag bit 3, push table_0x010DB4[pos/6] to both the filter and
; tone parameter sets.
Voice_ToneTableRamp_Up_FilterIncrement:
	incm8 1, (xiz + 101)
	resm 3, (xiz + 99)
	ld a, (xiz + 101)
	extz wa
	div a, 0x6
	ld (xsp + 4), a
	ld a, (xsp + 6)
	ld e, a
	extz de
	ld a, (xsp + 4)
	extz wa
	lda xbc, (0x010db4:24)
	ldb_sri C, 0x07, 0xE4, 0xE0
	ld wa, de
	calr Voice_LoadFilterTable_Ch
	ld a, (xsp + 6)
	ld e, a
	extz de
	ld a, (xsp + 4)
	extz wa
	lda xbc, (0x010db4:24)
	ldb_sri C, 0x07, 0xE4, 0xE0
	ld wa, de
	calr Voice_LoadToneTable_Ch

; Restore and return.
Voice_ToneTableRamp_Up_Done:
	pop xiz
	inc 4, xsp
	ret

; Voice_ToneTableRamp_Down(A = part index, XBC = part record). The mirror of
; Voice_ToneTableRamp_Up: when +100 is already 0 it sets flag bit 4 and skips to the
; filter half; otherwise it decrements +100, clears bit 4, and pushes
; table_0x010DB4[+100 >> 1]. The filter half decrements +101 and pushes
; table_0x010DB4[+101 / 5] to both the filter and tone parameter sets.
; Sole caller: Audio_Tick_ServiceVoices_B_LFO_CheckRampDown.
; ⚠ The two halves index the SAME 26-entry table 0x010DB4 with different scales -- >>1
; (max 0x4F/2 = 39) and /5 (max 0x96/5 = 30) -- both of which exceed the table's 26
; entries and read into the adjacent table at 0x010DCE. See [UNCERTAIN].
Voice_ToneTableRamp_Down:
	dec 4, xsp
	push xiz
	ld xiz, xbc
	ld (xsp + 6), a
	cp (xiz + 100), 0x0
	jr nz, Voice_ToneTableRamp_Down_Decrement
	setm 4, (xiz + 99)
	jr Voice_ToneTableRamp_Down_CheckFilter

; Pitch ramp above 0: --position, clear flag bit 4, push table_0x010DB4[pos >> 1].
Voice_ToneTableRamp_Down_Decrement:
	decm8 1, (xiz + 100)
	resm 4, (xiz + 99)
	ld a, (xiz + 100)
	srl a, 1
	ld (xsp + 4), a
	ld a, (xsp + 6)
	ld e, a
	extz de
	ld a, (xsp + 4)
	extz wa
	lda xbc, (0x010db4:24)
	ldb_sri C, 0x07, 0xE4, 0xE0
	ld wa, de
	calr Voice_LoadPitchTable_Ch

; Filter ramp: return if already 0, else --position and push table_0x010DB4[pos / 5].
Voice_ToneTableRamp_Down_CheckFilter:
	cp (xiz + 101), 0x0
	jr z, Voice_ToneTableRamp_Down_Done
	decm8 1, (xiz + 101)
	resm 4, (xiz + 99)
	ld a, (xiz + 101)
	extz wa
	div a, 0x5
	ld (xsp + 4), a
	ld a, (xsp + 6)
	ld e, a
	extz de
	ld a, (xsp + 4)
	extz wa
	lda xbc, (0x010db4:24)
	ldb_sri C, 0x07, 0xE4, 0xE0
	ld wa, de
	calr Voice_LoadFilterTable_Ch
	ld a, (xsp + 6)
	ld e, a
	extz de
	ld a, (xsp + 4)
	extz wa
	lda xbc, (0x010db4:24)
	ldb_sri C, 0x07, 0xE4, 0xE0
	ld wa, de
	calr Voice_LoadToneTable_Ch

; Restore and return.
Voice_ToneTableRamp_Down_Done:
	pop xiz
	inc 4, xsp
	ret

; Voice_ToneTableApply_Pitch(A = part index, XBC = part record). Jumps the ramp straight
; to the position that matches the current pitch value, instead of stepping.
; Clears flag bits 3 and 4 of +99, reads L = table_0x010D64[+100], then searches DOWNWARD
; from index 0x19 for the largest index whose table_0x010DB4 entry is <= L. That index
; becomes the new +100; +101 is rescaled from the /6 domain into the /5 domain
; ((+101 / 6) is discarded and the found index * 5 is stored). Finally it pushes all
; three parameter sets with Voice_LoadPitchTable_Ch, Voice_LoadFilterTable_Ch and
; Voice_LoadToneTable_Ch.
; Sole caller: Audio_Tick_ServiceVoices_B_LFO_RampDown.
Voice_ToneTableApply_Pitch:
	dec 6, xsp
	pushw_erp 0xFA
	ld (xsp + 2), xbc
	ld (xsp + 6), a
	ld xwa, (xsp + 2)
	andmi8 (xwa + 99), 0xE7
	ld xwa, (xsp + 2)
	ld a, (xwa + 100)
	extz wa
	lda xbc, (0x010d64:24)
	ldb_sri L, 0x07, 0xE4, 0xE0
	ldi_erpb 0xFB, 0x19
	jr Voice_ToneTableApply_Pitch_Loop

; Search step: decrement the candidate index.
Voice_ToneTableApply_Pitch_Decrement:
	dec1b_erp 0xFB

; Search test: continue while L < table_0x010DB4[index]. The loop has no explicit lower
; bound; it is bounded only by table_0x010DB4[0] == 0x00, which no unsigned L can be
; below, so index 0 always terminates it.
Voice_ToneTableApply_Pitch_Loop:
	stb_erp A, 0xFB
	extz wa
	lda xbc, (0x010db4:24)
	cpb_sri_rm L, 0x07, 0xE4, 0xE0
	jr c, Voice_ToneTableApply_Pitch_Decrement
	ld xwa, (xsp + 2)
	stb_erp C, 0xFB
	ld (xwa + 100), c
	ld a, (xsp + 6)
	ld e, a
	extz de
	ld a, l
	extz wa
	lda xbc, (0x010d64:24)
	ldb_sri C, 0x07, 0xE4, 0xE0
	ld wa, de
	calr Voice_LoadPitchTable_Ch
	ld xwa, (xsp + 2)
	ld l, (xwa + 101)
	ld a, l
	extz wa
	div a, 0x6
	ld l, a
	ldb_erp L, 0xFB
	ld a, l
	mul a, 0x5
	ld l, a
	ld xwa, (xsp + 2)
	ld (xwa + 101), l
	ld a, (xsp + 6)
	ld e, a
	extz de
	stb_erp A, 0xFB
	extz wa
	lda xbc, (0x010db4:24)
	ldb_sri C, 0x07, 0xE4, 0xE0
	ld wa, de
	calr Voice_LoadFilterTable_Ch
	ld a, (xsp + 6)
	ld e, a
	extz de
	stb_erp A, 0xFB
	extz wa
	lda xbc, (0x010db4:24)
	ldb_sri C, 0x07, 0xE4, 0xE0
	ld wa, de
	calr Voice_LoadToneTable_Ch
	popw_erp 0xFA
	inc 6, xsp
	ret

; Voice_ToneTableApply_Filter(A = part index, XBC = part record). The mirror of
; Voice_ToneTableApply_Pitch: reads E = table_0x010DB4[+100 >> 1] and searches UPWARD
; from index 0 for the first index whose table_0x010D64 entry is >= E. That index becomes
; +100; +101 is rescaled from the /5 domain into the /6 domain (index * 6). Then pushes
; all three parameter sets with the three _Ch broadcasters.
; Sole caller: Audio_Tick_ServiceVoices_B_LFO_ApplyFilter.
Voice_ToneTableApply_Filter:
	dec 6, xsp
	pushw_erp 0xFA
	ld (xsp + 2), xbc
	ld (xsp + 6), a
	ld xwa, (xsp + 2)
	andmi8 (xwa + 99), 0xE7
	ld xwa, (xsp + 2)
	ld a, (xwa + 100)
	srl a, 1
	extz wa
	lda xbc, (0x010db4:24)
	ldb_sri E, 0x07, 0xE4, 0xE0
	ldib_erp 0xFB, 0
	jr Voice_ToneTableApply_Filter_Loop

; Search step: increment the candidate index.
Voice_ToneTableApply_Filter_Increment:
	inc1b_erp 0xFB

; Search test: continue while E > table_0x010D64[index] (unsigned). The loop has no
; explicit upper bound; it is bounded only by the fact that table_0x010D64 reaches 0xFF
; at index 78 of its 80 entries.
Voice_ToneTableApply_Filter_Loop:
	stb_erp A, 0xFB
	extz wa
	lda xbc, (0x010d64:24)
	cpb_sri_rm E, 0x07, 0xE4, 0xE0
	jr ugt, Voice_ToneTableApply_Filter_Increment
	ld xwa, (xsp + 2)
	stb_erp C, 0xFB
	ld (xwa + 100), c
	ld a, (xsp + 6)
	ld e, a
	extz de
	stb_erp A, 0xFB
	extz wa
	lda xbc, (0x010db4:24)
	ldb_sri C, 0x07, 0xE4, 0xE0
	ld wa, de
	calr Voice_LoadPitchTable_Ch
	ld xwa, (xsp + 2)
	ld e, (xwa + 101)
	ld a, e
	extz wa
	div a, 0x5
	ld e, a
	ldb_erp E, 0xFB
	ld a, e
	mul a, 0x6
	ld e, a
	ld xwa, (xsp + 2)
	ld (xwa + 101), e
	ld a, (xsp + 6)
	ld e, a
	extz de
	stb_erp A, 0xFB
	extz wa
	lda xbc, (0x010db4:24)
	ldb_sri C, 0x07, 0xE4, 0xE0
	ld wa, de
	calr Voice_LoadFilterTable_Ch
	ld a, (xsp + 6)
	ld e, a
	extz de
	stb_erp A, 0xFB
	extz wa
	lda xbc, (0x010db4:24)
	ldb_sri C, 0x07, 0xE4, 0xE0
	ld wa, de
	calr Voice_LoadToneTable_Ch
	popw_erp 0xFA
	inc 6, xsp
	ret

Audio_Tick_ServiceVoices_A:
	dec 4, xsp
	push xiz
	calr Voice_UpdateAllLFO
	call Voice_Query_AllChannels
	lda xwa, (xhl + 5)
	ld (xsp + 4), xwa
	cp (xwa), 0x40
	jr nc, Audio_Tick_ServiceVoices_A_Done

; Body of Audio_Tick_ServiceVoices_A (entry 0x027A46, already named -- left alone).
; That routine is the EVEN phase of the audio tick: it calls Voice_UpdateAllLFO once,
; then Voice_Query_AllChannels to obtain the list of sounding slot indices at (XHL+5), and
; walks it. XIZ is loaded here as 0x04308E + slot*0x47 (the voice-slot record base and
; stride; the LLVM source spells the instruction as the raw-encoding pseudo-op
; "lda_dri XIZ, 0x07,0xE4,0xE0", which unidasm decodes as "lda XIZ,XBC+WA").
; Per slot: if bit 15 of tonerec[+10] is set and (slot+47 & 0x8080) is non-zero, call
; Voice_Step_DelayTimers; if the bit is clear and the timers are armed, release the slot
; outright (Voice_Clear_HoldBit + Voice_Reload_Levels, slot+47 = 0).
; The routine's remaining labels (_ClearSlot 0x027A91, _NextSlot 0x027AB3,
; _Done 0x027AC0) fall past this region's upper boundary.
Audio_Tick_ServiceVoices_A_Loop:
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	muls wa, 0x47
	lda xbc, (0x04308e:24)
	lda_dri XIZ, 0x07, 0xE4, 0xE0
	ld xwa, (xiz + 35)
	ld wa, (xwa + 10)
	extz xwa
	bit 15, wa
	jr z, Audio_Tick_ServiceVoices_A_ClearSlot
	ld wa, (xiz + 47)
	extz xwa
	and xwa, 0x8080
	jr z, Audio_Tick_ServiceVoices_A_NextSlot
	ld xwa, xiz
	calr Voice_Step_DelayTimers
	jr Audio_Tick_ServiceVoices_A_NextSlot

; Release path of Audio_Tick_ServiceVoices_A (entry 0x027A46, just below this region).
; Reached when the word at [voice+0x23]+0x0A has bit 15 CLEAR, i.e. the voice's tone record
; says the note is not still being held by the envelope.  If (voice+0x2F) & 0x8080 is non-zero
; (a note-off or a portamento-off request is pending) the voice is handed back:
;   call Voice_Clear_HoldBit (0x022587), call Voice_Reload_Levels (0x02CD71), then (voice+0x2F)=0.
; If neither request bit is set the voice is left alone and the walk continues.
; This is one of only two places in the whole sub-CPU where a sounding voice is returned to
; the free pool during normal play; the other is Audio_Tick_ServiceVoices_B below.
Audio_Tick_ServiceVoices_A_ClearSlot:
	ld wa, (xiz + 47)
	extz xwa
	and xwa, 0x8080
	jr z, Audio_Tick_ServiceVoices_A_NextSlot
	ld a, (xiz)
	extz wa
	call Voice_Clear_HoldBit
	ld a, (xiz)
	extz wa
	call Voice_Reload_Levels
	ldw (xiz + 47), 0x0

; Advance the per-part voice-index cursor by 1 and loop while *cursor < 0x40 (0x40 = list end).
Audio_Tick_ServiceVoices_A_NextSlot:
	lds32 xwa, 1
	add (xsp + 4), xwa
	ld xwa, (xsp + 4)
	cp (xwa), 0x40
	jr c, Audio_Tick_ServiceVoices_A_Loop

; Restore XIZ and return.
Audio_Tick_ServiceVoices_A_Done:
	pop xiz
	inc 4, xsp
	ret

; Per-audio-tick voice state machine, phase B.  Called from Audio_Process_Init (0x031F..,
; `call Audio_Tick_ServiceVoices_B`) which alternates between this and
; Audio_Tick_ServiceVoices_A every tick by XORing the byte at 0x041342 with 0xFF.
; Prologue: calr Voice_TickNoteDecay (0x027363), calr Pitch_Bend_Ramp_Tick (0x0271BC).
; Then reads the global flag word 0x041343 and tests bit 10:
;   bit 10 SET   -> loop A (0x027AE8): additionally re-writes the pitch register, twice --
;                   Pitch_Emit_Reg400 (0x023A4A) and ToneGen_WriteVoicePitch (0x02D0BA),
;                   both of which write +0x400 -- for every voice whose flags word
;                   (voice+0x01) has bit 10 set;
;   bit 10 CLEAR -> loop B (0x027BA0): the same retire/portamento bookkeeping WITHOUT any
;                   pitch register traffic.
; Both loops walk the part's voice-index list obtained from Voice_Query_AllChannels (0x02CD55),
; list pointer = XHL+5, terminated by a byte >= 0x40, voice record = 0x04308E + idx*0x47.
; Per voice: if [voice+0x23]+0x0A bit 15 is SET the note is still held -> Voice_Step_DelayTimers
; (0x026E5B) or Voice_Step_ExprRamp (0x026EC3); if CLEAR, and the matching request bit in
; (voice+0x2F) mask 0x8080 or (voice+0x31) bit 15 is set, the voice is released
; (Voice_Clear_HoldBit + Voice_Reload_Levels) and the request word is zeroed.
; Ends with the LFO/tone-table scan at 0x027C48.  Touches no hardware directly in loop B.
Audio_Tick_ServiceVoices_B:
	dec 4, xsp
	push xiz
	calr Voice_TickNoteDecay
	calr Pitch_Bend_Ramp_Tick
	ld wa, (0x041343:24)
	bit 10, wa
	jrl z, Audio_Tick_ServiceVoices_B_LoopB_Start
	call Voice_Query_AllChannels
	lda xwa, (xhl + 5)
	ld (xsp + 4), xwa
	cp (xwa), 0x40
	jrl nc, Audio_Tick_ServiceVoices_B_ScanLFO

; Loop A body: full update including the tone-generator pitch and pan re-writes.
Audio_Tick_ServiceVoices_B_LoopA:
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	muls wa, 0x47
	lda xbc, (0x04308e:24)
	lda_dri XIZ, 0x07, 0xE4, 0xE0
	ld wa, (xiz + 1)
	bit 10, wa
	jr z, Audio_Tick_ServiceVoices_B_CheckPortaA
	ld xwa, xiz
	calr Pitch_Emit_Reg400
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	lda xbc, (0x0451cc:24)
	call ToneGen_WriteVoicePitch

; Load the tone record pointer from voice+0x23 and test bit 15 of its +0x0A word.
Audio_Tick_ServiceVoices_B_CheckPortaA:
	ld xwa, (xiz + 35)
	ld wa, (xwa + 10)
	extz xwa
	bit 15, wa
	jr z, Audio_Tick_ServiceVoices_B_ClearNoteOffA
	ld wa, (xiz + 47)
	extz xwa
	and xwa, 0x8080
	jr z, Audio_Tick_ServiceVoices_B_CheckPortamento2A
	ld xwa, xiz
	calr Voice_Step_DelayTimers
	jr Audio_Tick_ServiceVoices_B_NextSlotA

; Note-off not pending: test the portamento-active word (voice+0x31) bit 15.
Audio_Tick_ServiceVoices_B_CheckPortamento2A:
	ld wa, (xiz + 49)
	extz xwa
	bit 15, wa
	jr z, Audio_Tick_ServiceVoices_B_NextSlotA
	ld xwa, xiz
	calr Voice_Step_ExprRamp
	jr Audio_Tick_ServiceVoices_B_NextSlotA

; Tone record says "not held": release the voice if (voice+0x2F) & 0x8080, then zero it.
Audio_Tick_ServiceVoices_B_ClearNoteOffA:
	ld wa, (xiz + 47)
	extz xwa
	and xwa, 0x8080
	jr z, Audio_Tick_ServiceVoices_B_ClearPorta2A
	ld a, (xiz)
	extz wa
	call Voice_Clear_HoldBit
	ld a, (xiz)
	extz wa
	call Voice_Reload_Levels
	ldw (xiz + 47), 0x0
	jr Audio_Tick_ServiceVoices_B_NextSlotA

; Same, driven by the portamento word (voice+0x31) instead; zeroes (voice+0x31).
Audio_Tick_ServiceVoices_B_ClearPorta2A:
	ld wa, (xiz + 49)
	extz xwa
	bit 15, wa
	jr z, Audio_Tick_ServiceVoices_B_NextSlotA
	ld a, (xiz)
	extz wa
	call Voice_Clear_HoldBit
	ld a, (xiz)
	extz wa
	call Voice_Reload_Levels
	ldw (xiz + 49), 0x0

; Advance the loop-A cursor; loop while *cursor < 0x40.
Audio_Tick_ServiceVoices_B_NextSlotA:
	lds32 xwa, 1
	add (xsp + 4), xwa
	ld xwa, (xsp + 4)
	cp (xwa), 0x40
	jrl c, Audio_Tick_ServiceVoices_B_LoopA
	jrl Audio_Tick_ServiceVoices_B_ScanLFO

; Entry to loop B (global flag 0x041343 bit 10 clear): re-fetch the part voice list.
Audio_Tick_ServiceVoices_B_LoopB_Start:
	call Voice_Query_AllChannels
	lda xwa, (xhl + 5)
	ld (xsp + 4), xwa
	cp (xwa), 0x40
	jrl nc, Audio_Tick_ServiceVoices_B_ScanLFO

; Loop B body: retire/portamento bookkeeping only, no TG register writes.
Audio_Tick_ServiceVoices_B_LoopB:
	ld xwa, (xsp + 4)
	ld a, (xwa)
	extz wa
	muls wa, 0x47
	lda xbc, (0x04308e:24)
	lda_dri XIZ, 0x07, 0xE4, 0xE0
	ld xwa, (xiz + 35)
	ld wa, (xwa + 10)
	extz xwa
	bit 15, wa
	jr z, Audio_Tick_ServiceVoices_B_ClearNoteOffB
	ld wa, (xiz + 47)
	extz xwa
	and xwa, 0x8080
	jr z, Audio_Tick_ServiceVoices_B_CheckPortamento2B
	ld xwa, xiz
	calr Voice_Step_DelayTimers
	jr Audio_Tick_ServiceVoices_B_NextSlotB

; CheckPortamento2B of Audio_Tick_ServiceVoices_B.
Audio_Tick_ServiceVoices_B_CheckPortamento2B:
	ld wa, (xiz + 49)
	extz xwa
	bit 15, wa
	jr z, Audio_Tick_ServiceVoices_B_NextSlotB
	ld xwa, xiz
	calr Voice_Step_ExprRamp
	jr Audio_Tick_ServiceVoices_B_NextSlotB

; ClearNoteOffB of Audio_Tick_ServiceVoices_B.
Audio_Tick_ServiceVoices_B_ClearNoteOffB:
	ld wa, (xiz + 47)
	extz xwa
	and xwa, 0x8080
	jr z, Audio_Tick_ServiceVoices_B_ClearPorta2B
	ld a, (xiz)
	extz wa
	call Voice_Clear_HoldBit
	ld a, (xiz)
	extz wa
	call Voice_Reload_Levels
	ldw (xiz + 47), 0x0
	jr Audio_Tick_ServiceVoices_B_NextSlotB

; ClearPorta2B of Audio_Tick_ServiceVoices_B.
Audio_Tick_ServiceVoices_B_ClearPorta2B:
	ld wa, (xiz + 49)
	extz xwa
	bit 15, wa
	jr z, Audio_Tick_ServiceVoices_B_NextSlotB
	ld a, (xiz)
	extz wa
	call Voice_Clear_HoldBit
	ld a, (xiz)
	extz wa
	call Voice_Reload_Levels
	ldw (xiz + 49), 0x0

; Loop-B counterparts of the loop-A labels above; identical logic minus the hardware writes.
Audio_Tick_ServiceVoices_B_NextSlotB:
	lds32 xwa, 1
	add (xsp + 4), xwa
	ld xwa, (xsp + 4)
	cp (xwa), 0x40
	jrl c, Audio_Tick_ServiceVoices_B_LoopB

; Second phase: iterate parts 0..0x19 (stride 0x11F from 0x041368) and drive each part's
; tone-table ramp state machine from the byte at part+0x63.
Audio_Tick_ServiceVoices_B_ScanLFO:
	ldib_erp 0xFB, 0
	cp_erpb 0xFB, 0x1A
	jr nc, Audio_Tick_ServiceVoices_B_Done

; Decode part+0x63: b0 = enabled, b1/b2/b3/b4 select ramp-up / apply-filter / ramp-down /
; apply-pitch.  Calls Voice_ToneTableRamp_Up 0x027798, _Down 0x02783D,
; Voice_ToneTableApply_Filter 0x027987, _Pitch 0x0278CB.
Audio_Tick_ServiceVoices_B_LFOLoopBody:
	stb_erp A, 0xFB
	extz wa
	muls wa, 0x11F
	lda xbc, (0x041368:24)
	lda_dri XBC, 0x07, 0xE4, 0xE0
	ld a, (xbc + 99)
	bit 0, a
	jr z, Audio_Tick_ServiceVoices_B_LFONextSlot
	bit 1, a
	jr z, Audio_Tick_ServiceVoices_B_LFO_CheckRampDown
	bit 2, a
	jr z, Audio_Tick_ServiceVoices_B_LFO_ApplyFilter
	bit 3, a
	jr nz, Audio_Tick_ServiceVoices_B_LFONextSlot
	stb_erp A, 0xFB
	extz wa
	calr Voice_ToneTableRamp_Up
	jr Audio_Tick_ServiceVoices_B_LFONextSlot

; Sets bit 2 of part+0x63 and calls Voice_ToneTableApply_Filter.
Audio_Tick_ServiceVoices_B_LFO_ApplyFilter:
	setm 2, (xbc + 99)
	stb_erp A, 0xFB
	extz wa
	calr Voice_ToneTableApply_Filter
	jr Audio_Tick_ServiceVoices_B_LFONextSlot

; CheckRampDown of Voice_UpdateAllNoteStates_LFO.
Audio_Tick_ServiceVoices_B_LFO_CheckRampDown:
	bit 2, a
	jr nz, Audio_Tick_ServiceVoices_B_LFO_RampDown
	bit 4, a
	jr nz, Audio_Tick_ServiceVoices_B_LFONextSlot
	stb_erp A, 0xFB
	extz wa
	calr Voice_ToneTableRamp_Down
	jr Audio_Tick_ServiceVoices_B_LFONextSlot

; Clears bit 2 of part+0x63 and calls Voice_ToneTableApply_Pitch.
Audio_Tick_ServiceVoices_B_LFO_RampDown:
	resm 2, (xbc + 99)
	stb_erp A, 0xFB
	extz wa
	calr Voice_ToneTableApply_Pitch

; LFONextSlot of Audio_Tick_ServiceVoices_B.
Audio_Tick_ServiceVoices_B_LFONextSlot:
	inc1b_erp 0xFB
	cp_erpb 0xFB, 0x1A
	jr c, Audio_Tick_ServiceVoices_B_LFOLoopBody

; exit path of Audio_Tick_ServiceVoices_B.
Audio_Tick_ServiceVoices_B_Done:
	pop xiz
	inc 4, xsp
	ret

; WA = part index.  ORs 0x0020 into the part flags word at part+0x02 (0x04136A + idx*0x11F).
; Called once per part from Voice_ResetAllControllers.
Voice_SetLFO_ActiveFlag:
	extz wa
	muls wa, 0x11F
	lda xbc, (0x04136a:24)
	or_sriw_im 0x07, 0xE4, 0xE0, 0x00, 0x20
	ret

; WA = part index.  ANDs 0xFFDF into the same word.  Inverse of the above.
Voice_ClearLFO_ActiveFlag:
	extz wa
	muls wa, 0x11F
	lda xbc, (0x04136a:24)
	and_sriw_im 0x07, 0xE4, 0xE0, 0xFF, 0xDF
	ret

; ----------------------------------------------------------------------------
; Voice_DSP_OutputConfig - Configure voice-to-DSP output routing
; Entry: A = voice number, C = channel
; Notes: Calls DSP_AlgoType_Dispatch1 for algorithm type lookup
;        Stores result to DSP state at 0x04520E
;        Iterates voice output list via Voice_BuildOutputList
;        Configures tone generator params via ToneGen_ExtParams56b_DataTable
;        Two-pass: first updates 0x04520E, then 0x04520C
; ----------------------------------------------------------------------------
; Emitted as `.byte` in the LLVM source but is ordinary code.  A = voice, C = channel.
; Walks the voice output list (Voice_BuildOutputList 0x021A8E), consults
; DSP_AlgoType_Dispatch1 (0x0337D2) and writes the effect-routing shadow words at 0x04520E
; and then 0x04520C.  Twin of Voice_DSP_OutputConfig2 with different shadow offsets.
Voice_DSP_OutputConfig:
	lda	xsp, (xsp-10)
	ld	(xsp+6), c
	ld	(xsp+8), a
	cp8_imm_rid8	xsp, 0x06, 0x00	; cp (XSP+0x06),0x00
	jr	nz, LABEL_027D61
	ld	a, (xsp+8)
	ld	e, a
	extz	de
	ld	a, (xsp+6)
	ld	c, a
	extz	bc
	ld	wa, de
	call	DSP_AlgoType_Dispatch1
	stw_da	(283150), hl
	ld	a, (xsp+8)
	ld	e, a
	extz	de
	ld	a, (xsp+6)
	extz	wa
	or	wa, 12
	ld	c, a
	extz	bc
	ld	wa, de
	lds	de, 0
	call	Voice_BuildOutputList
	ld	(xsp), xhl
	ldw	(xsp+4), 0x0000	; ld (XSP+0x04),0x0000
	jr	LABEL_027D4A
LABEL_027D31:
	ld	wa, (xsp+4)
	extz	xwa
	add	xwa, xwa
	add32_src_ri	xsp, xwa	; add XWA,(XSP)
	ld	wa, (xwa)
	ldb	w, 0
	lda	xbc, (283084:24)
	call	ToneGen_ExtParams56b_DataTable
	incw	1, (xsp+4)
LABEL_027D4A:
	ld	wa, (xsp+4)
	extz	xwa
	add	xwa, xwa
	add32_src_ri	xsp, xwa	; add XWA,(XSP)
	ld	wa, (xwa)
	and	wa, 255
	cp	wa, 128
	jr	c, LABEL_027D31
	jr	LABEL_027DCD
LABEL_027D61:
	ld	a, (xsp+8)
	ld	e, a
	extz	de
	ld	a, (xsp+6)
	ld	c, a
	extz	bc
	ld	wa, de
	call	DSP_AlgoType_Dispatch1
	stw_da	(283148), hl
	ld	a, (xsp+8)
	ld	e, a
	extz	de
	ld	a, (xsp+6)
	extz	wa
	or	wa, 12
	ld	c, a
	extz	bc
	ld	wa, de
	lds	de, 0
	call	Voice_BuildOutputList
	ld	(xsp), xhl
	ldw	(xsp+4), 0x0000	; ld (XSP+0x04),0x0000
	jr	LABEL_027DB8
LABEL_027D9F:
	ld	wa, (xsp+4)
	extz	xwa
	add	xwa, xwa
	add32_src_ri	xsp, xwa	; add XWA,(XSP)
	ld	wa, (xwa)
	ldb	w, 0
	lda	xbc, (283084:24)
	call	ToneGen_WriteExtParam_600
	incw	1, (xsp+4)
LABEL_027DB8:
	ld	wa, (xsp+4)
	extz	xwa
	add	xwa, xwa
	add32_src_ri	xsp, xwa	; add XWA,(XSP)
	ld	wa, (xwa)
	and	wa, 255
	cp	wa, 128
	jr	c, LABEL_027D9F
LABEL_027DCD:
	lda	xsp, (xsp+10)
	ret
; ----------------------------------------------------------------------------
; Voice_DSP_OutputConfig2 - Configure voice-to-DSP output routing (type 2)
; Entry: A = voice number, C = channel
; Notes: Same algorithm as Voice_DSP_OutputConfig with different table offsets
; ----------------------------------------------------------------------------
; NOT PRESENT in symbols/subcpu_symbols_reference.txt -- add it.
; Same body as Voice_DSP_OutputConfig but targets shadow words 0x04520A / 0x045208.
Voice_DSP_OutputConfig2:
	lda	xsp, (xsp-10)
	ld	(xsp+6), c
	ld	(xsp+8), a
	cp8_imm_rid8	xsp, 0x06, 0x00	; cp (XSP+0x06),0x00
	jr	nz, LABEL_027E4E
	ld	a, (xsp+8)
	ld	e, a
	extz	de
	ld	a, (xsp+6)
	ld	c, a
	extz	bc
	ld	wa, de
	call	DSP_AlgoType_Dispatch2
	stw_da	(283146), hl
	ld	a, (xsp+8)
	ld	e, a
	extz	de
	ld	a, (xsp+6)
	extz	wa
	or	wa, 12
	ld	c, a
	extz	bc
	ld	wa, de
	lds	de, 0
	call	Voice_BuildOutputList
	ld	(xsp), xhl
	ldw	(xsp+4), 0x0000	; ld (XSP+0x04),0x0000
	jr	LABEL_027E37
LABEL_027E1E:
	ld	wa, (xsp+4)
	extz	xwa
	add	xwa, xwa
	add32_src_ri	xsp, xwa	; add XWA,(XSP)
	ld	wa, (xwa)
	ldb	w, 0
	lda	xbc, (283084:24)
	call	ToneGen_Write_ExtParam_05C0_Strobe
	incw	1, (xsp+4)
LABEL_027E37:
	ld	wa, (xsp+4)
	extz	xwa
	add	xwa, xwa
	add32_src_ri	xsp, xwa	; add XWA,(XSP)
	ld	wa, (xwa)
	and	wa, 255
	cp	wa, 128
	jr	c, LABEL_027E1E
	jr	LABEL_027EBA
LABEL_027E4E:
	ld	a, (xsp+8)
	ld	e, a
	extz	de
	ld	a, (xsp+6)
	ld	c, a
	extz	bc
	ld	wa, de
	call	DSP_AlgoType_Dispatch2
	stw_da	(283144), hl
	ld	a, (xsp+8)
	ld	e, a
	extz	de
	ld	a, (xsp+6)
	extz	wa
	or	wa, 12
	ld	c, a
	extz	bc
	ld	wa, de
	lds	de, 0
	call	Voice_BuildOutputList
	ld	(xsp), xhl
	ldw	(xsp+4), 0x0000	; ld (XSP+0x04),0x0000
	jr	LABEL_027EA5
LABEL_027E8C:
	ld	wa, (xsp+4)
	extz	xwa
	add	xwa, xwa
