	nop
	nop
	nop
	stb_erp A, 0xFB
	extz wa
	calr Voice_Init_Type2

Voice_SetVelocity_Type80_LoopStep:
	inc1b_erp 0xFA
	cpib_erp 0xFA, 2
	jr c, Voice_SetVelocity_Type80_SlotLoop

Voice_SetVelocity_Type80_Loop2Start:
	ldib_erp 0xFA, 0
	cpib_erp 0xFA, 2
	jr nc, Voice_SetVelocity_Type80_Loop2Exit

Voice_SetVelocity_Type80_Loop2Body:
	stb_erp A, 0xFA
	extz wa
	add wa, 0xA
	lda xbc, (xsp + 2)
	ldb_sri A, 0x07, 0xE4, 0xE0
	ldb_erp A, 0xFB
	cp_erpb 0xFB, 0x40
	jr nc, Voice_SetVelocity_Type80_Loop2Step
	stb_erp A, 0xFB
	ld l, a
	extz hl
	stb_erp A, 0xFB
	extz wa
	muls wa, 0x47
	ld bc, wa
	lda xde, (0x0430bb:24)
	ld wa, hl
	ldw_sri BC, 0x07, 0xE8, 0xE4
