	extz wa
	muls wa, 0x25
	ld de, wa
	add de, 0x6E
	ld a, (xsp + 4)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x041368:24)
	exts xwa
	add xwa, xbc
	ld_sril3 XWA, 0x07, 0xE0, 0xE8
