	bit 0, wa
	jr z, VoiceAlloc_InitNewAllocation
	ld a, (xsp)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x041368:24)
	or_sriw_im 0x07, 0xE4, 0xE0, 0x01, 0x00
	jr VoiceAlloc_CheckAndInit_Return

