	extz wa
	muls wa, 0x11F
	lda xbc, (0x041382:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	ld e, a
	extz de
	ld wa, hl
	ld bc, ix
	call WaveSel_Rebuild_PartCaches

