	extz	wa
	calr	VoiceAlloc_CheckAndInit
	ld	a, (xiz+4)
	ld	c, a
	extz	bc
	ld	a, (xiz+3)
	extz	wa
	ld	hl, wa
	sll	hl, 8
	or	hl, bc
	ld	a, (xiz+1)
	ld	c, a
	extz	bc
	ld	a, (xiz+5)
	ld	e, a
	extz	de
	ld	wa, bc
	ld	bc, hl
	calr	63699
	jrl	318
; Opcode 0x0B: reads the patch record (PART+0x06) and tests (patch+0x10) & 0xC0 == 0x40.
; If so, calls 0x02AF82(WA = part, BC = rec+4) and returns; otherwise falls through to
