	sll	hl, 8
	or	hl, bc
	ld	a, (xiz+5)
	ld	c, a
	extz	bc
	ld	wa, hl
	calr	VoiceParam_CustomTone_Apply_Catalog8C
	ld	xwa, (283420:24)
	ld	a, (xwa+29351)
	extz	wa
	calr	64876
	jr	52
; Opcode 0x16: 0x02EB8A with the 16-bit value and BC = rec+5, then the same
