	lds	wa, 0
	calr	64890
	jr	33
; Only when (rec+5) == 7: DSP_SlotParam_Write_From_Cache_B(index 1).
Audio_Cmd_ToneEdit_Reply_Case_Slot1:
	cp	(xiz+5), 7
	jr	nz, 27
	lds	wa, 1
	calr	64877
	jr	20
; DSP_SlotParam_Read_To_Cache_B for indices 0 and 1.
Audio_Cmd_ToneEdit_Reply_Case_ReadBack:
	ld	a, (xiz+1)
	extz	wa
	lds	bc, 0
	calr	65206
; Table entry that enters the read-back pair at its second call only (index 1).
Audio_Cmd_ToneEdit_Reply_Case_ReadBack1:
	ld	a, (xiz+1)
	extz	wa
	lds	bc, 1
	calr	65196
; ★ The unconditional sub->main reply.  Builds
;   dst = 0x001E0000 + 0x4AA7 + editIndex*0x50   (editIndex = [ToneDB_RamBankA + 0x72A7])
;   src = the buffer pointer saved at (XSP+0x04)
;   len = 0x3A (58 bytes)
; and calls InterCPU_E1_DMA_Transfer (0x020DB3).  If that call times out the command is
; still acknowledged locally and the main CPU simply never sees the update.
Audio_Cmd_ToneEdit_Reply_Send:
	ld	xde, 1966080
	ldw	bc, 58
	ld	xwa, (283420:24)
	ld	a, (xwa+29351)
	extz	wa
	muls	wa, 80
	add	wa, 19111
	exts	xwa
	add	xwa, xde
	ld	xde, xwa
	ld	xwa, (xsp+4)
	call	134579
	pop xiz
	inc	4, xsp
	ret
; Sibling of 0x030428 for the sub-field form of the command.  The opcode's top two bits
; select a group 0..3 (kept in QIZH) and its low six bits select a byte within that group.
; After ToneDB_Find_SubToneRecord it advances the buffer pointer by group*0x15 + 0x10,
; calls WaveSel_StageA1_FromToneSlot (0x032682) with WA = group, XBC = buffer, DE = editIndex
; and the part pushed on the stack, stores (rec+4) at buffer[opcode & 0x3F], and then
; DMAs that single byte to
;   0x001E0000 + 0x4AE1 + editIndex*0x50 + group*0x0B + (opcode & 0x3F)
; via InterCPU_E1_DMA_Transfer.  Caller: 0x031B33.
Audio_Cmd_ToneEdit_Field_Write_And_Reply:
	dec	4, xsp
	push qiz
	ld	(xsp+2), xwa
	ld	xwa, (xsp+2)
	ld	a, (xwa+1)
	extz	wa
	muls	wa, 287
	lda	xbc, (267118:24)
	ld_rrl	xhl, xbc, wa
	ld	xwa, (283420:24)
	ld	a, (xwa+29351)
	ld	c, a
	extz	bc
	ld	xwa, (xsp+2)
	ld	a, (xwa+1)
	ld	e, a
	extz	de
	ld	xwa, xhl
	call	207584
	ld	xwa, (xsp+2)
	ld	a, (xwa+2)
	and	a, 192
	srl	a, 6
	ldb_erp	a, 251
	extz	wa
	muls	wa, 21
	add	wa, 16
	lda_rr	xhl, xhl, wa
	stb_erp	a, 251
	ld	c, a
	extz	bc
	ld	xwa, (283420:24)
	ld	a, (xwa+29351)
	ld	e, a
	extz	de
	ld	xwa, (xsp+2)
	ld	a, (xwa+1)
	extz	wa
	pushw wa
	ld	wa, bc
	ld	xbc, xhl
	call	206466
	ld	xwa, (xsp+2)
	ld	a, (xwa+2)
	and	a, 63
	extz	wa
	extz	xwa
	add	xhl, xwa
	ld	xwa, (xsp+2)
	ld	a, (xwa+4)
	ld	(xhl), a
	ld	xde, 1966080
	stb_erp	a, 251
	extz	wa
	muls	wa, 11
	ld	bc, wa
	ld	xwa, (283420:24)
	ld	a, (xwa+29351)
	extz	wa
	muls	wa, 80
	add	wa, bc
	exts	xwa
	add	xwa, xde
	lda	xwa, (xwa+19169)
	ld	xbc, xwa
	ld	xwa, (xsp+2)
	ld	a, (xwa+2)
	and	a, 63
	extz	wa
	extz	xwa
	ld	xde, xwa
	add	xde, xbc
	ld	xwa, xhl
	lds	bc, 1
	call	134579
	pop qiz
	inc	4, xsp
	ret

; DSP_EffectStateQuery -- Query whether effect is active for a voice
; Reads bit 0 of voice struct at 0x041368; returns 1 (active) or 0.
; Input WA = part, XBC = one-byte result buffer.  Writes 1 if PART+0x00 bit 0 is set
; (the part is allocated), 0 otherwise, and returns HL = 1.
; Called from DSP_SetCoeff_MasterConfig at 0x0317E2 with XBC = 0x045216, and from
; AUDIO_PROCESS_DSP at 0x035BFC.
DSP_EffectStateQuery:
	extz wa
	muls wa, 0x11F
	lda xde, (0x041368:24)
	ldw_sri WA, 0x07, 0xE8, 0xE0
	bit 0, wa
	jr z, DSP_EffectStateQuery_WriteZero
	ld (xbc), 0x1
	jr DSP_EffectStateQuery_SetResult

; Part not allocated: store 0.
DSP_EffectStateQuery_WriteZero:
	ld (xbc), 0x0

; Return HL = 1 (success).
DSP_EffectStateQuery_SetResult:
	lds hl, 1
	ret

; Input XWA = PART record base.  Applies the five global offset bytes at 0x0451A6..0x0451AC
; to a part's four operator slots and to the part's patch record:
;   0x0451A6 << 2  -> slot+0x4D (and slot+0x4F for shape 5), clamped by TVF_Clamp_Cutoff
;   0x0451AB << 2  -> slot+0x27, clamped 0..0xFF by ClampS16_WA_To_DEBC
;   0x0451AC << 2  -> slot+0x2D, same clamp
;   0x0451A7 << 1  -> patch+0x2B and patch+0x3B, clamped 0..0x7F (skipped when 0x0451A7
;                     reads 0xF5, the "unset" sentinel)
;   0x0451A8 << 1  -> patch+0x2C and patch+0x3C, clamped 0..0x7F
;   0x0451A9 << 1  -> the low 6 bits of patch+0x2E and patch+0x3E, clamped 0..0x1E
; Slot addressing is FP_MulAccum64(index, 0x25) + 0x6E + PART, then a long pointer fetch.
; Called only from DSP_AlgoSelect_AlreadyAllocated (0x0309BD).
DSP_AdjustVoiceParams:
	lda xsp, (xsp - 10)
	push xiz
	ld (xsp + 10), xwa
	ldb_da a, 0x0451a6
	sla a, 2
	exts wa
	ld (xsp + 4), wa
	ldb_da a, 0x0451ab
	sla a, 2
	exts wa
	ld (xsp + 6), wa
	ldb_da a, 0x0451ac
	sla a, 2
	exts wa
	ld (xsp + 8), wa
	ldiw_erp 0xFA, 0
	cpiw_erp 0xFA, 4
	jrl nc, DSP_AdjustVoiceParams_Vibrato

; Four-iteration loop over the part's operator slots; QIZ is the slot counter.
DSP_AdjustVoiceParams_SlotLoop:
	stw_erp WA, 0xFA
	extz xwa
	ld xbc, 0x25
	call FP_MulAccum64
	add xhl, 0x6E
	add xhl, (xsp + 10)
	ld xwa, (xhl)
	ld a, (xwa + 54)
	and a, 0x7
	cps a, 5
	jr z, DSP_AdjustVoiceParams_Type5
	cps a, 4
	jr z, DSP_AdjustVoiceParams_Type1to4
	cps a, 3
	jr z, DSP_AdjustVoiceParams_Type1to4
	cps a, 2
	jr z, DSP_AdjustVoiceParams_Type1to4
	cps a, 1
	jrl nz, DSP_AdjustVoiceParams_ReverbChorus

; Slot shapes 1..4: adjust slot+0x4D only.
DSP_AdjustVoiceParams_Type1to4:
	stw_erp WA, 0xFA
	extz xwa
	ld xbc, 0x25
	call FP_MulAccum64
	add xhl, 0x6E
	add xhl, (xsp + 10)
	ld xwa, (xhl)
	ld a, (xwa + 77)
	extz wa
	add wa, (xsp + 4)
	call TVF_Clamp_Cutoff
	ld iz, hl
	stw_erp WA, 0xFA
	extz xwa
	ld xbc, 0x25
	call FP_MulAccum64
	add xhl, 0x6E
	add xhl, (xsp + 10)
	ld xwa, (xhl)
	stb_erp C, 0xF8
	ld (xwa + 77), c
	jrl DSP_AdjustVoiceParams_ReverbChorus

; Slot shape 5: adjust both slot+0x4D and slot+0x4F.
DSP_AdjustVoiceParams_Type5:
	stw_erp WA, 0xFA
	extz xwa
	ld xbc, 0x25
	call FP_MulAccum64
	add xhl, 0x6E
	add xhl, (xsp + 10)
	ld xwa, (xhl)
	ld a, (xwa + 77)
	extz wa
	add wa, (xsp + 4)
	call TVF_Clamp_Cutoff
	ld iz, hl
	stw_erp WA, 0xFA
	extz xwa
	ld xbc, 0x25
	call FP_MulAccum64
	add xhl, 0x6E
	add xhl, (xsp + 10)
	ld xwa, (xhl)
	stb_erp C, 0xF8
	ld (xwa + 77), c
	stw_erp WA, 0xFA
	extz xwa
	ld xbc, 0x25
	call FP_MulAccum64
	add xhl, 0x6E
	add xhl, (xsp + 10)
	ld xwa, (xhl)
	ld a, (xwa + 79)
	extz wa
	add wa, (xsp + 4)
	call TVF_Clamp_Cutoff
	ld iz, hl
	stw_erp WA, 0xFA
	extz xwa
	ld xbc, 0x25
	call FP_MulAccum64
	add xhl, 0x6E
	add xhl, (xsp + 10)
	ld xwa, (xhl)
	stb_erp C, 0xF8
	ld (xwa + 79), c

; Common per-slot tail: the 0x0451AB -> slot+0x27 and 0x0451AC -> slot+0x2D adjustments,
; then loop back to the slot loop.
DSP_AdjustVoiceParams_ReverbChorus:
	stw_erp WA, 0xFA
	extz xwa
	ld xbc, 0x25
	call FP_MulAccum64
	add xhl, 0x6E
	add xhl, (xsp + 10)
	ld xwa, (xhl)
	ld a, (xwa + 39)
	extz wa
	add wa, (xsp + 6)
	ldw bc, 0xFF
	lds de, 0
	call ClampS16_WA_To_DEBC
	ld iz, hl
	stw_erp WA, 0xFA
	extz xwa
	ld xbc, 0x25
	call FP_MulAccum64
	add xhl, 0x6E
	add xhl, (xsp + 10)
	ld xwa, (xhl)
	stb_erp C, 0xF8
	ld (xwa + 39), c
	stw_erp WA, 0xFA
	extz xwa
	ld xbc, 0x25
	call FP_MulAccum64
	add xhl, 0x6E
	add xhl, (xsp + 10)
	ld xwa, (xhl)
	ld a, (xwa + 45)
	extz wa
	add wa, (xsp + 8)
	ldw bc, 0xFF
	lds de, 0
	call ClampS16_WA_To_DEBC
	ld iz, hl
	stw_erp WA, 0xFA
	extz xwa
	ld xbc, 0x25
	call FP_MulAccum64
	add xhl, 0x6E
	add xhl, (xsp + 10)
	ld xwa, (xhl)
	stb_erp C, 0xF8
	ld (xwa + 45), c
	inc1w_erp 0xFA
	cpiw_erp 0xFA, 4
	jrl c, DSP_AdjustVoiceParams_SlotLoop

; After all four slots: the 0x0451A7 pair, skipped entirely when 0x0451A7 == 0xF5.
DSP_AdjustVoiceParams_Vibrato:
	cpib_da 0x0451a7, 0xf5
	jr z, DSP_AdjustVoiceParams_Filter
	ldb_da a, 0x0451a7
	sla a, 1
	ld c, a
	exts bc
	ld xwa, (xsp + 10)
	ld xwa, (xwa + 6)
	ld a, (xwa + 43)
	extz wa
	add wa, bc
	ldw bc, 0x7F
	lds de, 0
	call ClampS16_WA_Short
	ld iz, hl
	ld xwa, (xsp + 10)
	ld xwa, (xwa + 6)
	stb_erp C, 0xF8
	ld (xwa + 43), c
	ldb_da a, 0x0451a7
	sla a, 1
	ld c, a
	exts bc
	ld xwa, (xsp + 10)
	ld xwa, (xwa + 6)
	ld a, (xwa + 59)
	extz wa
	add wa, bc
	ldw bc, 0x7F
	lds de, 0
	call ClampS16_WA_Short
	ld iz, hl
	ld xwa, (xsp + 10)
	ld xwa, (xwa + 6)
	stb_erp C, 0xF8
	ld (xwa + 59), c

; The 0x0451A8 and 0x0451A9 adjustments; the latter is a read-modify-write that preserves
; the top two bits of patch+0x2E / patch+0x3E.
DSP_AdjustVoiceParams_Filter:
	ldb_da a, 0x0451a8
	sla a, 1
	ld c, a
	exts bc
	ld xwa, (xsp + 10)
	ld xwa, (xwa + 6)
	ld a, (xwa + 44)
	extz wa
	add wa, bc
	ldw bc, 0x7F
	lds de, 0
	call ClampS16_WA_Short
	ld iz, hl
	ld xwa, (xsp + 10)
	ld xwa, (xwa + 6)
	stb_erp C, 0xF8
	ld (xwa + 44), c
	ldb_da a, 0x0451a8
	sla a, 1
	ld c, a
	exts bc
	ld xwa, (xsp + 10)
	ld xwa, (xwa + 6)
	ld a, (xwa + 60)
	extz wa
	add wa, bc
	ldw bc, 0x7F
	lds de, 0
	call ClampS16_WA_Short
	ld iz, hl
	ld xwa, (xsp + 10)
	ld xwa, (xwa + 6)
	stb_erp C, 0xF8
	ld (xwa + 60), c
	ld xwa, (xsp + 10)
	ld xwa, (xwa + 6)
	ld a, (xwa + 46)
	and a, 0x3F
	ldb_erp A, 0xF8
	extz iz
	ldb_da a, 0x0451a9
	sla a, 1
	exts wa
	add wa, iz
	ldw bc, 0x1E
	lds de, 0
	call ClampS16_WA_Short
	ld iz, hl
	ld xwa, (xsp + 10)
	ld xwa, (xwa + 6)
	andmi8 (xwa + 46), 0xC0
	ld xwa, (xsp + 10)
	ld xwa, (xwa + 6)
	stb_erp C, 0xF8
	or (xwa + 46), c
	ld xwa, (xsp + 10)
	ld xwa, (xwa + 6)
	ld a, (xwa + 62)
	and a, 0x3F
	ldb_erp A, 0xF8
	extz iz
	ldb_da a, 0x0451a9
	sla a, 1
	exts wa
	add wa, iz
	ldw bc, 0x1E
	lds de, 0
	call ClampS16_WA_Short
	ld iz, hl
	ld xwa, (xsp + 10)
	ld xwa, (xwa + 6)
	andmi8 (xwa + 62), 0xC0
	ld xwa, (xsp + 10)
	ld xwa, (xwa + 6)
	stb_erp C, 0xF8
	or (xwa + 62), c
	pop xiz
	lda xsp, (xsp + 10)
	ret

; =============================================================================
; DSP_AlgoSelect -- Select DSP algorithm for a voice slot
; =============================================================================
; Allocates a DSP algorithm slot in the voice structure array at 0x041368.
; Multiplies algo index by 0x11F (287 bytes per voice), sets bit 0 of flags
; to mark as allocated, configures the DSP processing chain.
; Validates algo sub-type < 0x28 (40); returns error code 2 on failure.
; Called from DSP_Cmd2B_AlgoSelect (sub-command 0x00 in Audio_Process_DSP).
; Input A = part, BC = algorithm number, XDE = one-byte status buffer.
; Rejects algorithm numbers >= 0x28 by writing status 2.  Otherwise, if the part is not yet
; allocated it allocates it exactly like VoiceAlloc_InitNewAllocation (set PART+0x00 bit 0,
; VoiceParam_FullSetup, WaveSel_Rebuild_PartCaches with PART+0x19 / PART+0x1A); if it already was
; allocated it instead calls DSP_AdjustVoiceParams.  Either way it then calls
; DSP_WriteAlgoBuffer (0x03522E) and DSP_VoiceState_Dispatch (0x035490) with WA = BC = 0xFF,
; writes status 0 and returns HL = 1.
; Callers: 0x031822 (DSP_SetCoeff_MasterConfig) and 0x035BEA (AUDIO_PROCESS_DSP).
DSP_AlgoSelect:
	dec 8, xsp
	push xiz
	ld (xsp + 4), xde
	ld (xsp + 8), bc
	ld (xsp + 10), a
	cpw (xsp + 8), 0x28
	jr nc, DSP_AlgoSelect_InvalidParam
	ld a, (xsp + 10)
	extz wa
	muls wa, 0x11F
	lda xbc, (0x041368:24)
	lda_dri XIZ, 0x07, 0xE4, 0xE0
	ld wa, (xiz)
	bit 0, wa
	jr nz, DSP_AlgoSelect_AlreadyAllocated
	ormi16 (xiz), 0x1
	ld a, (xsp + 10)
	extz wa
	calr VoiceParam_FullSetup
	ld a, (xsp + 10)
	ld l, a
	extz hl
	ld a, (xiz + 25)
	ld c, a
	extz bc
	ld a, (xiz + 26)
	ld e, a
	extz de
	ld wa, hl
	call WaveSel_Rebuild_PartCaches

; Part already had bit 0 set: apply the global offsets via DSP_AdjustVoiceParams instead of
; re-initialising.
DSP_AlgoSelect_AlreadyAllocated:
	ld wa, (xiz)
	bit 0, wa
	jr z, DSP_AlgoSelect_WriteAndDispatch
	ld xwa, xiz
	calr DSP_AdjustVoiceParams

; Push the algorithm to the DSP and report status 0.
DSP_AlgoSelect_WriteAndDispatch:
	ld a, (xsp + 10)
	extz wa
	ld bc, (xsp + 8)
	call DSP_WriteAlgoBuffer
	ldw wa, 0xFF
	ldw bc, 0xFF
	call DSP_VoiceState_Dispatch
	ld xwa, (xsp + 4)
	ld (xwa), 0x0
	jr DSP_AlgoSelect_Return

; Algorithm number out of range: status byte = 2.
DSP_AlgoSelect_InvalidParam:
	ld xwa, (xsp + 4)
	ld (xwa), 0x2

; HL = 1, restore XIZ, return.
DSP_AlgoSelect_Return:
	lds hl, 1
	pop xiz
	inc 8, xsp
	ret

; DSP_MixSendConfig -- Configure DSP mix/send routing
; Copies 0x11 bytes of routing data via ToneDB_Find_ToneRecord.
; Input XDE = destination buffer.  Calls ToneDB_Find_ToneRecord (0x03206F) and copies the
; first 0x11 bytes of the returned buffer into the caller's buffer.  Callers: 0x031847 and
; AUDIO_PROCESS_DSP at 0x035CB8.
DSP_MixSendConfig:
	push xiz
	ld xiz, xde
	call ToneDB_Find_ToneRecord
	ld xbc, xhl
	ldw hl, 0x11
	lds de, 0
	cp de, hl
	jr nc, DSP_MixSendConfig_Return

; 0x11-byte post-increment copy loop.
DSP_MixSendConfig_CopyLoop:
	ldb_spi A, 0xE4
	lda_dpi XBC, 0xF8
	inc 1, de
	cp de, hl
	jr c, DSP_MixSendConfig_CopyLoop

; Restore XIZ and return.
DSP_MixSendConfig_Return:
	pop xiz
	ret

; ----------------------------------------------------------------------------
; DSP_RouteCoeffs_TypeA - Route DSP coefficients via type-A table
; Entry: WA = voice parameter (masked to 7 bits)
;        BC = channel/type packed (low 4 bits = channel, bits 6-7 = type)
; Notes: 4-way dispatch based on type bits to select coefficient table
;        Table offsets: 0x44/0x48/0x4C from routing config at (0x45314)
;        Computes index: (channel << 7 + voice) * 2
;        Copies 13 bytes from source to DSP buffer at 0x45210
; ----------------------------------------------------------------------------
; Input WA = a 7-bit index, BC = a selector whose bits 7:6 pick one of four descriptor
; pointers and whose bits 3:0 form the high part of a table index.
; Reads a long pointer from (0x045314)+0x44/+0x48/+0x4C (bits 7:6 = 0/1/2, and 3 aliases 0),
; adds the window base (0x045310), fetches a word at ((BC & 0x0F) << 7 | WA) * 2, and uses
; that word as a 16-byte-stride row index into the block at (0x045314)+0x50.  Copies 0x0D
; bytes of the selected row into the staging buffer at 0x045210+6.
; Caller: 0x031865.
DSP_RouteCoeffs_TypeA:
	push	xiz
	and	wa, 127
	ld	de, bc
	and	bc, 15
	and	de, 192
	cp	de, 192
	jr	z, DSP_RouteCoeffs_TypeA_Sel3
	cp	de, 128
	jr	z, DSP_RouteCoeffs_TypeA_Sel2
	cp	de, 64
	jr	z, DSP_RouteCoeffs_TypeA_Sel1
	cps	de, 0
	jr	nz, DSP_RouteCoeffs_TypeA_Fetch
	ld	xde, (283412:24)
	ld	xhl, (xde+68)
	jr	DSP_RouteCoeffs_TypeA_Fetch
; Selector bits 7:6 == 01 -> descriptor pointer at (0x045314)+0x4C.
DSP_RouteCoeffs_TypeA_Sel1:
	ld	xde, (283412:24)
	ld	xhl, (xde+76)
	jr	DSP_RouteCoeffs_TypeA_Fetch
; Selector bits 7:6 == 10 -> descriptor pointer at (0x045314)+0x48.
DSP_RouteCoeffs_TypeA_Sel2:
	ld	xde, (283412:24)
	ld	xhl, (xde+72)
	jr	DSP_RouteCoeffs_TypeA_Fetch
; Selector bits 7:6 == 11 -> same pointer as selector 00, (0x045314)+0x44.
DSP_RouteCoeffs_TypeA_Sel3:
	ld	xde, (283412:24)
	ld	xhl, (xde+68)
; Common tail: compute the row number and set up the 0x0D-byte copy.
DSP_RouteCoeffs_TypeA_Fetch:
	sll	bc, 7
	add	bc, wa
	add	bc, bc
	ld	wa, bc
	extz	xwa
	add	xwa, xhl
	addda32_24	xwa, (283408)
	ld	xwa, (xwa)
	ld	ix, wa
	ld	xwa, (283412:24)
	ld	xhl, (xwa+80)
	ld	xiy, (283408:24)
	add	xiy, xhl
	ldw	hl, 13
	lds	de, 0
	cp	de, hl
	jr	nc, 40
; 0x0D-byte copy into 0x045210+6.
DSP_RouteCoeffs_TypeA_CopyLoop:
	ld	bc, de
	extz	xbc
	ld	wa, ix
	extz	xwa
	sll	xwa, 4
	add	xwa, xbc
	ld	xbc, xwa
	add	xbc, xiy
	ld	wa, de
	inc	6, wa
	extz	xwa
	ld	xiz, 283152
	add	xiz, xwa
	ld	a, (xbc)
	ld	(xiz), a
	inc	1, de
	cp	de, hl
	jr	c, DSP_RouteCoeffs_TypeA_CopyLoop
	pop	xiz
	ret
; ----------------------------------------------------------------------------
; DSP_RouteCoeffs_TypeB - Route DSP coefficients via type-B table
; Entry: Same as TypeA
; Notes: Same algorithm as TypeA with different table offsets (0x58-0x64)
; ----------------------------------------------------------------------------
; Structural twin of DSP_RouteCoeffs_TypeA using the second descriptor set:
; pointers at (0x045314)+0x58/+0x5C/+0x60 and the row block at (0x045314)+0x64.
; Caller: 0x031883.  The ELF already carries this name; the reference file simply lacks the
; line, so this is an "add", not a supersede.
DSP_RouteCoeffs_TypeB:
	push	xiz
	and	wa, 127
	ld	de, bc
	and	bc, 15
	and	de, 192
	cp	de, 192
	jr	z, DSP_RouteCoeffs_TypeB_Sel3
	cp	de, 128
	jr	z, DSP_RouteCoeffs_TypeB_Sel2
	cp	de, 64
	jr	z, DSP_RouteCoeffs_TypeB_Sel1
	cps	de, 0
	jr	nz, DSP_RouteCoeffs_TypeB_Fetch
	ld	xde, (283412:24)
	ld	xhl, (xde+88)
	jr	DSP_RouteCoeffs_TypeB_Fetch
; Selector bits 7:6 == 01 -> (0x045314)+0x60.
DSP_RouteCoeffs_TypeB_Sel1:
	ld	xde, (283412:24)
	ld	xhl, (xde+96)
	jr	DSP_RouteCoeffs_TypeB_Fetch
; Selector bits 7:6 == 10 -> (0x045314)+0x5C.
DSP_RouteCoeffs_TypeB_Sel2:
	ld	xde, (283412:24)
	ld	xhl, (xde+92)
	jr	DSP_RouteCoeffs_TypeB_Fetch
; Selector bits 7:6 == 11 -> (0x045314)+0x58.
DSP_RouteCoeffs_TypeB_Sel3:
	ld	xde, (283412:24)
	ld	xhl, (xde+88)
; Common tail: row number and copy setup.
DSP_RouteCoeffs_TypeB_Fetch:
	sll	bc, 7
	add	bc, wa
	add	bc, bc
	ld	wa, bc
	extz	xwa
	add	xwa, xhl
	addda32_24	xwa, (283408)
	ld	xwa, (xwa)
	ld	ix, wa
	ld	xwa, (283412:24)
	ld	xhl, (xwa+100)
	ld	xiy, (283408:24)
	add	xiy, xhl
	ldw	hl, 13
	lds	de, 0
	cp	de, hl
	jr	nc, 40
; 0x0D-byte copy into 0x045210+6.
DSP_RouteCoeffs_TypeB_CopyLoop:
	ld	bc, de
	extz	xbc
	ld	wa, ix
	extz	xwa
	sll	xwa, 4
	add	xwa, xbc
	ld	xbc, xwa
	add	xbc, xiy
	ld	wa, de
	inc	6, wa
	extz	xwa
	ld	xiz, 283152
	add	xiz, xwa
	ld	a, (xbc)
	ld	(xiz), a
	inc	1, de
	cp	de, hl
	jr	c, DSP_RouteCoeffs_TypeB_CopyLoop
	pop	xiz
	ret
; ----------------------------------------------------------------------------
; DSP_CopyCoeffs_TypeA - Direct coefficient copy (type A)
; Entry: WA = voice parameter
; Notes: Direct copy without 4-way dispatch, uses offset 0x50
;        Copies 13 bytes from source to DSP buffer at 0x45210
; ----------------------------------------------------------------------------
; Input WA = row number.  Copies 0x0D bytes of that row out of the block at (0x045314)+0x50
; (16-byte stride, offset by the window base at 0x045310) into the staging buffer at
; 0x045210+6.  Same arithmetic as DSP_RouteCoeffs_TypeA but with the row supplied directly
; instead of looked up through a descriptor.  Caller: 0x0318A2.
DSP_CopyCoeffs_TypeA:
	push	xiz
	ld	xbc, (283412:24)
	ld	xbc, (xbc+80)
	ld	xiy, (283408:24)
	add	xiy, xbc
	ldw	hl, 13
	lds	ix, 0
	cp	ix, hl
	jr	nc, DSP_CopyCoeffs_TypeA_Return
; 0x0D-byte copy loop, counter in IX.
DSP_CopyCoeffs_TypeA_Loop:
	ld	de, ix
	extz	xde
	ld	bc, wa
	extz	xbc
	sll	xbc, 4
	add	xbc, xde
	ld	xde, xbc
	add	xde, xiy
	ld	bc, ix
	inc	6, bc
	extz	xbc
	ld	xiz, 283152
	add	xiz, xbc
	ld	c, (xde)
	ld	(xiz), c
	inc	1, ix
	cp	ix, hl
	jr	c, -40
; Restore XIZ and return.
DSP_CopyCoeffs_TypeA_Return:
	pop	xiz
	ret
; ----------------------------------------------------------------------------
; DSP_CopyCoeffs_TypeB - Direct coefficient copy (type B)
; Entry: WA = voice parameter
; Notes: Direct copy without 4-way dispatch, uses offset 0x64
;        Copies 13 bytes from source to DSP buffer at 0x45210
; ----------------------------------------------------------------------------
; The (0x045314)+0x64 flavour of DSP_CopyCoeffs_TypeA.  Caller: 0x0318C1.
DSP_CopyCoeffs_TypeB:
	push	xiz
	ld	xbc, (283412:24)
	ld	xbc, (xbc+100)
	ld	xiy, (283408:24)
	add	xiy, xbc
	ldw	hl, 13
	lds	ix, 0
	cp	ix, hl
	jr	nc, DSP_CopyCoeffs_TypeB_Return
; 0x0D-byte copy loop, counter in IX.
DSP_CopyCoeffs_TypeB_Loop:
	ld	de, ix
	extz	xde
	ld	bc, wa
	extz	xbc
	sll	xbc, 4
	add	xbc, xde
	ld	xde, xbc
	add	xde, xiy
	ld	bc, ix
	inc	6, bc
	extz	xbc
	ld	xiz, 283152
	add	xiz, xbc
	ld	c, (xde)
	ld	(xiz), c
	inc	1, ix
	cp	ix, hl
	jr	c, -40
; Restore XIZ and return.
DSP_CopyCoeffs_TypeB_Return:
	pop	xiz
	ret
; ----------------------------------------------------------------------------
; DSP_VoiceCoeffRoute - Voice-specific coefficient routing
; Entry: A = voice number, C = channel (low 4 bits)
; Notes: Looks up voice allocation at 0x41368 (voice * 287 + chan * 37 + 110)
;        Reads routing type from allocation entry byte 2 (bits 6-7)
;        4-way dispatch to select coefficient source table
;        Copies 13 coefficient bytes + 3 extra config bytes
;        Extra bytes: voice DE value (low, 0x00, high >> 8)
; ----------------------------------------------------------------------------
; Input A = part, C = slot (low nibble).  Resolves the slot descriptor at
; PART + 0x6E + slot*0x25 (long pointer), takes the row index from descriptor bytes +0x02
; (low 7 bits) and +0x03 (low nibble), selects a descriptor pointer from (0x045314)+0x44/
; +0x48/+0x4C according to bits 7:6 of descriptor+0x03, and copies 0x0D coefficient bytes
; plus three trailing bytes into 0x045210+6.  Caller: 0x0318DF.
DSP_VoiceCoeffRoute:
	push	xiz
	ld	e, c
	and	e, 15
	ld	c, e
	extz	bc
	muls	bc, 37
	ld	iy, bc
	add	iy, 110
	ld	c, a
	extz	bc
	muls	bc, 287
	lda	xix, (267112:24)
	exts	xbc
	add	xbc, xix
	ld_rrl	xbc, xbc, iy	; ld XBC,(XBC+IY)
	ld	c, (xbc+2)
	ldb_erp	c, 0xf0	; ld IXL,C
	extz	ix
	and	ix, 127
	ld	c, e
	extz	bc
	muls	bc, 37
	ld	iz, bc
	add	iz, 110
	ld	c, a
	extz	bc
	muls	bc, 287
	lda	xiy, (267112:24)
	exts	xbc
	add	xbc, xiy
	ld_rrl	xbc, xbc, iz	; ld XBC,(XBC+IZ)
	ld	c, (xbc+3)
	ldb_erp	c, 0xf4	; ld IYL,C
	extz	iy
	and	iy, 15
	ld	c, e
	extz	bc
	muls	bc, 37
	ld	de, bc
	add	de, 110
	extz	wa
	muls	wa, 287
	lda	xbc, (267112:24)
	exts	xwa
	add	xwa, xbc
	ld_rrl	xwa, xwa, de	; ld XWA,(XWA+DE)
	ld	a, (xwa+3)
	extz	wa
	and	wa, 192
	cp	wa, 192
	jr	z, DSP_VoiceCoeffRoute_Sel3
	cp	wa, 128
	jr	z, DSP_VoiceCoeffRoute_Sel2
	cp	wa, 64
	jr	z, DSP_VoiceCoeffRoute_Sel1
	cps	wa, 0
	jr	nz, DSP_VoiceCoeffRoute_Fetch
	ld	xwa, (283412:24)
	ld	xhl, (xwa+68)
	jr	DSP_VoiceCoeffRoute_Fetch
; Inside DSP_VoiceCoeffRoute: slot descriptor byte +0x03, bits 7:6 == 01 ->
; descriptor pointer (0x045314)+0x4C.
DSP_VoiceCoeffRoute_Sel1:
	ld	xwa, (283412:24)
	ld	xhl, (xwa+76)
	jr	DSP_VoiceCoeffRoute_Fetch
; Bits 7:6 == 10 -> (0x045314)+0x48.
DSP_VoiceCoeffRoute_Sel2:
	ld	xwa, (283412:24)
	ld	xhl, (xwa+72)
	jr	DSP_VoiceCoeffRoute_Fetch
; Bits 7:6 == 11 -> (0x045314)+0x44.
DSP_VoiceCoeffRoute_Sel3:
	ld	xwa, (283412:24)
	ld	xhl, (xwa+68)
; Common tail: row = ((desc+0x03 & 0x0F) << 7 | (desc+0x02 & 0x7F)) * 2.
DSP_VoiceCoeffRoute_Fetch:
	sll	iy, 7
	add	iy, ix
	add	iy, iy
	ld	wa, iy
	extz	xwa
	add	xwa, xhl
	addda32_24	xwa, (283408)
	ld	xwa, (xwa)
	ld	de, wa
	ld	xwa, (283412:24)
	ld	xhl, (xwa+80)
	ld	xix, (283408:24)
	add	xix, xhl
	ldw	hl, 13
	lds	iy, 0
	cp	iy, hl
	jr	nc, DSP_VoiceCoeffRoute_Epilogue
; 0x0D-byte copy into 0x045210+6, followed by three extra bytes: row+0x0D, then the row
; number's low and high halves -- i.e. the reply carries the row index back to the caller.
DSP_VoiceCoeffRoute_CopyLoop:
	ld	bc, iy
	extz	xbc
	ld	wa, de
	extz	xwa
	sll	xwa, 4
	add	xwa, xbc
	ld	xbc, xwa
	add	xbc, xix
	ld	wa, iy
	inc	6, wa
	extz	xwa
	ld	xiz, 283152
	add	xiz, xwa
	ld	a, (xbc)
	ld	(xiz), a
	inc	1, iy
	cp	iy, hl
	jr	c, -40
; The three trailing bytes described above.
DSP_VoiceCoeffRoute_Epilogue:
	ld	wa, hl
	inc	6, wa
	extz	xwa
	ld	xbc, 283152
	add	xbc, xwa
	ld	wa, de
	extz	xwa
	sll	xwa, 4
	add	xwa, xix
	ld	a, (xwa+13)
	ld	(xbc), a
	inc	1, hl
	ld	wa, hl
	inc	6, wa
	extz	xwa
	ld	xbc, 283152
	add	xbc, xwa
	ld	wa, de
	ldb	w, 0
	ld	(xbc), a
	inc	1, hl
	ld	wa, hl
	inc	6, wa
	extz	xwa
	ld	xbc, 283152
	add	xbc, xwa
	ld	wa, de
	srl	wa, 8
	ld	(xbc), a
	inc	1, hl
	pop	xiz
	ret
; ----------------------------------------------------------------------------
; DSP_VoiceCoeffRoute2 - Voice coefficient routing (variant 2)
; Entry: A = voice number, C = channel/type packed
; Notes: Similar to DSP_VoiceCoeffRoute but extracts both channel
;        and type from C (low 4 = channel, high 4 >> 4 = type)
;        Uses prevbank registers (D7 prefix) for extended operations
;        Multiple nested table lookups with different coefficient sets
;        Includes filter and vibrato coefficient routing
; ----------------------------------------------------------------------------
; Input A = part, C = packed (slot in the low nibble, sub-index in the high nibble).
; Follows the slot record's SECOND pointer (slotrec+0x04) and indexes it by
; sub-index*2 + 3 to obtain the row index, then does the DSP_VoiceCoeffRoute copy through the
; (0x045314)+0x58/+0x5C/+0x60 descriptor set and the +0x64 row block.  Caller: 0x0318FD.
DSP_VoiceCoeffRoute2:
	push	xiz
	ld	l, c
	and	l, 15
	and	c, 240
	srl	c, 4
	ld	e, c
	ld	c, l
	extz	bc
	muls	bc, 37
	ld	iz, bc
	add	iz, 110
	ld	c, a
	extz	bc
	muls	bc, 287
	lda	xiy, (267112:24)
	exts	xbc
	add	xbc, xiy
	lda_rr	xiy, xbc, iz	; lda XIY,XBC+IZ
	ld	c, e
	extz	bc
	add	bc, bc
	ld	iz, bc
	inc	3, iz
	ld	xbc, (xiy+4)
	ld_rrb	c, xbc, iz	; ld C,(XBC+IZ)
	ldb_erp	c, 0xf4	; ld IYL,C
	extz	iy
	and	iy, 127
	ld	c, l
	extz	bc
	muls	bc, 37
	ld	qwa, bc
	add_erpw	0xe2, 0x6e, 0x00	; add QWA,0x006e
	ld	c, a
	extz	bc
	muls	bc, 287
	lda	xiz, (267112:24)
	exts	xbc
	add	xbc, xiz
	lda_rrq	xiz, xbc, qwa	; lda XIZ,XBC+QWA
	ld	c, e
	extz	bc
	add	bc, bc
	ld	qwa, bc
	inc	3, qwa
	ld	xbc, (xiz+4)
	lda_rrq	xbc, xbc, qwa	; lda XBC,XBC+QWA
	ld	c, (xbc+1)
	ldb_erp	c, 0xf8	; ld IZL,C
	extz	iz
	and	iz, 15
	ld	c, l
	extz	bc
	muls	bc, 37
	ld	hl, bc
	add	hl, 110
	extz	wa
	muls	wa, 287
	lda	xbc, (267112:24)
	exts	xwa
	add	xwa, xbc
	lda_rr	xbc, xwa, hl	; lda XBC,XWA+HL
	ld	a, e
	extz	wa
	add	wa, wa
	ld	de, wa
	inc	3, de
	ld	xwa, (xbc+4)
	lda_rr	xwa, xwa, de	; lda XWA,XWA+DE
	ld	a, (xwa+1)
	extz	wa
	and	wa, 192
	cp	wa, 192
	jr	z, DSP_VoiceCoeffRoute2_Sel3
	cp	wa, 128
	jr	z, DSP_VoiceCoeffRoute2_Sel2
	cp	wa, 64
	jr	z, DSP_VoiceCoeffRoute2_Sel1
	cps	wa, 0
	jr	nz, DSP_VoiceCoeffRoute2_Fetch
	ld	xwa, (283412:24)
	ld	xix, (xwa+88)
	jr	DSP_VoiceCoeffRoute2_Fetch
; Inside DSP_VoiceCoeffRoute2: bits 7:6 == 01 -> (0x045314)+0x60.
DSP_VoiceCoeffRoute2_Sel1:
	ld	xwa, (283412:24)
	ld	xix, (xwa+96)
	jr	DSP_VoiceCoeffRoute2_Fetch
; Bits 7:6 == 10 -> (0x045314)+0x5C.
DSP_VoiceCoeffRoute2_Sel2:
	ld	xwa, (283412:24)
	ld	xix, (xwa+92)
	jr	DSP_VoiceCoeffRoute2_Fetch
; Bits 7:6 == 11 -> (0x045314)+0x58.
DSP_VoiceCoeffRoute2_Sel3:
	ld	xwa, (283412:24)
	ld	xix, (xwa+88)
; Common tail; row block is (0x045314)+0x64.
DSP_VoiceCoeffRoute2_Fetch:
	sll	iz, 7
	add	iz, iy
	add	iz, iz
	ld	wa, iz
	extz	xwa
	add	xwa, xix
	addda32_24	xwa, (283408)
	ld	xwa, (xwa)
	ld	de, wa
	ld	xwa, (283412:24)
	ld	xix, (xwa+100)
	ld	xwa, (283408:24)
	add	xwa, xix
	ld	xix, xwa
	ldw	hl, 13
	lds	iy, 0
	cp	iy, hl
	jr	nc, DSP_VoiceCoeffRoute2_Epilogue
; 0x0D-byte copy into 0x045210+6.
DSP_VoiceCoeffRoute2_CopyLoop:
	ld	bc, iy
	extz	xbc
	ld	wa, de
	extz	xwa
	sll	xwa, 4
	add	xwa, xbc
	ld	xbc, xwa
	add	xbc, xix
	ld	wa, iy
	inc	6, wa
	extz	xwa
	ld	xiz, 283152
	add	xiz, xwa
	ld	a, (xbc)
	ld	(xiz), a
	inc	1, iy
	cp	iy, hl
	jr	c, -40
; The same three trailing bytes (row+0x0D and the row index) as DSP_VoiceCoeffRoute.
DSP_VoiceCoeffRoute2_Epilogue:
	ld	wa, hl
	inc	6, wa
	extz	xwa
	ld	xbc, 283152
	add	xbc, xwa
	ld	wa, de
	extz	xwa
	sll	xwa, 4
	add	xwa, xix
	ld	a, (xwa+13)
	ld	(xbc), a
	inc	1, hl
	ld	wa, hl
	inc	6, wa
	extz	xwa
	ld	xbc, 283152
	add	xbc, xwa
	ld	wa, de
	ldb	w, 0
	ld	(xbc), a
	inc	1, hl
	ld	wa, hl
	inc	6, wa
	extz	xwa
	ld	xbc, 283152
	add	xbc, xwa
	ld	wa, de
	srl	wa, 8
	ld	(xbc), a
	inc	1, hl
	pop	xiz
	ret
; ----------------------------------------------------------------------------
; DSP_AlgoCoeffLookup - Algorithm-based coefficient table lookup
; Entry: A = algorithm number (0-4)
; Notes: 5-way dispatch based on algorithm (0-4) to select table
;        Tables at config offsets: 0x54, 0x70, 0x7C, 0x88-0x98
;        Reads entry count from byte 2 of selected table entry
;        Copies coefficient data to DSP buffer at 0x45210
; ----------------------------------------------------------------------------
; Input A = bank 0..4.  Selects one of five descriptor blocks hanging off (0x045314) and
; copies (block+0x02)+3 bytes of it into the staging buffer at 0x045210+6 -- i.e. the block
; carries its own length in its third byte.  Caller: 0x03190D.
DSP_AlgoCoeffLookup:
	cps	a, 4
	jr	z, 60
	cps	a, 3
	jr	z, 44
	cps	a, 2
	jr	z, 28
	cps	a, 1
	jr	z, 14
	cps	a, 0
	jr	nz, 56
	ld	xwa, (283412:24)
	ld	xix, (xwa+84)
	jr	t, 54
; Bank 1 -> (0x045314)+0x68.
DSP_AlgoCoeffLookup_Bank1:
	ld	xwa, (283412:24)
	ld	xix, (xwa+104)
	jr	t, 44
; Bank 2 -> (0x045314)+0x0084.
DSP_AlgoCoeffLookup_Bank2:
	ld	xwa, (283412:24)
	ld	xix, (xwa+132)
	jr	t, 32
; Bank 3 -> (0x045314)+0x0090.
DSP_AlgoCoeffLookup_Bank3:
	ld	xwa, (283412:24)
	ld	xix, (xwa+144)
	jr	t, 20
; Bank 4 -> (0x045314)+0x0098.
DSP_AlgoCoeffLookup_Bank4:
	ld	xwa, (283412:24)
	ld	xix, (xwa+152)
	jr	t, 8
; Bank 0 or out of range -> (0x045314)+0x54.
DSP_AlgoCoeffLookup_BankDefault:
	ld	xwa, (283412:24)
	ld	xix, (xwa+84)
; Copies (block+0x02)+3 bytes from the selected block into 0x045210+6; the length is stored
; in the block's own third byte.
DSP_AlgoCoeffLookup_CopyLoop:
	ld	xwa, (283408:24)
	add	xwa, xix
	ld	xix, xwa
	ld	a, (xwa+2)
	inc	3, a
	ld	l, a
	extz	hl
	lds	de, 0
	cp	de, hl
	ret	nc
	ld	wa, de
	extz	xwa
	ld	xbc, xix
	add	xbc, xwa
	ld	wa, de
	inc	6, wa
	extz	xwa
	ld	xiy, 283152
	add	xiy, xwa
	ld	a, (xbc)
	ld	(xiy), a
	inc	1, de
	cp	de, hl
	jr	c, -31
	ret

; =============================================================================
; DSP_VoiceParamReadWrite -- Read/write a single DSP parameter
; =============================================================================
; Accesses DSP parameter storage at 0x44FCE + 0x1D8 + param_index.
; If voice is allocated (bit 0 set), reads from single slot.
; Otherwise iterates 4 sub-slots via DSP_VoiceParam_MultiSlot.
; Args: wa = voice number (0-15), bc = param index (0-7),
;       xde = pointer to voice parameter data area
; Called from: sub-commands 0x10-0x17 (DSP param set) in Audio_Process_DSP
; Input WA = part, BC = parameter index, XDE = one-byte result buffer.
; If PART+0x00 bit 0 is set (part allocated), the answer is simply the shadow byte at
; UserTone_VelSplit_Base + 0x1D8 + index.  If the part is NOT allocated it instead surveys
; the part's four operator slots (DSP_VoiceParam_MultiSlot) and only reports a value when
; all four agree.  Called from 0x03193B and from eight consecutive sites in
; AUDIO_PROCESS_DSP (0x035C10..0x035C9C), i.e. it is the main query primitive.
DSP_VoiceParamReadWrite:
	lda xsp, (xsp - 14)
	push xiz
	ld (xsp + 10), xde
	ld (xsp + 14), bc
	ld (xsp + 16), wa
	ldw (xsp + 8), 0x0
	ld wa, (xsp + 16)
	extz xwa
	ld xbc, 0x11F
	call FP_MulAccum64
	ld xwa, 0x41368
	add xwa, xhl
	ld wa, (xwa)
	bit 0, wa
	jr z, DSP_VoiceParam_MultiSlot
	ld wa, (xsp + 14)
	extz xwa
	add xwa, 0x1D8
	ld xbc, 0x44FCE
	add xbc, xwa
	ld xwa, (xsp + 10)
	ld c, (xbc)
	ld (xwa), c
	jrl DSP_VoiceParamReadWrite_Return

; Part not allocated: zero the match counter at (XSP+0x08) and walk the four slots.
DSP_VoiceParam_MultiSlot:
	ldw (xsp + 6), 0x0
	cpw (xsp + 6), 0x4
	jr nc, DSP_VoiceParam_MultiSlot_CheckResult

; Per slot: skip the slot if (slotptr+0x06) & 0xC0 is non-zero or bit 5 of (slotptr+0x06) is
; set; otherwise increment the match counter.
DSP_VoiceParam_MultiSlot_LoopBody:
	ld wa, (xsp + 6)
	extz xwa
	ld xbc, 0x25
	call FP_MulAccum64
	ld xiz, xhl
	add xiz, 0x6E
	ld wa, (xsp + 16)
	extz xwa
	ld xbc, 0x11F
	call FP_MulAccum64
	ld xwa, 0x41368
	add xwa, xhl
	add xwa, xiz
	ld xwa, (xwa)
	ld a, (xwa + 6)
	and a, 0xC0
	jr nz, DSP_VoiceParam_MultiSlot_LoopNext
	ld wa, (xsp + 6)
	extz xwa
	ld xbc, 0x25
	call FP_MulAccum64
	ld xiz, xhl
	add xiz, 0x6E
	ld wa, (xsp + 16)
	extz xwa
	ld xbc, 0x11F
	call FP_MulAccum64
	ld xwa, 0x41368
	add xwa, xhl
	add xwa, xiz
	ld xwa, (xwa)
	bitm 5, (xwa + 6)
	jr nz, DSP_VoiceParam_MultiSlot_LoopNext
	incw 1, (xsp + 8)

; Advance the slot counter and loop while < 4.
DSP_VoiceParam_MultiSlot_LoopNext:
	incw 1, (xsp + 6)
	cpw (xsp + 6), 0x4
	jr c, DSP_VoiceParam_MultiSlot_LoopBody

; Result = 0 unless all four slots matched, in which case the answer comes from
; DSP_VOICEPARAM_DEFAULT_TABLE (0x00F95D) indexed by the parameter index.
DSP_VoiceParam_MultiSlot_CheckResult:
	ld xde, (xsp + 10)
	ldb a, 0x0
	cpw (xsp + 8), 0x4
	jr nz, DSP_VoiceParam_MultiSlot_StoreResult
	ld wa, (xsp + 14)
	extz xwa
	ld xbc, 0xF95D
	add xbc, xwa
	ld a, (xbc)

; Store the byte into the caller's buffer.
DSP_VoiceParam_MultiSlot_StoreResult:
	ld (xde), a

; HL = (XSP+0x04), unwind and return.
DSP_VoiceParamReadWrite_Return:
	ld hl, (xsp + 4)
	pop xiz
	lda xsp, (xsp + 14)
	ret

; Input XDE = one-byte result buffer.  Calls ToneDB_Find_ToneRecord (0x03206F) and returns
; byte +0x5D of that buffer -- the algorithm-type byte this whole region dispatches on.
; Returns HL = 1.  Callers: 0x031966 and AUDIO_PROCESS_DSP 0x035CD4.
DSP_ReadVoiceParam5D:
	push xiz
	ld xiz, xde
	call ToneDB_Find_ToneRecord
	ld a, (xhl + 93)
	ld (xiz), a
	lds hl, 1
	pop xiz
	ret

; ----------------------------------------------------------------------------
; DSP_VoiceParam_Dispatch - Voice parameter dispatch with routing type check
; Entry: WA = voice parameter, BC = channel/type, XDE = data pointer
; Notes: Checks bit 5 of IX (from BC) for routing mode dispatch
;        If bit 5 set: uses alternate routing path
;        Otherwise: masks WA to 7 bits, extracts HL from BC bits 4:0,
;        uses 4-way dispatch on BC bits 7:6 for coefficient table selection
;        Computes routing index and copies parameters
; ----------------------------------------------------------------------------
; Input WA = 7-bit index, BC = selector, XDE = destination buffer.  If BC bit 5 is set the
; source is ToneDB_Find_ToneRecord's buffer; if BC bits 5 is clear it is a coefficient row
; selected exactly like DSP_RouteCoeffs_TypeA but through the pointer at (0x045314)+0x7C and
; the row block at (0x045314)+0x0080; any other value of (BC & 0x20) leaves XHL untouched
; from the caller.  Either way 0x0D bytes are copied to the caller's buffer and HL = 0x0D is
; returned.  Caller: 0x03198B.
DSP_VoiceParam_Dispatch:
	push	xiz
	ld	xiz, xde
	ld	ix, bc
	and	ix, 32
	cp	ix, 32
	jr	z, DSP_VoiceParam_Dispatch_UseVoiceBuffer
	cps	ix, 0
	jr	nz, DSP_VoiceParam_Dispatch_Copy
	and	wa, 127
	ld	hl, bc
	and	hl, 31
	and	bc, 192
	cp	bc, 192
	jr	z, DSP_VoiceParam_Dispatch_LoadRowBase
	cp	bc, 128
	jr	z, DSP_VoiceParam_Dispatch_LoadRowBase
	cp	bc, 64
	jr	z, DSP_VoiceParam_Dispatch_LoadRowBase
	cps	bc, 0
	jr	nz, DSP_VoiceParam_Dispatch_ComputeRow
; All four values of (BC & 0xC0) load the same pointer, (0x045314)+0x7C -- the four-way
; compare is vestigial.
DSP_VoiceParam_Dispatch_LoadRowBase:
	ld	xbc, (283412:24)
	ld	xde, (xbc+124)
; row = ((BC & 0x1F) << 7 | (WA & 0x7F)) * 2, then a 16-byte-stride row address.
DSP_VoiceParam_Dispatch_ComputeRow:
	ld	bc, hl
	sll	bc, 7
	add	bc, wa
	add	bc, bc
	ld	wa, bc
	extz	xwa
	add	xwa, xde
	addda32_24	xwa, (283408)
	ld	xwa, (xwa)
	ld	bc, wa
	ld	xwa, (283412:24)
	ld	xde, (xwa+128)
	ld	xwa, (283408:24)
	add	xwa, xde
	ld	xde, xwa
	ld	wa, bc
	extz	xwa
	sll	xwa, 4
	add	xwa, xde
	ld	xhl, xwa
	jr	DSP_VoiceParam_Dispatch_Copy
; (BC & 0x20) == 0x20: source is ToneDB_Find_ToneRecord's buffer instead.
DSP_VoiceParam_Dispatch_UseVoiceBuffer:
	call	ToneDB_Find_ToneRecord
; Copy 0x0D bytes from XHL to the caller's buffer (post-increment through XIZ).
DSP_VoiceParam_Dispatch_Copy:
	ldw	wa, 13
	lds	ix, 0
	cp	ix, wa
	jr	nc, DSP_VoiceParam_Dispatch_Return
; Loop body of that copy.
DSP_VoiceParam_Dispatch_CopyLoop:
	stb_dpi	b, 248
	ld	bc, ix
	extz	xbc
	add	xbc, xhl
	ld	c, (xbc)
	ld	(xde), c
	inc	1, ix
	cp	ix, wa
	jr	c, -19
; HL = 0x0D, restore XIZ, return.  This is the last instruction pair of the region.
DSP_VoiceParam_Dispatch_Return:
	ld	hl, wa
	pop	xiz
	ret

; DSP_SetVoiceCoefficients -- Write DSP voice coefficients
; Complex parameter setter using voice+0x27 region with coefficient lookups.
; Resolve one of a patch record's sub-tone references and copy the 10-byte
; ToneDB record it names into a caller-supplied buffer.
; Entry: A  = part index (0..25)
;        C  = sub-tone index i
;        XDE = destination buffer (the inter-CPU reply payload 0x045216 when
;              called from DSP_Cmd2B_SetParam)
; Exit:  HL = 10 (the byte count produced -- see the note on the reply protocol
;        in Voice_ParamFinalize / DSP_Cmd2B_PostProcess), XIZ = source record.
; Body: the part's 16-bit tone selector is Part_UserToneIndex[part] =
;       {byte 0x041381+part*0x11F, byte 0x041382+part*0x11F} (lo,hi); it is
;       handed to ToneDB_Find_ToneRecord (0x03206F) to get the patch record.
;       The sub-tone reference is the {lo,hi} pair at patchrec+0x27+2*i.
;         hi & 0x20 set -> ToneDB_Find_SubToneRecord (0x032AE0) with DE=0xFF
;                          supplies the source record directly.
;         otherwise     -> idx = ((hi & 0x1F) << 7) + (lo & 0x7F)
;                          e   = u16[ ToneDB_RelBase + Root->+0x7C + 2*idx ]
;                          src = ToneDB_RelBase + Root->+0xB0 + 10*e
;       Ten bytes are then copied src -> XDE.
; Touches no hardware; reads ToneDB_RelBase (0x045310) and ToneDB_RootPtr
; (0x045314).  Sole caller: DSP_Cmd2B_SetParam 0x035CEF.
; NOTE: the LLVM source currently calls this DSP_SetVoiceCoefficients; nothing
; in the body touches a DSP, so that name is misleading (see [UNCERTAIN]).
DSP_SetVoiceCoefficients:
	lda xsp, (xsp - 10)
	push xiz
	ld (xsp + 8), xde
	ld (xsp + 12), c
	lds32 xiz, 0
	lds32 xbc, 0
	ld (xsp + 4), xbc
	ld c, a
	extz bc
	muls bc, 0x11F
	lda xde, (0x041381:24)
	ldb_sri C, 0x07, 0xE8, 0xE4
	ld e, c
	extz de
	extz wa
	muls wa, 0x11F
	lda xbc, (0x041382:24)
	ldb_sri A, 0x07, 0xE4, 0xE0
	ld c, a
	extz bc
	ld wa, de
	call ToneDB_Find_ToneRecord
	ld a, (xsp + 12)
	extz wa
	add wa, wa
	add wa, 0x27
	ldb_sri A, 0x07, 0xEC, 0xE0
	ld c, a
	extz bc
	ld a, (xsp + 12)
	extz wa
	add wa, wa
	add wa, 0x27
	exts xwa
	add xwa, xhl
	ld a, (xwa + 1)
	ldb_erp A, 0xF0
	extz ix
	ld wa, ix
	and wa, 0x20
	cp wa, 0x20
	jr z, DSP_SetCoeff_DirectLookup
	cps wa, 0
	jr nz, DSP_SetCoeff_CopyLoop
	and bc, 0x7F
	ld de, ix
	and de, 0x1F
	ld wa, ix
	and wa, 0xC0
	cp wa, 0xC0
	jr z, DSP_SetCoeff_LoadTableBase
	cp wa, 0x80
	jr z, DSP_SetCoeff_LoadTableBase
	cp wa, 0x40
	jr z, DSP_SetCoeff_LoadTableBase
	cps wa, 0
	jr nz, DSP_SetCoeff_ComputeIndex

; Load ToneDB_RootPtr->+0x7C (the sub-tone index table) into the frame slot.
DSP_SetCoeff_LoadTableBase:
	ld xwa, (0x045314:24)
	ld xwa, (xwa + 124)
	ld (xsp + 4), xwa

; idx=(hi&0x1F)<<7 | lo; u16 lookup; then Root->+0xB0 + 10*e -> XIZ.
DSP_SetCoeff_ComputeIndex:
	ld wa, de
	sll wa, 7
	add wa, bc
	add wa, wa
	extz xwa
	add xwa, (xsp + 4)
	addda32_24 xwa, 283408
	ld xwa, (xwa)
	ld bc, wa
	ld xwa, (0x045314:24)
	ld_sril XWA, (xwa + 0x00b0)
	ld (xsp + 4), xwa
	ld xiz, (0x045310:24)
	add xiz, (xsp + 4)
	ld wa, bc
	mul wa, 0xA
	add xiz, xwa
	jr DSP_SetCoeff_CopyLoop

; hi bit 5 set: source comes from ToneDB_Find_SubToneRecord instead.
DSP_SetCoeff_DirectLookup:
	ld a, (xsp + 12)
	ld c, a
	extz bc
	ld xwa, xhl
	ldw de, 0xFF
	call ToneDB_Find_SubToneRecord
	ld xiz, xhl

; Set the 10-byte copy count in HL (this value is also the return value).
DSP_SetCoeff_CopyLoop:
	ldw hl, 0xA
	lds de, 0
	cp de, hl
	jr nc, DSP_SetCoeff_Return

; Byte copy XIZ+ -> (XSP+8)+, 10 iterations.
DSP_SetCoeff_CopyLoop_Body:
	ld xwa, (xsp + 8)
	ldb_spi C, 0xF8
	lda_dpi XHL, 0xE0
	ld (xsp + 8), xwa
	inc 1, de
	cp de, hl
	jr c, DSP_SetCoeff_CopyLoop_Body

; Frame teardown; HL still holds 10.
DSP_SetCoeff_Return:
	pop xiz
	lda xsp, (xsp + 10)
	ret

; ----------------------------------------------------------------------------
; DSP_SetCoeff_CopyDirect - Copy coefficients directly to DSP buffer
; Notes: Reads routing config from (0x45314), adds base from (0x45310)
;        Copies to DSP coefficient buffer at 0x45210
