	ld	xbc, (283412:24)
	ld	xbc, (xbc+128)
	ld	xiy, (283408:24)
	add	xiy, xbc
	ldw	hl, 13
	lds	ix, 0
	cp	ix, hl
	jr	nc, LABEL_031272
