	extz	xde
	ld	bc, wa
	extz	xbc
	sll	xbc, 4
	add	xbc, xde
	ld	xde, xbc
	add	xde, xiy
	ld	bc, ix
	inc	6, bc
	extz	xbc
	ld	xiz, 283152
	add	xiz, xbc
	ld	c, (xde)
	ld	(xiz), c
	inc	1, ix
	cp	ix, hl
	jr	c, LABEL_03124A
LABEL_031272:
	pop	xiz
	ret
