	extz	ix
	and	ix, 32
	ld	xwa, (283412:24)
	ld	xhl, (xwa+124)
	ld	wa, iy
	sll	wa, 7
	add	wa, de
	add	wa, wa
	extz	xwa
	add	xwa, xhl
	addda32_24	xwa, 283408
	ld	xwa, (xwa)
	ld	de, wa
	ld	xwa, (283412:24)
	ld	xhl, (xwa+128)
	ld	xwa, (283408:24)
	add	xwa, xhl
	ld	(xsp+4), xwa
	ldw	hl, 13
	ld	wa, ix
	cp	wa, 32
	jr	z, 53
	cps	wa, 0
	jr	nz, 108
	lds	ix, 0
	cp	ix, hl
	jr	nc, 102
	ld	bc, ix
	extz	xbc
	ld	wa, de
	extz	xwa
	sll	xwa, 4
